window.BANQUE_INFINI = {"module":"annee-1/theorique/semestre-2/anat","titre":"Anatomie II","sources":[{"t":"Anatomie II — Cardiovasculaire — 1","q":"qcm/qcm-systeme-cardio-lymphatique-01-cardio-1.html","f":"systeme-cardio-lymphatique/01-cardio-1.html"},{"t":"Anatomie II — Cardiovasculaire — 2","q":"qcm/qcm-systeme-cardio-lymphatique-02-cardio-2.html","f":"systeme-cardio-lymphatique/02-cardio-2.html"},{"t":"Anatomie II — Cardiovasculaire — 3","q":"qcm/qcm-systeme-cardio-lymphatique-03-cardio-3.html","f":"systeme-cardio-lymphatique/03-cardio-3.html"},{"t":"Anatomie II — Lymphatique — 1","q":"qcm/qcm-systeme-cardio-lymphatique-04-lymphatique-1.html","f":"systeme-cardio-lymphatique/04-lymphatique-1.html"},{"t":"Anatomie II — Lymphatique — 2","q":"qcm/qcm-systeme-cardio-lymphatique-05-lymphatique-2.html","f":"systeme-cardio-lymphatique/05-lymphatique-2.html"},{"t":"Anatomie II — Lymphatique — 3","q":"qcm/qcm-systeme-cardio-lymphatique-06-lymphatique-3.html","f":"systeme-cardio-lymphatique/06-lymphatique-3.html"},{"t":"Anatomie II — Introduction au système digestif","q":"qcm/qcm-systeme-digestif-01-intro.html","f":"systeme-digestif/01-intro.html"},{"t":"Anatomie II — Tube digestif (bouche, pharynx, œsophage)","q":"qcm/qcm-systeme-digestif-02-tube-digestif.html","f":"systeme-digestif/02-tube-digestif.html"},{"t":"Anatomie II — Estomac","q":"qcm/qcm-systeme-digestif-03-estomac.html","f":"systeme-digestif/03-estomac.html"},{"t":"Anatomie II — Intestin grêle","q":"qcm/qcm-systeme-digestif-04-intestin-grele.html","f":"systeme-digestif/04-intestin-grele.html"},{"t":"Anatomie II — Gros intestin","q":"qcm/qcm-systeme-digestif-05-gros-intestin.html","f":"systeme-digestif/05-gros-intestin.html"},{"t":"Anatomie II — Foie — partie 1","q":"qcm/qcm-systeme-digestif-06-foie-1.html","f":"systeme-digestif/06-foie-1.html"},{"t":"Anatomie II — Foie — partie 2","q":"qcm/qcm-systeme-digestif-07-foie-2.html","f":"systeme-digestif/07-foie-2.html"},{"t":"Anatomie II — Foie — partie 3","q":"qcm/qcm-systeme-digestif-08-foie-3.html","f":"systeme-digestif/08-foie-3.html"},{"t":"Anatomie II — Vésicule biliaire","q":"qcm/qcm-systeme-digestif-09-vesicule-biliaire.html","f":"systeme-digestif/09-vesicule-biliaire.html"},{"t":"Anatomie II — Pancréas","q":"qcm/qcm-systeme-digestif-10-pancreas.html","f":"systeme-digestif/10-pancreas.html"},{"t":"Anatomie II — Vascularisation du système digestif","q":"qcm/qcm-systeme-digestif-11-vascularisation.html","f":"systeme-digestif/11-vascularisation.html"},{"t":"Anatomie II — Voies respiratoires supérieures","q":"qcm/qcm-systeme-respiratoire-01-voies-respiratoires-sup.html","f":"systeme-respiratoire/01-voies-respiratoires-sup.html"},{"t":"Anatomie II — Voies respiratoires inférieures","q":"qcm/qcm-systeme-respiratoire-02-voies-respiratoires-inf.html","f":"systeme-respiratoire/02-voies-respiratoires-inf.html"},{"t":"Anatomie II — Paroi thoracique","q":"qcm/qcm-systeme-respiratoire-03-paroi-thoracique.html","f":"systeme-respiratoire/03-paroi-thoracique.html"},{"t":"Anatomie II — Système urinaire","q":"qcm/qcm-systeme-urinaire-01-systeme-urinaire.html","f":"systeme-urinaire/01-systeme-urinaire.html"},{"t":"Anatomie II — Reproducteur féminin — 1","q":"qcm/qcm-systeme-urinaire-02-reproducteur-feminin-1.html","f":"systeme-urinaire/02-reproducteur-feminin-1.html"},{"t":"Anatomie II — Reproducteur féminin — 2","q":"qcm/qcm-systeme-urinaire-02-reproducteur-feminin-2.html","f":"systeme-urinaire/02-reproducteur-feminin-2.html"},{"t":"Anatomie II — Reproducteur féminin — 3","q":"qcm/qcm-systeme-urinaire-02-reproducteur-feminin-3.html","f":"systeme-urinaire/02-reproducteur-feminin-3.html"},{"t":"Anatomie II — Reproducteur féminin — 4","q":"qcm/qcm-systeme-urinaire-02-reproducteur-feminin-4.html","f":"systeme-urinaire/02-reproducteur-feminin-4.html"},{"t":"Anatomie II — Reproducteur féminin — 5","q":"qcm/qcm-systeme-urinaire-02-reproducteur-feminin-5.html","f":"systeme-urinaire/02-reproducteur-feminin-5.html"},{"t":"Anatomie II — Reproducteur masculin","q":"qcm/qcm-systeme-urinaire-03-reproducteur-masculin.html","f":"systeme-urinaire/03-reproducteur-masculin.html"},{"t":"Anatomie II — Cavité pelvienne","q":"qcm/qcm-systeme-urinaire-04-cavite-pelvienne.html","f":"systeme-urinaire/04-cavite-pelvienne.html"}],"questions":[{"q":"Poids du cœur adulte :","o":["100-150 g","250-350 g","500-700 g","1 kg"],"r":1,"e":"~300 g. Dimensions 12 × 9 × 6 cm.","s":0},{"q":"Le cœur se trouve dans :","o":["Médiastin supérieur","Médiastin moyen","Médiastin postérieur","Cavité abdominale"],"r":1,"e":"Médiastin moyen, entre les 2 poumons.","s":0},{"q":"% du cœur à gauche de la ligne médiane :","o":["50%","2/3","90%","10%"],"r":1,"e":"2/3 à gauche, 1/3 à droite. Apex à gauche.","s":0},{"q":"Apex cardiaque :","o":["Postérieur et droit, au 2ᵉ espace intercostal","Antéro-inférieur gauche, au 5ᵉ espace intercostal","Supérieur, sous la clavicule gauche","Au centre, derrière le sternum"],"r":1,"e":"Apex = 5ème EICG ligne médio-claviculaire. Point de palpation du choc apexien. Il est sur la ligne médio-claviculaire.","s":0},{"q":"La base du cœur :","o":["Inférieure, posée sur le centre tendineux du diaphragme","Postéro-supérieure, surtout l'oreillette gauche","Antérieure, derrière le sternum","Latérale gauche, contre le poumon"],"r":1,"e":"Postéro-sup, formée surtout par l'oreillette gauche.","s":0},{"q":"Combien de cavités cardiaques ?","o":["Deux, une oreillette et un ventricule","Trois, deux oreillettes et un ventricule","Quatre, deux oreillettes et deux ventricules","Six, avec les sinus veineux"],"r":2,"e":"2 oreillettes (atria) en arrière + 2 ventricules en avant et en bas.","s":0},{"q":"OD reçoit :","o":["Les quatre veines pulmonaires","Les deux veines caves et le sinus coronaire","L'aorte et ses branches","Le tronc pulmonaire et les artères bronchiques"],"r":1,"e":"VCS + VCI (retour systémique) + sinus coronaire (drainage cardiaque).","s":0},{"q":"OG reçoit :","o":["La veine cave supérieure","Les quatre veines pulmonaires","L'aorte ascendante","Le tronc pulmonaire et le sinus coronaire"],"r":1,"e":"4 veines pulmonaires (sang oxygéné).","s":0},{"q":"VD éjecte vers :","o":["L'aorte, par la valve aortique","Le tronc pulmonaire","La veine cave supérieure","La veine cave inférieure"],"r":1,"e":"VD → tronc pulmonaire (via valve pulmonaire). Il passe par la valve pulmonaire.","s":0},{"q":"VG éjecte vers :","o":["Aorte","Tronc pulmonaire","VCS","VCI"],"r":0,"e":"VG → aorte (via valve aortique). Vers la circulation systémique.","s":0},{"q":"Valve entre OD et VD :","o":["Mitrale, à deux cuspides","Tricuspide, à trois cuspides","Aortique, à trois valvules","Pulmonaire, à trois valvules semi-lunaires"],"r":1,"e":"3 cuspides : antérieure, postérieure, septale.","s":0},{"q":"Valve entre OG et VG :","o":["Tricuspide, à trois cuspides fines","Mitrale, ou bicuspide, à deux cuspides","Aortique, à trois valvules","Pulmonaire, à trois valvules"],"r":1,"e":"Mitrale = bicuspide. 2 cuspides : antérieure et postérieure.","s":0},{"q":"Valves sigmoïdes :","o":["La mitrale et la tricuspide, à cuspides","L'aortique et la pulmonaire, semi-lunaires","Le foramen ovale, chez le fœtus","Le sinus coronaire, à sa valvule"],"r":1,"e":"Aortique + pulmonaire = sigmoïdes (3 valvules semi-lunaires). Chacune a trois valvules.","s":0},{"q":"B1 « toum » correspond à :","o":["La fermeture des valves AV, au début de la systole","La fermeture des valves sigmoïdes, en début de diastole","L'ouverture de la valve mitrale, en diastole","Le pic de pression du VG"],"r":0,"e":"B1 = mitrale + tricuspide. B2 = aortique + pulmonaire.","s":0},{"q":"Paroi du cœur de l'intérieur vers l'extérieur :","o":["Épicarde, myocarde, endocarde","Endocarde, myocarde, épicarde","Péricarde, myocarde, endocarde","Épithélium, conjonctif, muscle"],"r":1,"e":"Endocarde (interne) → myocarde (muscle) → épicarde = feuillet viscéral du péricarde.","s":0},{"q":"Épaisseur du VG vs VD :","o":["Identique, de 3 à 5 mm","VG environ trois fois plus épais que le VD","VD plus épais que le VG","VG moins épais, car il éjecte à basse pression"],"r":1,"e":"VG plus épais car éjecte vers la grande circulation (haute pression). Le VG mesure 12 à 15 mm, le VD 3 à 5 mm.","s":0},{"q":"Péricarde fibreux :","o":["Un sac très extensible, qui suit le cœur","Un sac fibreux peu extensible, qui protège","Un muscle, qui aide la contraction","Un réseau nerveux, qui règle le rythme cardiaque"],"r":1,"e":"Limite la dilatation cardiaque. Adhérent au diaphragme.","s":0},{"q":"Péricarde séreux a :","o":["Un seul feuillet, viscéral","Deux feuillets, pariétal et viscéral","Trois feuillets, fibreux, pariétal et viscéral","Quatre feuillets superposés"],"r":1,"e":"Cavité péricardique entre les 2 feuillets, ~20 mL de liquide. Le feuillet viscéral est l'épicarde.","s":0},{"q":"Tamponnade :","o":["Une maladie virale du myocarde, avec fièvre élevée","Un épanchement rapide dans le péricarde","Une inflammation chronique du péricarde","Une anomalie congénitale du septum"],"r":1,"e":"Compression cardiaque par épanchement péricardique. Urgence : drainage.","s":0},{"q":"Fosse ovale :","o":["Sur le septum interventriculaire, près de l'apex","Un vestige du foramen ovale, sur le septum interatrial","Au niveau valvulaire, sous la mitrale","Sur le myocarde ventriculaire, à la base du cœur, en arrière"],"r":1,"e":"Vestige du shunt fœtal entre OD et OG.","s":0},{"q":"Cuspides valvulaires retenues par :","o":["Des tendons cardiaques isolés","Des cordages tendineux et des muscles papillaires","Des ligaments fibreux de l'anneau","Des nerfs et des fibres de Purkinje, enroulés autour des valves"],"r":1,"e":"Cordages tendineux + muscles papillaires (= piliers) maintiennent les valves AV. Les muscles papillaires sont aussi appelés piliers.","s":0},{"q":"Sillon coronaire :","o":["Sépare les deux ventricules, en avant","Sépare oreillettes et ventricules, avec deux artères","Se situe au sommet du cœur, près de l'apex, et contient l'IVA","N'existe pas chez l'adulte"],"r":1,"e":"Sillon atrio-ventriculaire = sillon coronaire. Il contient l'artère coronaire droite et la circonflexe.","s":0},{"q":"Squelette fibreux du cœur :","o":["Un os intracardiaque, chez l'adulte","Des anneaux fibreux valvulaires, isolants électriques","Du cartilage hyalin, autour des valves","Des vaisseaux nourriciers, disposés en anneaux autour des orifices"],"r":1,"e":"4 anneaux + 2 trigones + septum membraneux. Isole oreillettes-ventricules sauf au faisceau de His. Il isole oreillettes et ventricules, sauf au faisceau de His.","s":0},{"q":"Muscles pectinés :","o":["Dans le ventricule droit","Dans l'oreillette droite, en avant","Dans le ventricule gauche, près de l'apex","Sur le septum interventriculaire"],"r":1,"e":"Aspect côtelé caractéristique de la paroi antérieure de l'OD.","s":0},{"q":"Trabécules charnues :","o":["Dans l'OG","Dans les ventricules","Sur le péricarde","Sur les valves"],"r":1,"e":"Reliefs musculaires de la paroi interne des ventricules.","s":0},{"q":"Sillon interventriculaire antérieur contient :","o":["L'artère coronaire droite","L'artère interventriculaire antérieure","Le sinus coronaire et la grande veine cardiaque","La veine cave inférieure"],"r":1,"e":"IVA (branche de la coronaire gauche) descend dans ce sillon vers l'apex. C'est l'IVA, branche de la coronaire gauche.","s":0},{"q":"Cardiomyocytes :","o":["Muscle lisse","Cellules striées involontaires","Muscle strié squelettique","Cellules épithéliales"],"r":1,"e":"Striées (sarcomères) mais involontaires. Communication par disques intercalaires.","s":0},{"q":"Le cœur bat environ :","o":["20 fois/min","60-100 fois/min au repos","150 fois/min toujours","300 fois/min"],"r":1,"e":"60-100 bpm au repos. < 60 = bradycardie. > 100 = tachycardie.","s":0},{"q":"Double circulation :","o":["Un cœur droit pour tout le corps","Une petite et une grande circulation","Une seule circulation","Trois circulations distinctes"],"r":1,"e":"Cœur droit → poumons (petite). Cœur gauche → tissus (grande). La petite est pulmonaire, la grande systémique.","s":0},{"q":"Trigone fibreux du cœur :","o":["Un ventricule accessoire, chez le fœtus","Un élément fibreux entre les anneaux valvulaires","Une cavité de l'oreillette droite, près du sinus","Un vaisseau coronaire"],"r":1,"e":"2 trigones (droit et gauche) jonctionnent les anneaux fibreux.","s":0},{"q":"Les dimensions approximatives du cœur adulte sont :","o":["12 cm de long, 9 cm de large et 6 cm d'épaisseur","20 cm de long, 12 de large et 8 d'épaisseur","8 cm de long, 6 de large et 4 d'épaisseur","15 cm de long, 10 de large et 5 d'épaisseur"],"r":0,"e":"Il pèse 250 à 350 g et a la forme d'une pyramide triangulaire à sommet antéro-gauche.","s":0},{"q":"Les oreillettes se situent, par rapport aux ventricules :","o":["En arrière et en haut","En avant et en bas","Latéralement","Au même niveau"],"r":0,"e":"Le cœur compte quatre cavités : deux oreillettes postéro-supérieures et deux ventricules antéro-inférieurs.","s":0},{"q":"Le cœur se situe :","o":["Dans le médiastin moyen, entre les deux poumons","Dans le médiastin postérieur, devant l'aorte","Dans le médiastin supérieur, au-dessus de la crosse aortique","Dans la cavité pleurale gauche"],"r":0,"e":"Il est en arrière du sternum et des cartilages costaux 3 à 6, et repose sur le diaphragme.","s":0},{"q":"L'axe long du cœur est oblique :","o":["D'arrière en avant, de haut en bas et de droite à gauche","D'avant en arrière, de bas en haut","Verticalement, de la base vers l'apex, sans aucune inclinaison","Horizontalement, de gauche à droite"],"r":0,"e":"La base est postéro-supérieure et droite, l'apex antéro-inférieur et gauche.","s":0},{"q":"La base du cœur est formée surtout par :","o":["L'oreillette gauche","L'oreillette droite","Le ventricule gauche","Le ventricule droit"],"r":0,"e":"L'apex, lui, est formé par le ventricule gauche et se projette au 5ᵉ espace intercostal gauche sur la ligne médio-claviculaire.","s":0},{"q":"La face sterno-costale du cœur est formée surtout par :","o":["Le ventricule droit","Le ventricule gauche","L'oreillette droite","L'oreillette gauche"],"r":0,"e":"La face diaphragmatique est formée par les deux ventricules, surtout le gauche, et la face pulmonaire gauche par le ventricule gauche.","s":0},{"q":"Le sillon coronaire contient :","o":["L'artère coronaire droite et l'artère circonflexe","L'artère interventriculaire antérieure","L'artère interventriculaire postérieure et la grande veine","Le sinus coronaire, à lui seul"],"r":0,"e":"Il sépare les oreillettes des ventricules ; le sillon interventriculaire antérieur contient l'IVA.","s":0},{"q":"L'oreillette droite reçoit le sang par :","o":["Les deux veines caves et le sinus coronaire","Les quatre veines pulmonaires, oxygénées","L'aorte ascendante et la crosse","Le tronc pulmonaire et ses branches"],"r":0,"e":"Sa paroi interne présente des muscles pectinés en avant et une paroi lisse en arrière.","s":0},{"q":"La fosse ovale est un vestige :","o":["Du foramen ovale fœtal","Du canal artériel","Du canal veineux","De la veine ombilicale"],"r":0,"e":"Elle siège sur le septum interatrial, dans l'oreillette droite.","s":0},{"q":"La paroi interne du ventricule droit présente :","o":["Des trabécules, des piliers et des cordages tendineux","Des muscles pectinés, comme l'oreillette droite","Une paroi entièrement lisse, sans relief","Des villosités, comme l'intestin"],"r":0,"e":"Sa paroi est fine, de 3 à 5 mm, contre 12 à 15 mm pour le ventricule gauche. Les piliers sont les muscles papillaires.","s":0},{"q":"L'oreillette gauche reçoit le sang par :","o":["Deux veines pulmonaires","Quatre veines pulmonaires","La veine cave supérieure","Le sinus coronaire"],"r":1,"e":"Sa paroi est lisse, avec un petit auricule en avant ; elle forme la base du cœur.","s":0},{"q":"La paroi du ventricule gauche est :","o":["Deux fois plus épaisse que celle du ventricule droit","Trois fois plus épaisse que celle du ventricule droit","De même épaisseur que celle du ventricule droit","Plus fine que celle du ventricule droit"],"r":1,"e":"Elle mesure 12 à 15 mm contre 3 à 5 mm, et forme l'apex du cœur.","s":0},{"q":"La valve tricuspide comporte des cuspides :","o":["Antérieure, postérieure et septale","Antérieure et postérieure","Gauche, droite et postérieure","Semi-lunaires"],"r":0,"e":"Elle est maintenue par les cordages tendineux et les piliers ; la valve mitrale n'a que deux cuspides.","s":0},{"q":"La valve aortique comporte des valvules :","o":["Antérieure, postérieure et septale","Gauche, droite et postérieure","Antérieure et postérieure","Au nombre de deux"],"r":1,"e":"Les artères coronaires naissent juste au-dessus de ces valvules, dans les sinus aortiques.","s":0},{"q":"Le bruit B2, « ta », correspond à :","o":["La fermeture des valves atrio-ventriculaires","La fermeture des valves sigmoïdes, en début de diastole","L'ouverture des valves atrio-ventriculaires","La contraction auriculaire, en fin de diastole ventriculaire"],"r":1,"e":"Le bruit B1, « toum », correspond à la fermeture des valves AV et marque le début de la systole.","s":0},{"q":"L'endocarde est :","o":["Continu avec l'endothélium et tapisse cavités et valves","La couche musculaire, faite de cardiomyocytes","La couche externe, avec les vaisseaux","Le feuillet pariétal du péricarde séreux, collé au sac fibreux"],"r":0,"e":"Le myocarde, fait de cardiomyocytes, est la couche la plus épaisse, et l'épicarde correspond au feuillet viscéral du péricarde séreux.","s":0},{"q":"L'épicarde contient :","o":["Les vaisseaux coronaires et la graisse épicardique","Les cardiomyocytes contractiles","Les valves et les cordages tendineux, avec les piliers","Le liquide péricardique"],"r":0,"e":"C'est le feuillet viscéral du péricarde séreux, couche la plus externe de la paroi cardiaque.","s":0},{"q":"Le péricarde fibreux adhère :","o":["Au diaphragme et, en avant, au sternum","Aux poumons, par la plèvre","À l'aorte seule, au-dessus du cœur","Aux côtes, par des ligaments costo-péricardiques"],"r":0,"e":"Sac résistant et peu extensible, il protège et limite la dilatation cardiaque. Les ligaments sterno-péricardiques le relient au sternum.","s":0},{"q":"La cavité péricardique contient environ :","o":["5 mL de liquide séreux","20 mL de liquide séreux","100 mL de liquide séreux","500 mL de liquide séreux"],"r":1,"e":"Ce liquide permet le glissement entre les feuillets pariétal et viscéral du péricarde séreux.","s":0},{"q":"Le squelette fibreux du cœur assure notamment :","o":["La forme des orifices et l'isolement électrique","La contraction des oreillettes","La conduction de l'influx vers les ventricules","La vascularisation du myocarde"],"r":0,"e":"Cet isolement électrique fait du faisceau de His la seule voie de passage entre oreillettes et ventricules. Il sert aussi d'insertion aux fibres myocardiques et aux valves.","s":0},{"q":"Les artères coronaires naissent de :","o":["Du tronc pulmonaire, juste au-dessus de sa valve","De la racine de l'aorte, aux sinus aortiques","De la veine cave supérieure","De la veine cave inférieure"],"r":1,"e":"Premières branches de l'aorte, au-dessus de la valve aortique.","s":1},{"q":"Artère coronaire gauche se divise en :","o":["IVA + marginale droite","IVA + circonflexe","Circonflexe + coronaire droite","Marginale gauche + IVP"],"r":1,"e":"Tronc commun court → IVA (interventriculaire antérieure) + circonflexe.","s":1},{"q":"IVA vascularise :","o":["L'oreillette gauche et la circonflexe","Les faces antérieures, les 2/3 antérieurs du septum et l'apex","Le ventricule droit seul, sur ses 2 faces, et tout l'infundibulum","La paroi postéro-inférieure des ventricules"],"r":1,"e":"IVA = la « widow maker » → infarctus antérieur massif. Ce sont les faces antérieures des deux ventricules.","s":1},{"q":"Dominance droite (%) :","o":["30%","50%","70-80%","95%"],"r":2,"e":"70-80% dominance droite (IVP naît de la coronaire droite).","s":1},{"q":"Sinus coronaire se draine dans :","o":["Veine porte","Oreillette droite","VCI","OG"],"r":1,"e":"Sinus coronaire = drainage veineux principal cardiaque, débouche dans l'OD.","s":1},{"q":"Pacemaker physiologique du cœur :","o":["Le nœud atrio-ventriculaire","Le nœud sinusal, de Keith et Flack","Le faisceau de His et ses deux branches","Le réseau de Purkinje, distal"],"r":1,"e":"Nœud sinusal dans la paroi OD, près VCS. 60-100/min.","s":1},{"q":"Nœud AV :","o":["Dans le ventricule gauche, près de l'apex du cœur","Au plancher de l'oreillette droite, près du septum","Sur la valve aortique, en avant","Dans le sinus coronaire, en arrière"],"r":1,"e":"Nœud d'Aschoff-Tawara. Ralentit l'influx (~0,1 s).","s":1},{"q":"Faisceau de His :","o":["Une voie d'innervation parasympathique","La seule voie de passage du squelette fibreux","Une artère coronaire, branche de la circonflexe gauche","Une branche du nerf vague"],"r":1,"e":"His traverse le squelette fibreux (isolant électrique).","s":1},{"q":"Fréquence du nœud AV (relais) :","o":["100-150/min","40-60/min","10-20/min","200/min"],"r":1,"e":"Hiérarchie : sinusal 60-100 > AV 40-60 > His/Purkinje 20-40.","s":1},{"q":"Cycle cardiaque dure :","o":["0,1 s, à 75 bpm","Environ 0,8 s, à 75 bpm","2 s, à 75 bpm, au repos complet","5 s, à 75 bpm"],"r":1,"e":"~0,8 s. Systole 0,3 s + diastole 0,5 s.","s":1},{"q":"Phase d'éjection systolique :","o":["Les valves AV restent ouvertes pendant toute la phase","Les valves sigmoïdes s'ouvrent","C'est une phase de relaxation","C'est la phase de remplissage"],"r":1,"e":"Ouverture des sigmoïdes → éjection du sang vers aorte/tronc pulmonaire.","s":1},{"q":"Parasympathique du cœur :","o":["Tachycardisant, par le nerf vague","Bradycardisant, par le nerf vague","Sans aucun effet sur la fréquence cardiaque","Vasoconstricteur des coronaires"],"r":1,"e":"Vague → ralentit le cœur. Sympathique → accélère. Le nerf vague est le X.","s":1},{"q":"Médiateur du sympathique cardiaque :","o":["Acétylcholine","Noradrénaline","Sérotonine","Dopamine"],"r":1,"e":"Sympa = noradrénaline (β1). Para = acétylcholine.","s":1},{"q":"Origine sympathique cardiaque :","o":["C1-C4","T1-T4","L1-L4","S1-S4"],"r":1,"e":"T1-T4 (parfois jusqu'à T5).","s":1},{"q":"Douleur de l'infarctus est portée par :","o":["Le nerf vague, ou X","Les fibres sympathiques de T1 à T4","Le nerf phrénique, de C3 à C5","Le nerf pudendal, de S2 à S4, par voie sacrée"],"r":1,"e":"Sympathique T1-T4. Projection à bras gauche, mâchoire.","s":1},{"q":"Obstruction IVA donne :","o":["Un infarctus inférieur, du VD","Un infarctus antérieur, du VG et du septum","Un infarctus du VD, avec un bloc atrio-ventriculaire","Une hypertension artérielle"],"r":1,"e":"IVA → paroi antérieure du VG + septum antérieur.","s":1},{"q":"Obstruction coronaire droite donne :","o":["Un infarctus antérieur, par atteinte de l'IVA","Un infarctus inférieur, avec un risque de BAV","Un infarctus latéral, de la paroi gauche","Une embolie pulmonaire, avec une détresse respiratoire aiguë"],"r":1,"e":"CD → paroi inférieure + nœud AV (BAV).","s":1},{"q":"Fibrillation auriculaire =","o":["Un arrêt cardiaque, avec une perte de connaissance","Une activité électrique anarchique des oreillettes","Un blocage de la conduction AV","Une tachycardie ventriculaire"],"r":1,"e":"Risque : embolies (formation de caillots auriculaires).","s":1},{"q":"Tachycardie ventriculaire / fibrillation V :","o":["Sans gravité, chez le sujet jeune","Une urgence vitale, traitée par choc électrique","Bénigne, si elle est brève","Chronique, traitée par des médicaments au long cours"],"r":1,"e":"FV = arrêt circulatoire. Choc électrique externe (DEA) sauve. Le choc électrique externe se fait par DEA.","s":1},{"q":"Bloc atrio-ventriculaire :","o":["Une anomalie du muscle ventriculaire","Une altération de la conduction au nœud AV","Un arrêt cardiaque, sans pouls","Une fibrillation des oreillettes, la FA"],"r":1,"e":"Conduction OD → VG altérée. BAV grade 1, 2, 3 (complet). BAV3 = pacemaker.","s":1},{"q":"Grande veine cardiaque :","o":["Dans le sillon coronaire droit, avec la coronaire droite","Avec l'IVA puis la circonflexe","Dans l'atrium gauche, contre la paroi","Vers le tronc pulmonaire et la VCS"],"r":1,"e":"Tributaire majeure du sinus coronaire. Elle rejoint le sinus coronaire.","s":1},{"q":"Veines de Thébésius :","o":["Des veines cervicales, du cou","Des petites veines qui s'ouvrent dans les cavités","Des veines abdominales, du foie","Des veines disparues à la naissance, comme le canal artériel"],"r":1,"e":"Veines « minimes » s'ouvrant directement dans les cavités (court-circuit).","s":1},{"q":"Signes typiques d'infarctus :","o":["Une toux et une dyspnée, sans douleur","Une douleur constrictive, des sueurs et un sus-décalage ST","Des vomissements isolés, sans douleur","Une fièvre élevée et un souffle au cœur, puis un ECG normal"],"r":1,"e":"Douleur typique + signes vagaux + ECG (sus-ST). La douleur irradie souvent.","s":1},{"q":"Réseau de Purkinje :","o":["Un réseau de fibres sympathiques","Des fibres conductrices terminales du myocarde","Des veines cardiaques, minimes","Des artères nourricières du myocarde, sous l'endocarde"],"r":1,"e":"Fibres distribuant l'influx dans le myocarde ventriculaire.","s":1},{"q":"Diastole comporte :","o":["L'éjection du sang dans l'aorte","La relaxation iso-volumétrique et le remplissage","La contraction ventriculaire","Une pause, sans aucun mouvement de sang ni de valve"],"r":1,"e":"Diastole = relaxation iso + remplissage passif puis actif (contraction auriculaire).","s":1},{"q":"Système nerveux entérique des plexus cardiaques :","o":["Aucun plexus, l'innervation venant directement du tronc","Des plexus cardiaques, superficiel et profond","Le plexus brachial, au cou","Le plexus solaire, sous le diaphragme"],"r":1,"e":"Plexus cardiaques autour de l'aorte ascendante et de la crosse. Ils sont autonomes.","s":1},{"q":"Drainage lymphatique cardiaque :","o":["Les ganglions de la veine porte et du hile du foie","Les ganglions trachéo-bronchiques et médiastinaux","Les ganglions inguinaux","Les ganglions cervicaux postérieurs"],"r":1,"e":"2 troncs lymphatiques : gauche → trachéo-bronchiques, droit → médiastinaux antérieurs.","s":1},{"q":"Phase iso-volumétrique :","o":["Le volume change, la pression reste stable","Le volume est constant, la pression change","Il n'existe aucune phase iso-volumétrique","La pression reste constante, le volume aussi"],"r":1,"e":"Phase iso-volumétrique : toutes valves fermées, pression monte (systole) ou baisse (diastole).","s":1},{"q":"Co-dominance coronaire :","o":["50%","5-10%","30%","Impossible"],"r":1,"e":"Co-dominance = IVP partagée entre CD et Cx. 5-10%.","s":1},{"q":"ECG sus-décalage ST signe :","o":["Une hypertension artérielle","Un infarctus du myocarde en cours","Une fibrillation auriculaire","Une hypoglycémie sévère"],"r":1,"e":"STEMI = sus-décalage ST = infarctus en cours. C'est le STEMI.","s":1},{"q":"Les artères coronaires naissent :","o":["Des sinus aortiques, juste au-dessus de la valve","Du tronc pulmonaire, juste au-dessus de la valve pulmonaire","De la crosse aortique, au-dessus du cœur","Du sinus coronaire, en arrière"],"r":0,"e":"Elles assurent la vascularisation nourricière du cœur.","s":1},{"q":"L'artère du nœud sinusal naît de la coronaire droite dans :","o":["30 % des cas","60 % des cas","80 % des cas","100 % des cas"],"r":1,"e":"La coronaire droite donne aussi l'artère marginale droite, l'IVP dans 70 à 80 % des cas et l'artère du nœud atrio-ventriculaire.","s":1},{"q":"La coronaire droite vascularise :","o":["Les cavités droites, la paroi inférieure, le nœud AV","La paroi latérale du ventricule gauche","Les deux tiers antérieurs du septum, avec l'IVA","L'oreillette gauche et la circonflexe"],"r":0,"e":"Elle chemine dans le sillon coronaire droit. Elle irrigue souvent aussi le nœud sinusal et la partie postéro-inférieure du septum.","s":1},{"q":"L'artère circonflexe vascularise :","o":["L'oreillette gauche et la paroi latérale du VG","Le septum antérieur, avec l'IVA","L'apex et la pointe du ventricule droit, en avant","Le ventricule droit et l'infundibulum"],"r":0,"e":"Elle chemine dans le sillon coronaire gauche ; l'IVA vascularise la face antérieure des deux ventricules, les deux tiers antérieurs du septum et l'apex.","s":1},{"q":"La dominance gauche, où l'IVP naît de la circonflexe, concerne :","o":["70 à 80 % des sujets","10 à 15 %","5 à 10 %","50 %"],"r":1,"e":"La dominance droite concerne 70 à 80 % des sujets et la co-dominance 5 à 10 %.","s":1},{"q":"La grande veine cardiaque accompagne :","o":["L'IVA puis la circonflexe","L'IVP","La coronaire droite","La marginale droite"],"r":0,"e":"La veine cardiaque moyenne chemine dans le sillon interventriculaire postérieur et la petite veine cardiaque au bord droit du cœur.","s":1},{"q":"La veine oblique de l'oreillette gauche porte aussi le nom de :","o":["Veine de Marshall","Veine de Thébésius","Grande veine cardiaque","Veine cardiaque moyenne"],"r":0,"e":"Elle est tributaire du sinus coronaire, comme les grande, moyenne et petite veines cardiaques.","s":1},{"q":"Les veines de Thébésius, ou veines minimes :","o":["Se drainent directement dans les cavités cardiaques","Se jettent dans le sinus coronaire, en arrière","Rejoignent la veine cave supérieure","Sont des artères nourricières"],"r":0,"e":"Les veines antérieures du cœur se jettent, elles, directement dans l'oreillette droite.","s":1},{"q":"Le nœud sinusal est aussi appelé nœud :","o":["De Keith et Flack","D'Aschoff-Tawara","De His","De Purkinje"],"r":0,"e":"Situé dans la paroi de l'oreillette droite près de l'abouchement de la veine cave supérieure, c'est le pacemaker physiologique à 60-100/min.","s":1},{"q":"Le nœud atrio-ventriculaire est aussi appelé nœud :","o":["De Keith et Flack","D'Aschoff-Tawara","De Marshall","De Thébésius"],"r":1,"e":"Situé dans le plancher de l'oreillette droite près du septum interatrial, il ralentit l'influx d'environ 0,1 s pour permettre le remplissage ventriculaire.","s":1},{"q":"Le faisceau de His est :","o":["La seule voie de passage du squelette fibreux","Une des nombreuses voies de conduction","Situé dans l'oreillette gauche","Le pacemaker principal, à 60 à 100 battements par minute"],"r":0,"e":"Il se divise en branches droite et gauche, prolongées par le réseau de Purkinje dans le myocarde ventriculaire.","s":1},{"q":"La fréquence d'échappement du faisceau de His et du réseau de Purkinje est de :","o":["60 à 100/min","40 à 60/min","20 à 40/min","10 à 20/min"],"r":2,"e":"Le nœud sinusal bat à 60-100/min et le nœud AV à 40-60/min : c'est la hiérarchie des pacemakers.","s":1},{"q":"La systole dure environ :","o":["0,3 seconde","0,5 seconde","0,8 seconde","1 seconde"],"r":0,"e":"La diastole dure environ 0,5 seconde, pour un cycle complet de 0,8 seconde à 75 battements par minute.","s":1},{"q":"Lors de la contraction iso-volumétrique :","o":["Toutes les valves sont fermées et la pression monte","Les valves AV sont ouvertes et le ventricule se remplit","Les sigmoïdes sont ouvertes","Le sang est expulsé vers l'aorte"],"r":0,"e":"L'éjection suit, avec l'ouverture des valves sigmoïdes. Les valves AV et sigmoïdes sont fermées.","s":1},{"q":"Le remplissage ventriculaire se fait :","o":["Passivement, puis activement par la systole auriculaire","Uniquement activement, par la systole des oreillettes","Uniquement passivement, par gravité","Pendant la systole ventriculaire"],"r":0,"e":"Il suit la relaxation iso-volumétrique, où les sigmoïdes se ferment en produisant B2.","s":1},{"q":"Le médiateur du parasympathique cardiaque est :","o":["L'acétylcholine","La noradrénaline","L'adrénaline","La dopamine"],"r":0,"e":"Il exerce un effet bradycardisant, diminue la contractilité auriculaire et ralentit la conduction AV.","s":1},{"q":"Le sympathique cardiaque naît des niveaux :","o":["C1-C4","T1-T4","T5-T9","L1-L3"],"r":1,"e":"Son médiateur est la noradrénaline ; il augmente la fréquence, la contractilité et la conduction AV.","s":1},{"q":"La douleur cardiaque est véhiculée par :","o":["Les fibres sympathiques de T1 à T4","Le nerf vague, ou dixième nerf","Le nerf phrénique, de C3 à C5, par le diaphragme","Les fibres parasympathiques sacrées"],"r":0,"e":"Le nerf vague véhicule, lui, les réflexes comme le baroréflexe. D'où la projection dans le bras gauche et la mâchoire.","s":1},{"q":"Le drainage lymphatique du cœur se fait par :","o":["Deux troncs, trachéo-bronchique et médiastinal","Un tronc unique, vers le canal thoracique et la citerne","Les ganglions axillaires gauches","Les ganglions cœliaques, sous le diaphragme"],"r":0,"e":"Ce sont les deux troncs principaux décrits par le cours. Le gauche va aux ganglions trachéo-bronchiques, le droit aux médiastinaux antérieurs.","s":1},{"q":"L'obstruction de l'artère circonflexe entraîne un infarctus :","o":["De la paroi antérieure du ventricule gauche","De la paroi latérale du ventricule gauche","Du ventricule droit","Du septum antérieur"],"r":1,"e":"L'IVA touche la paroi antérieure et le septum antérieur, la coronaire droite le ventricule droit et la paroi postéro-inférieure du VG.","s":1},{"q":"3 tuniques des vaisseaux :","o":["Externe, moyenne, profonde","Intima, média, adventice","Endothélium, mésothelium, séreuse","Cortex, médulla, capsule"],"r":1,"e":"3 tuniques universelles (sauf capillaires).","s":2},{"q":"Vasa vasorum :","o":["Des veines lymphatiques des gros troncs","Des vaisseaux nourriciers de la paroi des gros vaisseaux","Des capillaires pulmonaires, autour des alvéoles et des bronches","Des glandes de la paroi aortique"],"r":1,"e":"Dans l'adventice des gros vaisseaux. Ils siègent dans l'adventice.","s":2},{"q":"Aorte ascendante donne :","o":["Carotides","Artères coronaires","Iliaques","Mésentériques"],"r":1,"e":"Coronaires droite et gauche aux sinus aortiques.","s":2},{"q":"Crosse de l'aorte donne (dans l'ordre) :","o":["La carotide gauche, le TABC, puis la subclavière gauche","Le TABC, la carotide gauche, puis la subclavière gauche","Les deux carotides, puis l'aorte descendante","Aucune branche, avant le diaphragme"],"r":1,"e":"3 troncs supra-aortiques. TABC se divise en carotide droite + subclavière droite. La carotide gauche est la carotide commune gauche.","s":2},{"q":"Carotide commune bifurque en :","o":["Vertébrale + cervicale","Carotide externe + interne","Faciale + linguale","Cervicale + thyroïdienne"],"r":1,"e":"Au niveau C4 (cartilage thyroïde). Externe = face. Interne = cerveau.","s":2},{"q":"Aorte abdominale se termine à :","o":["En L2, au niveau des artères rénales","En L3, sous l'ombilic","En L4, par la bifurcation iliaque","En S1, dans le petit bassin"],"r":2,"e":"L4 → 2 iliaques communes.","s":2},{"q":"VCS draine :","o":["La partie sous-diaphragmatique du corps","La partie sus-diaphragmatique du corps","Les membres inférieurs et le petit bassin, en entier","Le pelvis et les viscères"],"r":1,"e":"VCS = retour veineux supérieur. VCI = inférieur. Elle draine la tête, le cou, les membres supérieurs et le thorax.","s":2},{"q":"VCI traverse le diaphragme à :","o":["T10","T8","T12","L2"],"r":1,"e":"V8-Œ10-A12 : VCI à T8, œsophage à T10, aorte à T12.","s":2},{"q":"Système azygos :","o":["Pelvien, il draine le petit bassin","Thoracique, il draine les veines intercostales","Cervical, il draine le cou","Pulmonaire, il draine les alvéoles et la plèvre viscérale"],"r":1,"e":"Azygos + hémi-azygos. Voie de suppléance en cas d'obstruction VCS/VCI.","s":2},{"q":"Veine porte se forme par :","o":["La réunion des deux veines caves","La mésentérique supérieure et le tronc spléno-mésaraïque","La réunion des veines hépatiques, dans le foie droit","La réunion des deux veines rénales"],"r":1,"e":"En arrière du col pancréatique. Elle se forme en arrière du col du pancréas.","s":2},{"q":"Anastomose porto-cave œsophagienne donne :","o":["Des varices œsophagiennes","Des hémorroïdes, par la veine rectale supérieure","Une tête de méduse ombilicale","Une ascite, dans le péritoine"],"r":0,"e":"HTP → dilatation des veines œsophagiennes (anastomose porto-cave).","s":2},{"q":"Petite circulation :","o":["À haute pression, comme la grande circulation","À basse pression, vers les poumons","Systémique, vers les tissus","Splanchnique, vers les viscères"],"r":1,"e":"Cœur droit → poumons → cœur gauche. À basse pression.","s":2},{"q":"Tronc pulmonaire naît de :","o":["VG","VD","OG","Aorte"],"r":1,"e":"VD → tronc pulmonaire → APD + APG.","s":2},{"q":"Particularité des artères pulmonaires :","o":["Elles transportent du sang oxygéné, comme l'aorte","Elles transportent du sang désoxygéné","Elles sont identiques aux autres artères","Elles ne contiennent pas de sang"],"r":1,"e":"Exception unique : artères transportent sang désoxygéné. Ce sont les seules artères dans ce cas.","s":2},{"q":"Veines pulmonaires :","o":["Deux, une par poumon, vers l'oreillette gauche","Quatre, deux par poumon","Six, trois par poumon","Huit, quatre par poumon"],"r":1,"e":"4 veines pulmonaires → OG. Transportent sang oxygéné.","s":2},{"q":"Canal artériel (fœtal) devient :","o":["Ligament rond","Ligament artériel","Ligament veineux","Reste actif"],"r":1,"e":"Court-circuit pulmonaire fœtal. Se ferme à la naissance.","s":2},{"q":"Foramen ovale (fœtal) devient :","o":["Ligament artériel","Fosse ovale","VCS","Septum musculaire"],"r":1,"e":"Shunt fœtal OD-OG. Se ferme à la naissance → fosse ovale.","s":2},{"q":"Canal d'Arantius (fœtal) :","o":["Court-circuite les poumons","Court-circuite le foie","Court-circuite le rein","Court-circuite l'estomac"],"r":1,"e":"Devient le ligament veineux. Il va de la veine ombilicale à la veine cave inférieure.","s":2},{"q":"2 artères ombilicales (fœtus) :","o":["Sang oxygéné fœtus → placenta","Sang désoxygéné fœtus → placenta","Sang placenta → fœtus","Inexistantes"],"r":1,"e":"2 artères ombilicales → placenta. 1 veine ombilicale ← placenta (oxygéné).","s":2},{"q":"Veine ombilicale post-natale devient :","o":["Ligament artériel","Ligament rond du foie","Fosse ovale","Ligament veineux"],"r":1,"e":"Veine ombilicale → ligament rond du foie (dans le ligament falciforme).","s":2},{"q":"Tronc cœliaque naît à :","o":["T10","T12","L2","L4"],"r":1,"e":"T12, juste sous le hiatus aortique.","s":2},{"q":"AMS naît à :","o":["T10","T12","L1","L3"],"r":2,"e":"L1. AMI naît à L3.","s":2},{"q":"Artère vertébrale rejoint :","o":["La carotide externe, au niveau de la bifurcation du cou","Le tronc basilaire, puis le polygone de Willis","L'aorte, par la crosse aortique","La veine cave supérieure"],"r":1,"e":"2 vertébrales fusionnent → tronc basilaire → polygone de Willis.","s":2},{"q":"Artère thoracique interne naît de :","o":["L'aorte thoracique descendante","L'artère subclavière","La carotide commune, à la base du cou","L'artère axillaire"],"r":1,"e":"Branche de la subclavière. Importante pour pontages coronaires.","s":2},{"q":"Pression sanguine systémique normale :","o":["80/40","120/80 mmHg","200/100","10/5"],"r":1,"e":"Systolique 120, diastolique 80 mmHg.","s":2},{"q":"Artères élastiques :","o":["Toutes les petites artères, distales","Les grosses artères, comme l'aorte","Les artérioles terminales","Les capillaires sanguins"],"r":1,"e":"Grosses artères = élastiques (amortissent le pic systolique). Les troncs supra-aortiques en font aussi partie.","s":2},{"q":"Artérioles :","o":["Servent de réservoirs de sang, à basse pression","Règlent les résistances périphériques","Assurent les échanges gazeux","Assurent le drainage lymphatique"],"r":1,"e":"Vasoconstriction/dilatation → PAR (pression artérielle régulée).","s":2},{"q":"Capillaires :","o":["Ont les trois tuniques, comme les grosses artères","N'ont qu'un endothélium, pour les échanges","Sont musculaires, et contractiles","Sont les plus gros vaisseaux"],"r":1,"e":"Endothélium seul → échanges gazeux et nutritifs.","s":2},{"q":"Veines vs artères :","o":["Elles ont des médias identiques","Média plus fine, lumière plus large et valves","Les veines ont une paroi plus épaisse et plus musclée","Il n'y a aucune différence, en pratique"],"r":1,"e":"Veines : paroi fine + valves anti-reflux + capacitance. La média plus fine est celle des veines.","s":2},{"q":"Anastomose porto-cave rétro-péritonéale :","o":["Plexus de Bauhin","Veines de Retzius","Veines de Mascagni","Plexus de Marshall"],"r":1,"e":"Veines de Retzius = anastomoses profondes en cas d'HTP.","s":2},{"q":"L'intima des vaisseaux est limitée par :","o":["La limitante élastique interne","La membrane basale","L'adventice et ses vasa vasorum, en dehors","La média musculaire"],"r":0,"e":"Elle comprend l'endothélium et le tissu conjonctif sous-jacent.","s":2},{"q":"La média est composée de :","o":["Du muscle lisse et des fibres élastiques","Du tissu conjonctif fibreux et lâche","De l'endothélium, en une seule couche","Des vasa vasorum et des nerfs"],"r":0,"e":"Très épaisse dans les artères, elle est plus fine dans les veines.","s":2},{"q":"Les vasa vasorum se situent dans :","o":["L'intima","La média","L'adventice","La lumière"],"r":2,"e":"Ils assurent la vascularisation propre des gros vaisseaux.","s":2},{"q":"Les artères élastiques, comme l'aorte, ont pour rôle :","o":["D'amortir le pic systolique, par l'élastine","De réguler les résistances périphériques","D'assurer les échanges, avec les tissus","De distribuer le sang à chaque organe"],"r":0,"e":"Les artères musculaires assurent la distribution et les artérioles la régulation des résistances périphériques.","s":2},{"q":"L'aorte thoracique descendante s'étend :","o":["De T4 à T12","De T1 à T8","De T8 à L1","De T12 à L4"],"r":0,"e":"Elle traverse le diaphragme par le hiatus aortique ; l'aorte abdominale va de T12 à L4.","s":2},{"q":"L'aorte ascendante donne :","o":["Les artères coronaires","Les troncs supra-aortiques","Les artères rénales","Le tronc cœliaque"],"r":0,"e":"Elle va du ventricule gauche à la naissance du tronc brachio-céphalique.","s":2},{"q":"Les artères rénales naissent de l'aorte abdominale au niveau :","o":["De T12","De L1-L2","De L3","De L4"],"r":1,"e":"Le tronc cœliaque naît en T12-L1, l'AMS en L1, l'AMI en L3 et la bifurcation iliaque se fait en L4.","s":2},{"q":"Le tronc artériel brachio-céphalique se divise en :","o":["Carotide commune droite et subclavière droite","Carotide commune gauche et subclavière gauche","Deux carotides communes","Deux subclavières"],"r":0,"e":"Les carotide commune gauche et subclavière gauche naissent, elles, directement de la crosse aortique.","s":2},{"q":"La carotide commune bifurque au niveau :","o":["Au niveau de C2, sous la mandibule","Au bord du cartilage thyroïde, en C4","Au niveau de C6, sous le cricoïde","Au niveau de C7, au-dessus de la clavicule gauche"],"r":1,"e":"Elle donne la carotide externe pour la face, le cou et le cuir chevelu, et la carotide interne pour le cerveau.","s":2},{"q":"L'artère vertébrale est une branche de :","o":["La carotide interne","L'artère subclavière","La crosse aortique","Le tronc brachio-céphalique"],"r":1,"e":"Elle rejoint le tronc basilaire et le polygone de Willis ; la subclavière donne aussi l'artère thoracique interne.","s":2},{"q":"La veine cave supérieure est formée par :","o":["La réunion des deux troncs brachio-céphaliques","La réunion des deux veines iliaques communes","La veine azygos, à elle seule","Les deux veines jugulaires, seules"],"r":0,"e":"Elle draine la partie sus-diaphragmatique du corps, reçoit la veine azygos et se jette dans l'oreillette droite.","s":2},{"q":"La veine cave inférieure naît :","o":["De la réunion des deux iliaques communes, en L5","De la réunion des deux veines rénales, en L1","Des veines hépatiques, sous le diaphragme","En L2, de la réunion des veines lombaires ascendantes"],"r":0,"e":"Elle monte à droite de l'aorte et traverse le diaphragme en T8.","s":2},{"q":"Le système azygos comprend :","o":["L'azygos à droite et deux hémi-azygos à gauche","L'azygos seule, à droite","Deux veines azygos symétriques, une de chaque côté","L'azygos et la veine porte"],"r":0,"e":"Il draine les veines intercostales et pariétales du thorax et constitue une voie de suppléance en cas d'obstruction cave. À gauche, ce sont l'hémi-azygos et l'hémi-azygos accessoire.","s":2},{"q":"La circulation pulmonaire est caractérisée par :","o":["Une basse pression, dédiée aux échanges gazeux","Une haute pression, comme la grande circulation","Un rôle nourricier pour le poumon","Un sang oxygéné dans les artères et désoxygéné dans les veines"],"r":0,"e":"Les artères pulmonaires sont les seules artères du corps à transporter du sang désoxygéné.","s":2},{"q":"L'artère pulmonaire droite :","o":["Passe sous la crosse aortique","Passe au-dessus de la crosse","Naît du ventricule gauche","Est absente"],"r":0,"e":"Le tronc pulmonaire naît du ventricule droit, à gauche de l'aorte ascendante, avant de se diviser.","s":2},{"q":"Les veines pulmonaires sont au nombre de :","o":["Deux, une par poumon, très courtes","Quatre, une haute et une basse par poumon","Six, trois par poumon, une par lobe","Une seule, médiane, pour les deux poumons"],"r":1,"e":"Elles se jettent dans l'oreillette gauche et transportent du sang oxygéné.","s":2},{"q":"Le canal artériel fœtal relie :","o":["L'aorte au tronc pulmonaire","Les deux oreillettes","La veine ombilicale à la veine cave","L'aorte à la veine porte"],"r":0,"e":"Il se ferme à la naissance et devient le ligament artériel ; sa persistance constitue une cardiopathie congénitale.","s":2},{"q":"Le tronc spléno-mésaraïque, composant de la veine porte, réunit :","o":["La veine splénique et la veine mésentérique inférieure","Les deux veines mésentériques, supérieure et inférieure","La veine splénique et la mésentérique supérieure","Les veines gastriques, gauche et droite, et la veine cystique"],"r":0,"e":"Il draine la rate et le côlon gauche ; la VMS draine l'intestin grêle et le côlon droit.","s":2},{"q":"La veine porte monte dans le pédicule hépatique :","o":["Avec l'artère hépatique et la voie biliaire principale","Seule, sans aucun autre élément","Avec la veine cave inférieure et le canal thoracique, en arrière","Avec les lymphatiques uniquement"],"r":0,"e":"Elle entre dans le foie par le hile ; le foie reçoit 75 % de son sang par elle et 25 % par l'artère hépatique.","s":2},{"q":"L'aorte abdominale se termine :","o":["En bifurquant en deux iliaques communes, en L4","En T12, en traversant l'orifice aortique du diaphragme","En L2, au niveau des artères rénales","En S1, dans le petit bassin"],"r":0,"e":"Elle donne auparavant le tronc cœliaque, l'AMS, les rénales, les gonadiques et l'AMI.","s":2},{"q":"Le système lymphatique inclut :","o":["Les vaisseaux et la lymphe, sans les organes","Des vaisseaux, des organes lymphoïdes et la lymphe","Les ganglions et la rate, seuls","Le seul canal thoracique"],"r":1,"e":"3 composants : réseau vasculaire + organes lymphoïdes + lymphe circulante.","s":3},{"q":"Volume de lymphe drainé/jour :","o":["100 mL","500 mL","2-4 L","20 L"],"r":2,"e":"2-4 L/jour réabsorbés vers le système veineux.","s":3},{"q":"Le canal thoracique mesure :","o":["5 cm","15 cm","36-45 cm","1 m"],"r":2,"e":"36-45 cm × 1-5 mm. Le plus grand tronc lymphatique.","s":3},{"q":"Citerne du chyle se situe à :","o":["T8","T12","L2","L5"],"r":2,"e":"L2. Origine du canal thoracique (fusion des troncs lombaires et intestinal).","s":3},{"q":"Canal thoracique se termine à :","o":["Directement dans la veine cave supérieure","Au confluent jugulo-subclavier gauche","Dans l'aorte thoracique, au niveau de la crosse","Dans la veine cave inférieure"],"r":1,"e":"Angle veineux gauche = jugulaire interne + subclavière gauches.","s":3},{"q":"Le canal lymphatique droit draine :","o":["Tout le corps, sans exception","L'hémicorps supéro-droit, uniquement","Les membres inférieurs","Le pelvis et les viscères abdominaux, à droite"],"r":1,"e":"Droit : tête/cou droits + MS droit + hémi-thorax droit. Tout le reste = canal thoracique.","s":3},{"q":"Tissus sans drainage lymphatique :","o":["Les reins et les voies urinaires, avec la vessie","Le système nerveux central et la cornée","La peau, derme compris","Le foie et la vésicule"],"r":1,"e":"SNC, cartilages, cornée, épiderme, moelle osseuse n'ont pas de capillaires lymphatiques. Les cartilages, l'os compact et l'épiderme en sont aussi dépourvus.","s":3},{"q":"Chylifères :","o":["Des vaisseaux sanguins de l'intestin","Des capillaires lymphatiques des villosités","Des veines mésentériques du grêle","Des artères des villosités, qui apportent les graisses au foie"],"r":1,"e":"Transportent les chylomicrons (graisses absorbées). Aspect lactescent. Ils transportent les graisses.","s":3},{"q":"Composition de la lymphe :","o":["Plus riche en protéines que le plasma","Proche du plasma, avec moins de protéines","Riche en hématies, comme le sang veineux du membre","Identique au sang total"],"r":1,"e":"Lymphe ~ plasma mais moins de protéines. Riche en lymphocytes.","s":3},{"q":"Lymphangions :","o":["Des ganglions, en série","Des segments contractiles entre deux valves","Des vaisseaux artériels","Des capillaires de 2 à 3 µm, sans paroi musculaire"],"r":1,"e":"Unités contractiles propulsant la lymphe entre 2 valves.","s":3},{"q":"Drainage lymphatique manuel exploite :","o":["Une pression forte, pour vider vite","Une pression douce dans le sens du drainage","Des vibrations rapides et superficielles","Un étirement intense de la peau"],"r":1,"e":"DLM = pression douce, lente, jamais douloureuse. Elle stimule les lymphangions.","s":3},{"q":"Mini-valves des capillaires lymphatiques :","o":["Empêchent l'entrée des liquides, au repos","Laissent entrer mais empêchent la sortie","Fonctionnent dans les deux sens","N'existent pas chez l'adulte"],"r":1,"e":"Jonctions chevauchantes des cellules endothéliales = valves unidirectionnelles d'entrée.","s":3},{"q":"Capillaires lymphatiques sont :","o":["Moins perméables que les capillaires sanguins","Plus perméables que les sanguins","Identiques aux capillaires sanguins","Imperméables aux protéines"],"r":1,"e":"Très perméables → drainage de molécules grosses (protéines, débris). Ils laissent passer protéines, débris et microbes.","s":3},{"q":"Système lymphatique fait partie :","o":["Uniquement du système circulatoire","Des systèmes circulatoire et immunitaire","Uniquement du système immunitaire","Du système nerveux autonome, par ses plexus"],"r":1,"e":"Double fonction : drainage + défense immunitaire.","s":3},{"q":"Forces motrices de la lymphe :","o":["Le cœur, par sa seule contraction, comme pour le sang","Les lymphangions, les muscles, la respiration et le pouls","La pression artérielle, seule","Aucune, la lymphe stagnant"],"r":1,"e":"Multiples mécanismes auxiliaires. Pas de pompe centrale comme le cœur.","s":3},{"q":"Direction de la lymphe :","o":["Bidirectionnelle, selon la position","Unidirectionnelle, des tissus vers les veines","Circulaire et fermée, comme le sang","Stagnante, sauf lors de l'effort physique intense et prolongé"],"r":1,"e":"Toujours des tissus vers le sang. Valves empêchent le reflux.","s":3},{"q":"Lymphe = couleur :","o":["Rouge, comme le sang","Claire et jaunâtre","Bleue, comme les veines","Verte, comme la bile"],"r":1,"e":"Claire/jaunâtre. Chyle = lactescent (riche en lipides). Elle devient lactescente après un repas.","s":3},{"q":"Troncs lymphatiques principaux :","o":["Deux troncs, à droite et à gauche","Cinq troncs, dont jugulaire et intestinal","Dix troncs, un par segment du corps, symétriques","Aucun tronc, les vaisseaux allant au cœur"],"r":1,"e":"5 grands troncs convergent vers les voies terminales. Ce sont les troncs jugulaire, subclavier, broncho-médiastinal, lombaire et intestinal.","s":3},{"q":"Œdème lymphatique survient :","o":["Avec un drainage lymphatique normal","Par défaillance du drainage lymphatique","Par une hypotension artérielle prolongée, au lit","Par une hyperthermie, avec fièvre"],"r":1,"e":"Accumulation de lymphe → œdème ferme, peu mobilisable.","s":3},{"q":"Vitesse de la lymphe :","o":["Plus rapide que celle du sang veineux, au repos","Beaucoup plus lente que celle du sang","Identique à celle du sang","Quasi instantanée, en continu"],"r":1,"e":"Circulation lymphatique très lente vs circulation sanguine.","s":3},{"q":"Œdème par défaut de drainage :","o":["Il prend le godet, nettement","Il ne prend pas ou peu le godet","Il disparaît la nuit, en position couchée","Il est symétrique, aux deux membres inférieurs"],"r":1,"e":"Œdème ferme, ne prend pas le godet, asymétrique.","s":3},{"q":"Différence avec le système sanguin :","o":["Un système fermé, comme le sang","Un système ouvert, à sens unique","Un système bidirectionnel, avec une pompe centrale","Un système identique au sang"],"r":1,"e":"Système ouvert (sans pompe centrale), unidirectionnel.","s":3},{"q":"Cellules transportées par la lymphe :","o":["Des hématies, en grand nombre","Des lymphocytes, surtout T, et des macrophages","Des plaquettes, pour la coagulation","Des neurones et des cellules gliales, venus du système nerveux"],"r":1,"e":"Lymphocytes essentiellement T (recirculation). Aussi macrophages, débris.","s":3},{"q":"Système lymphatique a un rôle dans :","o":["Le drainage, uniquement","Le drainage, les lipides et la défense immunitaire","La digestion, uniquement, avec le foie et le pancréas","L'hématopoïèse de la moelle"],"r":1,"e":"3 grandes fonctions.","s":3},{"q":"Le canal thoracique chemine :","o":["À gauche du sternum, en avant","Devant la colonne, à droite de l'aorte","Dans le médiastin antérieur, derrière le thymus","À côté du foie, sous le diaphragme"],"r":1,"e":"Médiastin postérieur, à droite de l'aorte descendante.","s":3},{"q":"Aspect moniliforme des vaisseaux lymphatiques :","o":["Lisse et rectiligne, sans relief","En chapelet, à cause des valves","Spiralé, autour des artères","Triangulaire, en coupe, par la pression des muscles"],"r":1,"e":"Valves donnent l'aspect en chapelet ou perles.","s":3},{"q":"La paroi des capillaires lymphatiques se caractérise par :","o":["Une paroi continue, avec une membrane basale épaisse","Un endothélium simple, sans membrane basale continue","Une paroi fenestrée, comme au rein","Une triple paroi musculaire"],"r":1,"e":"Endothélium fin + jonctions chevauchantes (mini-valves).","s":3},{"q":"Lymphe filtrée par :","o":["Le foie, par ses cellules de Kupffer","Les ganglions lymphatiques","La rate, uniquement","Les reins, avec l'urine"],"r":1,"e":"Ganglions = filtres mécaniques et immunologiques.","s":3},{"q":"Le pourcentage drainé par le canal thoracique :","o":["25 %, le quart du corps","50 %, la moitié du corps, des deux côtés","75 %, les trois quarts du corps","100 %, tout le corps"],"r":2,"e":"Canal thoracique = tout sauf l'hémicorps supéro-droit.","s":3},{"q":"Lymphocytes T sont produits par :","o":["La moelle osseuse seule, sans aucune maturation ailleurs","La moelle osseuse, puis une maturation au thymus","La rate, en pulpe blanche","Les ganglions, dans le cortex"],"r":1,"e":"Précurseurs moelle → maturation thymique → LT fonctionnels.","s":3},{"q":"Le système lymphatique comprend :","o":["Des vaisseaux, des organes lymphoïdes et la lymphe","Les seuls vaisseaux, sans organe ni liquide propre","Les seuls ganglions, avec la rate","Le seul canal thoracique"],"r":0,"e":"Il appartient à la fois au système circulatoire et au système immunitaire.","s":3},{"q":"Parmi les organes lymphoïdes, le cours cite :","o":["Les ganglions, la rate, le thymus et les amygdales","Le foie, la rate et la moelle jaune, avec le pancréas","La moelle osseuse, à elle seule","Le thymus seul, chez l'enfant"],"r":0,"e":"Le thymus et la moelle osseuse sont les organes lymphoïdes primaires, où mûrissent respectivement les lymphocytes T et B. Le MALT en fait aussi partie.","s":3},{"q":"Le drainage des liquides interstitiels récupère :","o":["2 à 4 litres de filtrat par jour","10 litres de filtrat par jour","500 mL de filtrat par jour","20 litres de filtrat par jour"],"r":0,"e":"Sans ce drainage, un œdème se constitue.","s":3},{"q":"Les chylomicrons absorbés par l'intestin grêle passent :","o":["Dans les chylifères, puis le canal thoracique","Dans la veine porte, puis le foie","Dans les capillaires sanguins des villosités","Directement dans l'oreillette droite"],"r":0,"e":"C'est la fonction de transport des lipides du système lymphatique.","s":3},{"q":"Parmi les tissus dépourvus de capillaires lymphatiques figurent :","o":["Le système nerveux central, les cartilages et la cornée","Le derme et l'hypoderme, sous l'épiderme de la peau","Le muscle squelettique, au repos","L'intestin grêle, hors repas"],"r":0,"e":"Les capillaires lymphatiques sont présents dans presque tous les autres tissus. L'os compact, l'épiderme et la moelle osseuse en font aussi partie.","s":3},{"q":"Les capillaires lymphatiques sont plus perméables que les capillaires sanguins car ils laissent passer :","o":["Des protéines, des débris et des microbes","Uniquement l'eau, sans soluté","Uniquement les électrolytes, comme le sodium","Uniquement les lipides, absorbés"],"r":0,"e":"Ils sont constitués d'une seule couche d'endothélium, sans membrane basale continue, avec des mini-valves entre les cellules.","s":3},{"q":"Les chylifères se situent :","o":["Dans les villosités intestinales","Dans le foie, autour de la veine porte","Dans le thorax, près du canal","Dans les ganglions mésentériques"],"r":0,"e":"Ils transportent les graisses absorbées, ou chyle, d'aspect lactescent.","s":3},{"q":"Les vaisseaux lymphatiques collecteurs présentent :","o":["Trois tuniques fines et de nombreuses valves anti-reflux","Une paroi à une seule couche, sans valve, comme les capillaires","Aucune valve, la lymphe coulant par gravité","Une média épaisse et très musclée"],"r":0,"e":"Ces valves leur donnent un aspect moniliforme, en chapelet. Leurs tuniques sont plus fines que celles des veines.","s":3},{"q":"Le tronc broncho-médiastinal draine :","o":["La tête et le cou","Le membre supérieur","Le thorax","Les membres inférieurs"],"r":2,"e":"Les troncs jugulaires drainent la tête et le cou, les subclaviers le membre supérieur et les lombaires les membres inférieurs et le bassin.","s":3},{"q":"Le tronc intestinal draine :","o":["Le tube digestif sous-diaphragmatique","Le thorax et les poumons, au-dessus du diaphragme","Le membre inférieur gauche","La tête et le cou, à droite"],"r":0,"e":"Il fusionne avec les troncs lombaires pour former la citerne du chyle.","s":3},{"q":"La citerne du chyle, ou de Pecquet, se situe au niveau :","o":["De T8","De L2","De L5","De C7"],"r":1,"e":"Elle résulte de la fusion des troncs lombaires et du tronc intestinal, et donne naissance au canal thoracique.","s":3},{"q":"Le canal thoracique monte dans le thorax :","o":["Devant la colonne vertébrale, à droite de l'aorte","Derrière l'aorte, contre les vertèbres gauches","À gauche de l'œsophage, en avant","Dans le médiastin antérieur"],"r":0,"e":"Il se jette dans le confluent jugulo-subclavier gauche, ou angle de Pirogoff gauche.","s":3},{"q":"Le canal thoracique draine :","o":["La moitié du corps, le côté gauche entier","Les trois quarts du corps","L'hémicorps supéro-droit","Le seul abdomen, sous le diaphragme"],"r":1,"e":"La grande veine lymphatique, ou canal lymphatique droit, draine l'hémicorps supéro-droit. C'est tout sauf l'hémicorps supéro-droit.","s":3},{"q":"La grande veine lymphatique mesure environ :","o":["1 cm","10 cm","40 cm","5 cm"],"r":0,"e":"Elle reçoit les troncs jugulaire, subclavier et broncho-médiastinal droits et se jette dans le confluent jugulo-subclavier droit.","s":3},{"q":"Un lymphangion se définit comme :","o":["Le segment de vaisseau compris entre deux valves","Un ganglion lymphatique de petite taille","Un capillaire lymphatique initial","Un tronc collecteur, qui rejoint le canal thoracique"],"r":0,"e":"Ses contractions intrinsèques constituent l'une des forces motrices de la lymphe.","s":3},{"q":"Parmi les forces motrices de la lymphe, le cours cite :","o":["Les lymphangions, la pompe musculaire et la respiration","La seule pesanteur, en position debout","La seule pression artérielle, transmise aux capillaires","Le seul cœur, par l'aspiration diastolique"],"r":0,"e":"La circulation lymphatique est à sens unique, des tissus vers le système veineux, et bien plus lente que la circulation sanguine. Les pulsations artérielles et les valves y participent aussi.","s":3},{"q":"Le drainage lymphatique manuel exploite :","o":["Une pression douce, dans le sens du drainage","Une pression forte et rapide","Un travail à contresens du drainage, distal","Les seules mobilisations articulaires"],"r":0,"e":"Il traite les œdèmes lymphatiques, ce qui en fait une application directe de cette physiologie en kinésithérapie. Elle stimule les contractions des lymphangions.","s":3},{"q":"La lymphe est décrite comme un liquide :","o":["Clair et jaunâtre, sauf le chyle, lactescent","Rouge foncé, comme le sang veineux","Toujours lactescent, même à jeun","Incolore et transparent, comme l'eau pure"],"r":0,"e":"Sa composition est proche de celle du plasma, mais avec moins de protéines.","s":3},{"q":"La lymphe contient notamment :","o":["De l'eau, des lymphocytes, des macrophages et des débris","Des érythrocytes, en grand nombre","Des plaquettes, pour la coagulation","Du fibrinogène, en forte concentration, avec des hématies"],"r":0,"e":"Les ganglions en assurent la filtration ; les lymphocytes T y sont notamment représentés. Électrolytes, chylomicrons après repas, microbes et antigènes en font aussi partie.","s":3},{"q":"Le système lymphatique participe à la défense immunitaire par :","o":["Le filtrage ganglionnaire et l'activation des lymphocytes","La production d'anticorps par les vaisseaux","La phagocytose dans les capillaires","La destruction des érythrocytes, dans les ganglions"],"r":0,"e":"La maturation lymphocytaire a lieu, elle, dans les organes lymphoïdes primaires : thymus et moelle osseuse. Les lymphocytes B et T sont activés.","s":3},{"q":"Nomenclature utilisée en kinésithérapie pour le drainage du membre supérieur :","o":["Couinaud","Caplan / Leduc","McNeal","Bauhin"],"r":1,"e":"Nomenclature Caplan/Leduc utilisée pour le DLM.","s":4},{"q":"Pédicule =","o":["Un ganglion isolé, sur un collecteur","Un ensemble de collecteurs lymphatiques","Un vaisseau sanguin, satellite","Un nerf, satellite des vaisseaux"],"r":1,"e":"Groupement de collecteurs lymphatiques dans une région donnée.","s":4},{"q":"Pédicules primaires (avant-bras) :","o":["Deux, un antérieur et un postérieur","Trois, dont un pédicule médian","Quatre, radiaux et cubitaux, en avant et en arrière","Six, avec les pédicules interosseux et les deux médians"],"r":2,"e":"4 pédicules primaires de l'avant-bras.","s":4},{"q":"Pédicule radial antérieur :","o":["1 collecteur","2 collecteurs","3 collecteurs","4 collecteurs"],"r":1,"e":"Radial ant (2), Cubital ant (1), Radial post (2), Cubital post (1). Total = 6.","s":4},{"q":"Radial antérieur s'étend de :","o":["De l'épaule au coude, en dedans","De la région terminale de la main au coude","Des doigts jusqu'à l'aisselle","De la main jusqu'à l'épaule, sans relais au coude"],"r":1,"e":"De la main au coude. Trajet oblique externe-interne.","s":4},{"q":"Cubital antérieur part de :","o":["De la région radiale, au pouce","De la région hypothénar de la main","Du pouce et de l'éminence thénar","De l'épaule, en direction du poignet et de la main"],"r":1,"e":"Région hypothénar (face cubitale).","s":4},{"q":"Voie de Caplan :","o":["La voie principale du membre supérieur","Une voie postérieure, sans anastomose postéro-antérieure","La voie axillaire, par la chaîne céphalique et l'aisselle","Une voie veineuse, satellite de la céphalique"],"r":1,"e":"Caplan = drainage par pédicules postérieurs → ganglion supérieur. Elle est alternative, par les pédicules postérieurs.","s":4},{"q":"Pédicules secondaires (bras) :","o":["Deux, céphalique et basilique","Trois, céphalique, bicipitale et basilique","Quatre, céphalique, bicipitale, basilique et axillaire","Cinq, une par doigt de la main"],"r":1,"e":"3 chaînes pédiculaires : céphalique (2 coll), bicipitale (3 coll), basilique (4 coll).","s":4},{"q":"Chaîne céphalique (autre nom) :","o":["Bicipitale interne","Bicipitale externe","Bicipitale antérieure","Subscapulaire"],"r":1,"e":"Céphalique = externe. Basilique = interne. Bicipitale = antérieure.","s":4},{"q":"Voie de Mascagni est présente chez :","o":["20 % des personnes","40 % des personnes","70 % des personnes","100 % des personnes"],"r":2,"e":"Constante chez 70% des personnes. Variante de la chaîne céphalique vers le cou.","s":4},{"q":"Chaîne céphalique se termine :","o":["Toujours dans le creux axillaire, au même endroit","Selon trois variantes possibles","Dans le canal thoracique, à gauche","Dans la veine porte, sous le foie"],"r":1,"e":"3 variantes possibles selon les anastomoses individuelles. Elles sont axillaire, cervicale et supraclaviculaire.","s":4},{"q":"Chaîne basilique a :","o":["Un seul trajet, superficiel","Deux trajets, supra- et infra-aponévrotique","Trois trajets, dont un profond et deux superficiels","Aucun trajet propre, distinct"],"r":1,"e":"2 trajets distincts. Tous deux vers les ganglions axillaires.","s":4},{"q":"Ganglion sus-trochléen :","o":["Sur la chaîne céphalique, au coude","Sur la chaîne basilique, au coude","Sur le poignet, à la face antérieure, près du pouce","Au cou, au-dessus de la clavicule"],"r":1,"e":"Centre ganglionnaire le plus important du système superficiel. 1-3 ganglions habituels. Il est à la face antérieure du coude.","s":4},{"q":"Ganglions axillaires :","o":["5-10","~20 à 40","100","1"],"r":1,"e":"20-40 ganglions répartis en 5 groupes.","s":4},{"q":"Groupes axillaires :","o":["Trois, pectoral, central et apical, seulement","Cinq, dont pectoral, central et apical","Deux, médial et latéral","Sept, dont deux sous-claviers"],"r":1,"e":"5 groupes secondaires verticaux et 1 horizontal (Berg pour les chirurgiens du sein). Les cinq sont pectoral, subscapulaire, brachial, central et apical.","s":4},{"q":"Curage axillaire risque de causer :","o":["Une arthrite, de l'épaule opérée","Un lymphœdème du membre supérieur","Une anémie, par saignement","Une hypotension, à l'orthostatisme"],"r":1,"e":"10-20% des cas. Justifie le concept de ganglion sentinelle.","s":4},{"q":"Principe du DLM :","o":["Vider d'abord les zones distales, puis le centre","Vider d'abord le quadrant central, puis remonter","Appuyer fort, pour chasser la lymphe","Masser vite, en surface"],"r":1,"e":"Méthode Vodder/Leduc : pression douce, vider centre d'abord.","s":4},{"q":"Contre-indication majeure du DLM :","o":["Une obésité importante, avec un très net surpoids","Une infection aiguë ou une phlébite non traitée","Un asthme, même stabilisé","Un diabète, même équilibré"],"r":1,"e":"Risque de dissémination infectieuse ou embolique. L'érysipèle et la TVP non traitée en sont des exemples.","s":4},{"q":"Chaîne céphalique compte :","o":["5 collecteurs","2 collecteurs","10 collecteurs","1 collecteur"],"r":1,"e":"Céphalique = 2 collecteurs (la plus petite des chaînes secondaires).","s":4},{"q":"Chaîne bicipitale antérieure (3 collecteurs) prend naissance dans :","o":["Les seuls pédicules postérieurs","Les quatre pédicules primaires","Aucun pédicule primaire","La veine porte et ses branches, au foie"],"r":1,"e":"Convergence des 4 pédicules primaires.","s":4},{"q":"Chaîne basilique part de :","o":["Des radiaux antérieur et postérieur","Des cubitaux antérieur et postérieur","De tous les pédicules primaires","D'aucun pédicule, directement de la peau du coude"],"r":1,"e":"Chaîne basilique = cubitaux. Chaîne céphalique = radiaux.","s":4},{"q":"Suivi de la veine céphalique permet à la chaîne céphalique de :","o":["D'atteindre directement le cou","D'atteindre les ganglions axillaires","De drainer le bras en profondeur","De drainer le cœur et le médiastin, par la veine cave"],"r":1,"e":"Suit la veine céphalique → perfore l'aponévrose → axillaire. Elle perfore pour cela l'aponévrose.","s":4},{"q":"Tronc subclavier reçoit :","o":["La lymphe du tronc et de toute la paroi thoracique","La lymphe du membre supérieur, via l'aisselle","La lymphe du membre inférieur","La lymphe digestive, du grêle"],"r":1,"e":"Subclavier drainage du membre supérieur (droit ou gauche selon le côté).","s":4},{"q":"Drainage du membre supérieur droit termine dans :","o":["Le canal thoracique, à gauche du cou","La grande veine lymphatique, à droite","La veine cave, directement","La veine cave inférieure"],"r":1,"e":"Droite = canal lymphatique droit. Gauche = canal thoracique. C'est le canal lymphatique droit.","s":4},{"q":"Vidange manuelle d'un quadrant doit commencer :","o":["Aux doigts, puis remonter vers le poignet","Par les ganglions, au centre","À la peau, en surface","Le matin uniquement"],"r":1,"e":"Vider les zones centrales avant de pousser depuis la périphérie. Ce sont les ganglions axillaires et sus-claviculaires.","s":4},{"q":"Sens de drainage manuel :","o":["Du proximal vers le distal","Du distal vers le proximal","Au hasard, sans ordre","En cercles, autour du membre"],"r":1,"e":"Toujours vers les ganglions sains (chez patient curage : éviter la zone). Le drainage va vers les ganglions sains.","s":4},{"q":"Cubital postérieur et radial postérieur partent de :","o":["De la paume, au creux de la main","De la face dorsale des doigts","Du coude, en arrière","De l'aisselle, en remontant"],"r":1,"e":"Origine et trajet communs sur la face dorsale, du dos des doigts au 1/3 inférieur de l'avant-bras.","s":4},{"q":"Anastomoses postéro-antérieures :","o":["Sur le bras, au-dessus du coude","Du dos de la main au tiers proximal de l'avant-bras","Aux doigts, uniquement, sur toute leur face dorsale","Inexistantes chez l'adulte"],"r":1,"e":"Anastomoses postéro-antérieures = bypass entre faces postérieures et antérieures.","s":4},{"q":"La voie de Mascagni se termine dans :","o":["Dans les ganglions axillaires","Dans les ganglions cervicaux transverses","Dans les ganglions inguinaux, par une voie descendante","Dans la veine porte, au foie"],"r":1,"e":"Variante de la chaîne céphalique : passe devant la clavicule → ganglions cervicaux transverses.","s":4},{"q":"La nomenclature Caplan/Leduc est essentielle pour :","o":["La chirurgie cardiaque, à cœur ouvert","Le drainage manuel et la rééducation post-curage","Le diagnostic immunologique, par une biopsie","L'hématologie et les greffes de moelle"],"r":1,"e":"Référence pour les kinésithérapeutes en DLM, surtout post-cancer du sein.","s":4},{"q":"Un pédicule lymphatique se définit comme :","o":["Des collecteurs qui cheminent ensemble dans une région","Un ganglion volumineux, au carrefour de plusieurs collecteurs","Un capillaire lymphatique initial","Un tronc terminal, vers le cou"],"r":0,"e":"La nomenclature Caplan/Leduc organise ces pédicules en primaires à l'avant-bras et secondaires au bras.","s":4},{"q":"Les quatre pédicules primaires de l'avant-bras totalisent :","o":["4 collecteurs","6 collecteurs","8 collecteurs","3 collecteurs"],"r":1,"e":"Radial antérieur 2, cubital antérieur 1, radial postérieur 2 et cubital postérieur 1.","s":4},{"q":"Le pédicule radial antérieur comporte :","o":["1 collecteur","2 collecteurs","3 collecteurs","4 collecteurs"],"r":1,"e":"Il s'étend de la région terminale de la main au coude, selon un trajet oblique de l'extérieur vers l'intérieur.","s":4},{"q":"Le pédicule cubital antérieur prend naissance :","o":["Dans la région hypothénar de la main","Dans la région thénar, au pouce","À la face dorsale des doigts","Au coude, au niveau du pli antérieur du bras"],"r":0,"e":"Son trajet est moins oblique que celui du radial antérieur ; il contribue aux pédicules secondaires interne et antérieur.","s":4},{"q":"Les pédicules postérieurs, cubital et radial, s'étendent :","o":["Du dos des doigts jusqu'au tiers inférieur de l'avant-bras","De la main au coude, puis jusqu'à l'aisselle, sans aucun relais","Du coude jusqu'à l'aisselle, en dedans","De l'aisselle jusqu'au cou, à droite"],"r":0,"e":"Ils s'anastomosent avec les pédicules antérieurs, de la région dorsale de la main au tiers proximal de l'avant-bras.","s":4},{"q":"La voie de Caplan commence dans :","o":["Les pédicules postérieurs, jusqu'au ganglion supérieur","Les pédicules antérieurs, jusqu'aux ganglions axillaires","La chaîne céphalique, au bras","Les ganglions axillaires apicaux"],"r":0,"e":"Elle prend le relais en l'absence d'anastomoses postéro-antérieures, notamment si la voie antérieure est obstruée par une cicatrice ou un curage. Ce sont les pédicules primaires postérieurs.","s":4},{"q":"La chaîne bicipitale antérieure comporte :","o":["2 collecteurs","3 collecteurs","4 collecteurs","1 collecteur"],"r":1,"e":"La chaîne céphalique en compte 2 et la chaîne basilique 4.","s":4},{"q":"La chaîne pédiculaire basilique prend naissance dans :","o":["Les pédicules cubitaux postérieur et antérieur","Les pédicules radiaux, en dehors","Les quatre pédicules primaires de l'avant-bras, réunis","La voie de Caplan, en arrière"],"r":0,"e":"Elle suit deux trajets distincts, supra-aponévrotique et infra-aponévrotique, tous deux vers les ganglions axillaires.","s":4},{"q":"La chaîne bicipitale antérieure prend naissance dans :","o":["Les quatre pédicules primaires","Les seuls pédicules radiaux","Les seuls pédicules cubitaux","La chaîne céphalique"],"r":0,"e":"Elle s'étend du coude à la base de l'aisselle, obliquement de l'extérieur vers l'intérieur.","s":4},{"q":"La chaîne céphalique prend naissance dans :","o":["Les pédicules radiaux postérieur et antérieur","Les pédicules cubitaux, en dedans","Les quatre pédicules primaires","La chaîne basilique, par une anastomose au coude"],"r":0,"e":"Son trajet externe rejoint le sillon delto-pectoral et le triangle claviculo-delto-pectoral.","s":4},{"q":"Parmi les trois variantes terminales de la chaîne céphalique figure :","o":["Le trajet de la veine céphalique jusqu'à l'aisselle","Le trajet cubital, en dedans","La voie de Caplan, par les pédicules postérieurs du bras","Le tronc intestinal, vers la citerne"],"r":0,"e":"Les deux autres sont la voie de Mascagni et le groupe ganglionnaire claviculo-pectoral vers les ganglions supraclaviculaires. Ce trajet perfore l'aponévrose avant les ganglions axillaires.","s":4},{"q":"La voie de Mascagni est présente chez environ :","o":["30 % des personnes","50 %","70 %","100 %"],"r":2,"e":"Elle passe devant la clavicule et se termine dans la chaîne cervicale transverse.","s":4},{"q":"L'intérêt clinique de la voie de Mascagni est :","o":["De drainer le membre en contournant l'aisselle","D'accélérer le drainage normal, par la voie axillaire habituelle","De remplacer le canal thoracique","De drainer le sein et la paroi"],"r":0,"e":"Elle est très utile après curage axillaire pour un cancer du sein, en orientant le drainage vers les ganglions sus-claviculaires.","s":4},{"q":"Les ganglions axillaires sont au nombre de :","o":["5 à 10","20 à 40","50 à 60","100"],"r":1,"e":"Ils constituent la cible principale du drainage du membre supérieur et se répartissent en cinq groupes.","s":4},{"q":"Les ganglions axillaires pectoraux, ou mammaires externes :","o":["Drainent aussi le sein","Drainent la face postérieure du tronc","Drainent le membre supérieur","Constituent le confluent terminal"],"r":0,"e":"Les subscapulaires drainent la face postérieure du tronc et les brachiaux le membre supérieur.","s":4},{"q":"Les ganglions axillaires apicaux, ou infraclaviculaires :","o":["Constituent le confluent final vers le tronc subclavier","Drainent le sein et toute la paroi thoracique antérieure","Drainent la face postérieure du tronc","Sont les plus superficiels du creux axillaire"],"r":0,"e":"Ils reçoivent l'ensemble des autres groupes axillaires.","s":4},{"q":"Les ganglions sus-épitrochléens se situent :","o":["Au-dessus de l'épicondyle médial","Au-dessus de l'épicondyle latéral","Dans l'aisselle","Au creux poplité"],"r":0,"e":"Ce sont des ganglions intercalaires du coude, drainant une partie de la main et la face médiale de l'avant-bras.","s":4},{"q":"Le risque principal d'un curage axillaire est :","o":["Un lymphœdème du membre supérieur","Une paralysie du nerf radial","Une thrombose veineuse profonde","Une infection pulmonaire"],"r":0,"e":"C'est ce qui justifie la connaissance des voies alternatives comme celle de Mascagni.","s":4},{"q":"La chaîne céphalique porte aussi le nom de :","o":["Bicipitale externe","Bicipitale antérieure","Bicipitale interne","Chaîne cubitale"],"r":0,"e":"La chaîne bicipitale est dite bicipitale antérieure et la chaîne basilique bicipitale interne.","s":4},{"q":"Le drainage du membre supérieur droit se termine :","o":["Dans le canal lymphatique droit, puis le confluent droit","Dans le canal thoracique, à gauche","Dans la citerne du chyle, puis le canal thoracique, à gauche","Dans le tronc intestinal, au ventre"],"r":0,"e":"Le canal lymphatique droit draine l'hémicorps supéro-droit, le canal thoracique tout le reste. Ce confluent est jugulo-subclavier.","s":4},{"q":"Canal thoracique mesure :","o":["10 cm","36-45 cm","1 m","5 cm"],"r":1,"e":"36-45 cm × 1-5 mm. Plus grand tronc lymphatique.","s":5},{"q":"Canal thoracique draine :","o":["Un demi-litre par jour","Un litre par jour","Environ 3 litres par jour","10 litres par jour"],"r":2,"e":"~3 L/jour, 3/4 de la lymphe corporelle. C'est les trois quarts de la lymphe totale.","s":5},{"q":"Canal thoracique se termine à l'angle veineux :","o":["Droit, au confluent jugulo-subclavier du côté droit","Gauche, au confluent jugulo-subclavier gauche","Dans aucune veine, mais dans l'aorte","Au cou, en arrière, dans la nuque"],"r":1,"e":"Confluent jugulo-subclavier gauche. Présence de valves anti-reflux.","s":5},{"q":"Canal lymphatique droit mesure :","o":["1-1,5 cm","10 cm","30 cm","60 cm"],"r":0,"e":"Court tronc de ~1-1,5 cm.","s":5},{"q":"Territoires du canal lymphatique droit :","o":["L'hémicorps inférieur, sous l'ombilic","La moitié droite de la tête, du cou et du thorax","Tout le corps, à l'exception de la tête et des pieds","La région pelvienne et le périnée"],"r":1,"e":"Quart supérieur droit du corps uniquement. Il draine aussi le membre supérieur droit.","s":5},{"q":"Chaîne basilique du membre supérieur :","o":["Au coude, en arrière, sur l'olécrane","À la face antérieure du coude, supra-trochléenne","À l'épaule, près du sillon delto-pectoral, en avant","À la main, sur la face dorsale"],"r":1,"e":"Supra-trochléen sur le trajet de la veine basilique. Centre principal du système superficiel.","s":5},{"q":"Ganglions sus-trochléens :","o":["10 à 20 ganglions, en amas","1 à 3 ganglions, en général","50 ganglions, en chaîne","Aucun ganglion chez l'adulte, après 20 ans"],"r":1,"e":"1-3 (parfois jusqu'à 5). Il peut y en avoir jusqu'à 5.","s":5},{"q":"Centres ganglionnaires profonds du MS :","o":["Deux chaînes, radiale et cubitale","Quatre, radiale, cubitale, interosseuse et humérale","Huit chaînes, deux par segment","Une seule chaîne, humérale, le long de l'artère du bras"],"r":1,"e":"Chaînes : radiale, cubitale, interosseuse antérieure, humérale.","s":5},{"q":"Pédicule saphène interne se draine dans :","o":["Ganglions poplités","Ganglions inguinaux supérieurs","Ganglions sus-claviculaires","Aucun ganglion"],"r":1,"e":"Saphène interne (face antéro-interne) → inguinaux supérieurs.","s":5},{"q":"Pédicule saphène externe se draine dans :","o":["Les ganglions inguinaux, par la saphène interne","Les ganglions poplités","Les ganglions axillaires","Les ganglions cervicaux"],"r":1,"e":"Face postérieure de la jambe. Perce dans la région poplitée vers les ganglions poplités. Il perce dans la région poplitée.","s":5},{"q":"Ganglions inguinaux profonds :","o":["10 à 15, en amas autour du pli","2 à 3, sur le trajet de la veine fémorale","Aucun, chez l'adulte sain","20, répartis le long de toute la veine fémorale"],"r":1,"e":"2-3 ganglions profonds, le plus haut = ganglion de Cloquet.","s":5},{"q":"Pédicules lymphatiques profonds du membre inférieur :","o":["Les saphènes interne et externe","Les tibiaux antérieur et postérieur","Le fémoral et l'obturateur","Le sciatique, le long du nerf, à la face postérieure"],"r":1,"e":"Tibial ant + post = pédicules profonds. Saphène int/ext = superficiels.","s":5},{"q":"Voie finale du drainage du MI :","o":["Directement la veine cave inférieure, sans relais","Les inguinaux, puis les iliaques et l'aorte","Les iliaques internes, seuls","La veine porte, par le foie"],"r":1,"e":"MI → inguinaux → iliaques → lombo-aortiques → cisterne → canal thoracique. Les lombo-aortiques, la citerne du chyle puis le canal thoracique suivent.","s":5},{"q":"Ganglions tibiaux :","o":["Un seul ganglion, à la face postérieure du genou","Deux, tibial antérieur et tibial postérieur","Dix, en chaîne le long du tibia","Aucun, ils sont inexistants"],"r":1,"e":"Tibial antérieur + tibial postérieur sur les trajets profonds.","s":5},{"q":"Anneau ganglionnaire péri-cervical comprend :","o":["Deux groupes seulement, en avant et en arrière","Six groupes, dont parotidiens et occipitaux","Cinq groupes axillaires","Les ganglions inguinaux"],"r":1,"e":"6 groupes périphériques de la face/cou. Les sub-mentonniers, sub-mandibulaires, sterno-cléido-mastoïdiens et mastoïdiens complètent la liste.","s":5},{"q":"Ganglion de Troisier :","o":["Inguinal, révélant une infection du membre inférieur","Sus-claviculaire gauche, métastatique","Axillaire, révélant un cancer du sein","Cervical droit, après une angine"],"r":1,"e":"Adénopathie sus-claviculaire gauche = drapeau rouge oncologique (estomac, pancréas, ovaire, testicule).","s":5},{"q":"Chaîne ganglionnaire axillaire principale horizontale suit :","o":["Veine subclavière","Veine axillaire","Artère brachiale","Veine porte"],"r":1,"e":"Chaîne principale dans le trajet de la veine axillaire.","s":5},{"q":"Amygdales :","o":["Des glandes salivaires accessoires","Du tissu lymphoïde de l'oropharynx","Des ganglions sympathiques cervicaux, contre la carotide","Des vaisseaux du pharynx"],"r":1,"e":"Produisent des lymphocytes. Barrière contre les micro-organismes. Elles forment l'anneau de Waldeyer.","s":5},{"q":"Thymus :","o":["Augmente de volume avec l'âge","Plus développé chez le fœtus, il involue après la puberté","N'existe qu'à l'âge adulte, après 20 ans","N'existe pas chez l'humain, seulement chez l'oiseau et le poisson"],"r":1,"e":"Involution graisseuse à l'âge adulte. Maturation des LT.","s":5},{"q":"Rate :","o":["Elle s'interpose dans la circulation lymphatique","Elle s'interpose dans la seule circulation sanguine","C'est un vrai ganglion lymphatique","C'est un vaisseau lymphatique"],"r":1,"e":"Considérée comme « gros ganglion », mais interposée dans la circulation sanguine. Elle est exclue de la circulation lymphatique.","s":5},{"q":"Rate située :","o":["Hypochondre droit","Hypochondre gauche","Pelvis","Thorax"],"r":1,"e":"HCG, en regard des 9-11ème côtes.","s":5},{"q":"Fonctions de la rate :","o":["La digestion des graisses","La filtration du sang et l'immunité","L'hématopoïèse de l'adulte","La sécrétion d'enzymes digestives"],"r":1,"e":"« Cimetière des hématies » + organe immunitaire + réservoir sanguin. Elle produit aussi des lymphocytes.","s":5},{"q":"Splénectomie expose à :","o":["Un diabète, par atteinte du pancréas","Des infections par bactéries encapsulées","Une hypertension artérielle","Aucun risque particulier"],"r":1,"e":"Pneumocoque, méningocoque, Hib. Vaccins indispensables.","s":5},{"q":"Ganglion de Cloquet :","o":["Axillaire, le plus haut de l'aisselle","Inguinal profond, le plus haut, à l'anneau crural","Sus-claviculaire gauche","Cervical, le plus bas de la chaîne jugulaire interne"],"r":1,"e":"Le plus haut des inguinaux profonds.","s":5},{"q":"Ganglion poplité superficiel :","o":["N'existe pas chez l'adulte","Draine la partie basse de la jambe et le pied","Se situe à l'aine, sous le ligament inguinal, en dedans","Se situe au cou, à gauche"],"r":1,"e":"Reçoit la saphène externe. Profonds + 1 superficiel.","s":5},{"q":"Chaîne jugulaire interne :","o":["Le drainage du tronc et de l'abdomen","Le drainage principal de la tête","Le drainage du membre supérieur","Elle n'existe pas"],"r":1,"e":"Chaîne cervicale profonde majeure pour le drainage de la tête.","s":5},{"q":"Inguinaux superficiels organisés en :","o":["Deux groupes, interne et externe","Six secteurs, trois proximaux et trois distaux","Cinq chaînes verticales, le long de la saphène interne","Aucune organisation précise"],"r":1,"e":"Organisation en sextant : 3 sup pluri + 3 inf mono. Les proximaux sont pluri-ganglionnaires, les distaux mono-ganglionnaires.","s":5},{"q":"Drainage des organes génitaux externes féminins :","o":["Lombo-aortiques","Inguinaux superficiels","Iliaques internes","Mésentériques"],"r":1,"e":"Région génitale externe → inguinaux superficiels.","s":5},{"q":"Drainage de l'ovaire :","o":["Les ganglions inguinaux, comme le reste du petit bassin","Les lombo-aortiques, en suivant l'artère ovarienne","Les iliaques internes, pelviens","Les ganglions mésentériques"],"r":1,"e":"Origine embryologique abdominale → drainage lombo-aortique.","s":5},{"q":"Rate produit :","o":["Hémoglobine","Lymphocytes","Bile","Insuline"],"r":1,"e":"Lymphocytes + anticorps. Pulpe blanche.","s":5},{"q":"Les dimensions du canal thoracique sont :","o":["36 à 45 cm de long et 1 à 5 mm de diamètre","10 à 15 cm de long et 1 cm de diamètre","60 cm de long et 2 cm de diamètre","20 cm de long et 5 mm de diamètre"],"r":0,"e":"C'est le plus grand tronc lymphatique du corps ; il traverse le diaphragme avec l'aorte et la suit dans son trajet.","s":5},{"q":"Le canal thoracique se termine dans :","o":["L'angle veineux gauche, jugulo-subclavier","L'angle veineux droit, jugulo-subclavier","L'oreillette droite, directement","La veine cave supérieure, directement, sans valve"],"r":0,"e":"Il draine environ 3 L par jour, soit les trois quarts du total.","s":5},{"q":"Les valves situées à la terminaison du canal thoracique :","o":["Empêchent le reflux du sang veineux dans le canal","Accélèrent le flux de la lymphe","Sont absentes chez l'adulte","Régulent la pression artérielle, au niveau de la crosse"],"r":0,"e":"Elles complètent le dispositif anti-reflux présent tout au long des vaisseaux lymphatiques. On parle de « cœur lymphatique ».","s":5},{"q":"Parmi les territoires drainés par le canal thoracique figurent :","o":["L'hémicorps gauche, les membres inférieurs et l'abdomen","Le seul abdomen, sous le diaphragme","Les seuls membres inférieurs, jusqu'aux ganglions inguinaux","L'hémicorps supéro-droit, en entier"],"r":0,"e":"Le canal lymphatique droit draine, lui, l'hémicorps supéro-droit uniquement. Il draine aussi les organes génitaux.","s":5},{"q":"Le canal lymphatique droit mesure :","o":["1 à 1,5 cm","5 cm","10 cm","20 cm"],"r":0,"e":"Il converge vers l'angle veineux droit et draine environ un quart de la lymphe totale.","s":5},{"q":"La chaîne basilique supra-trochléenne est :","o":["Le principal centre du système superficiel du membre","Un centre ganglionnaire profond","Absente chez l'adulte, involuée","Située à l'aisselle, au contact direct de la veine axillaire"],"r":0,"e":"Située sur le trajet de la veine basilique, à la face antérieure du coude, elle comprend généralement 1 à 3 ganglions, parfois jusqu'à 5.","s":5},{"q":"La chaîne céphalique de la région delto-pectorale :","o":["Est non constante et emprunte deux voies","Est constante et ne prend qu'une voie, vers l'aisselle","N'a qu'une seule voie, cervicale","Se termine dans le canal thoracique"],"r":0,"e":"La voie la moins fréquente se dirige vers les ganglions sus-claviculaires. L'une est quasi constante, vers les centres axillaires profonds.","s":5},{"q":"La chaîne cubitale superficielle :","o":["Est le 3ᵉ centre superficiel, et n'existe pas toujours","Est constante, au tiers supérieur de l'avant-bras, en dedans","Comprend 5 ganglions, en chaîne","Se situe au bras, en dehors"],"r":0,"e":"Elle compte 1 ou 2 ganglions sous l'épitrochlée, et ses collecteurs efférents rejoignent la chaîne basilique. Elle siège au tiers supérieur de l'avant-bras.","s":5},{"q":"Les centres ganglionnaires profonds du membre supérieur comprennent :","o":["Les chaînes radiale, cubitale, interosseuse et humérale","La chaîne basilique et la chaîne céphalique du bras","La chaîne céphalique, delto-pectorale","Les ganglions axillaires superficiels"],"r":0,"e":"Les chaînes basilique, céphalique et cubitale superficielle constituent, elles, le système superficiel. L'interosseuse est antérieure.","s":5},{"q":"Les ganglions axillaires comportent :","o":["Trois chaînes verticales et une chaîne horizontale","Une seule chaîne, le long de la veine axillaire, horizontale","Quatre chaînes horizontales","Deux chaînes verticales, parallèles"],"r":0,"e":"Les chaînes verticales sont les chaînes thoracique supérieure, infra-scapulaire et mammaire externe ; l'ensemble donne les troncs sous-claviers. La chaîne horizontale suit la veine axillaire.","s":5},{"q":"Le pédicule saphène interne :","o":["Naît du dos du pied et finit aux ganglions inguinaux","Naît de la face externe du pied","Se termine dans les ganglions poplités, au creux du genou","Est un pédicule profond, tibial"],"r":0,"e":"Il suit la veine saphène interne, de l'extérieur vers l'intérieur. Ce sont les ganglions inguinaux supérieurs.","s":5},{"q":"Le pédicule saphène externe :","o":["Naît au bord externe du pied et finit aux poplités","Se termine dans les ganglions inguinaux, à l'aine","Naît de la région dorsale du pied, en dedans","Reste superficiel jusqu'à l'aine, sans relais"],"r":0,"e":"Il perce le système profond dans la région poplitée. Son trajet est postérieur.","s":5},{"q":"Les pédicules lymphatiques profonds du membre inférieur sont :","o":["Les pédicules tibiaux antérieur et postérieur","Les pédicules saphènes, interne et externe","Le pédicule fémoral, à lui seul","Le pédicule poplité, isolé"],"r":0,"e":"Les pédicules saphènes interne et externe constituent le système superficiel.","s":5},{"q":"Les ganglions inguinaux superficiels s'organisent en :","o":["Trois secteurs proximaux et trois secteurs distaux","Deux secteurs, un interne et un externe, de part et d'autre","Quatre secteurs égaux, en croix","Un groupe unique, central"],"r":0,"e":"Ils reçoivent le drainage de la cuisse, de la face antéro-interne de la jambe et du pied et de la région génitale externe. Les proximaux sont pluri-ganglionnaires, les distaux mono-ganglionnaires.","s":5},{"q":"Les ganglions inguinaux profonds sont au nombre de :","o":["Un seul, sous le ligament","2 à 3, sur le trajet de la veine fémorale","5 à 6, autour de l'artère fémorale et du nerf","10, en chaîne continue"],"r":1,"e":"Le ganglion de Cloquet en est le plus haut, situé à l'anneau crural.","s":5},{"q":"La voie finale du drainage du membre inférieur passe par :","o":["Les inguinaux profonds, les iliaques, puis la citerne","Les ganglions axillaires, par la voie thoraco-épigastrique","Le canal lymphatique droit, seul","Les ganglions cervicaux, au cou"],"r":0,"e":"Cette chaîne explique la remontée du drainage vers l'angle veineux gauche. Les lombo-aortiques précèdent la citerne du chyle, puis le canal thoracique.","s":5},{"q":"Le ganglion de Troisier est :","o":["Sus-claviculaire gauche, signe d'un cancer abdominal","Sus-claviculaire droit, signe d'un cancer du poumon","Inguinal, signe d'une infection du pied","Axillaire, signe d'un cancer du sein"],"r":0,"e":"Il correspond à la terminaison des chaînes cervicales du côté du canal thoracique. Il est notamment gastrique.","s":5},{"q":"La chaîne jugulaire interne, ou cervicale profonde :","o":["Assure le principal drainage de la tête","Draine le membre supérieur","Draine le thorax et le médiastin moyen","Draine l'abdomen supérieur"],"r":0,"e":"Les chaînes spinale et cervicale transverse la complètent.","s":5},{"q":"Le thymus :","o":["Est maximal avant la naissance, puis involue","Grossit avec l'âge, jusqu'à 60 ans","Est absent à la naissance et apparaît à la puberté","Se situe dans l'abdomen, sous le foie"],"r":0,"e":"Situé dans le médiastin antéro-supérieur derrière le manubrium, il est le siège de la maturation des lymphocytes T. Il s'atrophie entre la naissance et la puberté et devient graisseux à l'âge adulte.","s":5},{"q":"La rate est décrite comme :","o":["Un organe lymphatique placé sur la circulation sanguine","Un ganglion lymphatique classique, sur un collecteur","Un organe du système digestif, annexé à l'estomac","Un organe endocrinien, qui sécrète des hormones"],"r":0,"e":"Elle filtre les vieilles hématies, participe à la réponse immunitaire, produit des lymphocytes et constitue une réserve de sang et de plaquettes. Elle est exclue de la circulation lymphatique.","s":5},{"q":"Longueur totale du tube digestif :","o":["3-4 m","8-9 m","15 m","25 m"],"r":1,"e":"8-9 m de la bouche à l'anus.","s":6},{"q":"Combien de tuniques dans le tube digestif ?","o":["Deux, muqueuse et musculeuse","Trois, muqueuse, musculeuse et séreuse","Quatre, de la muqueuse à la séreuse","Cinq, avec le péritoine pariétal"],"r":2,"e":"4 tuniques de l'intérieur vers l'extérieur. Ce sont la muqueuse, la sous-muqueuse, la musculeuse et la séreuse ou l'adventice.","s":6},{"q":"Plexus de Meissner se trouve dans :","o":["Muqueuse","Sous-muqueuse","Musculeuse","Séreuse"],"r":1,"e":"Meissner = sous-muqueux (sécrétions). Auerbach = myentérique (motilité).","s":6},{"q":"Plexus d'Auerbach (myentérique) :","o":["Entre la muqueuse et la sous-muqueuse","Entre les deux couches musculaires","Dans la séreuse, sous le péritoine","Dans l'épithélium, au contact de la lumière intestinale"],"r":1,"e":"Entre circulaire interne et longitudinale externe. Contrôle la motilité.","s":6},{"q":"Organes intra-péritonéaux :","o":["Les reins et les surrénales","L'estomac, le jéjuno-iléon, le foie et la rate","Le pancréas et le duodénum, sauf sa 1ʳᵉ partie","L'aorte, la veine cave inférieure et les uretères pelviens"],"r":1,"e":"Intra-péritonéaux : estomac, jéjuno-iléon, cæcum, transverse, sigmoïde, foie, rate, vésicule. Le sigmoïde en fait aussi partie.","s":6},{"q":"Organes rétro-péritonéaux primitifs :","o":["Le foie et la vésicule biliaire","Les reins, les surrénales, les uretères et le rectum","L'estomac, le jéjunum, l'iléon et le côlon transverse","Le cæcum et l'appendice, mobiles"],"r":1,"e":"Reins, surrénales, uretères, gros vaisseaux, rectum sont rétro-péritonéaux primitifs. Les gros vaisseaux en font aussi partie.","s":6},{"q":"Organes rétro-péritonéaux secondaires :","o":["Le sigmoïde et le côlon transverse","Le duodénum, le pancréas et deux segments coliques","L'iléon terminal, le cæcum et l'appendice, mobiles","Le foie, la rate et l'estomac"],"r":1,"e":"Organes accolés par fascia : D2-D3-D4, pancréas, côlon ascendant et descendant. Ce sont les côlons ascendant et descendant ; le duodénum l'est sauf sa 1ʳᵉ partie.","s":6},{"q":"Tronc cœliaque naît à :","o":["T10","T12","L1","L3"],"r":1,"e":"T12, juste sous le hiatus aortique. 3 branches : gastrique gauche, splénique, hépatique commune.","s":6},{"q":"Artère mésentérique supérieure naît à :","o":["T12","L1","L3","L5"],"r":1,"e":"L1, 1 cm sous le tronc cœliaque. Vascularise D2 → 2/3 côlon transverse.","s":6},{"q":"Artère mésentérique inférieure naît à :","o":["T12","L1","L3","L5"],"r":2,"e":"L3, vascularise 1/3 gauche du transverse → rectum supérieur.","s":6},{"q":"Petit omentum est entre :","o":["L'estomac et le côlon transverse","La petite courbure de l'estomac et le foie","Le foie et le diaphragme, en haut et en arrière","Le côlon et la rate, à gauche"],"r":1,"e":"Gastro-hépatique. Contient gastrique gauche, voie biliaire et pédicule hépatique.","s":6},{"q":"Grand omentum descend de :","o":["Petite courbure de l'estomac","Grande courbure de l'estomac","Foie","Côlon transverse"],"r":1,"e":"« Tablier épiploïque » de la grande courbure gastrique. Rôle de défense (limite les infections).","s":6},{"q":"Foramen omental (de Winslow) communique :","o":["Le thorax avec l'abdomen, en arrière","La grande cavité péritonéale avec la bourse omentale","L'estomac et le duodénum, au pylore","Le foie et la rate, par le ligament gastro-splénique en arrière"],"r":1,"e":"Communique grande cavité et bourse omentale (derrière l'estomac). La bourse omentale est l'arrière-cavité des épiploons.","s":6},{"q":"Branches du tronc cœliaque :","o":["Deux, l'hépatique et la splénique","Trois, dont la gastrique gauche et la splénique","Quatre, avec la gastro-duodénale","Cinq, avec les deux artères diaphragmatiques"],"r":1,"e":"Trépied de Haller : gastrique gauche, splénique, hépatique commune. La troisième est l'hépatique commune.","s":6},{"q":"Veine porte se forme par réunion de :","o":["Deux veines hépatiques, droite et gauche","La mésentérique supérieure et le tronc spléno-mésaraïque","La veine cave supérieure et la mésentérique supérieure","L'aorte et la veine cave inférieure"],"r":1,"e":"VMS + tronc spléno-mésaraïque (= splénique + VMI). En arrière du col pancréatique.","s":6},{"q":"Parasympathique digestif (X) atteint :","o":["Tout le rectum, jusqu'à l'anus","Jusqu'à l'angle colique gauche","Uniquement l'estomac","Jusqu'à l'iléon terminal"],"r":1,"e":"Vague jusqu'à l'angle colique gauche. Au-delà : nerfs splanchniques pelviens (S2-S4). Au-delà, les nerfs splanchniques pelviens prennent le relais.","s":6},{"q":"Sympathique digestif :","o":["Il stimule la digestion et la motricité","Il inhibe la digestion et vasoconstricte","Il n'a aucun effet sur le tube digestif, même au stress","Il sécrète des enzymes digestives"],"r":1,"e":"Sympa = inhibe motilité et sécrétions, vasoconstriction. Para = stimule.","s":6},{"q":"Glandes salivaires principales :","o":["Deux paires, parotides et sub-linguales","Trois paires, parotides, sub-mandibulaires et sub-linguales","Quatre paires, avec les glandes palatines, labiales et jugales","Une seule paire, les parotides"],"r":1,"e":"3 paires + multiples glandes accessoires. Production ~1,5 L/jour.","s":6},{"q":"Volume salivaire quotidien :","o":["100 mL","500 mL","~1,5 L","5 L"],"r":2,"e":"~1,5 L/jour. 99% eau + amylase + mucines + IgA.","s":6},{"q":"Foie reçoit ~75% de son sang de :","o":["Artère hépatique","Veine porte","VCI","Aorte abdominale"],"r":1,"e":"75% veine porte (nutriments) + 25% artère hépatique (O₂).","s":6},{"q":"Mésentère contient :","o":["Le tronc cœliaque et ses trois branches","Les vaisseaux mésentériques supérieurs","L'artère hépatique propre","La voie biliaire principale"],"r":1,"e":"Mésentère = méso du jéjuno-iléon, contient l'AMS, ses branches, veines, lymphatiques, nerfs.","s":6},{"q":"Salive contient l'enzyme :","o":["La pepsine, active en milieu acide","L'amylase salivaire, ou ptyaline","La trypsine, pancréatique","La lipase pancréatique"],"r":1,"e":"Amylase salivaire → début de digestion des amidons.","s":6},{"q":"Le tube digestif est appelé « tube » entre :","o":["L'estomac et le rectum","La bouche et l'anus","Le foie et le pancréas","L'œsophage et le côlon"],"r":1,"e":"Tube continu de la bouche à l'anus. Glandes annexes : salivaires, foie, vésicule, pancréas.","s":6},{"q":"Le système nerveux entérique contient :","o":["10 millions de neurones",">100 millions de neurones","1000 neurones","Aucun neurone propre"],"r":1,"e":"« Cerveau de l'intestin ». >100M de neurones. Fonctionne en partie indépendamment du SNC.","s":6},{"q":"Mésocôlon transverse :","o":["Il suspend le rectum, dans le petit bassin","Il suspend le côlon transverse","Il suspend l'intestin grêle","Il suspend le foie"],"r":1,"e":"Méso du côlon transverse. Contient l'artère colique moyenne. Il contient l'artère colique moyenne.","s":6},{"q":"Couches musculaires du tube digestif (sauf estomac) :","o":["Une seule, circulaire et épaisse","Deux, circulaire interne et longitudinale externe","Trois, avec une oblique interne","Quatre, dont deux circulaires et deux longitudinales"],"r":1,"e":"2 couches. Estomac = exception, 3 couches (avec oblique interne).","s":6},{"q":"Anastomoses porto-caves principales :","o":["Trois, œsophagienne, ombilicale et recto-anale seules","Quatre, dont œsophagienne, ombilicale et recto-anale","Cinq, avec la splénique et la rénale","Deux, œsophagienne et ombilicale"],"r":1,"e":"4 anastomoses, importantes en cas d'HTP (cirrhose). La quatrième est rétro-péritonéale.","s":6},{"q":"Drainage lymphatique digestif terminal :","o":["La veine porte, puis le foie","Le canal thoracique, via la citerne du chyle","La veine cave supérieure, directement, sans relais ganglionnaire","Le foie, directement, par le hile"],"r":1,"e":"Tous les lymphatiques digestifs → ganglions lombo-aortiques → citerne du chyle → canal thoracique.","s":6},{"q":"Hormones digestives clés :","o":["Insuline, glucagon","Gastrine, sécrétine, CCK","FSH, LH","Cortisol"],"r":1,"e":"Gastrine (estomac), sécrétine (acide → bicarbonates), CCK (lipides → bile + enzymes pancr).","s":6},{"q":"GALT signifie :","o":["Glandular Adenoid Lymph Tissue","Gut-Associated Lymphoid Tissue","General Antibody Linked Tissue","Aucun"],"r":1,"e":"GALT = tissu lymphoïde associé à l'intestin (plaques de Peyer, follicules isolés, appendice).","s":6},{"q":"Le système digestif se définit comme l'ensemble des organes assurant :","o":["La digestion, l'absorption et l'élimination des déchets","La seule absorption, sans transformation ni élimination","La seule digestion chimique","Le seul transit intestinal"],"r":0,"e":"Il s'étend de la bouche à l'anus et comprend le tube digestif proprement dit et les glandes annexes.","s":6},{"q":"La digestion mécanique regroupe :","o":["La mastication, le brassage et le péristaltisme","L'hydrolyse enzymatique, par la salive et les sucs","L'absorption des nutriments","La sécrétion hormonale"],"r":0,"e":"La digestion chimique correspond, elle, à l'hydrolyse enzymatique par la salive, le suc gastrique, le suc pancréatique, la bile et les sucs intestinaux. La déglutition en fait aussi partie.","s":6},{"q":"L'absorption des nutriments se fait essentiellement :","o":["Dans l'estomac","Dans l'intestin grêle","Dans le côlon","Dans l'œsophage"],"r":1,"e":"Le passage se fait vers le sang ou la lymphe ; le côlon absorbe surtout eau et électrolytes.","s":6},{"q":"La fonction endocrine du tube digestif comprend la sécrétion de :","o":["La gastrine, la sécrétine et la cholécystokinine","L'insuline, le glucagon et la somatostatine, par l'estomac","Le cortisol et l'aldostérone","Les hormones thyroïdiennes"],"r":0,"e":"La fonction immunitaire est assurée par le GALT, tissu lymphoïde associé à la muqueuse.","s":6},{"q":"Les glandes salivaires principales sont :","o":["Les parotides, les sub-mandibulaires et les sub-linguales","Les parotides et les sub-linguales, sans les sub-mandibulaires","Les parotides, à elles seules","Les sub-mandibulaires et les accessoires"],"r":0,"e":"Elles font partie des glandes annexes, avec le foie et ses voies biliaires, la vésicule biliaire et le pancréas.","s":6},{"q":"La muqueuse du tube digestif comprend :","o":["L'épithélium, le chorion et la musculaire muqueuse","L'épithélium et la sous-muqueuse","La musculeuse et la séreuse, avec le plexus d'Auerbach","Le chorion et l'adventice"],"r":0,"e":"Elle constitue la première des quatre tuniques, de l'intérieur vers l'extérieur.","s":6},{"q":"La sous-muqueuse contient :","o":["Du conjonctif lâche, des vaisseaux et le plexus de Meissner","Le plexus d'Auerbach, ou myentérique","Deux couches musculaires lisses","Le péritoine viscéral, avec la séreuse et le tissu graisseux"],"r":0,"e":"Le plexus d'Auerbach, ou myentérique, siège entre les deux couches de la musculeuse. Elle contient aussi des lymphatiques.","s":6},{"q":"La musculeuse comporte généralement :","o":["Une couche circulaire interne et longitudinale externe","Une couche longitudinale interne et circulaire externe","Trois couches, sur toute la longueur","Une seule couche, circulaire, qui assure seule le péristaltisme"],"r":0,"e":"L'estomac fait exception avec sa couche oblique supplémentaire.","s":6},{"q":"La quatrième tunique est une séreuse ou une adventice selon que l'organe est :","o":["Intra-péritonéal ou rétro-péritonéal","Proximal ou distal, par rapport à l'estomac","Fixe ou mobile dans l'abdomen","Vascularisé ou non, selon le segment"],"r":0,"e":"Les organes intra-péritonéaux sont recouverts de péritoine viscéral, les rétro-péritonéaux d'adventice.","s":6},{"q":"Le système nerveux entérique compte :","o":["Plus de 100 millions de neurones","Environ 1 million de neurones","Environ 10 000 neurones","Un milliard de neurones"],"r":0,"e":"Réunissant les plexus de Meissner et d'Auerbach, il est surnommé le « cerveau de l'intestin » et fonctionne en partie indépendamment du système nerveux central.","s":6},{"q":"La cavité péritonéale est :","o":["Un espace virtuel entre deux feuillets, avec peu de liquide","Une grande cavité, remplie de plusieurs litres de liquide","Un espace inexistant, sans liquide ni feuillet","Un organe plein, entre le foie et l'intestin"],"r":0,"e":"Elle est fermée chez l'homme et communique avec l'extérieur chez la femme par les trompes.","s":6},{"q":"Parmi les organes rétro-péritonéaux primitifs figurent :","o":["Les reins, les surrénales, les uretères et l'aorte","Le duodénum et le pancréas, accolés à la paroi","Les côlons ascendant et descendant","L'estomac et la rate, mobiles"],"r":0,"e":"Duodénum, pancréas, côlons ascendant et descendant sont rétro-péritonéaux secondaires, donc accolés. L'œsophage abdominal et le rectum en font aussi partie.","s":6},{"q":"Les mésos se définissent comme :","o":["Des doubles feuillets reliant un organe à la paroi postérieure","Des ligaments du foie, vers le diaphragme","Des replis de la muqueuse de l'estomac","Des adhérences pathologiques, apparues après une opération abdominale"],"r":0,"e":"Ils contiennent les pédicules vasculo-nerveux : mésentère, mésocôlons transverse et sigmoïde, mésoappendice. Ces feuillets sont péritonéaux.","s":6},{"q":"Le petit omentum contient :","o":["La gastrique gauche, la veine porte et la voie biliaire","Le pancréas et le duodénum, en arrière","La rate et les vaisseaux courts","L'artère mésentérique supérieure et ses branches jéjunales"],"r":0,"e":"Il s'étend entre la petite courbure de l'estomac et le foie ; son bord libre constitue le ligament hépato-duodénal, qui contient le pédicule hépatique. La voie biliaire est la voie biliaire principale.","s":6},{"q":"Le rôle attribué au grand omentum est :","o":["La défense, en limitant les infections par adhérences","La vascularisation du côlon transverse et du côlon sigmoïde","Le soutien du foie, en haut","La production de liquide péritonéal"],"r":0,"e":"Il descend de la grande courbure de l'estomac comme un tablier.","s":6},{"q":"Le ligament falciforme relie :","o":["Le foie à la paroi abdominale antérieure","Le foie au diaphragme, en arrière","L'estomac à la rate, par la grande courbure gauche","Le duodénum au foie, au hile"],"r":0,"e":"Les ligaments coronaire et triangulaires relient, eux, le foie au diaphragme.","s":6},{"q":"L'arrière-cavité des épiploons se situe :","o":["Derrière l'estomac","Devant l'estomac","Sous le foie","Dans le pelvis"],"r":0,"e":"Elle communique avec la grande cavité par le foramen omental, ou de Winslow.","s":6},{"q":"Le tronc cœliaque vascularise :","o":["L'estomac, le foie, la rate et le pancréas","Le côlon descendant et le rectum","Le jéjunum et l'iléon, en totalité","Le rectum inférieur et le canal anal, par les branches iliaques"],"r":0,"e":"Il naît en T12 et donne les artères gastrique gauche, splénique et hépatique commune. L'œsophage abdominal et le premier duodénum en dépendent aussi.","s":6},{"q":"L'artère mésentérique supérieure vascularise :","o":["Du 2ᵉ duodénum aux deux tiers du côlon transverse","L'estomac et la rate, avec les vaisseaux gastriques courts","Le 1/3 gauche du côlon transverse et le rectum","Le foie, par l'artère hépatique"],"r":0,"e":"Elle naît en L1 ; l'artère mésentérique inférieure naît en L3 et prend le relais jusqu'au rectum supérieur.","s":6},{"q":"Le foie reçoit environ quelle part de son sang par la veine porte ?","o":["25 %","50 %","75 %","100 %"],"r":2,"e":"Le sang veineux des organes digestifs sous-diaphragmatiques y converge ; le reste provient de l'artère hépatique.","s":6},{"q":"Longueur de l'œsophage :","o":["15 cm","25 cm","40 cm","60 cm"],"r":1,"e":"~25 cm. De C6 à T11.","s":7},{"q":"Niveau de début de l'œsophage :","o":["En C2, sous la mandibule","En C6, au bord du cricoïde","En T2, derrière le manubrium","En T5, au niveau de la bifurcation trachéale"],"r":1,"e":"C6. Niveau du cartilage cricoïde.","s":7},{"q":"Hiatus œsophagien diaphragmatique :","o":["T8","T10","T12","L2"],"r":1,"e":"V8-Œ10-A12 : VCI à T8, Œsophage à T10, Aorte à T12.","s":7},{"q":"Épithélium œsophagien :","o":["Cubique simple, en une couche","Pavimenteux stratifié non kératinisé","Cylindrique simple, avec des villosités","Cilié, comme celui des bronches et de la trachée"],"r":1,"e":"Pavimenteux stratifié → résistance mécanique (bol alimentaire).","s":7},{"q":"Musculeuse œsophagienne dans le 1/3 supérieur :","o":["Lisse","Striée","Cardiaque","Mixte"],"r":1,"e":"Strié dans le 1/3 sup, mixte au milieu, lisse dans le 1/3 inf.","s":7},{"q":"SOI (sphincter œsophagien inférieur) :","o":["Anatomique, avec un vrai muscle annulaire","Fonctionnel, sans vrai sphincter anatomique","Strié et volontaire, comme au cou","Inexistant chez l'adulte"],"r":1,"e":"SOI = système anti-reflux fonctionnel (tonus + angle de His). Pas de sphincter anatomique vrai.","s":7},{"q":"Rétrécissements œsophagiens physiologiques :","o":["Deux, cricoïdien et diaphragmatique","Trois, sans le bronchique","Quatre, du cricoïde au diaphragme","Cinq, avec le cardia et le pylore, en bas"],"r":2,"e":"4 : C6 (cricoïdien), T4 (aortique), T5 (bronchique), T10 (diaphragmatique). Ce sont les rétrécissements cricoïdien, aortique, bronchique et diaphragmatique.","s":7},{"q":"Cavité buccale :","o":["Un seul espace, continu, sans limite","Deux, le vestibule et la cavité proprement dite","Trois, avec le pharynx buccal","Quatre, avec les deux loges amygdaliennes et le pharynx"],"r":1,"e":"Vestibule (entre lèvres et dents) + cavité proprement dite (en arrière des dents).","s":7},{"q":"Palais dur =","o":["Le tiers antérieur du palais","Les deux tiers antérieurs, à support osseux","Les deux tiers postérieurs, musculaires","Tout le palais, de l'avant à l'arrière"],"r":1,"e":"Palais dur = 2/3 ant osseux. Palais mou = 1/3 post musculo-membraneux.","s":7},{"q":"Dentition définitive comporte :","o":["20 dents","28 dents","32 dents","36 dents"],"r":2,"e":"32 dents adultes (2I + 1C + 2PM + 3M par hémi-arcade × 4).","s":7},{"q":"Canal de Sténon est le canal de :","o":["Parotide","Sub-mandibulaire","Sub-linguale","Lacrymale"],"r":0,"e":"Sténon = parotide. Wharton = sub-mandibulaire. Rivinus = sub-linguale.","s":7},{"q":"Canal de Wharton est le canal de :","o":["Parotide","Sub-mandibulaire","Sub-linguale","Pancréatique"],"r":1,"e":"Wharton = sub-mandibulaire. S'ouvre sous la langue à côté du frein.","s":7},{"q":"Parotide est traversée par :","o":["Le nerf trijumeau, ou V","Le nerf facial, ou VII","Le nerf vague, ou X","Le nerf phrénique, ou C4"],"r":1,"e":"Nerf VII (facial) traverse la parotide. Risque de paralysie faciale en chirurgie.","s":7},{"q":"Nerf moteur de la langue :","o":["Trijumeau (V)","Facial (VII)","Glosso-pharyngien (IX)","Hypoglosse (XII)"],"r":3,"e":"XII innerve tous les muscles de la langue (intrinsèques + extrinsèques sauf palato-glosse).","s":7},{"q":"Goût des 2/3 antérieurs de la langue :","o":["Glosso-pharyngien","Corde du tympan (VII)","Lingual (V3)","Hypoglosse"],"r":1,"e":"Goût 2/3 ant : corde du tympan (VII). Sensibilité tactile 2/3 ant : V3.","s":7},{"q":"Goût et sensibilité du 1/3 postérieur de la langue :","o":["Le VII, ou nerf facial","Le IX, ou glosso-pharyngien","Le V3, ou nerf mandibulaire, sensitif","Le XII, ou hypoglosse"],"r":1,"e":"IX assure goût et sensibilité 1/3 postérieur.","s":7},{"q":"Pharynx a 3 régions :","o":["Supérieure, moyenne et inférieure, sans autre nom","Nasopharynx, oropharynx et laryngopharynx","Antérieure, moyenne et postérieure","Externe, interne et profonde"],"r":1,"e":"3 étages : nasopharynx (sus-palais mou), oropharynx, laryngopharynx.","s":7},{"q":"La déglutition comporte :","o":["Deux temps, buccal et pharyngé","Trois temps, buccal, pharyngé et œsophagien","Quatre temps, avec la mastication du bol","Cinq temps, avec l'apnée et la toux"],"r":1,"e":"3 temps. Buccal volontaire, pharyngé et œsophagien réflexes. Le buccal est volontaire, les deux autres réflexes.","s":7},{"q":"Vascularisation principale de l'œsophage thoracique :","o":["Les artères thyroïdiennes inférieures, au cou","Des artères œsophagiennes directes de l'aorte","L'artère gastrique gauche","L'artère hépatique commune"],"r":1,"e":"Œsophage thoracique : aorte directement. Cervical : thyroïdiennes inf. Abdominal : gastrique gauche.","s":7},{"q":"RGO (reflux gastro-œsophagien) est lié à :","o":["Une hyperpepsie gastrique","Une hypotonie du SOI","Une hypertonie du SOS pharyngé","Une hypersécrétion biliaire"],"r":1,"e":"Hypotonie du SOI → reflux acide. Aggravé par hernie hiatale.","s":7},{"q":"Hernie hiatale =","o":["Une hernie ombilicale, du nombril","Une ascension de l'estomac par le hiatus","Une hernie inguinale, par le canal inguinal de l'aine","Une hernie congénitale du diaphragme"],"r":1,"e":"Passage anormal de l'estomac à travers le hiatus œsophagien. Favorise le RGO.","s":7},{"q":"Anneau de Waldeyer comprend :","o":["Les deux amygdales palatines","Les amygdales pharyngée, tubaires, palatines et linguale","Les ganglions cervicaux profonds","Les glandes salivaires, parotides et sub-mandibulaires comprises"],"r":1,"e":"Tissu lymphoïde au carrefour aéro-digestif.","s":7},{"q":"Réflexe protecteur du larynx :","o":["Bâillement","Réflexe de toux","Hoquet","Éternuement"],"r":1,"e":"Toux = réflexe protecteur contre l'aspiration de corps étrangers.","s":7},{"q":"Apnée déglutitive est nécessaire :","o":["Pour ralentir le cœur, par un réflexe vagal marqué","Pour éviter une fausse route vers le larynx","Pour économiser l'oxygène","Pour mieux mastiquer le bol"],"r":1,"e":"Pendant la phase pharyngée, l'épiglotte se rabat et la respiration est suspendue.","s":7},{"q":"Œsophage abdominal est :","o":["~2 cm","5 cm","10 cm","15 cm"],"r":0,"e":"Très court : environ 2 cm, du hiatus œsophagien du diaphragme (T10) au cardia (T11). L'œsophage entier mesure environ 25 cm, mais sa portion abdominale est minime.","s":7},{"q":"Le SOI est sous contrôle :","o":["Volontaire, par un muscle strié","Involontaire, par un muscle lisse","Mixte, lisse et strié","Aucun contrôle, il reste toujours ouvert"],"r":1,"e":"Lisse, involontaire. Le SOS (sphincter sup) est strié, volontaire.","s":7},{"q":"Achalasie :","o":["Hypotonie du SOI","Défaut de relaxation du SOI","Inflammation pharyngée","Ulcère"],"r":1,"e":"Achalasie = SOI ne se relâche pas → dysphagie, dilatation œsophagienne en amont.","s":7},{"q":"Onde péristaltique œsophagienne dure :","o":["2 minutes","~5-6 secondes","1 minute","30 secondes"],"r":1,"e":"Onde péristaltique primaire propulse le bol en ~5-6 s.","s":7},{"q":"Varices œsophagiennes causées par :","o":["Une hypertension artérielle, sévère et ancienne","Une hypertension portale, dans la cirrhose","Une insuffisance respiratoire","Un diabète déséquilibré"],"r":1,"e":"Anastomose porto-cave œsophagienne se dilate en cas d'HTP. Risque hémorragique majeur.","s":7},{"q":"Sphincter œsophagien supérieur (SOS) =","o":["Un muscle lisse, involontaire","Le crico-pharyngien, muscle strié","Le diaphragme, par ses piliers droit et gauche","Le cardia, à l'entrée de l'estomac"],"r":1,"e":"Crico-pharyngien, strié, volontaire. Niveau C6.","s":7},{"q":"Le vestibule buccal correspond :","o":["À l'espace entre les lèvres, les joues et les dents","À l'espace en arrière des arcades dentaires","Au palais, dur en avant et mou en arrière, au plafond","Au plancher buccal, sous la langue"],"r":0,"e":"La cavité buccale proprement dite se situe en arrière des arcades dentaires et contient la langue.","s":7},{"q":"Le plancher de la cavité buccale est formé par :","o":["Les muscles mylo-hyoïdiens et la langue","Le palais mou et la luette","Les joues et les lèvres, en dehors","L'isthme du gosier, entre les piliers du voile du palais"],"r":0,"e":"Le toit est formé du palais dur sur les deux tiers antérieurs et du palais mou sur le tiers postérieur.","s":7},{"q":"La langue mesure chez l'adulte environ :","o":["5 cm","10 cm","15 cm","20 cm"],"r":1,"e":"C'est un organe musculaire impair, médian et mobile, constitué de muscles striés squelettiques.","s":7},{"q":"Les papilles linguales les plus nombreuses sont :","o":["Les filiformes, qui sont sensitives","Les fungiformes, qui sont gustatives, en surface","Les caliciformes, en V","Les foliées, sur les bords"],"r":0,"e":"Les fungiformes, caliciformes et foliées sont gustatives ; les caliciformes se disposent en V à la limite corps/base.","s":7},{"q":"Les muscles intrinsèques de la langue, au nombre de quatre paires :","o":["Modifient la forme de la langue","Mobilisent la langue en bloc","Assurent la déglutition","Ferment la glotte"],"r":0,"e":"Ce sont les longitudinaux supérieur et inférieur, le transverse et le vertical ; les extrinsèques mobilisent la langue.","s":7},{"q":"Parmi les muscles extrinsèques de la langue figurent :","o":["Le génio-glosse, l'hyo-glosse et le stylo-glosse","Le longitudinal supérieur et inférieur","Le transverse de la langue","Le vertical et le transverse, à l'intérieur de la langue"],"r":0,"e":"Ils mobilisent la langue, alors que les intrinsèques en modifient la forme. Le palato-glosse en fait aussi partie.","s":7},{"q":"La sensibilité tactile des deux tiers antérieurs de la langue dépend :","o":["Du nerf lingual, branche du V3","De la corde du tympan, branche du VII","Du IX, sur le 1/3 postérieur de la langue","De l'hypoglosse, ou XII"],"r":0,"e":"Le goût des deux tiers antérieurs dépend de la corde du tympan, branche du VII.","s":7},{"q":"La dentition de lait comporte :","o":["20 dents","28 dents","32 dents","24 dents"],"r":0,"e":"Elle apparaît entre 6 mois et 2 ans ; la dentition définitive compte 32 dents.","s":7},{"q":"La formule dentaire de l'adulte par hémi-arcade est :","o":["2 incisives, 1 canine, 2 prémolaires et 3 molaires","2 incisives, 2 canines, 2 prémolaires et 2 molaires","1 incisive, 1 canine, 3 prémolaires et 3 molaires","3 incisives, 1 canine, 2 prémolaires et 2 molaires"],"r":0,"e":"Soit 8 dents par hémi-arcade et 32 au total.","s":7},{"q":"Le composant principal de la dent est :","o":["L'émail, sur toute la couronne","La dentine, ou ivoire, sous l'émail","Le cément, sur la racine","La pulpe, au centre de la dent"],"r":1,"e":"L'émail recouvre la couronne, le cément la racine, et la pulpe centrale est vasculaire et nerveuse.","s":7},{"q":"La parotide pèse environ :","o":["5 g","10 g","25 g","50 g"],"r":2,"e":"C'est la plus volumineuse des glandes salivaires ; elle est traversée par le nerf facial.","s":7},{"q":"La sécrétion de la glande sub-mandibulaire est :","o":["Essentiellement séreuse","Mixte, séreuse et muqueuse","Essentiellement muqueuse","Purement aqueuse, sans protéines"],"r":1,"e":"La parotide a une sécrétion essentiellement séreuse et la sub-linguale essentiellement muqueuse.","s":7},{"q":"Les canaux de Rivinus appartiennent à :","o":["La parotide","La glande sub-mandibulaire","La glande sub-linguale","Les glandes accessoires"],"r":2,"e":"Ce sont de multiples petits canaux qui s'ouvrent sous la langue ; le canal de Sténon appartient à la parotide et celui de Wharton à la sub-mandibulaire.","s":7},{"q":"La salive est composée de :","o":["99 % d'eau, avec des enzymes, des mucines et des IgA","50 % d'eau, avec des protéines et des graisses","D'eau et d'amylase, uniquement","D'eau et de mucines, avec des IgG"],"r":0,"e":"Ses rôles sont l'humidification, la lubrification, le début de la digestion des amidons, la protection antibactérienne et la gustation. Elle contient aussi des électrolytes.","s":7},{"q":"Le laryngopharynx, ou hypopharynx, se situe :","o":["Derrière les choanes, en haut","Derrière la cavité buccale, en dessous du voile","Derrière le larynx, en continuité avec l'œsophage","Au-dessus du palais mou, en arrière"],"r":2,"e":"Le nasopharynx est derrière les choanes et l'oropharynx derrière la cavité buccale.","s":7},{"q":"Les muscles constricteurs du pharynx :","o":["Rétrécissent le pharynx et propulsent le bol","Élèvent le pharynx et le larynx pendant la déglutition","Ferment la glotte, par réflexe","Ouvrent le sphincter œsophagien"],"r":0,"e":"Les muscles élévateurs — stylo-pharyngien, palato-pharyngien et salpingo-pharyngien — élèvent le pharynx pendant la déglutition.","s":7},{"q":"Lors du temps pharyngé de la déglutition :","o":["Le voile s'élève et le larynx monte, sous l'épiglotte","La langue pousse le bol vers l'arrière","Le péristaltisme œsophagien démarre","Le sphincter œsophagien inférieur s'ouvre, puis se referme"],"r":0,"e":"C'est un temps réflexe, contrairement au temps buccal qui est volontaire. L'épiglotte se rabat et le nasopharynx est fermé.","s":7},{"q":"Le centre de la déglutition se situe :","o":["Dans le cortex frontal","Dans le bulbe rachidien","Dans le cervelet","Dans la moelle cervicale"],"r":1,"e":"Les nerfs V, VII, IX, X et XII y participent, respectivement pour la sensibilité, le palais, l'oropharynx, la motricité pharyngo-œsophagienne et la langue.","s":7},{"q":"L'œsophage s'étend de :","o":["C6 à T11","C4 à T8","T1 à T12","C6 à T8"],"r":0,"e":"Il mesure 25 cm et se divise en portions cervicale (5 cm), thoracique (18 cm) et abdominale.","s":7},{"q":"L'œsophage se distingue des autres segments du tube digestif par :","o":["L'absence de séreuse, sauf sur sa partie abdominale","L'absence de musculeuse, sur toute sa longueur","L'absence de muqueuse, remplacée par la peau","La présence de trois couches musculaires, comme l'estomac"],"r":0,"e":"C'est pourquoi il n'a pas véritablement de mésos.","s":7},{"q":"Capacité de l'estomac :","o":["100 mL","500 mL","1-4 L","10 L"],"r":2,"e":"1-4 L selon réplétion. Volume vide ~50 mL.","s":8},{"q":"4 portions de l'estomac :","o":["Tête, corps, queue","Cardia, fundus, corps, antre pylorique","Petit, moyen, grand","Antérieur, postérieur, médial, latéral"],"r":1,"e":"Cardia (entrée) → fundus → corps → antre → pylore (sortie).","s":8},{"q":"pH gastrique :","o":["7,4","5-6","1-2 (très acide)","8 (alcalin)"],"r":2,"e":"pH 1-2, très acide grâce au HCl des cellules pariétales.","s":8},{"q":"Cellules pariétales (bordantes) sécrètent :","o":["Du pepsinogène, activé ensuite par l'HCl","De l'HCl et du facteur intrinsèque","Du mucus protecteur","De la gastrine, en circulation"],"r":1,"e":"Cellules pariétales = HCl + facteur intrinsèque (absorption B12). Le facteur intrinsèque permet l'absorption de la vitamine B12.","s":8},{"q":"Cellules principales sécrètent :","o":["HCl","Pepsinogène","Gastrine","Somatostatine"],"r":1,"e":"Cellules principales (zymogéniques) = pepsinogène → activé en pepsine par l'acide.","s":8},{"q":"Gastrine est sécrétée par :","o":["Cellules pariétales","Cellules G de l'antre","Cellules principales","Hépatocytes"],"r":1,"e":"Cellules G antrales → gastrine → ↑ sécrétion d'HCl par les pariétales.","s":8},{"q":"Estomac dans la cavité abdominale :","o":["Rétro-péritonéal","Intra-péritonéal","Mésopéritonéal","Extra-péritonéal"],"r":1,"e":"Intra-péritonéal. Suspendu par petit/grand omentum, ligaments gastro-spléniques et phréniques.","s":8},{"q":"Particularité musculaire de l'estomac :","o":["Une seule couche, épaisse et circulaire","Deux couches, comme le reste du tube","Trois couches, avec une oblique interne","Quatre couches, dont deux obliques"],"r":2,"e":"3 couches : longitudinale externe + circulaire moyenne + oblique interne (caractéristique gastrique).","s":8},{"q":"Vagotomie diminue :","o":["Sécrétion biliaire","Sécrétion gastrique acide","Absorption","Péristaltisme intestinal"],"r":1,"e":"Para → ↑ acide. Vagotomie → ↓ HCl (traitement ancien de l'ulcère).","s":8},{"q":"Helicobacter pylori cause :","o":["Hépatite","Gastrite et ulcère","Cholécystite","Pancréatite"],"r":1,"e":"H. pylori = principale cause d'ulcère gastro-duodénal et de cancer gastrique.","s":8},{"q":"Sécrétion acide quotidienne :","o":["100 mL","500 mL","2-3 L","10 L"],"r":2,"e":"2-3 L/jour. Riche en HCl, pepsinogène, mucus, facteur intrinsèque.","s":8},{"q":"Pepsinogène est activé en pepsine par :","o":["Les bicarbonates du suc pancréatique","L'acide chlorhydrique du suc gastrique","La trypsine, déjà active","La lipase gastrique"],"r":1,"e":"Acidité → conversion en pepsine. Digestion protéique.","s":8},{"q":"Phases de sécrétion gastrique :","o":["Deux, céphalique et gastrique","Trois, céphalique, gastrique et intestinale","Quatre, avec une phase hormonale","Cinq, une par segment du tube digestif haut"],"r":1,"e":"Céphalique (vue/odeur), gastrique (distension), intestinale (modulation négative).","s":8},{"q":"Petite courbure reçoit :","o":["Grand omentum","Petit omentum","Mésocôlon","Aucun"],"r":1,"e":"Petite courbure → petit omentum (gastro-hépatique). Grande courbure → grand omentum.","s":8},{"q":"Artère gastrique gauche naît de :","o":["Le tronc cœliaque, directement","L'aorte abdominale, directement","L'artère splénique, le long du pancréas","L'artère mésentérique supérieure"],"r":0,"e":"Gastrique gauche = branche directe du tronc cœliaque. Suit la petite courbure.","s":8},{"q":"Vasa brevia viennent de :","o":["Gastrique gauche","Splénique","Hépatique","Gastro-duodénale"],"r":1,"e":"Artères courtes (vasa brevia) issues de la splénique → vascularisent le fundus.","s":8},{"q":"Pylore est sur :","o":["Estomac avec œsophage","Estomac avec duodénum","Estomac avec côlon","Estomac avec rate"],"r":1,"e":"Pylore = sphincter entre antre gastrique et duodénum.","s":8},{"q":"Cardia est la jonction :","o":["Œsophage-estomac","Estomac-duodénum","Duodénum-jéjunum","Iléon-cæcum"],"r":0,"e":"Cardia = jonction œso-gastrique. Niveau T11.","s":8},{"q":"Sécrétine est libérée par :","o":["L'estomac, face à la distension","Le duodénum, en réponse à l'acidité","Le foie, avec la bile","La rate, en continu"],"r":1,"e":"Sécrétine duodénale → ↑ sécrétion pancréatique de bicarbonates.","s":8},{"q":"Cellules mucipares produisent :","o":["HCl","Pepsinogène","Mucus protecteur","Gastrine"],"r":2,"e":"Mucus + bicarbonates → barrière physico-chimique protégeant la muqueuse.","s":8},{"q":"Évacuation gastrique : liquides vs solides :","o":["Les solides d'abord, puis les liquides","Les liquides d'abord, les solides après fragmentation","Les deux en même temps, mélangés","Selon le pH du repas, quelle que soit sa consistance réelle"],"r":1,"e":"Liquides évacués les premiers. Solides nécessitent une fragmentation en chyme.","s":8},{"q":"Absorption au niveau de l'estomac :","o":["Le glucose, par des transporteurs actifs de la muqueuse","Les acides aminés, libres","L'alcool, l'aspirine et certains médicaments","Les lipides, émulsionnés"],"r":2,"e":"Pas d'absorption significative sauf alcool et certains médicaments. Ces médicaments sont liposolubles.","s":8},{"q":"Rapport postérieur de l'estomac :","o":["Le foie, par son lobe gauche et le lobe caudé","Le pancréas, à travers la bourse omentale","Le rectum, dans le petit bassin","La vessie, en avant du sacrum"],"r":1,"e":"En arrière : arrière-cavité des épiploons, puis pancréas (corps), rate, rein gauche.","s":8},{"q":"Cellules entérochromaffines (ECL) sécrètent :","o":["HCl","Histamine","Gastrine","Pepsinogène"],"r":1,"e":"ECL → histamine → stimule les cellules pariétales (HCl). Cible des anti-H2.","s":8},{"q":"Forme de l'estomac vide :","o":["Une forme sphérique","Une forme de « J » majuscule","Une forme cylindrique","Une forme rectangulaire"],"r":1,"e":"« J » en position debout. Variable selon réplétion.","s":8},{"q":"Incisure angulaire =","o":["Un repère sur la grande courbure","La limite corps-antre sur la petite courbure","Un repère au niveau du cardia","Un repère sur la face postérieure, près du pancréas"],"r":1,"e":"Incisure angulaire de la petite courbure = limite anatomique entre corps et antre.","s":8},{"q":"Angle de His :","o":["L'angle entre fundus et œsophage, anti-reflux","L'angle de la grande courbure","L'angle pylorique, vers le bulbe duodénal","L'angle splénique du côlon"],"r":0,"e":"Incisure cardiale (angle de His) : rôle anti-reflux.","s":8},{"q":"Pli muqueux à vide :","o":["Des valvules conniventes, transversales","Des rugæ, plis longitudinaux","Des haustrations, entre tæniæ","Des tæniæ coli, bandelettes"],"r":1,"e":"Rugæ gastriques disparaissent à la réplétion.","s":8},{"q":"Vidange gastrique d'un repas normal :","o":["30 minutes","2-4 heures","10 heures","24 heures"],"r":1,"e":"2-4h. Plus rapide pour les liquides et glucides. Plus lente pour les lipides.","s":8},{"q":"Facteur intrinsèque permet l'absorption de :","o":["Du fer, au duodénum, en D1","Du calcium, sous l'effet de la PTH","De la vitamine B12, à l'iléon terminal","De la vitamine D, au jéjunum proximal"],"r":2,"e":"FI lie B12 → absorbée dans l'iléon terminal. Carence → anémie pernicieuse (Biermer).","s":8},{"q":"Le volume de l'estomac à vide est d'environ :","o":["50 mL","200 mL","500 mL","1 L"],"r":0,"e":"Sa capacité atteint 1 à 4 litres selon la réplétion.","s":8},{"q":"L'estomac se situe :","o":["Dans l'hypochondre gauche et l'épigastre","Dans l'hypochondre droit","Dans la région ombilicale, sous le côlon transverse","Dans l'hypogastre, au-dessus de la vessie"],"r":0,"e":"C'est un organe creux intra-péritonéal, en forme de « J » majuscule en position debout.","s":8},{"q":"Le fundus gastrique se caractérise par :","o":["Un dôme gauche sous le diaphragme, avec une poche à air","Une portion horizontale terminale, juste avant le pylore","La jonction avec l'œsophage, en T11","La jonction avec le duodénum, au pylore"],"r":0,"e":"Le cardia est la jonction œsophagienne en T11 et l'antre pylorique la portion horizontale terminale.","s":8},{"q":"La grande courbure de l'estomac reçoit :","o":["Le petit omentum et le ligament hépato-duodénal du foie","Le grand omentum et les ligaments vers la rate et le côlon","Le ligament falciforme du foie","Le mésocôlon transverse et le mésentère"],"r":1,"e":"La petite courbure, concave et à droite, reçoit le petit omentum. Ce sont les ligaments gastro-splénique et gastro-colique.","s":8},{"q":"L'angle de His correspond à :","o":["L'incisure cardiale, entre œsophage et fundus","L'incisure angulaire, sur la petite courbure","Le pylore, à la sortie de l'estomac vers le duodénum","Le cardia lui-même, en T11"],"r":0,"e":"L'incisure angulaire, sur la petite courbure, marque la limite corps/antre. Il joue un rôle anti-reflux.","s":8},{"q":"Les rugæ gastriques sont :","o":["Des plis longitudinaux qui disparaissent à la réplétion","Des glandes de la muqueuse fundique","Des villosités, comme dans l'intestin grêle, très nombreuses","Des replis péritonéaux de la séreuse"],"r":0,"e":"Le sphincter pylorique, épaississement musculaire annulaire, contrôle le passage vers le duodénum. Ils sont présents à vide.","s":8},{"q":"En arrière, l'estomac répond, à travers l'arrière-cavité des épiploons, à :","o":["Le pancréas, la rate, le rein gauche et le tronc cœliaque","Le lobe gauche du foie, en avant","La paroi abdominale antérieure","Le côlon transverse et le grand omentum, en bas et en avant"],"r":0,"e":"En bas il répond au côlon transverse et au grand omentum, en avant au lobe gauche du foie. La surrénale gauche et l'aorte en font aussi partie.","s":8},{"q":"L'artère gastrique droite, ou pylorique, est une branche de :","o":["L'artère splénique","L'artère hépatique commune","Le tronc cœliaque directement","L'artère mésentérique supérieure"],"r":1,"e":"L'artère gastrique gauche est, elle, une branche directe du tronc cœliaque.","s":8},{"q":"L'artère gastro-épiploïque droite est une branche de :","o":["L'artère gastro-duodénale","L'artère splénique","Le tronc cœliaque","L'artère mésentérique supérieure"],"r":0,"e":"La gastro-épiploïque gauche naît, elle, de l'artère splénique ; ensemble elles forment le cercle de la grande courbure.","s":8},{"q":"L'innervation sympathique de l'estomac provient :","o":["Du nerf vague, ou X","Du plexus cœliaque, de T5 à T9","Du nerf phrénique, de C3 à C5","Du plexus mésentérique, de T10 à L2"],"r":1,"e":"Elle inhibe la digestion, provoque une vasoconstriction et véhicule la sensibilité douloureuse.","s":8},{"q":"Les cellules D de la muqueuse gastrique sécrètent :","o":["La gastrine","La somatostatine","L'histamine","Le pepsinogène"],"r":1,"e":"Les cellules G de l'antre sécrètent la gastrine et les cellules ECL l'histamine.","s":8},{"q":"La musculeuse gastrique se distingue par :","o":["Trois couches, dont une oblique interne","Deux couches seulement, comme ailleurs","Une seule couche, circulaire","Une couche oblique externe, en plus"],"r":0,"e":"La couche oblique interne est caractéristique de l'estomac. Ce sont la longitudinale externe, la circulaire moyenne et l'oblique interne.","s":8},{"q":"Le volume de la sécrétion gastrique est de :","o":["0,5 L/jour","1 L/jour","2 à 3 L/jour","5 L/jour"],"r":2,"e":"Elle comprend eau, HCl, pepsinogène, facteur intrinsèque, mucus et électrolytes, pour un pH de 1 à 2.","s":8},{"q":"La phase céphalique de la sécrétion gastrique est déclenchée par :","o":["La vue, l'odeur et la pensée des aliments","La distension gastrique, par l'arrivée du bol alimentaire","L'arrivée du chyme dans le duodénum","La gastrine circulante, seule"],"r":0,"e":"La phase gastrique repose sur la distension et la gastrine, la phase intestinale étant surtout inhibitrice. Elle passe par le nerf vague.","s":8},{"q":"La phase intestinale de la sécrétion gastrique est :","o":["Purement stimulatrice, du début à la fin du repas","Brièvement stimulatrice, puis surtout inhibitrice","Sans aucun effet sur l'estomac","Identique à la phase gastrique"],"r":1,"e":"Ce rétrocontrôle adapte la vidange gastrique aux capacités duodénales. L'inhibition survient quand le chyme arrive dans le duodénum.","s":8},{"q":"Le stockage alimentaire dans l'estomac repose sur :","o":["La relaxation réceptive du fundus","Les contractions antrales","L'ouverture du pylore","Le péristaltisme œsophagien"],"r":0,"e":"Le brassage est assuré par les contractions antrales et l'évacuation par le pylore.","s":8},{"q":"La digestion des triglycérides dans l'estomac est assurée par :","o":["La pepsine, en milieu acide","La lipase gastrique, de façon mineure","L'amylase salivaire, qui continue d'agir","La trypsine, venue du pancréas par reflux"],"r":1,"e":"La pepsine, active en milieu acide, amorce la digestion des protéines.","s":8},{"q":"L'absorption gastrique est significative uniquement pour :","o":["L'alcool et l'aspirine","Les glucides simples","Les protéines","Les lipides"],"r":0,"e":"L'absorption des nutriments a lieu essentiellement dans l'intestin grêle.","s":8},{"q":"Le renouvellement de l'épithélium gastrique se fait en :","o":["24 heures","3 à 5 jours","2 semaines","1 mois"],"r":1,"e":"Il participe à la protection muqueuse, avec la barrière mucus-bicarbonates et les prostaglandines.","s":8},{"q":"L'ulcère gastro-duodénal résulte d'un déséquilibre entre :","o":["Les facteurs agressifs et les facteurs de défense","Le sympathique et le parasympathique","La gastrine et la somatostatine, sécrétées par l'antre","La phase céphalique et la phase gastrique"],"r":0,"e":"C'est ce raisonnement qui fonde à la fois l'éradication de H. pylori et l'inhibition de la sécrétion acide. L'HCl, la pepsine, H. pylori et les AINS agressent ; le mucus, les bicarbonates et les prostaglandines protègent.","s":8},{"q":"Longueur de l'intestin grêle :","o":["1-2 m","3-4 m","6-7 m","15 m"],"r":2,"e":"6-7 m. Duodénum (25 cm) + jéjunum (2/5) + iléon (3/5).","s":9},{"q":"Le duodénum mesure :","o":["10 cm","25-30 cm","50 cm","1 m"],"r":1,"e":"25-30 cm (« 12 doigts »). 4 portions en C autour de la tête du pancréas.","s":9},{"q":"Ampoule de Vater est en :","o":["D1","D2","D3","D4"],"r":1,"e":"D2 reçoit cholédoque + Wirsung à l'ampoule de Vater (papille majeure).","s":9},{"q":"Angle duodéno-jéjunal est aussi appelé :","o":["Angle de His","Angle de Treitz","Angle splénique","Angle hépatique"],"r":1,"e":"Treitz = fin du duodénum, début du jéjunum. Repère pour HD haute/basse.","s":9},{"q":"Jéjunum vs iléon — particularité du jéjunum :","o":["De nombreuses plaques de Peyer, en amas","Des vasa recta longs et peu d'arcades","Un diamètre plus étroit que l'iléon","Une paroi plus fine que l'iléon"],"r":1,"e":"Jéjunum : vasa recta longs + arcades simples. Iléon : arcades multiples + vasa recta courts.","s":9},{"q":"Plaques de Peyer sont surtout dans :","o":["Le duodénum","Le jéjunum","L'iléon distal","Le cæcum et l'appendice"],"r":2,"e":"Plaques de Peyer = agrégats lymphoïdes de la sous-muqueuse. Très abondantes dans l'iléon terminal.","s":9},{"q":"Valve iléo-cæcale s'appelle aussi :","o":["Valve de Houston","Valve de Bauhin","Valve d'Heister","Valve d'Eustache"],"r":1,"e":"Bauhin = valve iléo-cæcale, empêche le reflux du contenu colique vers l'iléon.","s":9},{"q":"3 niveaux d'amplification de surface du grêle :","o":["Les plis et les villosités, seuls","Les valvules, les villosités et les microvillosités","Les acini et les lobules glandulaires","Les acini, les tubules et les canaux excréteurs du pancréas"],"r":1,"e":"3 niveaux → surface ~250 m².","s":9},{"q":"Surface absorbante totale du grêle :","o":["Environ 5 m², la surface d'une petite pièce","Environ 50 m², un appartement","Environ 250 m², un court de tennis","Environ 1 000 m², un terrain"],"r":2,"e":"~250 m² grâce aux 3 niveaux d'amplification.","s":9},{"q":"Absorption de la B12 dans :","o":["Duodénum","Jéjunum","Iléon terminal","Côlon"],"r":2,"e":"Iléon terminal (avec facteur intrinsèque). Résection → anémie macrocytaire.","s":9},{"q":"Absorption du fer :","o":["Duodénum","Iléon","Côlon","Rectum"],"r":0,"e":"Duodénum + jéjunum proximal. Calcium aussi au duodénum.","s":9},{"q":"Lipides absorbés via :","o":["La veine porte, directement, vers le foie","Les chylifères, puis le canal thoracique","La veine cave inférieure, directement","L'aorte abdominale"],"r":1,"e":"Chylomicrons → chylifères (villosité) → canal thoracique → circulation systémique.","s":9},{"q":"Cellules de Paneth :","o":["Assurent l'absorption des nutriments, à l'apex","Sécrètent des défensines, pour l'immunité","Sécrètent le mucus protecteur","Assurent le renouvellement"],"r":1,"e":"Cellules de Paneth au fond des cryptes → défensines + lysozyme.","s":9},{"q":"Cryptes de Lieberkühn :","o":["Situées au sommet des villosités, en surface","Entre les villosités, riches en cellules souches","Situées dans le foie, autour des lobules","Situées dans le pancréas exocrine"],"r":1,"e":"Invaginations glandulaires entre les villosités. Cellules souches = renouvellement épithélial.","s":9},{"q":"Cellules M :","o":["Des cellules mucipares, sécrétant le mucus du grêle","Sur les plaques de Peyer, porteuses d'antigènes","Des cellules cancéreuses","Des cellules du métabolisme glucidique"],"r":1,"e":"Cellules M (microfold) sur les plaques de Peyer, échantillonnent les antigènes.","s":9},{"q":"Vascularisation du jéjuno-iléon :","o":["Le tronc cœliaque, seul","L'artère mésentérique supérieure","L'artère mésentérique inférieure","L'artère iliaque interne"],"r":1,"e":"AMS → artères jéjunales + iléales avec arcades + vasa recta. Elle donne les artères jéjunales et iléales.","s":9},{"q":"Veine mésentérique supérieure se draine dans :","o":["La veine cave inférieure","La veine porte, avec la splénique","L'aorte abdominale","Le foie directement, par les veines hépatiques"],"r":1,"e":"VMS + tronc spléno-mésaraïque = veine porte.","s":9},{"q":"Le muscle de Treitz :","o":["Le sphincter pylorique","Le muscle suspenseur du duodénum","Un muscle de la paroi abdominale, le transverse","Le pilier du diaphragme"],"r":1,"e":"Maintient le duodéno-jéjunum à l'angle de Treitz. Il agit à l'angle de Treitz.","s":9},{"q":"Sphincter d'Oddi :","o":["Le sphincter pylorique","Le sphincter de l'ampoule de Vater","Le sphincter œsophagien inférieur, au cardia","Le sphincter anal interne"],"r":1,"e":"Régule l'écoulement de la bile et du suc pancréatique dans D2.","s":9},{"q":"Hormone CCK est libérée en réponse à :","o":["L'acide gastrique, au duodénum","Les lipides et les acides aminés du duodénum","Le glucose, dans le jéjunum","L'eau ingérée, dès l'arrivée dans l'estomac, par distension"],"r":1,"e":"CCK → vésicule biliaire (contraction) + pancréas (enzymes) + relâche Oddi.","s":9},{"q":"Sites de la digestion finale :","o":["L'estomac, par la pepsine et l'acide","L'intestin grêle, avec la bile et le suc pancréatique","Le côlon, avec le microbiote","Le rectum, par absorption lente de l'eau et des sels minéraux"],"r":1,"e":"Digestion finale et absorption massive au grêle. Les entérocytes y participent.","s":9},{"q":"Le grêle est :","o":["Rétro-péritonéal, accolé à la paroi","Intra-péritonéal, suspendu par le mésentère","Sous-péritonéal, dans le petit bassin, sous la vessie","Sans méso, libre dans l'abdomen"],"r":1,"e":"Jéjunum + iléon = intra-péritonéal. Mésentère ~15 cm de racine.","s":9},{"q":"Complexe moteur migrant :","o":["Pendant la digestion, après chaque repas","À jeun, il balaie le grêle","Spécifique au côlon, la nuit","Pendant le sommeil seulement"],"r":1,"e":"CMM à jeun, « femme de ménage » de l'intestin.","s":9},{"q":"Maladie cœliaque :","o":["Un cancer du foie, primitif","Une intolérance au gluten, avec atrophie des villosités","Une maladie inflammatoire du côlon, avec ulcérations et diarrhée","Une carence en lactase, isolée"],"r":1,"e":"Auto-immunité au gluten → atrophie des villosités → malabsorption.","s":9},{"q":"Lieu fréquent des ulcères duodénaux :","o":["En D1, le bulbe duodénal","En D2, à la papille","En D3, devant l'aorte et la veine cave","En D4, à l'angle de Treitz"],"r":0,"e":"Bulbe duodénal = lieu d'ulcère typique. Souvent lié à H. pylori.","s":9},{"q":"Activation des enzymes pancréatiques par :","o":["La pepsine gastrique, au contact du chyme acide","L'entérokinase, qui active le trypsinogène","La bile, par ses sels","L'acide chlorhydrique"],"r":1,"e":"Entérokinase (bord en brosse) → active trypsinogène → trypsine active les autres zymogènes.","s":9},{"q":"Type de néphron particulier vu en histologie :","o":["Des plis circulaires, transitoires","Des plis de Kerckring, ou valvules conniventes","Des haustrations du côlon","Des tæniæ, bandelettes musculaires longitudinales du côlon"],"r":1,"e":"Valvules conniventes (Kerckring) = plis transversaux permanents.","s":9},{"q":"Mouvements de l'intestin grêle :","o":["Uniquement le péristaltisme","La segmentation et le péristaltisme","La rotation de l'anse","Aucun mouvement, la progression étant passive"],"r":1,"e":"Segmentation = brassage. Péristaltisme = propulsion. La segmentation brasse, le péristaltisme propulse.","s":9},{"q":"Mésentère a une racine de :","o":["5 cm","~15 cm","50 cm","1 m"],"r":1,"e":"~15 cm oblique, de l'angle de Treitz (L2 gauche) à la fosse iliaque droite.","s":9},{"q":"Diverticule de Meckel :","o":["Au cæcum, près de l'appendice","À l'iléon, vestige du canal omphalo-mésentérique","Au duodénum, vestige du bourgeon hépatique primitif","Au côlon, vestige du cloaque"],"r":1,"e":"Vestige embryonnaire sur l'iléon distal. Peut saigner ou s'enflammer.","s":9},{"q":"Le diamètre de l'intestin grêle est d'environ :","o":["1 cm, constant sur toute la longueur","2,5 cm, en diminuant vers l'aval","5 cm, comme le côlon ascendant et le cæcum","8 cm, dès le duodénum"],"r":1,"e":"Sa longueur est de 6 à 7 mètres, répartie entre duodénum, jéjunum et iléon.","s":9},{"q":"Le jéjunum représente :","o":["Les 2/5 supérieurs du jéjuno-iléon","Les 3/5 inférieurs du jéjuno-iléon","La moitié du jéjuno-iléon, en longueur","Le premier mètre, seul"],"r":0,"e":"L'iléon en représente les 3/5 inférieurs ; le duodénum mesure environ 25 cm.","s":9},{"q":"Le duodénum tire son nom du fait qu'il mesure :","o":["Douze doigts, soit 25 à 30 cm","Douze centimètres","Douze pouces, environ 30 cm","Deux fois l'estomac"],"r":0,"e":"Il forme un « C » qui encadre la tête du pancréas.","s":9},{"q":"La seule portion intra-péritonéale du duodénum est :","o":["D1, le bulbe","D2, verticale","D3, horizontale","D4, ascendante"],"r":0,"e":"C'est aussi le lieu de prédilection des ulcères duodénaux ; les autres portions sont rétro-péritonéales secondaires. D1 est le bulbe duodénal.","s":9},{"q":"La portion D2 du duodénum se situe :","o":["En avant de L3, horizontalement","Verticalement, à droite de la colonne, de L1 à L3","Horizontalement vers la droite, sous le foie","En L2, ascendante vers l'angle de Treitz, à gauche de l'aorte"],"r":1,"e":"Elle reçoit le canal cholédoque et le canal de Wirsung à l'ampoule de Vater, ou papille duodénale majeure.","s":9},{"q":"La portion D3 du duodénum :","o":["Passe devant L3, l'aorte et la veine cave inférieure","Remonte jusqu'à l'angle de Treitz, à gauche, en L2","Est le bulbe, mobile, en L1","Reçoit le cholédoque, en L2"],"r":0,"e":"Elle mesure environ 10 cm ; les vaisseaux mésentériques supérieurs passent entre D3 et D4.","s":9},{"q":"L'angle de Treitz se situe au niveau de :","o":["L1","L2","L3","L4"],"r":1,"e":"Maintenu par le muscle suspenseur du duodénum, il marque la fin du duodénum et constitue la limite haut/bas pour les hémorragies digestives.","s":9},{"q":"La vascularisation du duodénum est assurée par :","o":["Un double système, cœliaque et mésentérique","Le seul tronc cœliaque","La seule artère mésentérique, supérieure","L'artère mésentérique inférieure"],"r":0,"e":"Les arcades pancréatico-duodénales supérieures viennent de la gastro-duodénale, les inférieures de l'AMS. Les arcades pancréatico-duodénales relient la gastro-duodénale et l'AMS.","s":9},{"q":"Les vasa recta du jéjunum sont, par rapport à ceux de l'iléon :","o":["Plus longs","Plus courts","Identiques","Absents"],"r":0,"e":"Le jéjunum a une vascularisation riche avec peu d'arcades, l'iléon de multiples arcades et des vasa recta courts.","s":9},{"q":"La graisse mésentérique est :","o":["Modérée au jéjunum, abondante à l'iléon","Abondante au jéjunum, modérée à l'iléon","Absente sur tout le mésentère","Identique sur toute la longueur"],"r":0,"e":"Le jéjunum est par ailleurs plus large, à paroi plus épaisse, avec des valvules conniventes hautes et nombreuses.","s":9},{"q":"La racine du mésentère s'étend :","o":["De l'angle de Treitz à la fosse iliaque droite","Sur toute la paroi postérieure, en largeur","Du pylore au cæcum, en travers","De L1 à L5, sur la ligne médiane"],"r":0,"e":"Elle suit une ligne oblique et contient l'AMS et ses branches, les veines, les lymphatiques et chylifères, les nerfs et du tissu graisseux. Elle mesure environ 15 cm.","s":9},{"q":"L'artère mésentérique supérieure donne notamment :","o":["5 à 7 artères jéjunales et 7 à 10 artères iléales","2 artères jéjunales et 3 artères iléales","L'artère gastrique gauche et l'artère splénique","L'artère splénique et les vasa brevia"],"r":0,"e":"S'y ajoutent les pancréatico-duodénales inférieures, la colique droite, la colique moyenne et l'iléo-colique.","s":9},{"q":"Le drainage lymphatique du jéjuno-iléon aboutit :","o":["À la citerne du chyle","À la veine porte","Aux ganglions iliaques","Au canal thoracique directement"],"r":0,"e":"Sa particularité est le transport des chylomicrons, lipides absorbés.","s":9},{"q":"Les valvules conniventes multiplient la surface d'échange par :","o":["3","10","20","100"],"r":0,"e":"Les villosités la multiplient par 10 et les microvillosités par 20, pour une surface totale d'environ 250 m².","s":9},{"q":"Les villosités intestinales mesurent environ :","o":["0,1 mm, et sont invisibles à l'œil nu","1 mm, et sont visibles à l'œil nu","5 mm, comme des plis","1 cm, comme des doigts"],"r":1,"e":"Elles constituent le deuxième niveau d'amplification de surface, multipliant celle-ci par 10.","s":9},{"q":"Les cellules caliciformes de l'intestin grêle :","o":["Deviennent plus nombreuses vers l'iléon","Disparaissent progressivement vers l'iléon terminal","Sont absentes de l'intestin grêle","Sécrètent des défensines antibactériennes"],"r":0,"e":"Elles sécrètent le mucus ; les défensines sont produites par les cellules de Paneth au fond des cryptes.","s":9},{"q":"Les cryptes de Lieberkühn constituent :","o":["Le site du renouvellement de l'épithélium","Le site principal de l'absorption digestive","Des agrégats lymphoïdes","Des amplificateurs de surface"],"r":0,"e":"Ce sont des invaginations glandulaires situées entre les villosités. Ce renouvellement repose sur des cellules souches.","s":9},{"q":"Les plaques de Peyer siègent :","o":["Dans la sous-muqueuse, surtout à l'iléon distal","Dans la muqueuse duodénale, en amas","Dans la musculeuse, entre ses couches","Dans la séreuse, au contact du mésentère et des vaisseaux"],"r":0,"e":"Ce sont des agrégats de tissu lymphoïde constituant le GALT ; les cellules M y transportent les antigènes.","s":9},{"q":"Le calcium est absorbé principalement :","o":["Au duodénum","Au jéjunum","À l'iléon terminal","Au côlon"],"r":0,"e":"Le fer l'est également au duodénum, les vitamines liposolubles au jéjunum et la vitamine B12 à l'iléon terminal.","s":9},{"q":"Les enzymes de la bordure en brosse des entérocytes sont :","o":["Des disaccharidases et des peptidases","L'amylase et la lipase pancréatiques","La trypsine et la chymotrypsine","La pepsine"],"r":0,"e":"Elles complètent l'action du suc pancréatique et de la bile, qui émulsifie les lipides.","s":9},{"q":"Longueur du gros intestin :","o":["50 cm","~1,5 m","3 m","7 m"],"r":1,"e":"~1,5 m. De la valve iléo-cæcale à l'anus.","s":10},{"q":"Caractéristique spécifique du côlon :","o":["Des villosités et des plaques de Peyer, très nombreuses","Des tæniæ, des haustrations et des franges graisseuses","Des plaques de Peyer, seules","Des valvules conniventes"],"r":1,"e":"3 bandelettes longitudinales + bosselures + franges graisseuses.","s":10},{"q":"Appendice vermiforme s'attache à :","o":["Iléon","Cæcum","Côlon ascendant","Rectum"],"r":1,"e":"Diverticule de ~8-9 cm sur le cæcum. Très riche en tissu lymphoïde.","s":10},{"q":"Point de McBurney est :","o":["Sur la ligne médiane, sous l'ombilic","Au 1/3 externe de la ligne ombilic-EIAS droite","À gauche, sur la ligne ombilic-EIAS gauche","Au-dessus de l'ombilic, sur la ligne xipho-ombilicale à 2 cm"],"r":1,"e":"Projection cutanée de la base appendiculaire. Sensibilité à la palpation = appendicite.","s":10},{"q":"Portions du côlon dans l'ordre :","o":["Cæcum → ascendant → transverse → descendant → sigmoïde","Cæcum → descendant → transverse → ascendant → sigmoïde","Sigmoïde → ascendant → transverse → descendant","Rectum → cæcum → ascendant → transverse → sigmoïde"],"r":0,"e":"« Cadre colique » dans le sens des aiguilles d'une montre.","s":10},{"q":"Angle colique droit s'appelle aussi :","o":["Angle hépatique","Angle splénique","Angle de Treitz","Angle de His"],"r":0,"e":"Droit = hépatique. Gauche = splénique.","s":10},{"q":"Le côlon transverse est :","o":["Rétro-péritonéal, accolé à la paroi","Intra-péritonéal, avec le mésocôlon transverse","Sous-péritonéal, dans le petit bassin, sous le rectum","Extra-péritonéal, comme les reins"],"r":1,"e":"Intra-péritonéal mobile. Côlon ascendant et descendant sont rétro-péritonéaux accolés.","s":10},{"q":"Sigmoïde est :","o":["Rétro-péritonéal, accolé et fixe","Intra-péritonéal, en S, avec le mésosigmoïde","Linéaire, court et fixe, sans méso","Sphérique, comme une poche, au-dessus du rectum, à droite"],"r":1,"e":"Forme de S, mobile, suspendu par le mésosigmoïde. Lieu fréquent de diverticulose.","s":10},{"q":"Longueur du rectum :","o":["5 cm","~12-15 cm","25 cm","50 cm"],"r":1,"e":"12-15 cm. De S3 à la ligne pectinée du canal anal.","s":10},{"q":"Le rectum est :","o":["Intra-péritonéal","Sous-péritonéal","Sans rapports péritonéaux","Extra-abdominal"],"r":1,"e":"Sous-péritonéal. La portion supérieure est partiellement recouverte de péritoine.","s":10},{"q":"Valves de Houston :","o":["Les sphincters anaux, interne et externe","Les 3 plis transversaux du rectum","Des valves cardiaques de l'adulte, au nombre de 4","Des replis du sigmoïde"],"r":1,"e":"Plis transversaux internes du rectum.","s":10},{"q":"Ligne pectinée sépare :","o":["Le rectum et le sigmoïde","Deux épithéliums, cylindrique et pavimenteux","Le côlon et le rectum, à la jonction recto-sigmoïdienne","Le transverse et le descendant"],"r":1,"e":"Limite embryologique : endodermique au-dessus, ectodermique en dessous. Le cylindrique est au-dessus, le pavimenteux en dessous.","s":10},{"q":"Sphincter interne anal :","o":["Strié, volontaire","Lisse, involontaire","Inexistant","Mixte"],"r":1,"e":"Sphincter interne = lisse, autonome (continence de repos).","s":10},{"q":"Sphincter externe anal innervé par :","o":["Sympathique","Parasympathique","Nerf pudendal","Plexus mésentérique"],"r":2,"e":"Strié, volontaire, nerf pudendal (S2-S4).","s":10},{"q":"Hémorroïdes sont des :","o":["Des cancers du canal anal","Des dilatations des plexus veineux hémorroïdaires","Des infections des glandes anales","Des anomalies congénitales du rectum et de l'anus"],"r":1,"e":"Plexus interne (porte) ou externe (cave). Anastomose porto-cave.","s":10},{"q":"Vascularisation du côlon droit :","o":["Le tronc cœliaque, par la gastro-duodénale et l'épiploïque","L'artère mésentérique supérieure et ses coliques","L'artère mésentérique inférieure","L'artère iliaque interne, au petit bassin"],"r":1,"e":"AMS vascularise jusqu'à 2/3 du transverse. Ce sont l'iléo-colique, la colique droite et la colique moyenne.","s":10},{"q":"Vascularisation du côlon gauche :","o":["L'artère mésentérique supérieure","L'artère mésentérique inférieure et ses branches","Le tronc cœliaque, par l'artère splénique et ses branches","L'aorte, directement, par des rameaux"],"r":1,"e":"AMI : 1/3 gauche du transverse → rectum supérieur. Ce sont la colique gauche, les sigmoïdiennes et la rectale supérieure.","s":10},{"q":"Arcade marginale de Drummond :","o":["Une arcade au niveau gastrique","Une anastomose entre AMS et AMI, le long du côlon","Une articulation pelvienne, entre sacrum et iliaque","Un vaisseau issu de l'AMI, isolé"],"r":1,"e":"Arcade marginale court le long du bord mésentérique du côlon. Voie de suppléance.","s":10},{"q":"Drainage veineux du côlon :","o":["La veine cave inférieure, directement","Le système porte, sauf pour le bas rectum","La veine azygos, au thorax","Les veines iliaques, seules"],"r":1,"e":"VMS + VMI → veine porte. Rectum inf : drainage cave (anastomose).","s":10},{"q":"Fonction principale du gros intestin :","o":["La digestion finale des nutriments","La réabsorption d'eau et le stockage des fèces","La production de la bile, avec la vésicule biliaire","L'absorption massive des lipides"],"r":1,"e":"Côlon = réabsorption eau (~1,5 L/jour) + stockage + fermentation par microbiote.","s":10},{"q":"Le microbiote produit notamment :","o":["Vitamine A","Vitamines K et B","Vitamine C","Vitamine D"],"r":1,"e":"Microbiote fermente les fibres → AGCC + vitamines K et B.","s":10},{"q":"Mouvement de masse colique :","o":["10× par jour","2-3× par jour","1× par heure","Continus"],"r":1,"e":"2-3 mouvements/jour. Propulsent les selles vers le rectum.","s":10},{"q":"Réflexe gastro-colique :","o":["Pendant le sommeil","Déclenché par les repas","Le matin uniquement","N'existe pas"],"r":1,"e":"Le remplissage gastrique stimule la motilité colique → besoin défécatoire après repas.","s":10},{"q":"Diverticulose siège préférentiellement dans :","o":["Cæcum","Transverse","Sigmoïde","Rectum"],"r":2,"e":"Sigmoïde = lieu de prédilection. Diverticulite = inflammation.","s":10},{"q":"Points de vascularisation moins riche du côlon :","o":["Le cæcum et l'appendice, à droite","L'angle splénique et la jonction recto-sigmoïdienne","Le sigmoïde et le côlon transverse, en totalité","Aucun point faible, grâce aux arcades"],"r":1,"e":"Zones à risque d'ischémie colique. Ce sont les points de Griffith et de Sudeck.","s":10},{"q":"Cancer colorectal — siège :","o":["Toujours dans le rectum","Surtout le sigmoïde et le rectum, à 60-70 %","Le cæcum, dans 80 % des cas","L'angle hépatique, dans la moitié des cas, à 50 %"],"r":1,"e":"Côlon gauche, sigmoïde et rectum = sièges les plus fréquents.","s":10},{"q":"Innervation parasympathique du côlon droit :","o":["Le nerf vague, dixième nerf crânien","Les nerfs splanchniques pelviens","Le nerf pudendal","Le sympathique, de T10 à L1"],"r":0,"e":"Côlon droit + 2/3 du transverse : nerf vague. Côlon gauche → rectum : splanchniques pelviens (S2-S4).","s":10},{"q":"Histologie colique sans :","o":["De cryptes, comme le grêle","De villosités, à la différence du grêle","De cellules caliciformes, présentes pourtant ailleurs","De musculeuse, comme l'œsophage"],"r":1,"e":"Pas de villosités dans le côlon. Cryptes profondes + nombreuses cellules caliciformes.","s":10},{"q":"Volume de selles quotidien :","o":["10 g","100-200 g","500 g-1 kg","2 kg"],"r":1,"e":"100-200 g/jour. Composition : eau (75%) + résidus + bactéries.","s":10},{"q":"La défécation est :","o":["Purement volontaire, par le sphincter externe","Purement réflexe, sans contrôle","Mixte, réflexe et sous contrôle volontaire","Automatique, à heure fixe"],"r":2,"e":"Sphincter interne (involontaire, relâché par distension) + externe (volontaire, pudendal). Le sphincter interne est involontaire ; l'externe, volontaire, dépend du pudendal.","s":10},{"q":"Le diamètre du gros intestin passe de :","o":["7 cm au cæcum à 2,5 cm au sigmoïde","2,5 cm au cæcum à 7 cm au sigmoïde","5 cm partout, du cæcum au rectum","10 cm au cæcum à 5 cm au rectum"],"r":0,"e":"Sa longueur est de 1,5 m, de la valve iléo-cæcale à l'anus, et il forme le cadre colique autour de l'intestin grêle.","s":10},{"q":"Les appendices épiploïques sont :","o":["Des franges graisseuses, propres au côlon","Des bandes musculaires longitudinales","Des sacculations de la paroi","Des replis de la muqueuse, comme au grêle, très nombreux"],"r":0,"e":"Avec les tæniæ coli et les haustrations, ils distinguent le côlon de l'intestin grêle.","s":10},{"q":"Le cæcum mesure environ :","o":["3 à 4 cm","6 à 8 cm","15 cm","25 cm"],"r":1,"e":"Cul-de-sac initial intra-péritonéal de la fosse iliaque droite, il reçoit l'iléon par la valve de Bauhin.","s":10},{"q":"L'appendice vermiforme mesure environ :","o":["3 cm","5 cm","8 à 9 cm","15 cm"],"r":2,"e":"Il possède son propre méso, le mésoappendice, et est très riche en tissu lymphoïde.","s":10},{"q":"Les positions possibles de l'appendice sont :","o":["Pelvienne, rétro-cæcale, latéro-cæcale ou méso-cœliaque","Uniquement pelvienne, dans le petit bassin, devant le rectum","Uniquement rétro-cæcale, fixée","Fixe et constante chez tous"],"r":0,"e":"Cette variabilité explique la diversité des présentations cliniques de l'appendicite.","s":10},{"q":"La douleur de l'appendicite est décrite comme :","o":["Péri-ombilicale au début, puis en fosse iliaque droite","D'emblée en fosse iliaque droite","Épigastrique et permanente","Lombaire droite, irradiant vers la cuisse et le testicule"],"r":0,"e":"Elle s'accompagne de fièvre et d'une défense ; la rupture entraîne une péritonite.","s":10},{"q":"Le côlon transverse mesure environ :","o":["15 cm","25 cm","40 cm","50 cm"],"r":3,"e":"Intra-péritonéal et mobile, en U inversé, il est suspendu par le mésocôlon transverse.","s":10},{"q":"L'angle colique gauche, ou splénique, se situe :","o":["Plus bas que l'angle droit","Plus haut que l'angle droit","Au même niveau","Dans le pelvis"],"r":1,"e":"Le côlon transverse va de l'angle hépatique à l'angle splénique.","s":10},{"q":"Le côlon descendant mesure environ :","o":["15 cm","25 cm","40 cm","50 cm"],"r":1,"e":"Rétro-péritonéal secondaire, il va de l'angle splénique à la fosse iliaque gauche ; le côlon ascendant mesure environ 15 cm.","s":10},{"q":"Le rectum s'étend :","o":["De S3 à la ligne pectinée du canal anal","De L5 jusqu'à l'anus, sans canal anal","Du sigmoïde jusqu'à S1, au promontoire","De S1 jusqu'à S5, contre le sacrum"],"r":0,"e":"Il mesure 12 à 15 cm et est sous-péritonéal, sa portion supérieure étant partiellement recouverte de péritoine.","s":10},{"q":"L'ampoule rectale joue le rôle :","o":["De réservoir","De sphincter","De zone d'absorption","De zone de sécrétion"],"r":0,"e":"Le rectum présente trois courbures latérales et trois plis transversaux, les valves de Houston.","s":10},{"q":"En avant, le rectum répond chez l'homme à :","o":["La prostate, les vésicules séminales et la vessie","Le vagin et l'utérus, comme chez la femme, à l'identique","Le sacrum et le coccyx, en avant","Les muscles élévateurs de l'anus"],"r":0,"e":"Chez la femme, il répond au vagin et à l'utérus ; en arrière au sacrum et au coccyx dans les deux cas.","s":10},{"q":"Le canal anal mesure :","o":["1 à 2 cm","3 à 4 cm","6 à 8 cm","10 cm"],"r":1,"e":"Il traverse le diaphragme pelvien, formé des muscles élévateurs de l'anus.","s":10},{"q":"La ligne pectinée sépare :","o":["Deux épithéliums d'origines embryologiques différentes","Le rectum du sigmoïde, à la jonction recto-sigmoïdienne","Le sphincter interne du sphincter externe","Le côlon du rectum, en S3"],"r":0,"e":"Cette limite embryologique conditionne des drainages vasculaires et lymphatiques et des innervations différents. Il est cylindrique et endodermique au-dessus, pavimenteux et ectodermique en dessous.","s":10},{"q":"Le sphincter anal interne est :","o":["Un muscle lisse involontaire, à tonus permanent","Un muscle strié et volontaire","Innervé par le nerf pudendal, comme le sphincter externe","Absent chez l'adulte, involué"],"r":0,"e":"Le sphincter externe est strié, volontaire, et innervé par le nerf pudendal. Il assure la continence de repos.","s":10},{"q":"Le plexus hémorroïdaire interne se draine :","o":["Dans le système porte","Dans le système cave","Dans le système azygos","Dans les lymphatiques"],"r":0,"e":"Le plexus externe, situé sous la ligne pectinée, se draine dans le système cave — d'où une anastomose porto-cave.","s":10},{"q":"L'artère iléo-cæco-colo-appendiculaire vascularise :","o":["Le cæcum, l'appendice et l'iléon terminal","Le côlon transverse, sur ses deux tiers droits","Le côlon descendant, à gauche","Le rectum, en haut, et le sigmoïde"],"r":0,"e":"Elle naît de l'artère mésentérique supérieure, comme les coliques droite et moyenne.","s":10},{"q":"L'arcade de Riolan, ou arcade marginale de Drummond, anastomose :","o":["Les deux artères mésentériques, à l'angle splénique","Les artères rectales, entre elles","Le tronc cœliaque et l'AMS, au pancréas","Les artères iliaques internes et externes, au petit bassin"],"r":0,"e":"C'est une voie de suppléance en cas d'occlusion d'une des deux mésentériques.","s":10},{"q":"L'innervation parasympathique du côlon gauche, du sigmoïde et du rectum provient :","o":["Du nerf vague, ou X","Des nerfs splanchniques pelviens, de S2 à S4","Du nerf pudendal, de S2 à S4","Du plexus mésentérique inférieur, de L1 à L2"],"r":1,"e":"Le nerf vague innerve le côlon droit et les deux tiers du transverse.","s":10},{"q":"L'histologie colique se distingue de celle du grêle par :","o":["L'absence de villosités et des cryptes profondes","La présence de villosités, plus longues que dans le grêle","L'absence de cryptes glandulaires","L'absence de cellules caliciformes"],"r":0,"e":"Sa couche longitudinale est concentrée en trois bandelettes, sauf au rectum où elle redevient continue. Les cellules caliciformes y sont très nombreuses et les plaques de Peyer absentes.","s":10},{"q":"Poids du foie adulte :","o":["500 g","1 kg","~1,5 kg","3 kg"],"r":2,"e":"~1,5 kg. Organe le plus volumineux du corps. ~2,5% du poids corporel.","s":11},{"q":"Foie reçoit ~% du débit cardiaque :","o":["5%","10%","~25%","50%"],"r":2,"e":"~25% du débit cardiaque. Très vascularisé.","s":11},{"q":"Le foie est situé dans :","o":["L'hypochondre gauche, sous la coupole, contre la rate","L'hypochondre droit et l'épigastre, débordant à gauche","Le pelvis, derrière la vessie","Le médiastin, sous le cœur"],"r":1,"e":"Hypochondre droit principalement + épigastre, débord vers hypochondre gauche.","s":11},{"q":"Le foie est :","o":["Rétro-péritonéal, accolé à la paroi postérieure","Intra-péritonéal, sauf une zone nue en arrière","Sous-péritonéal, dans le pelvis","Extra-péritonéal, au thorax"],"r":1,"e":"Intra-péritonéal, sauf zone nue postérieure adhérente au diaphragme.","s":11},{"q":"Faces du foie :","o":["Une seule face, lisse","Deux faces, supérieure et inférieure, seulement","Trois faces, supérieure, inférieure et postérieure","Quatre faces, avec une antérieure"],"r":2,"e":"Sup/diaphragmatique + inf/abdominale (viscérale, en H) + postérieure. La supérieure est diaphragmatique, l'inférieure abdominale.","s":11},{"q":"Configuration en « H » :","o":["Sur la face supérieure, diaphragmatique","Sur la face viscérale, ou inférieure","Sur la face postérieure","Elle n'existe pas"],"r":1,"e":"« H » sur la face viscérale : 2 sillons antéro-postérieurs + 1 sillon transversal.","s":11},{"q":"Sillon antéro-postérieur droit contient :","o":["Le ligament rond et le canal d'Arantius","La vésicule biliaire et la veine cave inférieure","L'aorte abdominale, en arrière","La veine porte et ses deux branches, au hile hépatique"],"r":1,"e":"Sillon AP droit : vésicule en avant + VCI en arrière.","s":11},{"q":"Sillon antéro-postérieur gauche contient :","o":["Le ligament rond et le canal veineux d'Arantius","La vésicule biliaire et la veine cave","L'aorte et la veine porte, avec le cholédoque en avant","L'estomac, par son empreinte"],"r":0,"e":"Sillon AP gauche : lig rond (vestige veine ombilicale) + lig veineux d'Arantius. Le ligament rond est en avant, le canal d'Arantius en arrière.","s":11},{"q":"Sillon transversal = hile hépatique, contient :","o":["La veine porte, à elle seule","La veine porte, l'artère et la voie biliaire","L'artère hépatique, à elle seule","L'aorte, la veine cave et le canal thoracique"],"r":1,"e":"Pédicule hépatique au hile : 3 éléments principaux (VP, AH, VBP) + nerfs/lymphatiques. L'artère est l'artère hépatique ; plexus et lymphatiques l'accompagnent.","s":11},{"q":"4 lobes anatomiques :","o":["Supérieur, inférieur, médian et latéral","Droit, gauche, carré et caudé","Cortical, médullaire, hilaire et papillaire","Lingual, vésical, ombilical et falciforme"],"r":1,"e":"Lobes anatomiques : droit, gauche, carré (devant), caudé (de Spiegel, derrière). Le caudé est le lobe de Spiegel.","s":11},{"q":"Segmentation de Couinaud :","o":["4 segments","6 segments","8 segments","12 segments"],"r":2,"e":"8 segments (I à VIII) basés sur la vascularisation porte. Base de la chirurgie hépatique.","s":11},{"q":"Segment I correspond à :","o":["Au lobe droit, en arrière","Au lobe caudé, autonome","Au lobe gauche, latéral","Au lobe carré, devant le hile"],"r":1,"e":"Segment I = lobe caudé. Drainage veineux directement dans la VCI. Le lobe caudé, ou de Spiegel, se draine directement dans la VCI.","s":11},{"q":"Foie droit fonctionnel vs anatomique :","o":["Ils sont strictement identiques","Ils diffèrent, la limite passant par la veine cave","Le foie n'a aucune limite interne","Le foie gauche est plus gros que le droit, chez l'adulte"],"r":1,"e":"Lobation fonctionnelle = sillon VCI au lit vésiculaire (Cantlie). Anatomique = ligament falciforme. La limite fonctionnelle passe entre la VCI et le lit vésiculaire.","s":11},{"q":"Ligament falciforme contient :","o":["L'artère hépatique propre","Le ligament rond, vestige de la veine ombilicale","La veine cave inférieure, en arrière","La veine porte et ses branches gauches, vers le lobe gauche"],"r":1,"e":"Ligament rond dans le bord libre du falciforme.","s":11},{"q":"Pédicule hépatique contient :","o":["La veine cave inférieure et les trois veines hépatiques","L'artère hépatique, la voie biliaire et la veine porte","L'aorte abdominale et le tronc cœliaque","L'œsophage abdominal, et le nerf vague"],"r":1,"e":"Pédicule = AH + VBP + VP. Dans le ligament hépato-duodénal.","s":11},{"q":"Foie possède :","o":["Un seul type de sécrétion, biliaire","Une sécrétion externe, la bile, et une interne, sanguine","Aucune sécrétion propre, filtrante","Une sécrétion uniquement endocrine, par des îlots de cellules"],"r":1,"e":"Sécrétion externe = bile. Interne = nombreuses molécules dans le sang.","s":11},{"q":"Bord antérieur du foie est :","o":["Épais et arrondi, jamais palpable, même chez le maigre","Tranchant, palpable au rebord costal en inspiration","Inexistant, fusionné à la face","Concave, en forme de croissant"],"r":1,"e":"Bord antérieur tranchant. Sa palpation > rebord costal = hépatomégalie.","s":11},{"q":"Extrémité droite du foie :","o":["Fine et aplatie, comme à gauche","Très développée et arrondie","Indiscernable du reste","Pointue, et dirigée vers la rate, en dedans"],"r":1,"e":"Extrémité droite : volumineuse. Extrémité gauche : fine et aplatie.","s":11},{"q":"Ligaments triangulaires :","o":["Centraux, au niveau du hile","Latéraux, droit et gauche, prolongeant le coronaire","Situés au niveau du hile","Inexistants chez l'adulte, résorbés après la naissance"],"r":1,"e":"Ligaments triangulaires droit et gauche = prolongements du ligament coronaire.","s":11},{"q":"Zone nue du foie :","o":["À la face inférieure, viscérale","Postéro-supérieure, sans péritoine, contre le diaphragme","À la face antérieure, sans péritoine, contre la paroi des côtes","Inexistante chez l'adulte, recouverte"],"r":1,"e":"Zone nue postérieure adhérente au diaphragme. Pas de péritoine.","s":11},{"q":"Face postérieure correspond aux vertèbres :","o":["L1-L3","D9-D11/D12","D5-D7","D1-D3"],"r":1,"e":"Bord postérieur en regard de D9, D10, D11, parfois D12.","s":11},{"q":"Limite supérieure du foie :","o":["Au 3ᵉ espace intercostal, à droite","Au 5ᵉ espace intercostal droit, médio-claviculaire","À la 8ᵉ côte, sur la ligne axillaire","Au-dessus de la clavicule, au 1ᵉʳ espace intercostal gauche"],"r":1,"e":"5ème EICD, ligne médio-claviculaire = sommet de la coupole diaphragmatique droite.","s":11},{"q":"Hépatomégalie est :","o":["Normale chez l'adulte, en inspiration","Pathologique, le foie dépassant le rebord costal","Toujours sans gravité, si isolée","Une diminution du volume du foie, après une hépatite virale"],"r":1,"e":"Foie palpable sous le rebord costal = pathologique (sauf nourrisson). Le foie devient palpable, sauf chez le nourrisson.","s":11},{"q":"Lobe caudé est aussi appelé :","o":["Lobe de Bauhin","Lobe de Spiegel","Lobe de Riedel","Lobe carré"],"r":1,"e":"Lobe caudé = lobe de Spiegel = segment I.","s":11},{"q":"Foie reçoit la majorité de son sang de :","o":["Artère hépatique (25%)","Veine porte (75%)","VCI","Aorte"],"r":1,"e":"75% VP + 25% AH. Double apport sanguin unique.","s":11},{"q":"Capsule de Glisson :","o":["La capsule du pancréas","La capsule fibreuse du foie, sensible","La capsule du rein, adhérente au cortex","La capsule de la rate"],"r":1,"e":"Capsule fibreuse du foie. Sensible (douleur en cas de distension).","s":11},{"q":"Capacité de régénération du foie :","o":["Aucune, le tissu détruit devenant fibreux","Excellente, même après une hépatectomie partielle","Très lente, sur une dizaine d'années au moins","Limitée à l'enfance, avant 10 ans"],"r":1,"e":"Récupération en quelques semaines. Base des résections étendues et transplantation à donneur vivant.","s":11},{"q":"Rapports avec la face inférieure droite :","o":["L'estomac, par son antre pylorique","L'angle hépatique du côlon, le rein droit et le duodénum","La rate, en dehors du foie","La queue du pancréas, la rate et l'angle splénique du côlon"],"r":1,"e":"À droite du sillon AP droit : empreintes colique, rénale, duodénale.","s":11},{"q":"Rapport face inférieure gauche :","o":["Le rein gauche, en arrière","L'empreinte de l'estomac","Le cæcum, à droite","La vessie, dans le petit bassin"],"r":1,"e":"À gauche du sillon AP gauche : empreinte gastrique (estomac).","s":11},{"q":"Vésicule biliaire :","o":["À gauche, sous le lobe gauche","Dans le sillon antéro-postérieur droit du foie","Sous le diaphragme, contre la coupole droite","Dans le mésentère, à droite"],"r":1,"e":"Dans la fossette cystique de la face viscérale du foie, à droite.","s":11},{"q":"Le foie représente environ quelle part du poids corporel ?","o":["1 %","2,5 %","5 %","10 %"],"r":1,"e":"Il pèse 1,5 kg chez l'adulte et constitue la plus volumineuse glande de l'organisme.","s":11},{"q":"Le foie est une glande :","o":["Exclusivement exocrine, par la bile","Exclusivement endocrine, par le sang","Mixte, exocrine par la bile et endocrine par le sang","Ni exocrine ni endocrine, mais seulement filtrante"],"r":2,"e":"La sécrétion interne rejoint le sang via les veines hépatiques puis la veine cave inférieure.","s":11},{"q":"Parmi les fonctions de stockage du foie figurent :","o":["Le glycogène, le fer et des vitamines, dont la B12","Le calcium et le phosphore, avec la PTH","Les protéines musculaires et l'albumine, en grande réserve","Les lipides sous-cutanés, à 20 %"],"r":0,"e":"S'y ajoutent les fonctions métaboliques, de synthèse, de détoxification, de production de bile, de phagocytose et d'hématopoïèse fœtale. Les vitamines A et D y sont aussi stockées.","s":11},{"q":"La phagocytose hépatique est assurée par :","o":["Les hépatocytes","Les cellules de Kupffer","Les cellules étoilées","Les cholangiocytes"],"r":1,"e":"L'hépatocyte est, lui, la cellule fonctionnelle assurant métabolisme, synthèse et détoxification.","s":11},{"q":"La détoxification hépatique transforme notamment :","o":["L'ammoniac en urée","L'urée en ammoniac","Le glucose en glycogène","La bilirubine en hème"],"r":0,"e":"Elle porte aussi sur les médicaments et les toxines.","s":11},{"q":"La limite supérieure de projection du foie se situe :","o":["Au 5ᵉ espace intercostal droit, médio-claviculaire","Au 7ᵉ espace intercostal, sur la ligne axillaire","À la 6ᵉ côte gauche, sous le sein","Au rebord costal droit"],"r":0,"e":"La limite inférieure suit le rebord costal droit et la limite gauche atteint la 6ᵉ côte gauche.","s":11},{"q":"Chez le nourrisson, un foie palpable sous le rebord costal est :","o":["Toujours pathologique","Physiologique","Signe d'insuffisance hépatique","Signe d'hépatite"],"r":1,"e":"Chez l'adulte, en revanche, le débordement du rebord costal signe une hépatomégalie.","s":11},{"q":"Les dimensions approximatives du foie sont :","o":["28 × 16 × 8 cm","20 × 10 × 5 cm","35 × 20 × 12 cm","15 × 10 × 6 cm"],"r":0,"e":"Sa forme est ovoïde à grand axe transversal, comme un demi-ovoïde.","s":11},{"q":"La face postérieure du foie correspond au bord inférieur des vertèbres :","o":["De D7 à D9, en général","De D9 à D11, parfois D12","De D11 à L1, souvent","De L1 à L3, en arrière du rein"],"r":1,"e":"La face supérieure est diaphragmatique et convexe, la face inférieure viscérale et concave.","s":11},{"q":"La zone nue du foie est :","o":["Postéro-supérieure, sans péritoine, contre le diaphragme","Antérieure, sans péritoine, contre la paroi des côtes et du sternum","Située au hile, autour du pédicule","Recouverte de péritoine viscéral"],"r":0,"e":"Le foie est intra-péritonéal à l'exception de cette zone.","s":11},{"q":"Le sillon sagittal gauche de la face viscérale contient :","o":["La vésicule biliaire en avant et la veine cave en arrière","Le ligament rond en avant et le ligament d'Arantius en arrière","Le pédicule hépatique, au hile","Le ligament falciforme et le ligament coronaire"],"r":1,"e":"Le sillon droit contient la vésicule en avant et la veine cave inférieure en arrière ; le sillon transversal est le hile.","s":11},{"q":"Le ligament rond du foie est un vestige :","o":["De la veine ombilicale","Du canal d'Arantius","De l'artère ombilicale","Du canal vitellin"],"r":0,"e":"Le ligament veineux d'Arantius est, lui, le reliquat du canal veineux.","s":11},{"q":"Le lobe carré se situe :","o":["Entre la vésicule et le ligament rond, sous le hile","Entre la veine cave et le ligament veineux, au-dessus du hile","À gauche du ligament falciforme","En position postéro-supérieure, contre le diaphragme et la zone nue"],"r":0,"e":"Le lobe caudé, ou de Spiegel, occupe la position postérieure entre VCI et ligament veineux, au-dessus du hile.","s":11},{"q":"La lobation fonctionnelle du foie repose sur :","o":["Les sillons de la face viscérale","La vascularisation porte et la ligne de Cantlie","Le ligament falciforme, en avant","La position des lobes carré et caudé, au hile"],"r":1,"e":"Elle sépare un foie droit représentant 60 % et un foie gauche 40 %, et guide les hépatectomies.","s":11},{"q":"Le segment I de Couinaud correspond :","o":["Au lobe caudé, autonome","Au lobe carré, antérieur","Au secteur latéral gauche","Au secteur postérieur droit, de VI et VII"],"r":0,"e":"Le foie comporte 8 segments définis par la vascularisation porte et la position des veines hépatiques.","s":11},{"q":"Les segments VI et VII de Couinaud constituent :","o":["Le secteur antérieur droit, V en bas et VIII en haut","Le secteur postérieur droit, VI en bas et VII en haut","Le secteur latéral gauche, II et III","Le secteur paramédian gauche, le IV"],"r":1,"e":"Les segments V et VIII forment le secteur antérieur droit, V inférieur et VIII supérieur.","s":11},{"q":"Le segment IV de Couinaud :","o":["Le secteur paramédian gauche, divisé en IVa et IVb","Le lobe caudé, autonome, en arrière","Une partie du foie droit, à droite","Il n'existe pas dans la segmentation de Couinaud actuelle"],"r":0,"e":"Les segments II et III forment, eux, le secteur latéral gauche. IVa est supérieur, IVb inférieur.","s":11},{"q":"La segmentation de Couinaud est définie par :","o":["Les trois veines hépatiques et la bifurcation portale","Les sillons péritonéaux de la face viscérale","Les ligaments triangulaires","La capsule de Glisson et ses expansions dans le parenchyme"],"r":0,"e":"Chaque segment ayant son propre pédicule et son drainage veineux, des segmentectomies sont possibles sans compromettre le reste du foie. Il s'agit de leurs plans.","s":11},{"q":"Le ligament falciforme contient dans son bord libre :","o":["Le ligament rond","Le pédicule hépatique","La veine cave inférieure","Le ligament veineux"],"r":0,"e":"Il relie le foie à la paroi abdominale antérieure et au diaphragme.","s":11},{"q":"La face viscérale du foie présente une empreinte rénale correspondant :","o":["Au rein gauche, en arrière","Au rein droit et à la surrénale droite","À la rate, par sa face interne","Au pancréas et au duodénum, en bas et en arrière"],"r":1,"e":"Elle répond aussi à l'estomac et l'œsophage abdominal à gauche, au premier duodénum, à la vésicule et à l'angle colique droit.","s":11},{"q":"Face supérieure du foie : 5 segments :","o":["Supérieure, inférieure, droite, gauche et médiane, en tout","Postéro-supérieure et antérieure, en trois segments","Cervicale, thoracique et lombaire","Antérieure, latérale et postérieure"],"r":1,"e":"Postéro-supérieure + antérieure (subdivisée en 3 segments thoracique droit, épigastrique, thoracique gauche). L'antérieure comprend les segments thoracique droit, épigastrique et thoracique gauche.","s":12},{"q":"Rapports postéro-sup directs :","o":["Estomac","Diaphragme","Pancréas","Rate"],"r":1,"e":"Directement : diaphragme. Indirectement (à travers le diaphragme) : plèvre, poumon droit, péricarde, cœur.","s":12},{"q":"Rapport antérieur droit thoracique du foie :","o":["Les 1ʳᵉ à 3ᵉ côtes, sous la clavicule, à travers la plèvre","Les 8ᵉ à 10ᵉ côtes droites, et les 5ᵉ à 7ᵉ via la plèvre","Les 11ᵉ et 12ᵉ côtes, flottantes","Aucun rapport costal, direct ou non"],"r":1,"e":"8-9-10ème côtes droites + 5-6-7ème (recess costo-diaphragmatique droit).","s":12},{"q":"Sillon transverse contient :","o":["La veine cave inférieure, en arrière, et les veines hépatiques","Le pédicule hépatique, porte, artériel et biliaire","L'aorte abdominale, en arrière","La vésicule biliaire et le cystique"],"r":1,"e":"Hile = pédicule hépatique inférieur (VP, AH, VBP, nerfs, lymphatiques).","s":12},{"q":"Sillon AP gauche, partie antérieure :","o":["Le ligament rond, vestige de la veine ombilicale","Le canal d'Arantius, vestige fœtal","La vésicule biliaire, en avant","La veine cave inférieure et les veines spiégeliennes"],"r":0,"e":"Antérieur : lig rond. Postérieur : lig veineux d'Arantius.","s":12},{"q":"Sillon AP droit, partie postérieure :","o":["La vésicule biliaire","La veine cave inférieure","L'aorte abdominale","Le ligament rond, en avant du hile"],"r":1,"e":"Sillon AP droit : vésicule en avant + VCI en arrière.","s":12},{"q":"Empreintes face viscérale gauche :","o":["Empreinte colique","Empreinte gastrique","Empreinte rénale","Empreinte duodénale"],"r":1,"e":"À gauche du sillon AP gauche : empreinte gastrique (face antérieure de l'estomac).","s":12},{"q":"Face postérieure du foie correspond à :","o":["De L1 à L3, voire L4","De D9 à D11, voire D12","De D5 à D7, voire D8","De D1 à D3, voire D4"],"r":1,"e":"Face postérieure en regard de D9, D10, D11, parfois D12.","s":12},{"q":"Segment médian de la face postérieure :","o":["L'empreinte gastrique et l'œsophage abdominal, à gauche","Le pilier droit, le tronc cœliaque et le corps du pancréas","Le foie gauche, en entier, et la rate","La vésicule biliaire, en avant"],"r":1,"e":"Segment médian (entre les 2 sillons verticaux postérieurs) : pilier droit, aorte (gauche), VCI (droite), tronc cœliaque, pancréas, estomac. Le plexus solaire y est aussi.","s":12},{"q":"Empreinte surrénale est sur :","o":["La face supérieure, sous la coupole diaphragmatique","La face postérieure, sur son segment droit","La face inférieure, viscérale","Le bord antérieur, tranchant"],"r":1,"e":"Segment droit face postérieure : empreinte surrénale droite.","s":12},{"q":"Empreinte œsophagienne est sur :","o":["La face droite, contre les côtes et la paroi latérale","La face postérieure, sur son segment gauche","La face antérieure, sous le sternum","Le bord inférieur, tranchant"],"r":1,"e":"Segment gauche face postérieure : empreinte œsophagienne.","s":12},{"q":"Empreinte cardiaque est sur :","o":["La face viscérale, au contact de l'estomac","La face postéro-supérieure, via le diaphragme","La face postérieure, en arrière","Le hile, au centre de la face"],"r":1,"e":"Rapport indirect avec la face postéro-inf du cœur (via le diaphragme). C'est la face inférieure du cœur qui s'y imprime.","s":12},{"q":"Rapport antérieur du foie épigastrique :","o":["Les côtes droites, directement","La paroi abdominale antérieure, où il est palpable","La plèvre, à travers la coupole diaphragmatique","La rate, par son pôle supérieur"],"r":1,"e":"Segment abdominal épigastrique : palpable directement à travers la paroi antérieure.","s":12},{"q":"Segment thoracique gauche du foie :","o":["Les 8ᵉ à 10ᵉ côtes droites","Les 5ᵉ à 8ᵉ cartilages costaux gauches","Les 2ᵉ à 4ᵉ côtes gauches, sous le sein, en avant","Aucune côte, mais le sternum seul"],"r":1,"e":"Rapport : 5e-8e cartilages costaux gauches.","s":12},{"q":"Le pédicule hépatique passe dans :","o":["Le grand omentum, en avant du côlon","Le bord libre du petit omentum","Le ligament falciforme","Le mésocôlon transverse"],"r":1,"e":"Ligament hépato-duodénal = bord libre du petit omentum, contient le pédicule. C'est le ligament hépato-duodénal.","s":12},{"q":"Empreinte rénale du foie est en :","o":["En avant, sous les côtes","À droite, pour le rein droit","À gauche, pour l'estomac","En haut, sous la coupole, contre la surrénale"],"r":1,"e":"Face viscérale droite : empreinte rénale (rein droit) et empreinte duodénale (D2).","s":12},{"q":"Hépatorraphie (suture du foie) :","o":["Impossible, le foie se déchirant","Possible, mais le parenchyme est friable","La suture du rein, et non du foie","Une inflammation du foie, à distinguer de l'hépatite virale"],"r":1,"e":"Hépatorraphie = suture du foie. Tissu friable, technique délicate.","s":12},{"q":"Le lit vésiculaire est sur :","o":["La face postérieure, contre la veine cave inférieure","La face viscérale, dans le sillon droit","La face supérieure, sous le diaphragme","Le bord antérieur, tranchant"],"r":1,"e":"Fossette cystique = sillon AP droit antérieur. Au contact du lobe carré et droit.","s":12},{"q":"Échancrures du bord antérieur :","o":["Trois, dont une pour la veine porte","Deux, pour le ligament rond et la vésicule","Aucune, le bord étant lisse et continu","Cinq, une par segment hépatique"],"r":1,"e":"2 échancrures du bord antérieur : ligament rond (médiale) + vésicule (droite).","s":12},{"q":"Ligament veineux d'Arantius vestige de :","o":["De la veine ombilicale, à la naissance","Du canal veineux, court-circuit du foie fœtal","De la veine porte fœtale, avant la naissance, à gauche","De l'aorte abdominale fœtale"],"r":1,"e":"Canal veineux d'Arantius (Ductus venosus) chez le fœtus court-circuite le foie. Devient le ligament veineux.","s":12},{"q":"Lobe carré du foie est :","o":["Postéro-supérieur, contre le diaphragme et la VCI","Antérieur, entre les deux sillons, devant le hile","À gauche, contre l'estomac","Au-dessus du foie droit"],"r":1,"e":"Lobe carré : entre les 2 sillons AP, en avant du sillon transverse (hile). Les deux sillons sont antéro-postérieurs.","s":12},{"q":"Lobe caudé est :","o":["Antérieur, devant le hile","Postérieur, entre la VCI et le ligament veineux","Latéral droit, contre la VCI et la surrénale droite","Inexistant chez l'adulte"],"r":1,"e":"Lobe caudé (Spiegel) = postérieur, entre VCI (droite) et lig veineux (gauche), au-dessus du hile. Il est au-dessus du sillon transverse.","s":12},{"q":"Ligament hépato-rénal :","o":["Relie foie à pancréas","Relie foie au rein droit","Relie foie au diaphragme","N'existe pas"],"r":1,"e":"Repli péritonéal du foie au rein droit. Empreinte rénale.","s":12},{"q":"Rapports indirects de la face postéro-sup :","o":["L'estomac et le pancréas, en arrière","La plèvre, le poumon droit, le péricarde et le cœur","La rate et le rein gauche, en dehors","Les reins, les surrénales et les uretères, en arrière et en bas"],"r":1,"e":"À travers le diaphragme : plèvre, base poumon droit, base péricarde, face postéro-inf du cœur. Ce sont des rapports à travers le diaphragme.","s":12},{"q":"Du foie à la paroi abdominale antérieure :","o":["Ligament falciforme","Ligament coronaire","Ligament rond uniquement","Petit omentum"],"r":0,"e":"Ligament falciforme du foie à la paroi abdo antérieure et au diaphragme.","s":12},{"q":"Couleur du foie :","o":["Blanc","Jaune","Rouge-brun","Vert"],"r":2,"e":"Rouge-brun. Devient jaune (stéatose) ou nodulaire (cirrhose) en cas de pathologie.","s":12},{"q":"Le bord postérieur droit montre :","o":["L'empreinte de l'estomac, à gauche","L'orifice de la veine cave inférieure","Le passage de l'aorte","Le cardia de l'estomac"],"r":1,"e":"Bord postéro-droit : orifice de la VCI (qui traverse le diaphragme à T8).","s":12},{"q":"Bord postérieur gauche montre :","o":["Orifice de la VCI","Empreinte œsophagienne","Aorte","Empreinte gastrique"],"r":1,"e":"Bord postéro-gauche : empreinte œsophagienne (œsophage abdominal).","s":12},{"q":"Empreinte duodénale du foie :","o":["À D1, le bulbe mobile","À D2, la portion descendante","À D3, la portion horizontale, devant l'aorte","Au jéjunum proximal"],"r":1,"e":"L'empreinte duodénale correspond à D2 (descendante).","s":12},{"q":"Empreinte colique du foie correspond à :","o":["Côlon transverse moyen","Angle hépatique du côlon","Sigmoïde","Cæcum"],"r":1,"e":"Empreinte colique = angle hépatique (angle colique droit).","s":12},{"q":"La face supérieure du foie est divisée en deux parties par :","o":["Le ligament falciforme","Le ligament coronaire","Le sillon de la veine cave","Le hile"],"r":0,"e":"Sa partie antérieure se subdivise elle-même en segments thoracique droit, abdominal épigastrique et thoracique gauche.","s":12},{"q":"Les rapports postéro-supérieurs indirects du foie, à travers le diaphragme, sont :","o":["La plèvre, le poumon droit, le péricarde et le cœur","L'estomac, la rate et la queue du pancréas, à gauche","Le rein droit et la surrénale","Le côlon transverse et son méso"],"r":0,"e":"Le cœur y laisse une empreinte cardiaque ; seul le diaphragme est en rapport direct. Il s'agit de la base du poumon et du péricarde, et de la face postéro-inférieure du cœur.","s":12},{"q":"Un abcès ou une tumeur du foie peut, du fait de ses rapports thoraciques :","o":["S'étendre vers la plèvre ou refouler le diaphragme","Comprimer le rein gauche, puis la rate et le côlon gauche","Envahir la rate, à gauche","Atteindre le pancréas d'emblée"],"r":0,"e":"Une pleurésie réactionnelle en est la traduction clinique classique.","s":12},{"q":"Le segment thoracique droit de la face antérieure du foie répond :","o":["Aux côtes droites 8 à 10, et 5 à 7 via la plèvre","Aux 5ᵉ à 8ᵉ cartilages costaux gauches, en avant","À la paroi abdominale antérieure, palpable","Au sternum et au processus xiphoïde"],"r":0,"e":"Le segment thoracique gauche répond aux 5ᵉ à 8ᵉ cartilages costaux gauches.","s":12},{"q":"Le segment abdominal épigastrique de la face antérieure du foie correspond :","o":["À la zone palpable à travers la paroi abdominale","À la zone nue, sans péritoine","Au hile, avec le pédicule hépatique","À la face postérieure, contre le pilier droit du diaphragme"],"r":0,"e":"C'est par là que s'effectue la palpation hépatique clinique.","s":12},{"q":"Le sillon antéro-postérieur gauche de la face viscérale est :","o":["Peu profond et large","Étroit et très profond","Occupé par la vésicule","Occupé par la veine cave"],"r":1,"e":"Le sillon droit, peu profond, contient le canal cystique et la vésicule biliaire.","s":12},{"q":"L'empreinte duodénale de la face viscérale du foie correspond :","o":["À la 2ᵉ portion du duodénum","Au bulbe duodénal, en D1","À D3, horizontale","À D4, ascendante"],"r":0,"e":"Les empreintes colique et rénale correspondent, elles, à l'angle hépatique du côlon et au rein droit.","s":12},{"q":"L'empreinte gastrique de la face viscérale se situe :","o":["À droite du sillon antéro-postérieur droit","À gauche du sillon antéro-postérieur gauche","Au hile, autour du pédicule","Sur la face postérieure, en arrière"],"r":1,"e":"Elle correspond à la face antérieure de l'estomac.","s":12},{"q":"Le contenu du hile hépatique comprend :","o":["La veine porte, l'artère hépatique et le canal hépatique","La veine cave inférieure et les veines spiégeliennes","Le ligament rond, en avant","Les veines sus-hépatiques, au-dessus du hile"],"r":0,"e":"C'est le pédicule hépatique inférieur, situé dans le sillon transversal. Des plexus nerveux et des lymphatiques l'accompagnent.","s":12},{"q":"Au hile, la disposition du pédicule est :","o":["Porte en arrière, artère en dedans et canal en dehors","Porte en avant, artère en arrière, canal en dedans","Canal hépatique en arrière, porte en avant","Artère hépatique en arrière, canal en avant"],"r":0,"e":"Cette disposition est essentielle pour la chirurgie hépatique. L'artère est antéro-médiale et le canal antéro-latéral.","s":12},{"q":"Les deux sillons verticaux de la face postérieure du foie sont :","o":["Celui de la veine cave et celui du canal d'Arantius","Celui du ligament rond et celui de la vésicule","Deux sillons péritonéaux, aux bords du ligament coronaire","Les sillons coronaires, en haut"],"r":0,"e":"Ils divisent la face postérieure en trois segments : droit, médian et gauche. La veine cave est à droite, le canal d'Arantius à gauche.","s":12},{"q":"L'empreinte surrénale du foie se situe sur :","o":["Le segment droit de la face postérieure","Le segment médian de la face postérieure","Le segment gauche de la face postérieure","La face antérieure, sous les côtes droites"],"r":0,"e":"L'empreinte œsophagienne occupe, elle, le segment gauche de la face postérieure.","s":12},{"q":"Le segment médian de la face postérieure du foie répond en bas :","o":["Au tronc cœliaque, au corps du pancréas et à l'estomac","Au rein droit et à la surrénale droite, en dehors du foie","À la rate et à la queue du pancréas","Au côlon descendant, à gauche"],"r":0,"e":"En arrière il répond au pilier droit du diaphragme, à gauche à l'aorte et à droite à la veine cave inférieure. Le plexus solaire et la petite courbure en font aussi partie.","s":12},{"q":"L'extrémité droite du foie est :","o":["Très développée et arrondie, dans l'hypochondre droit","Fine et aplatie, logée dans l'hypochondre gauche","Située dans l'épigastre, sous le sternum","Absente, le foie étant symétrique"],"r":0,"e":"L'extrémité gauche est, elle, fine et aplatie.","s":12},{"q":"Le lobe carré est délimité, sur la face viscérale :","o":["Entre les deux sillons, en avant du sillon transverse","Entre les deux sillons, en arrière du sillon transverse","À droite du sillon droit, sur le rein","À gauche du sillon gauche, au contact de l'estomac et du cardia"],"r":0,"e":"Le lobe caudé, ou de Spiegel, occupe la même position mais en arrière du sillon transverse. Ce sont les deux sillons antéro-postérieurs.","s":12},{"q":"Le sillon antéro-postérieur gauche contient, en avant :","o":["Le sillon de la veine ombilicale, avec le ligament rond","Le canal d'Arantius, vestige du canal veineux du fœtus, seul","La vésicule biliaire, dans sa fossette","La veine cave inférieure, en arrière"],"r":0,"e":"En arrière, il contient le sillon du canal veineux d'Arantius, ou ligament veineux.","s":12},{"q":"Les plexus nerveux du hile hépatique proviennent :","o":["Du plexus solaire ou cœliaque","Du nerf phrénique","Du plexus mésentérique inférieur","Du nerf pudendal"],"r":0,"e":"Ils accompagnent la veine porte, l'artère hépatique et le canal hépatique dans le pédicule.","s":12},{"q":"La face inférieure du foie est aussi en rapport avec :","o":["Le duodénum, le pylore, le petit omentum et le côlon droit","La rate uniquement, par sa face interne et par son hile","Le rein gauche et la surrénale gauche, en arrière","La queue du pancréas, contre la rate"],"r":0,"e":"Les empreintes colique, rénale, duodénale et gastrique en marquent la surface. Le plexus solaire en fait aussi partie.","s":12},{"q":"Le lit vésiculaire se situe :","o":["Dans le sillon antéro-postérieur droit","Dans le sillon antéro-postérieur gauche","Au hile hépatique, en avant","Sur la face postérieure, contre la veine cave"],"r":0,"e":"Ce sillon contient la vésicule biliaire en avant et le canal cystique. C'est sur la face viscérale.","s":12},{"q":"La face supérieure du foie est décrite comme :","o":["Convexe et lisse","Concave et irrégulière","Plane","Recouverte d'empreintes"],"r":0,"e":"La face inférieure ou viscérale est au contraire concave et porte le « H » et les empreintes.","s":12},{"q":"Veine porte se forme par :","o":["La veine cave inférieure et l'aorte","La mésentérique supérieure et le tronc spléno-mésaraïque","La mésentérique supérieure et la veine cave, derrière le pancréas","La splénique et l'iliaque commune"],"r":1,"e":"VMS + tronc spléno-mésaraïque (= splénique + VMI). Elle se forme en arrière de la tête du pancréas.","s":13},{"q":"Artère hépatique commune naît de :","o":["Aorte directement","Tronc cœliaque","AMS","Veine porte"],"r":1,"e":"Tronc cœliaque → hépatique commune → gastro-duodénale + hépatique propre.","s":13},{"q":"Veines hépatiques se jettent dans :","o":["Veine porte","VCI","Veine azygos","VCS"],"r":1,"e":"3 veines hépatiques (droite, médiane, gauche) → VCI juste sous le diaphragme.","s":13},{"q":"Lobule hépatique classique :","o":["Triangulaire, avec un canal central","Hexagonal, avec une veine centro-lobulaire","Sphérique, sans organisation","Cylindrique, autour d'un espace porte"],"r":1,"e":"Lobule hexagonal. Veine centro-lobulaire au centre, espaces portes aux 6 angles.","s":13},{"q":"Espace porte de Kiernan contient (triade portale) :","o":["La veine cave inférieure, l'aorte et l'œsophage abdominal","Une branche porte, une artère et un canal biliaire","Une veine sus-hépatique, seule","Les veines centro-lobulaires"],"r":1,"e":"Triade portale aux 6 angles : VP + AH + canal biliaire. L'artère est une branche de l'artère hépatique.","s":13},{"q":"Hépatocyte est :","o":["Strictement mononucléé et diploïde","Souvent binucléé et polyploïde","Dépourvu de noyau, à maturité","Multinucléé, à dix noyaux"],"r":1,"e":"Souvent binucléé, polyploïde. Riche en mitochondries, REL, RER.","s":13},{"q":"Cellules de Kupffer :","o":["Des hépatocytes spécialisés dans la bile","Des macrophages des sinusoïdes hépatiques","Des cellules des canaux biliaires","Des cellules tumorales"],"r":1,"e":"Macrophages spécifiques du foie. Phagocytose.","s":13},{"q":"Cellules de Ito (stellaires) :","o":["Elles sécrètent la bile dans les canalicules","Elles stockent la vitamine A","Elles assurent la filtration glomérulaire","Elles produisent des hormones"],"r":1,"e":"Espace de Disse. Stockage vitamine A. Activation = fibrose hépatique (cirrhose). Leur activation entraîne la fibrose.","s":13},{"q":"Sinusoïdes hépatiques :","o":["Des capillaires continus, étanches","Des capillaires fenestrés, sans membrane basale","Des artères de petit calibre, avec une média musculaire","Des veinules de drainage"],"r":1,"e":"Sinusoïdes fenestrés → permettent les échanges entre sang et hépatocytes (espace de Disse).","s":13},{"q":"Circulation sanguine vs biliaire dans le lobule :","o":["Dans le même sens, de la périphérie au centre","À contre-courant, le sang vers le centre","Aléatoire, sans sens défini","Stagnante, sans aucun mouvement entre les repas"],"r":1,"e":"Sang vers le centre, bile vers les espaces portes. La bile, elle, va du centre vers la périphérie.","s":13},{"q":"Production journalière de bile :","o":["100 mL","300 mL","600-1000 mL","5 L"],"r":2,"e":"~600 à 1000 mL/jour, continue.","s":13},{"q":"La bile contient principalement :","o":["Des enzymes digestives, comme la lipase et l'amylase","Des sels biliaires, de la bilirubine et du cholestérol","Des hormones digestives","Du glucose et des acides aminés"],"r":1,"e":"Bile = 97% eau + sels biliaires + bilirubine conjuguée + cholestérol + phospholipides + électrolytes. Elle contient aussi des phospholipides.","s":13},{"q":"Cycle entéro-hépatique des sels biliaires :","o":["Aucun recyclage, tout étant perdu dans les selles","Environ 95 % réabsorbés à l'iléon","Une destruction dans le côlon","Une excrétion dans l'urine, à 50 %"],"r":1,"e":"Recyclage iléon → VP → foie → re-sécrétion. 6-10 cycles/jour. Ils rejoignent le foie par la veine porte.","s":13},{"q":"Bilirubine non conjuguée est :","o":["Hydrosoluble, éliminée dans l'urine","Liposoluble, transportée liée à l'albumine","Excrétée dans la bile sans modification","Toxique pour le foie, qu'elle détruit en quelques heures"],"r":1,"e":"Libre = liposoluble, fixée sur albumine. Foie la conjugue → hydrosoluble.","s":13},{"q":"Détoxification phase I :","o":["Une conjugaison avec l'acide glucuronique, en phase II","Une oxydation ou une réduction, par les cytochromes","Une excrétion dans la bile","Une phagocytose, par les cellules de Kupffer"],"r":1,"e":"Phase I = CYP450 (oxydation). Phase II = conjugaison (glucurono, sulfo). Ce sont les cytochromes P450.","s":13},{"q":"Foie synthétise (sauf un) :","o":["L'albumine plasmatique","Les facteurs de coagulation","Les gamma-globulines","Le fibrinogène"],"r":2,"e":"γ-globulines = anticorps, produites par plasmocytes. Le foie fait toutes les autres protéines plasmatiques.","s":13},{"q":"Facteurs de coagulation vitamine K dépendants :","o":["Aucun facteur, en réalité","Les facteurs II, VII, IX et X","Tous les facteurs","Les facteurs V et XI, seulement"],"r":1,"e":"II, VII, IX, X = vitamine K. Cible des AVK (anticoagulants).","s":13},{"q":"Glycogénogenèse :","o":["Dégrade le glycogène","Stocke le glucose en glycogène","Crée du glucose depuis des AA","Détruit les hépatocytes"],"r":1,"e":"Glycogénogenèse = synthèse de glycogène. Glycogénolyse = sa dégradation. Néoglucogenèse = depuis AA/lactate.","s":13},{"q":"Cycle de l'urée :","o":["Rénal, il élimine directement l'urée","Hépatique, il convertit l'ammoniac en urée","Intestinal, il forme l'ammoniac","Musculaire, il recycle les acides aminés à l'effort, via le NH3"],"r":1,"e":"Foie. NH3 (toxique) → urée (éliminée par les reins).","s":13},{"q":"Marqueurs de cytolyse hépatique :","o":["PAL et γ-GT","ASAT et ALAT","Bilirubine seule","TP et albumine"],"r":1,"e":"ASAT (TGO) + ALAT (TGP) = cytolyse. ALAT plus spécifique du foie.","s":13},{"q":"Marqueurs de cholestase :","o":["Les ASAT et les ALAT, très élevées","Les gamma-GT, les PAL et la bilirubine","L'albumine et le TP, abaissés","La CRP et la VS, élevées"],"r":1,"e":"γ-GT + PAL + bilirubine = cholestase (obstacle au flux biliaire).","s":13},{"q":"Insuffisance hépato-cellulaire :","o":["Des ASAT élevées, isolées","Un TP, un facteur V et une albumine abaissés","Une hausse des protéines plasmatiques","Une hyperbilirubinémie isolée, sans autre signe biologique"],"r":1,"e":"TP, facteur V, albumine évaluent les fonctions de synthèse hépatique.","s":13},{"q":"Hypertension portale survient si pression :","o":["> 5 mmHg","> 12 mmHg","> 30 mmHg","> 100 mmHg"],"r":1,"e":"Normalement ~10 mmHg. > 12 mmHg = HTP. Cause principale : cirrhose.","s":13},{"q":"Conséquences de l'HTP :","o":["Aucune conséquence clinique, en général","Des varices œsophagiennes, une ascite et une splénomégalie","Une hypertrophie cardiaque, avec insuffisance ventriculaire droite","Un diabète, par atteinte du pancréas"],"r":1,"e":"VO + ascite + splénomégalie + collatérales (tête de méduse) + encéphalopathie. La tête de méduse en fait aussi partie.","s":13},{"q":"Syndrome de Budd-Chiari :","o":["Un obstacle sur la veine porte","Une thrombose des veines hépatiques","Un cancer de la tête du pancréas","Une cirrhose alcoolique, ancienne"],"r":1,"e":"Thrombose des veines hépatiques → blocage de sortie → hépatomégalie douloureuse, ascite.","s":13},{"q":"Cirrhose hépatique :","o":["Une atteinte toujours réversible","Une fibrose diffuse avec des nodules, irréversible","Une hypertrophie pure du foie","Une infection aiguë, guérissant toujours sans séquelle"],"r":1,"e":"Stade ultime des hépatopathies chroniques. Causes : alcool, hépatites virales, NASH. Les nodules sont de régénération.","s":13},{"q":"Manœuvre de Pringle :","o":["Une manœuvre de réanimation cardiaque","Un clampage du pédicule, contre le saignement","Un examen clinique du foie, à la palpation","Un test biologique hépatique"],"r":1,"e":"Au foramen de Winslow. Tolérable ~15-20 min sans dommage. Le pédicule hépatique est clampé au foramen de Winslow.","s":13},{"q":"Douleur hépatique projetée :","o":["Au bras gauche, par les fibres sympathiques T1-T4","À l'épaule droite, par le nerf phrénique","À la mâchoire, par le trijumeau","Au genou droit, par le fémoral"],"r":1,"e":"Distension capsule de Glisson → irritation diaphragmatique → nerf phrénique → épaule droite. Le phrénique naît de C3 à C5.","s":13},{"q":"Stockage hépatique :","o":["L'insuline et le glucagon, en réserve","Le glycogène, les vitamines liposolubles, la B12 et le fer","Le sodium et le potassium, stockés dans les hépatocytes, en excès","Le calcium et la vitamine D3, comme l'os"],"r":1,"e":"Stockage : glycogène (~75 g), vitamines A/D/E/K, B12, fer (ferritine).","s":13},{"q":"Sensibilité du foie :","o":["Un parenchyme très sensible","Un parenchyme insensible, mais une capsule sensible","Aucune sensibilité, ni capsulaire ni parenchymateuse","Une sensibilité variable selon l'heure"],"r":1,"e":"Parenchyme insensible. Distension capsulaire = douleur hépatique. La capsule est celle de Glisson.","s":13},{"q":"Le foie est le seul organe du corps à recevoir :","o":["Un double apport sanguin","Un apport exclusivement veineux","Un apport exclusivement artériel","Un apport lymphatique direct"],"r":0,"e":"La veine porte fournit 75 % du sang et l'artère hépatique 25 %, mais cette dernière apporte 50 % de l'oxygène.","s":13},{"q":"Les deux circulations hépatiques convergent :","o":["Dans les sinusoïdes hépatiques","Dans la veine porte","Dans les canalicules biliaires","Dans la veine cave"],"r":0,"e":"La sortie se fait ensuite par les veines hépatiques vers la veine cave inférieure.","s":13},{"q":"La veine porte se forme :","o":["En arrière de la tête du pancréas","Au hile hépatique, en haut","Derrière l'estomac, à gauche","Devant l'aorte, en L3"],"r":0,"e":"Elle naît de la réunion de la veine mésentérique supérieure et du tronc spléno-mésaraïque.","s":13},{"q":"Le tronc spléno-mésaraïque réunit :","o":["La veine splénique et la mésentérique inférieure","Les deux veines mésentériques","La veine splénique et la mésentérique supérieure, ensemble","La mésentérique supérieure et la gastrique"],"r":0,"e":"Il draine la rate, l'estomac et le côlon gauche ; la VMS draine l'intestin grêle et le côlon droit.","s":13},{"q":"La veine porte mesure environ :","o":["4 cm","8 cm","15 cm","20 cm"],"r":1,"e":"Elle chemine dans le ligament hépato-duodénal et se divise au hile en branches droite et gauche.","s":13},{"q":"La pression dans le système porte est d'environ :","o":["5 mmHg","10 mmHg","25 mmHg","40 mmHg"],"r":1,"e":"C'est un système à basse pression et sans valvules.","s":13},{"q":"L'anastomose porto-cave ombilicale se traduit cliniquement par :","o":["Des varices œsophagiennes","Une tête de méduse","Des hémorroïdes","Un ascite"],"r":1,"e":"La dérivation œsophagienne donne des varices œsophagiennes au risque hémorragique majeur, et la dérivation rectale des hémorroïdes.","s":13},{"q":"L'artère hépatique commune donne :","o":["La gastro-duodénale et l'hépatique propre","L'artère splénique et la gastrique gauche, en haut","L'artère gastrique gauche","L'artère mésentérique supérieure"],"r":0,"e":"L'artère cystique naît habituellement de la branche droite de l'hépatique propre. La gastro-duodénale descend, l'hépatique propre monte.","s":13},{"q":"Parmi les variations fréquentes de l'artère hépatique, le cours cite :","o":["Une gauche issue de la gastrique gauche, une droite de l'AMS","Une hépatique issue directement de l'aorte, en T12, à droite","Une absence d'artère hépatique","Une double artère cystique, seule"],"r":0,"e":"Leur connaissance est essentielle en chirurgie et en transplantation.","s":13},{"q":"Les veines spiégeliennes drainent :","o":["Le lobe caudé, directement dans la veine cave","Le lobe droit, par la veine hépatique droite","Le lobe carré, vers la porte","Le segment IV, par la veine hépatique médiane et la gauche"],"r":0,"e":"Les trois veines hépatiques — droite, médiane et gauche — se jettent dans la VCI juste sous le diaphragme.","s":13},{"q":"Les veines hépatiques se caractérisent par :","o":["L'absence de gaine fibreuse propre","Une paroi épaisse","La présence de valvules","Un trajet extra-hépatique long"],"r":0,"e":"Elles servent de repères pour la segmentation hépatique.","s":13},{"q":"Dans le ligament hépato-duodénal, la disposition du pédicule est :","o":["Artère et voie biliaire en avant, veine porte en arrière","Veine porte en avant, artère et voie biliaire en arrière","Voie biliaire en arrière, artère et porte devant","Artère hépatique en arrière, voie biliaire et veine porte devant"],"r":0,"e":"Ce ligament constitue le bord libre du petit omentum. L'artère est à gauche, la voie biliaire à droite.","s":13},{"q":"Le lobule hépatique classique est :","o":["Hexagonal, avec une veine centrale et six espaces portes","Circulaire, avec un espace porte central et des sinus","Triangulaire, avec trois veines centrales","Sans organisation définie, en nappe"],"r":0,"e":"Chaque espace porte de Kiernan contient la triade portale : branche de la veine porte, branche de l'artère hépatique et canalicule biliaire. Les espaces portes sont aux six angles.","s":13},{"q":"L'hépatocyte représente environ :","o":["50 % des cellules hépatiques","80 % des cellules hépatiques","95 %","30 %"],"r":1,"e":"Souvent binucléé et polyploïde, il est riche en mitochondries, en réticulum lisse pour la détoxification et en réticulum granuleux pour la synthèse.","s":13},{"q":"Les trois pôles de l'hépatocyte sont :","o":["Sinusoïdal, biliaire et inter-hépatocytaire","Apical, basal et latéral","Portal, central et périphérique, comme le lobule","Vasculaire, biliaire et lymphatique"],"r":0,"e":"Les hépatocytes sont disposés en travées d'une seule cellule d'épaisseur.","s":13},{"q":"Les sinusoïdes hépatiques sont des capillaires :","o":["Fenestrés, sans membrane basale continue","Continus, avec une membrane épaisse","Musculaires, avec une média contractile épaisse","Lymphatiques, borgnes"],"r":0,"e":"L'espace de Disse, entre sinusoïde et hépatocyte, est le lieu des échanges.","s":13},{"q":"Les cellules de Ito, ou cellules stellaires :","o":["Stockent la vitamine A et participent à la fibrose","Sont des macrophages, comme les Kupffer","Produisent la bile, au pôle biliaire","Sont des cellules endothéliales, qui bordent les sinusoïdes"],"r":0,"e":"Les cellules de Kupffer sont, elles, les macrophages spécifiques du foie.","s":13},{"q":"Dans le lobule hépatique, le sang circule :","o":["De la périphérie vers le centre","Du centre vers la périphérie","De haut en bas","Dans les deux sens"],"r":0,"e":"La bile circule en sens inverse, ce qui définit la circulation à contre-courant.","s":13},{"q":"L'apport fonctionnel en oxygène du foie est assuré pour moitié par :","o":["La veine porte","L'artère hépatique","Les veines hépatiques","Les lymphatiques"],"r":1,"e":"L'artère hépatique ne fournit que 25 % du volume sanguin mais 50 % de l'oxygène ; la veine porte apporte le sang riche en nutriments mais peu oxygéné.","s":13},{"q":"La veine cave inférieure, dans ses rapports au foie :","o":["Est en partie incluse dans le parenchyme du foie","Est totalement extra-hépatique","Traverse le hile, avec la porte","Passe devant le foie, contre la paroi abdominale antérieure"],"r":0,"e":"La zone nue postérieure du foie est par ailleurs directement adhérente au diaphragme.","s":13},{"q":"Capacité de la vésicule biliaire :","o":["5 mL","30-60 mL","200 mL","500 mL"],"r":1,"e":"30-60 mL. Réservoir de bile concentrée.","s":14},{"q":"La vésicule a une forme de :","o":["Cube","Poire","Sphère","Cylindre"],"r":1,"e":"Piriforme. ~10 cm × 3-4 cm.","s":14},{"q":"3 parties de la vésicule :","o":["Tête, corps, queue","Fundus, corps, col","Apex, base, isthme","Sup, médian, inf"],"r":1,"e":"Fundus + corps + col (avec bassinet d'Hartmann).","s":14},{"q":"Voie biliaire principale =","o":["Le canal cystique, à lui seul","Le canal hépatique commun et le cholédoque","Le canal de Wirsung et le canal de Santorini, réunis","Le canal de Santorini, accessoire"],"r":1,"e":"VBP = hépatique commun (avant la jonction cystique) + cholédoque (après).","s":14},{"q":"Canal cystique a :","o":["Valves anti-reflux","Valve spirale de Heister","Aucun pli","Valvule conniventes"],"r":1,"e":"Valve spirale de Heister dans le canal cystique.","s":14},{"q":"Ampoule de Vater =","o":["Une ampoule située au niveau gastrique","La jonction du cholédoque et du Wirsung, en D2","Une dilatation du côlon ascendant","Une dilatation de l'œsophage, au-dessus du cardia, en T10"],"r":1,"e":"Confluence des canaux biliaire et pancréatique. Papille duodénale majeure.","s":14},{"q":"Sphincter d'Oddi régule :","o":["Le passage du chyme de l'estomac au duodénum, au pylore","L'écoulement de la bile et du suc pancréatique","Le reflux œsophagien, au cardia","La continence anale, au repos"],"r":1,"e":"Autour de l'ampoule de Vater. Contrôle l'arrivée de bile et suc pancréatique dans D2.","s":14},{"q":"Triangle de Calot délimité par :","o":["La vésicule, l'estomac et le foie","Le cystique, l'hépatique commun et le foie","Trois ligaments du foie, en avant","L'aorte, la veine cave inférieure et le foie"],"r":1,"e":"Triangle cysto-hépatique. Contient l'artère cystique. Repère chirurgical. C'est la face inférieure du foie.","s":14},{"q":"Triangle de Calot contient :","o":["L'artère hépatique propre","L'artère cystique et le ganglion de Mascagni","La veine porte, en arrière","Le cholédoque, le canal de Wirsung et l'ampoule de Vater"],"r":1,"e":"Artère cystique + ganglion cystique. Important en cholécystectomie.","s":14},{"q":"Artère cystique naît de :","o":["L'aorte abdominale, directement","L'artère hépatique droite, en général","L'artère splénique, par une branche gastrique courte","L'artère gastrique gauche"],"r":1,"e":"Branche droite de l'artère hépatique propre. Variations fréquentes.","s":14},{"q":"Point cystique de Murphy :","o":["Sur la ligne médiane, sous l'appendice xiphoïde","Au croisement du grand droit et du rebord costal droit","À gauche, au croisement du grand droit et du rebord costal gauche","Au-dessus du nombril, de 2 cm"],"r":1,"e":"Projection cutanée de la vésicule. Signe de Murphy = arrêt inspiratoire en cas de cholécystite. C'est le bord externe du grand droit.","s":14},{"q":"Bassinet d'Hartmann est :","o":["Une artère de la vésicule","Une dilatation du col vésiculaire","Un sphincter du canal cystique","Une partie du lobe carré"],"r":1,"e":"Bassinet d'Hartmann dans le col vésiculaire. Lieu de blocage des calculs. Les calculs s'y enclavent.","s":14},{"q":"Vésicule histologiquement :","o":["Elle est identique au tube digestif","Elle n'a ni sous-muqueuse ni musculaire muqueuse","Elle a cinq tuniques, dont deux musculeuses","Elle a une capsule fibreuse, comme celle de Glisson pour le foie"],"r":1,"e":"Particularité : pas de sous-muqueuse vraie. 3 tuniques : muqueuse + musculeuse + séreuse.","s":14},{"q":"Concentration de la bile dans la vésicule :","o":["Aucune, la bile restant identique à celle du foie","Elle est concentrée de 5 à 10 fois","Elle est concentrée 100 fois","Elle est concentrée 1 000 fois"],"r":1,"e":"Vésicule réabsorbe l'eau de la bile → concentration 5-10×. Par réabsorption d'eau.","s":14},{"q":"Cholécystokinine (CCK) provoque :","o":["Une relaxation de la vésicule","Une contraction de la vésicule et un relâchement d'Oddi","Une sécrétion d'HCl par les cellules pariétales de l'estomac","Une vasoconstriction digestive"],"r":1,"e":"CCK (duodénum) → contraction vésiculaire + ouvre Oddi → bile dans D2. La bile est alors libérée.","s":14},{"q":"CCK est libérée en réponse à :","o":["Du glucose dans le duodénum","Des lipides et des acides aminés du duodénum","De l'acide gastrique, au bulbe","De l'eau, dès qu'elle arrive dans l'estomac, par distension"],"r":1,"e":"Lipides et AA dans D2 → CCK → bile + enzymes pancréatiques.","s":14},{"q":"Rôle des sels biliaires :","o":["Digestion des protéines","Émulsification des lipides","Absorption du glucose","Métabolisme protéique"],"r":1,"e":"Émulsionnent les lipides → facilitent l'action de la lipase pancréatique.","s":14},{"q":"Lithiase biliaire :","o":["Très rare, sauf chez l'enfant de moins de 5 ans","Fréquente, avec les facteurs « 4 F »","Propre à l'enfant, avant 10 ans","Toujours symptomatique"],"r":1,"e":"« 4 F » classiques : Female, Forty, Fat, Fertile. Souvent asymptomatique. Ce sont Female, Forty, Fat et Fertile.","s":14},{"q":"Calculs biliaires les plus fréquents :","o":["Cholestéroliques (~75%)","Pigmentaires (~75%)","Calcium","Sodium"],"r":0,"e":"75% cholestéroliques, 25% pigmentaires.","s":14},{"q":"Colique hépatique se manifeste par :","o":["Une douleur épigastrique chronique, calmée par les repas","Une douleur de l'hypochondre droit, après un repas gras","Une diarrhée, après les repas","Une constipation, chronique"],"r":1,"e":"Douleur HCD post-prandiale, irradiation à l'épaule droite (nerf phrénique). Elle irradie vers l'épaule droite.","s":14},{"q":"Cholécystite aiguë :","o":["Une douleur sans fièvre, isolée","Une fièvre, une douleur et un signe de Murphy","Une forme toujours asymptomatique, découverte par hasard","Une forme indolore et apyrétique"],"r":1,"e":"Inflammation par blocage prolongé du canal cystique. Fièvre + douleur + Murphy +. La douleur siège à l'hypochondre droit.","s":14},{"q":"Lithiase du cholédoque entraîne :","o":["Aucun symptôme, en général","Un ictère obstructif, ou cholestatique","Une diarrhée chronique, grasse","Des vomissements isolés, sans fièvre ni douleur abdominale"],"r":1,"e":"Obstruction du cholédoque → bile ne s'écoule plus → ictère + selles décolorées + urines foncées.","s":14},{"q":"Angiocholite =","o":["Une inflammation du cœur, aiguë","Une infection des voies biliaires","Un œdème lymphatique, du bras","Une inflammation de la peau, au niveau de l'hypochondre droit"],"r":1,"e":"Triade de Charcot : fièvre + douleur HCD + ictère. Urgence. Elle complique souvent une lithiase.","s":14},{"q":"Cholécystectomie :","o":["L'ablation du foie, partielle","L'ablation de la vésicule biliaire","L'ablation du pancréas, céphalique","Un examen biologique du foie"],"r":1,"e":"Un des actes chirurgicaux les plus fréquents. Bonne tolérance après. Elle se fait souvent par cœlioscopie.","s":14},{"q":"Après cholécystectomie :","o":["Aucune digestion des graisses n'est possible","La bile coule directement dans le duodénum","Le foie cesse de produire de la bile, définitivement","Un régime sans graisse, à vie"],"r":1,"e":"Bile continue d'être produite par le foie, écoulement continu vers le duodénum. Adaptation digestive. La tolérance est bonne.","s":14},{"q":"Iléus biliaire :","o":["Une constipation, chronique et opiniâtre","Une occlusion par un gros calcul, passé par une fistule","Une diarrhée biliaire, après les repas","Un reflux de bile dans l'estomac, puis dans l'œsophage"],"r":1,"e":"Calcul migre via fistule vésico-duodénale → bloque l'intestin → occlusion.","s":14},{"q":"La vésicule est dans :","o":["Dans l'hypochondre gauche","Dans l'hypochondre droit, sous le foie","Dans le pelvis, derrière la vessie, en dessous du côlon","Dans le médiastin, sous le cœur"],"r":1,"e":"Sous le foie, dans la fossette cystique de la face viscérale (sillon AP droit). Elle est dans la fossette cystique.","s":14},{"q":"Stockage entre les repas — vésicule est :","o":["Pleine et concentrée, le sphincter d'Oddi fermé","Vide, le sphincter d'Oddi restant ouvert en continu","En contraction permanente","Sans aucun rôle de stockage"],"r":0,"e":"Entre les repas : remplissage et concentration. Oddi fermé.","s":14},{"q":"La couleur jaune de la bile vient de :","o":["Du cholestérol, en excès","De la bilirubine conjuguée","De l'hémoglobine, libre","De la lécithine, ou phosphatidylcholine"],"r":1,"e":"Bilirubine conjuguée. Donne aussi la couleur des selles (stercobiline) et urines (urobiline).","s":14},{"q":"Drainage lymphatique vésiculaire :","o":["Les ganglions iliaques, dans le petit bassin","Le ganglion de Mascagni, puis les cœliaques","Les ganglions axillaires, droits","Les ganglions inguinaux, profonds"],"r":1,"e":"Mascagni → pédicule hépatique → cœliaques. Il passe par les ganglions du pédicule hépatique.","s":14},{"q":"La vésicule biliaire mesure environ :","o":["5 cm de long et 1 cm de large","10 cm de long et 3 à 4 cm de large","15 cm de long et 6 cm de large, à jeun","20 cm de long et 8 cm de large"],"r":1,"e":"Sa capacité physiologique est de 30 à 60 mL. Sa capacité est de 30 à 60 mL.","s":14},{"q":"La vésicule biliaire se loge :","o":["Dans la fossette cystique, entre lobe droit et lobe carré","Sur la face postérieure du foie, contre la veine cave inférieure","Dans le hile, avec le pédicule","Sous le pancréas, en arrière"],"r":0,"e":"Son point de projection pariétale est le point cystique de Murphy, au croisement du bord externe du grand droit et du rebord costal droit. La fossette est sur la face viscérale du foie.","s":14},{"q":"Le bassinet d'Hartmann est :","o":["Une dilatation du col où les calculs peuvent se loger","Le fond arrondi de la vésicule","Le canal cystique, avec ses valvules spirales de Heister","Un repli du cholédoque, en bas"],"r":0,"e":"Le col, ou infundibulum, se prolonge par le canal cystique.","s":14},{"q":"Le fundus de la vésicule :","o":["L'extrémité antérieure, qui dépasse parfois le foie","Le segment qui se prolonge par le canal cystique et le col","La partie en contact, en bas, avec le duodénum","La partie qui contient le bassinet d'Hartmann"],"r":0,"e":"Le corps constitue la portion principale, en contact avec le foie. Il peut dépasser le bord inférieur du foie.","s":14},{"q":"Le canal hépatique commun résulte de la réunion :","o":["Des canaux hépatiques droit et gauche","Du canal hépatique et du canal cystique","Du cholédoque et du Wirsung","Des canaux pancréatiques"],"r":0,"e":"Sa réunion avec le canal cystique forme ensuite le canal cholédoque.","s":14},{"q":"Le canal cholédoque mesure environ :","o":["3 à 4 cm de long et 2 mm de diamètre","7 à 8 cm de long et 5 à 6 mm de diamètre","12 cm de long et 1 cm de diamètre","15 cm de long et 2 cm de diamètre"],"r":1,"e":"Il comporte trois portions : sus-duodénale, rétro-duodénale et intra-pancréatique.","s":14},{"q":"La portion rétro-duodénale du cholédoque passe :","o":["Derrière D1","Derrière D2","Dans le ligament hépato-duodénal","Dans le pancréas"],"r":0,"e":"La portion sus-duodénale chemine dans le ligament hépato-duodénal et la troisième est intra-pancréatique.","s":14},{"q":"Le canal cystique mesure environ :","o":["1 cm","3 à 4 cm","7 cm","10 cm"],"r":1,"e":"Il contient la valve spirale de Heister.","s":14},{"q":"Le triangle de Calot est délimité par :","o":["Le cystique, l'hépatique commun et la face inférieure du foie","Le cholédoque, le canal de Wirsung et le bord interne du duodénum","La vésicule, le foie et le pancréas","Les deux canaux hépatiques et le hile"],"r":0,"e":"Il contient l'artère cystique et le ganglion de Mascagni. Le cystique est à droite, l'hépatique commun à gauche.","s":14},{"q":"L'importance chirurgicale du triangle de Calot tient au fait qu'il faut :","o":["Repérer l'artère et le canal cystiques à ligaturer","Éviter la tête du pancréas et le duodénum, en bas","Repérer la veine porte, en arrière du pédicule","Préserver le ligament rond et le falciforme"],"r":0,"e":"C'est le repère essentiel de la cholécystectomie. Il ne faut pas léser le cholédoque.","s":14},{"q":"L'artère cystique naît :","o":["De l'artère hépatique droite, dans le triangle de Calot","De l'artère gastro-duodénale, derrière le duodénum","Du tronc cœliaque, directement","De l'artère mésentérique supérieure"],"r":0,"e":"Des variations sont fréquentes : artère cystique double, naissance de l'hépatique gauche, etc.","s":14},{"q":"Le drainage lymphatique de la vésicule suit la voie :","o":["Le ganglion de Mascagni, puis les cœliaques","Les ganglions mésentériques, puis la citerne du chyle","Les ganglions iliaques, dans le bassin","La citerne du chyle, directement"],"r":0,"e":"Les veines cystiques se drainent, elles, directement dans le parenchyme hépatique ou la veine porte. Les ganglions du pédicule hépatique sont un relais.","s":14},{"q":"L'innervation parasympathique de la vésicule, par le nerf vague, provoque :","o":["La contraction vésiculaire","Une vasoconstriction","Le relâchement vésiculaire","La sensibilité douloureuse"],"r":0,"e":"Le sympathique, de T5 à T9, assure vasoconstriction et sensibilité douloureuse.","s":14},{"q":"La paroi vésiculaire se distingue du reste du tube digestif par :","o":["L'absence de sous-muqueuse vraie et de musculaire muqueuse","L'absence de muqueuse, remplacée par la séreuse","L'absence de toute musculeuse","La présence de quatre tuniques, dont une sous-muqueuse épaisse"],"r":0,"e":"Elle comporte trois tuniques : muqueuse, musculeuse et séreuse sur la face libre.","s":14},{"q":"La muqueuse vésiculaire présente :","o":["Un épithélium prismatique simple, sans glande propre","Un épithélium pavimenteux stratifié, kératinisé","Des villosités, comme le grêle","Des cryptes, comme le côlon"],"r":0,"e":"Sa musculeuse est faite de fibres lisses orientées dans toutes les directions. Elle forme de nombreux replis.","s":14},{"q":"La production quotidienne de bile par le foie est de :","o":["100 à 300 mL","600 à 1 000 mL","2 à 3 L","50 mL"],"r":1,"e":"Cette production est continue, alors que l'évacuation est intermittente.","s":14},{"q":"Entre les repas, le sphincter d'Oddi est :","o":["Fermé, la bile remontant vers la vésicule","Ouvert, la bile coulant en continu, à jeun","Absent, sans rôle entre les repas","En contraction rythmique"],"r":0,"e":"La vésicule concentre alors la bile en réabsorbant l'eau, d'un facteur 5 à 10. Elle remonte par le canal cystique.","s":14},{"q":"La cholécystokinine est libérée par :","o":["Les cellules du duodénum, lors d'un repas gras","Les cellules gastriques, lors de la distension","Le pancréas, par les îlots","Le foie, avec la bile"],"r":0,"e":"Elle provoque la contraction de la vésicule et le relâchement du sphincter d'Oddi.","s":14},{"q":"Les sels biliaires facilitent l'action de la lipase pancréatique par :","o":["L'émulsification des lipides","L'hydrolyse des triglycérides","L'acidification du duodénum","L'activation de la trypsine"],"r":0,"e":"La bile permet aussi l'absorption des lipides et des vitamines liposolubles A, D, E et K.","s":14},{"q":"La bile assure également l'excrétion :","o":["De la bilirubine, du cholestérol et de médicaments","De l'urée, comme le rein","Du glucose et des acides aminés, juste après le repas","Des acides aminés, seuls"],"r":0,"e":"C'est la voie d'élimination hépatique des produits liposolubles, non éliminables par le rein.","s":14},{"q":"Le pancréas est :","o":["Une glande exocrine pure","Une glande endocrine pure","Une glande mixte, surtout exocrine","Un organe non sécrétoire, de stockage"],"r":2,"e":"Mixte : 98% exocrine (suc digestif) + 2% endocrine (insuline, glucagon). Il est exocrine à 98 % et endocrine à 2 %.","s":15},{"q":"Longueur du pancréas :","o":["5-8 cm","15-20 cm","30 cm","50 cm"],"r":1,"e":"15-20 cm, ~70-80 g.","s":15},{"q":"Position du pancréas :","o":["Intra-péritonéal, mobile","Rétro-péritonéal secondaire, sauf sa queue","Pelvien, sous le péritoine","Thoracique, juste au-dessus du diaphragme"],"r":1,"e":"Rétro-péritonéal accolé. Queue est intra-péritonéale dans le lig spléno-rénal.","s":15},{"q":"Niveau vertébral du pancréas :","o":["T8","L1-L2","L4-L5","S1"],"r":1,"e":"L1-L2, en avant de la colonne lombaire.","s":15},{"q":"Les 4 portions du pancréas :","o":["Sup, médian, inf, latéral","Tête, col, corps, queue","Lobe droit, gauche, médian","Apex, base, isthme"],"r":1,"e":"Tête (droite, dans le cadre duodénal) + col + corps + queue (au hile splénique).","s":15},{"q":"Processus uncinatus :","o":["Une partie de la queue, au hile splénique","Une partie de la tête, derrière les vaisseaux mésentériques","Une partie du col, devant la veine porte et l'artère mésentérique","Une partie du corps, devant l'aorte"],"r":1,"e":"« Crochet » pancréatique de la tête, en arrière des vaisseaux mésentériques. Ce sont les vaisseaux mésentériques supérieurs.","s":15},{"q":"Canal pancréatique principal :","o":["Santorini","Wirsung","Heister","Eustache"],"r":1,"e":"Wirsung = canal principal. Santorini = canal accessoire.","s":15},{"q":"Le Wirsung s'ouvre :","o":["Dans l'estomac, au pylore","Dans D2, à l'ampoule de Vater","Dans le jéjunum, après l'angle de D4","Dans le foie, par le canal hépatique commun et le hile"],"r":1,"e":"Confluence avec cholédoque → ampoule de Vater dans D2. Il s'y abouche avec le cholédoque.","s":15},{"q":"Cellules acineuses (exocrines) sécrètent :","o":["De l'insuline, en continu","Des enzymes digestives inactives","Du glucagon, par les cellules alpha des îlots","De la somatostatine, en continu"],"r":1,"e":"Acini produisent zymogènes (trypsinogène, chymotrypsinogène) + amylase + lipase.","s":15},{"q":"Îlots de Langerhans :","o":["Des cellules exocrines, en acini","Des amas endocrines, sécrétant insuline et glucagon","Des macrophages, comme au foie","Des cellules de soutien, du tissu conjonctif, autour des canaux"],"r":1,"e":"Îlots endocrines. ~1 million. Plus nombreux dans la queue. Ils sont plus nombreux dans la queue.","s":15},{"q":"Cellules β des îlots sécrètent :","o":["Glucagon","Insuline","Somatostatine","Polypeptide PP"],"r":1,"e":"β (70%) = insuline. α (20%) = glucagon. δ (5%) = somatostatine. PP = polypeptide pancréatique.","s":15},{"q":"Cellules α sécrètent :","o":["Insuline","Glucagon","Somatostatine","Amylase"],"r":1,"e":"α = glucagon = hyperglycémiant. Antagoniste de l'insuline.","s":15},{"q":"Volume de suc pancréatique quotidien :","o":["100 mL","500 mL","1-2 L","5 L"],"r":2,"e":"1-2 L/jour. Alcalin (~pH 8) grâce aux bicarbonates.","s":15},{"q":"pH du suc pancréatique :","o":["Acide (1-2)","Neutre (7)","Alcalin (~8)","Très acide (0)"],"r":2,"e":"Alcalin → neutralise le chyme gastrique acide dans le duodénum.","s":15},{"q":"Enzymes protéolytiques pancréatiques :","o":["L'amylase et la lipase, qui digèrent glucides et graisses","La trypsine, la chymotrypsine et l'élastase","La pepsine, active en milieu acide","La lipase pancréatique, seule"],"r":1,"e":"Toutes les protéolytiques sécrétées sous forme inactive (zymogènes). Les carboxypeptidases en font aussi partie.","s":15},{"q":"Lipase pancréatique :","o":["Elle digère les protéines","Elle digère les triglycérides","Elle digère les glucides, en partie","Elle synthétise des acides aminés"],"r":1,"e":"Lipase + bile (émulsification) → triglycérides → AG + glycérol.","s":15},{"q":"Sécrétine stimule :","o":["La sécrétion d'HCl gastrique","La sécrétion d'eau et de bicarbonates pancréatiques","La sécrétion biliaire et la contraction de la vésicule, au repas","La sécrétion gastrique de pepsine"],"r":1,"e":"Sécrétine = libérée en réponse à l'acide dans D2 → ↑ bicarbonates pancréatiques (neutralisation).","s":15},{"q":"CCK stimule :","o":["La sécrétion gastrique d'acide","La sécrétion d'enzymes pancréatiques et de bile","La sécrétion d'eau et de bicarbonates, seule","Aucune sécrétion pancréatique"],"r":1,"e":"CCK = libérée par lipides/AA dans D2 → enzymes pancréatiques + vésicule biliaire + relâche Oddi.","s":15},{"q":"Activation des zymogènes pancréatiques :","o":["Spontanée, dans le pancréas, dès leur sécrétion","Par l'entérokinase, qui active le trypsinogène","Par la pepsine gastrique","Par l'amylase salivaire"],"r":1,"e":"Entérokinase → trypsinogène → trypsine → active les autres zymogènes en cascade. La trypsine active ensuite les autres zymogènes.","s":15},{"q":"Insuline est :","o":["Hyperglycémiante","Hypoglycémiante","Sans effet sur la glycémie","Anti-inflammatoire"],"r":1,"e":"Insuline = hypoglycémiante. Stimule captation glucose, glycogénogenèse, lipogenèse.","s":15},{"q":"Diabète de type 1 :","o":["Une insulino-résistance liée au surpoids abdominal","Une destruction auto-immune des cellules bêta","Un excès de glucagon, chronique","Un excès d'insuline, à jeun"],"r":1,"e":"Type 1 = carence absolue en insuline (destruction des cellules β).","s":15},{"q":"Diabète de type 2 :","o":["Une carence absolue en insuline","Une insulino-résistance et un déficit relatif","Une destruction auto-immune des cellules bêta, chez l'enfant","Une cause génétique pure, unique"],"r":1,"e":"Type 2 = insulino-résistance (obésité, sédentarité) + déficit progressif de sécrétion.","s":15},{"q":"Pancréatite aiguë — causes principales :","o":["L'hypertension artérielle","L'alcool et la lithiase biliaire, à 80 %","Le stress, chez 50 % des patients jeunes, au travail","Le diabète, déséquilibré"],"r":1,"e":"Alcool + lithiase biliaire = 80% des causes.","s":15},{"q":"Pancréatite — marqueur biologique :","o":["Les ALAT, au-delà de 3N","La lipase, au-delà de 3N","La CRP, seule, élevée","Le CA 19-9, élevé"],"r":1,"e":"Lipase ↑ (>3N) = diagnostic biologique. Amylase aussi mais moins spécifique.","s":15},{"q":"Pancréatite chronique :","o":["Une atteinte réversible, sans séquelle, en quelques jours","Une fibrose progressive, avec double insuffisance","Un cancer obligatoire, à 5 ans","Une forme sans complication"],"r":1,"e":"Cause principale : alcool. Conséquences : stéatorrhée + diabète. L'insuffisance est exocrine et endocrine.","s":15},{"q":"Cancer du pancréas :","o":["Un pronostic excellent, après chirurgie","Un pronostic sombre, souvent diagnostiqué tard","Une tumeur très rare, de l'enfant","Une tumeur toujours bénigne, découverte au scanner"],"r":1,"e":"Adénocarcinome de la tête le plus souvent. Ictère obstructif révélateur.","s":15},{"q":"Insulinome :","o":["Une tumeur des cellules alpha, avec hyperglycémie","Une tumeur des cellules bêta, avec hypoglycémies","Un cancer primitif du foie","Un diabète sucré de type 1"],"r":1,"e":"Tumeur des cellules β → hypersécrétion d'insuline → hypoglycémies sévères.","s":15},{"q":"Tête du pancréas est entourée par :","o":["L'estomac, par sa grande courbure","Le cadre duodénal, en forme de C","Le foie, par le lobe carré","La rate, par son hile"],"r":1,"e":"Tête dans la concavité du C duodénal.","s":15},{"q":"Queue du pancréas atteint :","o":["Le foie, au hile","Le hile de la rate","Le côlon transverse","Le diaphragme, sous la coupole gauche"],"r":1,"e":"Queue dans le ligament spléno-rénal, atteint le hile de la rate.","s":15},{"q":"Vascularisation pancréatique :","o":["L'aorte, directement, par des rameaux","Le tronc cœliaque et l'artère mésentérique supérieure","L'artère mésentérique inférieure et les artères coliques gauches","L'artère iliaque interne, au bassin"],"r":1,"e":"Riche : arcades pancréatico-duodénales (TC + AMS) + branches spléniques. Ce sont les branches splénique et gastro-duodénale.","s":15},{"q":"La part exocrine du pancréas représente :","o":["50 % du parenchyme","98 % du parenchyme","2 %","80 %"],"r":1,"e":"Les 2 % restants correspondent à la part endocrine, les îlots de Langerhans.","s":15},{"q":"Le pancréas pèse environ :","o":["30 g","70 à 80 g","150 g","300 g"],"r":1,"e":"Il mesure 15 à 20 cm, de couleur jaune-rosé et de consistance ferme.","s":15},{"q":"La queue du pancréas se distingue du reste de l'organe par le fait :","o":["Qu'elle est intra-péritonéale, dans le ligament spléno-rénal","Qu'elle est rétro-péritonéale, accolée","Qu'elle est extra-abdominale","Qu'elle est dépourvue de toute vascularisation, sauf la splénique"],"r":0,"e":"Le reste du pancréas est rétro-péritonéal secondaire.","s":15},{"q":"Le pancréas se projette en regard des vertèbres :","o":["T12","L1-L2","L3-L4","T10-T11"],"r":1,"e":"Il s'étend du cadre duodénal à droite au hile splénique à gauche, oblique en haut, à gauche et en arrière.","s":15},{"q":"Le processus uncinatus se prolonge :","o":["Derrière les vaisseaux mésentériques supérieurs","Devant l'aorte, au niveau de L1","Dans le hile splénique, à gauche","Derrière le cholédoque, jusqu'au foie et à la vésicule biliaire"],"r":0,"e":"Il appartient à la tête du pancréas et limite avec D3.","s":15},{"q":"Le col, ou isthme du pancréas, repose :","o":["En avant des vaisseaux mésentériques supérieurs","En arrière de l'aorte, contre L1","Dans le hile splénique, contre la queue et les vaisseaux courts","Derrière le duodénum, en D2"],"r":0,"e":"En arrière de lui se forme le confluent porte, par réunion de la VMS et du tronc spléno-mésaraïque.","s":15},{"q":"La tête du pancréas répond en arrière à :","o":["La veine cave inférieure et la veine rénale droite","L'aorte et le tronc cœliaque","Le rein gauche, la surrénale gauche et la veine rénale gauche","La rate et son hile, à gauche"],"r":0,"e":"Elle est traversée par le canal cholédoque et logée dans la concavité du duodénum.","s":15},{"q":"Le corps du pancréas répond en arrière à :","o":["L'aorte, le tronc cœliaque, le rein et la surrénale gauches","La veine cave inférieure, à droite","Le duodénum, en D2, à droite","La vésicule biliaire, à droite, sous le foie, contre le lobe carré"],"r":0,"e":"En avant il répond à l'estomac, séparé par la bourse omentale ; son bord supérieur est longé par l'artère splénique. Le plexus solaire et la veine rénale gauche en font aussi partie.","s":15},{"q":"Le syndrome de la pince aorto-mésentérique correspond :","o":["À une compression de D3, en cas d'amaigrissement majeur","À une compression du cholédoque par la tête, en cas de cancer","À une compression de la veine porte, en L1","À une thrombose de la veine splénique"],"r":0,"e":"Il se manifeste par des vomissements. D3 est pris entre l'aorte et les vaisseaux mésentériques supérieurs.","s":15},{"q":"Le canal de Santorini :","o":["S'ouvre à la papille mineure, au-dessus de la majeure","S'ouvre dans l'ampoule de Vater, avec le cholédoque, en D2","Traverse toute la longueur du pancréas","Est toujours présent et fonctionnel"],"r":0,"e":"Il draine la partie supérieure de la tête et peut être absent ou non fonctionnel. La papille mineure est 3 à 4 cm plus haut.","s":15},{"q":"Le canal de Wirsung :","o":["Traverse tout le pancréas, de la queue à la tête","Ne draine que la queue du pancréas","Ne draine que la tête, avec le canal accessoire","S'ouvre dans l'estomac, au pylore"],"r":0,"e":"Il rejoint le cholédoque au niveau de la tête et s'ouvre à l'ampoule de Vater, en D2, sous contrôle du sphincter d'Oddi.","s":15},{"q":"Parmi les branches pancréatiques de l'artère splénique, le cours cite :","o":["La dorsale, la grande pancréatique et celle de la queue","Les pancréatico-duodénales supérieures","Les pancréatico-duodénales inférieures, issues de la splénique","L'artère gastro-duodénale, seule"],"r":0,"e":"Les pancréatico-duodénales supérieures viennent de la gastro-duodénale et les inférieures de l'AMS. La dorsale est l'artère pancréatique dorsale.","s":15},{"q":"Les veines pancréatiques de la queue se drainent :","o":["Dans la veine splénique","Dans la veine mésentérique supérieure","Directement dans la veine cave","Dans la veine rénale gauche"],"r":0,"e":"Les veines pancréatico-duodénales rejoignent, elles, la VMS ou la veine porte : tout le drainage est porte.","s":15},{"q":"Le drainage lymphatique du pancréas aboutit :","o":["Aux ganglions cœliaques et mésentériques supérieurs","Aux ganglions iliaques, puis aux lombaires et à la citerne","Aux ganglions inguinaux, profonds","Aux ganglions médiastinaux"],"r":0,"e":"Il passe d'abord par les ganglions pancréatiques et péri-pancréatiques.","s":15},{"q":"L'innervation sympathique du pancréas provient des niveaux :","o":["T1-T4","T5-T11","L1-L3","S2-S4"],"r":1,"e":"Elle inhibe la sécrétion, provoque une vasoconstriction et transmet la douleur.","s":15},{"q":"La douleur pancréatique est décrite comme :","o":["Intense, en barre, irradiant dans le dos","Sourde et péri-ombilicale, calmée par les repas copieux","Localisée à l'hypochondre droit","Pelvienne, basse et diffuse"],"r":0,"e":"Elle est transmise par les fibres sympathiques. Elle est transfixiante.","s":15},{"q":"Le nerf vague, au niveau du pancréas :","o":["Stimule les sécrétions exocrine et endocrine","Les inhibe toutes les deux","N'a aucune action sur l'organe","Provoque une vasoconstriction des artères pancréatiques"],"r":0,"e":"Le pancréas est innervé par les plexus cœliaque et mésentérique supérieur.","s":15},{"q":"Le pancréas exocrine est organisé en :","o":["Acini séreux","Îlots","Follicules","Tubules"],"r":0,"e":"Les cellules acineuses, ou zymogènes, y produisent les enzymes digestives.","s":15},{"q":"L'artère splénique, qui vascularise le pancréas, suit :","o":["Le bord supérieur du pancréas","Le bord inférieur du pancréas","La face antérieure du pancréas, sous l'estomac","La face postérieure, contre l'aorte"],"r":0,"e":"Son trajet sinueux est caractéristique ; elle donne aussi la gastro-épiploïque gauche et les vasa brevia. Son trajet est sinueux.","s":15},{"q":"Les artères pancréatico-duodénales forment :","o":["Des arcades autour du cadre duodénal","Un réseau terminal, sans anastomose","Une arcade unique, en avant du pancréas","Un plexus veineux, autour de la tête du pancréas et du cholédoque"],"r":0,"e":"C'est cette double origine, cœliaque et mésentérique supérieure, qui assure la sécurité vasculaire du bloc duodéno-pancréatique. Elles sont supérieures et inférieures.","s":15},{"q":"Combien de branches viscérales antérieures impaires de l'aorte abdominale ?","o":["Deux, le tronc cœliaque et l'AMS","Trois, le tronc cœliaque, l'AMS et l'AMI","Quatre, avec les rénales","Cinq, avec les rénales et les gonadiques, paires"],"r":1,"e":"3 branches digestives antérieures impaires : tronc cœliaque (T12), AMS (L1), AMI (L3).","s":16},{"q":"Tronc cœliaque vascularise :","o":["Le côlon descendant, à gauche","L'estomac, le foie, la rate et le pancréas","L'iléon et le côlon droit, par des branches jéjunales","Le rectum et le sigmoïde"],"r":1,"e":"Œsophage abdominal, estomac, foie, rate, pancréas, D1. La première moitié du duodénum en dépend aussi.","s":16},{"q":"AMS vascularise :","o":["L'estomac et le pylore, par la gastrique droite","De D2 aux deux tiers du côlon transverse","Le rectum, par la rectale moyenne","Le foie et le D1, par l'hépatique propre"],"r":1,"e":"D2-D3-D4, jéjunum, iléon, cæcum, appendice, côlon droit, 2/3 du transverse.","s":16},{"q":"AMI vascularise :","o":["L'estomac et le cardia, par la gastrique gauche","Du tiers gauche du transverse au haut du rectum","Le foie et la vésicule","Tout l'iléon, jusqu'au cæcum"],"r":1,"e":"Tiers gauche du transverse, côlon descendant, sigmoïde, rectum supérieur.","s":16},{"q":"3 branches du tronc cœliaque :","o":["Gastrique droite, hépatique, mésentérique","Gastrique gauche, splénique, hépatique commune","Pancréatique, splénique, gastro-duodénale","Œsophagienne, gastrique, hépatique"],"r":1,"e":"Trépied de Haller.","s":16},{"q":"Artère hépatique commune se divise en :","o":["La splénique et la cystique","La gastro-duodénale et l'hépatique propre","Les gastriques gauche et droite, en haut","La pancréatique et la cystique"],"r":1,"e":"Hépatique commune → gastro-duodénale (descendante) + hépatique propre (ascendante).","s":16},{"q":"Anastomose entre AMS et AMI :","o":["Inexistante, les territoires étant terminaux","L'arcade de Riolan et l'arcade de Drummond","Le cercle de Willis, comme au cerveau, à la base","L'arcade de Calot, au foie"],"r":1,"e":"Anastomoses entre les territoires AMS et AMI. Voie de suppléance.","s":16},{"q":"Veine porte se forme :","o":["À gauche du pancréas, près de la rate","Derrière le col du pancréas, par deux veines","Au-dessus du foie, sous le diaphragme","Dans l'aorte abdominale, par une fistule congénitale"],"r":1,"e":"VMS + tronc spléno-mésaraïque, en arrière du col pancréatique. Ce sont la VMS et le tronc spléno-mésaraïque.","s":16},{"q":"Longueur de la veine porte :","o":["2 cm","~8 cm","20 cm","40 cm"],"r":1,"e":"~8 cm. Pression basse (~10 mmHg). Pas de valvules.","s":16},{"q":"Anastomoses porto-caves : œsophagienne donne :","o":["Des hémorroïdes internes","Des varices œsophagiennes","Une tête de méduse, autour de l'ombilic","Une ascite, dans le péritoine"],"r":1,"e":"VO = anastomose œsophagienne avec veine gastrique gauche.","s":16},{"q":"Anastomose ombilicale en HTP :","o":["Varices œsophagiennes","Tête de méduse","Hémorroïdes","Varicocèle"],"r":1,"e":"Veines para-ombilicales se dilatent → tête de méduse péri-ombilicale.","s":16},{"q":"Anastomose recto-anale :","o":["Varices œsophagiennes","Tête de méduse","Hémorroïdes","Cirrhose"],"r":2,"e":"Veine rectale sup (porte) avec rectales moyennes/inf (cave).","s":16},{"q":"Niveau de bifurcation aortique :","o":["L2","L3","L4","L5"],"r":2,"e":"L4. En 2 artères iliaques communes.","s":16},{"q":"Veine porte se termine :","o":["Dans la veine cave inférieure","Au hile, en deux branches, droite et gauche","Dans le cœur, à l'oreillette droite","Dans la rate, après avoir traversé le foie de part en part"],"r":1,"e":"Au hile hépatique, se divise en branche droite et gauche.","s":16},{"q":"Artère iliaque commune se divise en :","o":["La fémorale et l'obturatrice, au pli de l'aine","L'iliaque externe et l'iliaque interne","La pudendale et la glutéale","L'aorte et la veine cave"],"r":1,"e":"Externe (cuisse) + interne / hypogastrique (organes pelviens).","s":16},{"q":"Artère iliaque interne donne (entre autres) :","o":["L'artère hépatique, en haut","L'utérine, la rectale moyenne et la pudendale","L'artère pancréatique, dorsale","Le tronc cœliaque, l'artère splénique et la gastrique gauche"],"r":1,"e":"Branches viscérales pelviennes : utérine, vésicales, rectale moyenne, pudendale interne, obturatrice.","s":16},{"q":"Rectum reçoit 3 sources artérielles :","o":["La seule artère mésentérique inférieure","La rectale supérieure, les moyennes et les inférieures","Le tronc cœliaque et l'artère splénique, par des branches basses","L'artère iliaque externe, au bassin"],"r":1,"e":"3 niveaux d'apport artériel pour le rectum. Elles viennent de l'AMI, de l'iliaque interne et de la pudendale.","s":16},{"q":"Points faibles de vascularisation colique :","o":["Le cæcum et le rectum, aux extrémités","L'angle splénique et la jonction recto-sigmoïdienne","Le sigmoïde uniquement, en entier","Aucun point faible, grâce aux arcades de suppléance multiples"],"r":1,"e":"Zones à risque d'ischémie colique = points de jonction de territoires artériels. Ce sont les points de Griffith et de Sudeck.","s":16},{"q":"Ischémie mésentérique aiguë :","o":["Une affection bénigne, spontanément résolutive","Une urgence vitale, par obstruction de l'AMS","Une forme asymptomatique, sur l'AMI","Une surinfection de la paroi, sans gravité, sous antibiotiques"],"r":1,"e":"Embolie/thrombose de l'AMS → nécrose intestinale. Mortalité élevée.","s":16},{"q":"Angor mésentérique :","o":["Une douleur thoracique, à l'effort, irradiant au bras","Une douleur abdominale après les repas, par ischémie","Une douleur de l'épaule","Des crampes des mollets"],"r":1,"e":"Sténoses athéromateuses → douleur post-prandiale, peur de manger, amaigrissement. L'ischémie est chronique.","s":16},{"q":"Drainage veineux digestif terminal :","o":["La veine cave supérieure, par la veine azygos","La veine porte, puis le foie et la veine cave","L'aorte abdominale, par des shunts","Le système lymphatique, seul"],"r":1,"e":"Système porte → foie (filtration) → VCI → cœur. Les veines hépatiques rejoignent la veine cave inférieure.","s":16},{"q":"Citerne du chyle (Pecquet) :","o":["Au cou, à gauche, en C7","En L2, par fusion des troncs lymphatiques","Dans le thorax, en T8","Dans le pelvis, en S2, devant le sacrum, en bas"],"r":1,"e":"Origine du canal thoracique à L2. Ce sont les troncs lombaires et intestinal.","s":16},{"q":"Chyle =","o":["La bile, concentrée dans la vésicule entre les repas","De la lymphe riche en lipides absorbés","Le suc gastrique, acide","Le sang artériel du grêle"],"r":1,"e":"Aspect lactescent. Chylifères des villosités intestinales. Ces lipides sont des chylomicrons.","s":16},{"q":"Drainage lymphatique digestif termine dans :","o":["La veine porte, puis le foie","Le canal thoracique, puis l'angle veineux gauche","La veine cave supérieure, directement","La veine cave inférieure, par les veines lombaires ascendantes"],"r":1,"e":"Lombo-aortiques → citerne du chyle → canal thoracique → angle veineux gauche.","s":16},{"q":"Hémorragies hautes = au-dessus de :","o":["Angle hépatique","Angle de Treitz","Pylore","Valve iléo-cæcale"],"r":1,"e":"Treitz = limite haute/basse. HD haute = hématémèse, méléna.","s":16},{"q":"Vascularisation de l'estomac est faite par :","o":["Deux artères seulement, gauche et droite","Quatre artères et les vasa brevia, cœliaques","L'artère mésentérique supérieure","L'artère mésentérique inférieure"],"r":1,"e":"2 cercles : petite courbure (gastrique gauche/droite) + grande courbure (gastro-épiploïques) + vasa brevia. Elles forment deux cercles, sur les deux courbures.","s":16},{"q":"Veine splénique se draine dans :","o":["La veine cave inférieure, par la veine rénale","Le tronc spléno-mésaraïque, puis la veine porte","L'aorte abdominale, par un shunt","La veine cave supérieure, par l'azygos"],"r":1,"e":"Splénique + VMI = tronc spléno-mésaraïque. + VMS = veine porte.","s":16},{"q":"Hile splénique reçoit/donne :","o":["L'artère et la veine hépatiques","L'artère et la veine spléniques, et la queue du pancréas","L'aorte directement, par un tronc court qui traverse le diaphragme","La veine mésentérique inférieure"],"r":1,"e":"Hile splénique : artère et veine + lymphatiques + nerfs + queue du pancréas.","s":16},{"q":"La couleur du sang dans la veine porte :","o":["Très oxygéné, comme l'aorte","Peu oxygéné mais riche en nutriments","Totalement sans oxygène","Identique au sang de l'aorte, à jeun"],"r":1,"e":"Sang post-digestif : peu oxygéné mais chargé en nutriments absorbés.","s":16},{"q":"TIPS = :","o":["Un examen biologique du foie","Un shunt dans le foie, de la porte aux sus-hépatiques","Un médicament de l'hypertension portale, à prendre à vie","Un test fonctionnel hépatique"],"r":1,"e":"Trans-jugular Intrahepatic Portosystemic Shunt → décompression du système porte. Il décomprime le système porte.","s":16},{"q":"Les trois artères digestives de l'aorte abdominale se caractérisent par le fait :","o":["D'être les seules branches antérieures et impaires","D'être paires et symétriques","De naître au même niveau, en L1","D'être latérales, comme les artères rénales et les gonadiques"],"r":0,"e":"Elles naissent à des niveaux différents : T12, L1 et L3.","s":16},{"q":"Le tronc cœliaque naît :","o":["Juste sous le hiatus aortique, en T12","En L1, sous l'artère mésentérique","En L3, au-dessus de la bifurcation","En T10, au-dessus du diaphragme"],"r":0,"e":"C'est un court tronc de 1 à 2 cm, première branche viscérale antérieure de l'aorte abdominale.","s":16},{"q":"Le trépied de Haller désigne :","o":["Les trois branches du tronc cœliaque","Les trois artères digestives de l'aorte","Les trois artères rectales","Les arcades pancréatico-duodénales"],"r":0,"e":"Il réunit les artères gastrique gauche, splénique et hépatique commune.","s":16},{"q":"L'artère gastrique gauche est :","o":["La plus petite des trois branches du tronc cœliaque","La plus volumineuse des trois branches, à trajet sinueux","Absente chez certains sujets","Issue de l'artère mésentérique supérieure"],"r":0,"e":"Elle monte vers le cardia, suit la petite courbure, s'anastomose avec la gastrique droite et donne des branches œsophagiennes.","s":16},{"q":"L'artère splénique est :","o":["La plus grosse branche du tronc cœliaque, au trajet sinueux","La plus petite des trois branches, qui monte vers le cardia","Rectiligne, le long du pancréas","Issue de l'aorte directement"],"r":0,"e":"Elle donne des branches pancréatiques, la gastro-épiploïque gauche et les vasa brevia avant de se terminer au hile splénique.","s":16},{"q":"L'artère gastro-duodénale donne :","o":["La pancréatico-duodénale supérieure et la gastro-épiploïque","L'artère gastrique droite, le long de la petite courbure","Les branches hépatiques droite et gauche","L'artère cystique, au triangle de Calot"],"r":0,"e":"L'artère hépatique propre donne, elle, la gastrique droite et les branches hépatiques droite et gauche.","s":16},{"q":"L'artère mésentérique supérieure naît :","o":["Environ 1 cm sous le tronc cœliaque, en L1","En T12, avec le tronc cœliaque","En L3, au-dessus de la bifurcation","Au niveau de la bifurcation aortique, en L4"],"r":0,"e":"Elle passe derrière le col du pancréas, puis devant le processus uncinatus et D3, avant de s'engager dans la racine du mésentère.","s":16},{"q":"Les branches jéjunales et iléales de l'AMS naissent :","o":["Du côté gauche de l'artère","Du côté droit","De sa terminaison","De sa face postérieure"],"r":0,"e":"Elles sont environ 15 ; les branches coliques naissent, elles, du côté droit.","s":16},{"q":"L'artère appendiculaire est une branche :","o":["De l'artère iléo-colique","De l'artère colique droite","De l'artère colique moyenne","De l'artère colique gauche"],"r":0,"e":"L'iléo-colique vascularise cæcum, appendice, iléon terminal et début du côlon ascendant.","s":16},{"q":"L'artère colique moyenne vascularise :","o":["Les deux tiers droits du côlon transverse","Le tiers gauche du transverse","Le côlon descendant, à gauche","Le sigmoïde et le haut rectum, par ses branches basses"],"r":0,"e":"L'artère colique droite vascularise le côlon ascendant et l'angle hépatique.","s":16},{"q":"L'artère mésentérique inférieure naît :","o":["En L3, environ 3 cm au-dessus de la bifurcation","En L1, environ 1 cm sous le tronc cœliaque, avec l'AMS","En T12, sous le diaphragme","Au niveau de la bifurcation, en L4"],"r":0,"e":"Elle descend obliquement à gauche et est plus petite que l'AMS.","s":16},{"q":"L'artère colique gauche vascularise :","o":["Le tiers gauche du transverse et le côlon descendant","Le côlon ascendant et l'angle hépatique, à droite du cadre","Le sigmoïde, par ses deux branches","Le rectum, en entier, jusqu'à l'anus"],"r":0,"e":"Les artères sigmoïdiennes, au nombre de 2 à 3, vascularisent le sigmoïde et la rectale supérieure termine l'AMI. Elle irrigue aussi l'angle splénique.","s":16},{"q":"Les artères rectales inférieures proviennent :","o":["De l'artère pudendale interne","De l'AMI","De l'iliaque interne directement","De l'AMS"],"r":0,"e":"Les rectales moyennes viennent de l'iliaque interne et la rectale supérieure de l'AMI.","s":16},{"q":"L'arcade de Riolan anastomose directement :","o":["La colique moyenne et la colique gauche, à l'angle splénique","Les deux artères rectales, entre elles","Le tronc cœliaque et l'AMS, autour de la tête du pancréas, en D2","Les artères jéjunales entre elles"],"r":0,"e":"L'arcade marginale de Drummond court, elle, le long du bord mésentérique du côlon et anastomose les coliques entre elles.","s":16},{"q":"L'anastomose entre le tronc cœliaque et l'AMS se fait par :","o":["Les arcades pancréatico-duodénales","L'arcade de Riolan","L'arcade de Drummond","L'anastomose rectale, entre AMI et iliaque"],"r":0,"e":"Elle réunit les pancréatico-duodénales supérieures, issues du tronc cœliaque, et les inférieures, issues de l'AMS.","s":16},{"q":"Le point de Griffith correspond :","o":["À l'angle splénique","À la jonction recto-sigmoïdienne","Au cæcum","À l'angle hépatique"],"r":0,"e":"Le point de Sudeck correspond à la jonction recto-sigmoïdienne ; tous deux sont des zones de vascularisation moins riche.","s":16},{"q":"L'anastomose entre l'AMI et l'iliaque interne se fait au niveau :","o":["Du rectum, entre la rectale supérieure et les autres","De l'angle splénique, à gauche","Du cæcum, par l'iléo-colique","Du duodénum, par les arcades pancréatico-duodénales inférieures"],"r":0,"e":"Le rectum reçoit ainsi trois sources artérielles, ce qui explique sa bonne vascularisation. Les autres sont les rectales moyennes et inférieures.","s":16},{"q":"Les différences vasculaires entre jéjunum et iléon sont :","o":["Au jéjunum des arcades simples et de longs vasa recta","L'inverse, le jéjunum ayant des arcades multiples","Aucune différence entre les deux segments du grêle mobile","L'absence de vasa recta à l'iléon"],"r":0,"e":"Les arcades comportent de 1 à 5 ordres avant de donner les vasa recta qui pénètrent la paroi. L'iléon a des arcades multiples et des vasa recta courts.","s":16},{"q":"L'artère hépatique droite donne :","o":["L'artère cystique","L'artère gastrique droite","L'artère gastro-duodénale","L'artère pancréatico-duodénale"],"r":0,"e":"Elle naît de l'artère hépatique propre, branche ascendante de l'hépatique commune.","s":16},{"q":"Le territoire du tronc cœliaque comprend :","o":["L'estomac, le foie, la rate et le pancréas","Le jéjunum et l'iléon, en entier","Le côlon descendant, le sigmoïde et le haut du rectum","Le rectum, à lui seul, en bas"],"r":0,"e":"L'AMS prend le relais de la seconde moitié du duodénum aux deux tiers droits du côlon transverse. L'œsophage abdominal et la première moitié du duodénum en font partie.","s":16},{"q":"Fonctions du système respiratoire (sauf une) :","o":["Filtrer l'air inspiré","Assurer les échanges gazeux, à l'alvéole","Digérer les protéines","Permettre la phonation"],"r":2,"e":"Fonctions : filtrer, humidifier, conduire, échanges, pH, olfaction, phonation.","s":17},{"q":"Voies aériennes supérieures :","o":["Trachée, bronches, poumons","Nez, pharynx, larynx","Diaphragme, intercostaux","Alvéoles"],"r":1,"e":"VAS = nez + pharynx + larynx (extrathoraciques).","s":17},{"q":"Le nez interne est divisé par :","o":["Choanes","Septum nasal","Os hyoïde","Palais dur"],"r":1,"e":"Septum nasal : antérieur cartilagineux + postérieur osseux.","s":17},{"q":"Choanes communiquent avec :","o":["Oropharynx","Nasopharynx","Larynx","Bouche"],"r":1,"e":"Orifices postérieurs des fosses nasales → nasopharynx.","s":17},{"q":"Cornets nasaux :","o":["Deux paires, moyenne et inférieure","Trois, supérieur, moyen et inférieur","Quatre, avec un cornet suprême constant et volumineux","Aucun, la cavité étant lisse"],"r":1,"e":"Supérieur, moyen, inférieur. Augmentent la surface de contact muqueuse.","s":17},{"q":"Sinus paranasaux :","o":["Deux paires, frontales et maxillaires","Quatre paires, dont les maxillaires et les frontaux","Six paires, avec les sinus temporaux et pariétaux de chaque côté","Aucun sinus, ils sont inexistants"],"r":1,"e":"4 paires de sinus. Drainent dans la cavité nasale via les méats. Les sphénoïdaux et les ethmoïdaux complètent la liste.","s":17},{"q":"Sinus le plus volumineux :","o":["Maxillaire","Frontal","Sphénoïdal","Ethmoïdal"],"r":0,"e":"Sinus maxillaire = le plus grand.","s":17},{"q":"Cavité nasale assure (sauf un) :","o":["Filtration de l'air","Humidification, réchauffement","Digestion","Olfaction"],"r":2,"e":"Pas de rôle digestif.","s":17},{"q":"Pharynx — 3 régions :","o":["Antérieur, moyen et postérieur, de face","Nasopharynx, oropharynx et laryngopharynx","Supérieur, médian et inférieur","Cervical, thoracique et abdominal"],"r":1,"e":"3 étages successifs du pharynx.","s":17},{"q":"Le pharynx est :","o":["Purement respiratoire","Carrefour aéro-digestif","Purement digestif","Purement neurologique"],"r":1,"e":"Carrefour des voies respiratoire et digestive.","s":17},{"q":"Le larynx s'étend entre :","o":["C1-C2","C3-C6","T1-T4","T5-T8"],"r":1,"e":"C3 à C6, dans le prolongement du pharynx.","s":17},{"q":"Nombre de cartilages du larynx :","o":["Cinq cartilages","Sept cartilages","Neuf cartilages","Douze cartilages, dont six paires"],"r":2,"e":"3 impairs (thyroïde, cricoïde, épiglotte) + 3 paires (aryténoïdes, corniculés, cunéiformes). Ce sont trois impairs et trois paires.","s":17},{"q":"Le plus grand cartilage du larynx :","o":["Le cricoïde, en bague","Le thyroïde, ou pomme d'Adam","L'épiglotte, en rabat","L'aryténoïde, en pyramide"],"r":1,"e":"Pomme d'Adam plus visible chez l'homme.","s":17},{"q":"Épiglotte est :","o":["Un os du larynx, rattaché à l'os hyoïde par un ligament","Un cartilage élastique, en rabat protecteur","Un cartilage hyalin, rigide","Une muqueuse, sans squelette"],"r":1,"e":"Cartilage élastique. Se rabat pour fermer la glotte à la déglutition.","s":17},{"q":"Cricoïde est :","o":["Le sommet du larynx, en haut","La base du larynx, en forme de bague","Un cartilage latéral, pair","Un cartilage postérieur, au contact de l'œsophage"],"r":1,"e":"Base du larynx, supportant les autres cartilages.","s":17},{"q":"Vraies cordes vocales :","o":["Les plis vestibulaires, au-dessus du ventricule","Les plis vocaux, ou ligaments inférieurs","Du tissu adipeux, sous la muqueuse","Des os, rattachés au thyroïde"],"r":1,"e":"Plis vocaux = vraies CV (ligaments inférieurs). Vestibulaires = fausses CV.","s":17},{"q":"Innervation motrice principale du larynx :","o":["Le nerf trijumeau, ou V","Le nerf vague, par sa branche récurrente","L'hypoglosse, ou XII, par ses branches descendantes","Le nerf phrénique, de C3 à C5"],"r":1,"e":"Tous les muscles intrinsèques sont innervés par le X (récurrent).","s":17},{"q":"Principal abducteur des cordes vocales :","o":["Crico-thyroïdien","Crico-aryténoïdien postérieur","Crico-aryténoïdien latéral","Vocalis"],"r":1,"e":"CAP = ouvre la rima glottidis. Adducteurs : CAL + transverse + thyro-aryténoïdien.","s":17},{"q":"Fonctions du larynx (sauf une) :","o":["Conduit l'air","Phonation","Protège des fausses routes","Digestion"],"r":3,"e":"Pas de rôle digestif. Conduit l'air + phonation + protection + toux.","s":17},{"q":"Manœuvre de Valsalva :","o":["Une inspiration forcée, bouche ouverte","Une expiration forcée à glotte fermée","Une hyperventilation, pendant une minute, en position assise","Une toux volontaire, répétée"],"r":1,"e":"Augmente la pression intrathoracique. Utile pour palier les rythmes ou tester un BAV.","s":17},{"q":"Épithélium des voies respiratoires :","o":["Pavimenteux stratifié, kératinisé","Pseudo-stratifié cilié, avec des cellules caliciformes","Cubique simple, comme dans les canaux des glandes salivaires","Pavimenteux simple, comme l'alvéole"],"r":1,"e":"Cilié + mucus → ascenseur mucociliaire vers le pharynx.","s":17},{"q":"pH du sang varie en cas d'hypoventilation :","o":["Un pH qui monte, par alcalose respiratoire","Un pH qui baisse, par acidose respiratoire","Un pH inchangé, compensé","Une hausse des bicarbonates, seule"],"r":1,"e":"Hypoventilation → CO2 ↑ → pH ↓ = acidose respiratoire.","s":17},{"q":"La langue intervient dans (sauf un) :","o":["Goût","Phonation","Digestion mécanique","Olfaction"],"r":3,"e":"Olfaction = nez. Langue : goût + déglutition + phonation.","s":17},{"q":"Réflexe nauséeux :","o":["Une protection de l'oreille","Une protection contre l'aspiration vers les poumons","Une protection de l'œil, par le clignement réflexe","Un spasme de l'intestin"],"r":1,"e":"Stimulation de la base de la langue → vomissement → protège les poumons. Il part de la face postérieure de la langue.","s":17},{"q":"Position de la tête influence :","o":["La vue, en orientant les yeux vers l'horizon","L'ouverture des voies aériennes","Le rythme cardiaque","La digestion, par la déglutition"],"r":1,"e":"Flexion ferme, extension ouvre les voies (manœuvre de réanimation).","s":17},{"q":"Acidose respiratoire :","o":["Un pH haut et un CO₂ bas, en hyperventilation","Un pH bas, un CO₂ haut et des bicarbonates normaux","Un pH haut et des bicarbonates hauts","Un pH bas et des bicarbonates bas, par diarrhée chronique"],"r":1,"e":"Hypoventilation → rétention CO2 → acidose.","s":17},{"q":"Alcalose respiratoire :","o":["Un pH bas, par rétention de CO₂ et hypoventilation","Un pH haut et un CO₂ bas, par hyperventilation","Un pH normal, sans variation","Un CO₂ élevé, isolé, au repos"],"r":1,"e":"Hyperventilation → CO2 ↓ → alcalose respiratoire.","s":17},{"q":"Os hyoïde supporte :","o":["Le crâne, par des ligaments stylo-hyoïdiens épais","La langue et le larynx, par des membranes","Les vertèbres cervicales","La mandibule, directement"],"r":1,"e":"Os impair flottant, ancre langue et larynx.","s":17},{"q":"Aspiration nasopharyngée — risque :","o":["Aucun, le geste étant sans danger, même répété souvent","Un traumatisme de la muqueuse et un saignement","Une hausse de l'oxygénation","Une fièvre, par infection"],"r":1,"e":"Muqueuse fragile + cornets étroits = risque saignement, surtout si thrombopénie. Le risque est majoré en cas de thrombopénie.","s":17},{"q":"Sinusite chronique peut conduire à :","o":["Une insuffisance cardiaque","Une source d'aspiration vers les voies inférieures","Un diabète, par atteinte du pancréas et du foie, à long terme","Une hypertension, par la douleur"],"r":1,"e":"Matière contaminée peut descendre dans les voies inférieures.","s":17},{"q":"La première barrière du système de défense respiratoire est assurée par :","o":["Les vibrisses et l'épithélium cilié des voies aériennes","Le surfactant, dans l'alvéole","Les macrophages alvéolaires, qui phagocytent les particules","Le réflexe de toux, au larynx"],"r":0,"e":"Le système respiratoire filtre l'air, le conditionne, participe à la défense, à la régulation du pH et à la phonation. L'épithélium est pseudo-stratifié, dans la trachée et les bronches.","s":17},{"q":"La régulation du pH par le système respiratoire s'opère :","o":["En modifiant la concentration sanguine de CO₂","En modifiant les bicarbonates","Par une excrétion rénale d'ions H⁺, en quelques heures","Par le foie, en métabolisant les acides"],"r":0,"e":"Elle fonde la distinction entre acidose et alcalose respiratoires.","s":17},{"q":"L'alcalose respiratoire se caractérise par :","o":["Un pH abaissé et une pCO₂ élevée","Un pH élevé et une pCO₂ abaissée","Un pH abaissé et des bicarbonates abaissés","Un pH élevé et des bicarbonates élevés"],"r":1,"e":"L'acidose respiratoire associe au contraire pH abaissé et pCO₂ élevée.","s":17},{"q":"La phonation met en jeu :","o":["Les cordes vocales et la résonance des sinus","Le seul larynx, sans résonance","La seule cavité buccale, avec la langue","Le diaphragme seul, par la pression"],"r":0,"e":"L'olfaction fait, elle, intervenir l'épithélium olfactif et le nerf I. Ce sont les sinus paranasaux.","s":17},{"q":"La division fonctionnelle du système respiratoire distingue :","o":["Une partie conductrice et une portion respiratoire","Des voies supérieures et inférieures","Un poumon droit et un poumon gauche","Une partie extrathoracique et intrathoracique"],"r":0,"e":"La portion respiratoire comprend bronchioles respiratoires, canaux alvéolaires, sacs alvéolaires et alvéoles.","s":17},{"q":"La charpente osseuse du nez externe comprend :","o":["Les os propres du nez et des expansions maxillaires","Les seuls os propres du nez, sans les maxillaires","Le vomer et la lame perpendiculaire de l'ethmoïde","Les cartilages alaires et latéraux"],"r":0,"e":"La charpente cartilagineuse comprend les cartilages latéraux, septal et alaires. Le frontal y contribue aussi.","s":17},{"q":"Le septum nasal est constitué :","o":["D'une partie antérieure cartilagineuse et postérieure osseuse","Entièrement de cartilage, du nez aux choanes","Entièrement d'os, par le vomer, l'ethmoïde et le palatin réunis","De l'os frontal et des os propres"],"r":0,"e":"Il divise la cavité nasale en deux fosses nasales. La partie osseuse comprend la lame perpendiculaire de l'ethmoïde et le vomer.","s":17},{"q":"Le vestibule nasal correspond :","o":["À la partie antérieure de la cavité nasale","Aux choanes, à l'arrière de la cavité nasale","Au méat inférieur, sous le cornet","Au nasopharynx, au-dessus du voile"],"r":0,"e":"La cavité nasale s'étend des narines aux choanes, qui communiquent avec le nasopharynx.","s":17},{"q":"Sous chaque cornet nasal se trouve :","o":["Un méat irrigué, recevant le drainage des sinus","Une amygdale, comme au pharynx","Un sinus paranasal, en communication directe avec l'orbite","L'épithélium olfactif, sensoriel"],"r":0,"e":"Les cornets sont au nombre de trois : supérieur, moyen et inférieur.","s":17},{"q":"Les sinus paranasaux sont au nombre de :","o":["2 paires","4 paires","6 paires","1 paire"],"r":1,"e":"Sinus frontaux, sphénoïdaux, cellules ethmoïdales et sinus maxillaires, ces derniers étant les plus volumineux.","s":17},{"q":"L'obstruction du drainage sinusien expose à :","o":["Une sinusite chronique, source d'aspiration vers le bas","Une rhinite allergique, saisonnière, avec éternuements","Une otite moyenne aiguë, par la trompe","Une laryngite, avec dysphonie"],"r":0,"e":"C'est le lien entre pathologie des voies supérieures et risque d'infection pulmonaire. La matière contaminée peut être aspirée dans les voies inférieures.","s":17},{"q":"Le palais mou correspond :","o":["Aux deux tiers antérieurs, avec support osseux","Au tiers postérieur, sans support osseux","À la luette seule, en arrière, avec ses muscles propres","À la totalité du palais"],"r":1,"e":"La luette, protubérance musculaire du palais mou, agit comme une valve lors de la déglutition, des éternuements, de la toux et des vomissements.","s":17},{"q":"Le réflexe nauséeux est déclenché par :","o":["L'innervation riche de la face postérieure de la langue","Les amygdales palatines, entre les piliers du voile","Les cordes vocales, lors de la phonation","L'épiglotte, quand elle se rabat"],"r":0,"e":"Il protège les poumons contre l'aspiration.","s":17},{"q":"Les amygdales sont décrites comme :","o":["Des tissus lymphoïdes, surtout actifs chez l'enfant","Des glandes salivaires accessoires, nombreuses","Des cartilages du pharynx","Des replis muqueux, sans fonction"],"r":0,"e":"On distingue les amygdales pharyngées, palatines et linguales. Ils sont vascularisés.","s":17},{"q":"Le pharynx est constitué :","o":["De muscle lisse et d'une muqueuse","De cartilage hyalin, en anneaux","D'os, comme le larynx, en partie","De tissu adipeux, en couches"],"r":0,"e":"Canal commun aux systèmes digestif et respiratoire, il communique en haut avec les cavités nasale et buccale, en bas avec le larynx et l'œsophage.","s":17},{"q":"L'oropharynx se situe :","o":["Au-dessus du palais mou, en arrière des choanes","Derrière la cavité buccale, après l'isthme du gosier","En arrière du larynx, vers l'œsophage","En arrière des fosses nasales"],"r":1,"e":"Le nasopharynx est au-dessus du palais mou et en arrière des choanes.","s":17},{"q":"La cavité nasale permet notamment :","o":["Le passage de l'air, même la bouche pleine","La digestion des aliments, par la salive","La phonation, à elle seule","La déglutition du bol alimentaire"],"r":0,"e":"Elle filtre, humidifie et réchauffe l'air, contient l'épithélium olfactif et sert, avec les sinus, de cavité de résonance.","s":17},{"q":"Les voies aériennes supérieures sont dites :","o":["Extrathoraciques","Intrathoraciques","Abdominales","Médiastinales"],"r":0,"e":"Les voies respiratoires inférieures — trachée, bronches, poumons — sont intrathoraciques.","s":17},{"q":"L'épithélium olfactif est innervé par :","o":["Le nerf I","Le nerf V","Le nerf VII","Le nerf X"],"r":0,"e":"Les molécules en suspension traversent les fosses nasales pour l'atteindre.","s":17},{"q":"Le réchauffement et l'humidification de l'air reposent sur :","o":["La riche vascularisation nasale et le mucus de la muqueuse","Le surfactant, sécrété par les pneumocytes de type 2","Les cartilages trachéaux, qui gardent l'air chaud","Les alvéoles, au contact du sang capillaire"],"r":0,"e":"Les muqueuses de la cavité buccale et de la langue y contribuent également.","s":17},{"q":"Trachée s'étend de :","o":["C2 à T2","C6 à T4-T5","T2 à T10","T1 à L1"],"r":1,"e":"C6 (cricoïde) à T4-T5 (carène).","s":18},{"q":"Longueur de la trachée :","o":["3 cm","10-12 cm","25 cm","50 cm"],"r":1,"e":"10-12 cm. Diamètre 2-2,5 cm.","s":18},{"q":"Anneaux cartilagineux de la trachée :","o":["5","15-20","50","100"],"r":1,"e":"15-20 anneaux en forme de fer à cheval, ouverts en arrière (contre l'œsophage).","s":18},{"q":"Carène trachéale :","o":["Au-dessus du sternum, en C7, au cou","En T4-T5, au niveau de la bifurcation","En C6, au bord du cricoïde","En T10, au niveau du diaphragme"],"r":1,"e":"Bifurcation trachéale en bronches souches. Repère endoscopique. C'est l'éperon interne de la bifurcation.","s":18},{"q":"Différences bronche souche droite/gauche :","o":["Elles sont identiques, en tous points","La droite est plus courte, plus large et plus verticale","La droite est plus longue et plus étroite","La droite est horizontale, et passe sous la crosse aortique"],"r":1,"e":"Droite plus verticale → corps étrangers tombent plus à droite.","s":18},{"q":"Bronches lobaires : combien ?","o":["Deux à droite et trois à gauche","Trois à droite et deux à gauche","Deux de chaque côté, symétriques, sans lobe moyen","Cinq de chaque côté, une par lobe"],"r":1,"e":"Poumon droit = 3 lobes. Poumon gauche = 2 lobes (incisure cardiaque). La droite a un lobe moyen ; à gauche, il n'y a que supérieur et inférieur.","s":18},{"q":"Segments broncho-pulmonaires :","o":["Deux à droite, et deux à gauche","Dix à droite, huit à dix à gauche","Cinq à droite, cinq à gauche","Vingt de chaque côté"],"r":1,"e":"10 segments à droite. À gauche, S1+S2 fusionnés (apico-postérieur).","s":18},{"q":"Lingula appartient au :","o":["Au poumon droit, au lobe moyen","Au poumon gauche, au lobe supérieur","Au foie, au lobe gauche","Au pancréas, à la queue, contre la rate et le rein"],"r":1,"e":"Lingula = portion antérieure du lobe sup gauche, équivalent du lobe moyen droit. C'est l'équivalent du lobe moyen droit.","s":18},{"q":"Hile pulmonaire contient :","o":["La bronche souche, à elle seule","La bronche, les vaisseaux, les nerfs et les lymphatiques","Les vaisseaux pulmonaires, seuls, sans la bronche ni les nerfs","La veine cave et le nerf phrénique"],"r":1,"e":"Pédicule pulmonaire complet au hile. Il y a l'artère pulmonaire et deux veines pulmonaires.","s":18},{"q":"Nombre d'alvéoles :","o":["1 million","10 millions","300-500 millions","10 milliards"],"r":2,"e":"300-500 millions. Surface 70-100 m².","s":18},{"q":"Pneumocytes type I :","o":["Ils sécrètent le surfactant, en continu","Ils couvrent 95 % de la surface, pour les échanges","Ils phagocytent les particules inhalées","Ils sont absents chez l'adulte, remplacés à 90 % par les type 2"],"r":1,"e":"Cellules aplaties, surface des échanges.","s":18},{"q":"Pneumocytes type II :","o":["Ils forment la surface d'échange","Ils produisent le surfactant","Ce sont des macrophages alvéolaires","Ce sont des cellules ciliées, comme dans les bronches"],"r":1,"e":"Surfactant → abaisse tension superficielle → empêche le collapsus alvéolaire.","s":18},{"q":"Macrophages alvéolaires :","o":["Ils produisent le surfactant","Ils phagocytent les particules et les microbes","Ils assurent les échanges gazeux, avec le sang","Ils n'ont aucune fonction"],"r":1,"e":"Défense immunitaire pulmonaire.","s":18},{"q":"Plèvre comporte :","o":["Un seul feuillet, viscéral","Deux feuillets, viscéral et pariétal","Trois feuillets superposés","Quatre feuillets, deux par côté et un médiastinal"],"r":1,"e":"Plèvre viscérale (poumon) + pariétale (cavité thoracique).","s":18},{"q":"Cavité pleurale contient :","o":["Du sang, en petite quantité","Un peu de liquide pleural, environ 10 mL","De la lymphe, en grande quantité, environ 200 mL","De l'air, sous pression"],"r":1,"e":"Espace virtuel + 10 mL de liquide. Pression négative.","s":18},{"q":"Pneumothorax :","o":["Du sang dans la plèvre, après un choc","De l'air dans la plèvre, avec collapsus du poumon","Du liquide dans la plèvre, avec un poumon intact et ventilé","Une infection de la plèvre"],"r":1,"e":"Perte de la pression négative → poumon se collabe.","s":18},{"q":"Récessus costo-diaphragmatique :","o":["Le récessus le plus haut, à l'apex","Le plus déclive, où s'accumulent les épanchements","Un récessus inexistant chez l'adulte","Un récessus médiastinal, en avant du péricarde"],"r":1,"e":"Cul-de-sac le plus bas. Épanchements pleuraux s'y accumulent.","s":18},{"q":"Vascularisation fonctionnelle :","o":["Les artères bronchiques, issues de l'aorte","Les artères pulmonaires, de sang désoxygéné","Les artères coronaires","Les artères phréniques"],"r":1,"e":"Artères pulm = échanges gazeux. Bronchiques = nourricières. Elles assurent les échanges gazeux.","s":18},{"q":"Veines pulmonaires :","o":["2 (1 par poumon)","4 (2 par poumon)","6","8"],"r":1,"e":"4 veines pulmonaires → OG (sang oxygéné).","s":18},{"q":"Artères bronchiques naissent de :","o":["Tronc pulmonaire","Aorte thoracique","Carotides","VCS"],"r":1,"e":"Branches de l'aorte thoracique. Vascularisation nourricière.","s":18},{"q":"Innervation parasympathique pulmonaire :","o":["Une bronchodilatation rapide, par le nerf vague","Une bronchoconstriction, par le nerf vague","Une vasoconstriction pulmonaire","Aucun effet sur les bronches"],"r":1,"e":"Vague (X) → bronchoconstriction + sécrétions. Sympa → bronchodilatation.","s":18},{"q":"β2-agonistes :","o":["Des vasoconstricteurs, contre l'hypotension","Des bronchodilatateurs, contre l'asthme","Des diurétiques, contre l'œdème","Des antalgiques, contre la douleur"],"r":1,"e":"Salbutamol = β2-mimétique → bronchodilatation rapide (asthme).","s":18},{"q":"Bronchioles ne contiennent pas :","o":["Muscle lisse","Cartilage","Cellules ciliées","Mucus"],"r":1,"e":"Pas de cartilage dans les bronchioles → contrôle du diamètre par le muscle lisse uniquement.","s":18},{"q":"Acinus pulmonaire =","o":["Un lobe entier, avec sa bronche lobaire propre","L'unité fonctionnelle des échanges gazeux","Un segment broncho-pulmonaire","Une bronche segmentaire"],"r":1,"e":"Bronchiole respiratoire → canaux alvéolaires → sacs alvéolaires → alvéoles. Il va de la bronchiole respiratoire aux alvéoles.","s":18},{"q":"Pleurésie :","o":["De l'air dans la plèvre","Un excès de liquide pleural","Du sang dans la plèvre","Un bronchospasme aigu"],"r":1,"e":"Épanchement liquidien dans la cavité pleurale.","s":18},{"q":"Drainage lymphatique pulmonaire termine vers :","o":["Les ganglions inguinaux, puis la citerne du chyle","Les ganglions du hile, puis du médiastin","Les ganglions mésentériques","Les ganglions axillaires"],"r":1,"e":"Voie ganglionnaire médiastinale classique. Les trachéo-bronchiques sont un relais, avant le canal thoracique.","s":18},{"q":"Barrière alvéolo-capillaire — épaisseur :","o":["10 μm","0,5-1 μm","100 μm","1 mm"],"r":1,"e":"Très fine pour permettre les échanges gazeux rapides.","s":18},{"q":"Surfactant :","o":["Une hormone pulmonaire, de croissance","Un phospholipide qui abaisse la tension superficielle","Un mucus bronchique, protecteur","Une enzyme digestive, qui dégrade les protéines inhalées"],"r":1,"e":"Déficit (prématurité) → maladie des membranes hyalines.","s":18},{"q":"Surface d'échange totale des poumons :","o":["5 m²","20 m²","70-100 m²","1000 m²"],"r":2,"e":"Très grande surface grâce aux 300-500M d'alvéoles.","s":18},{"q":"Le poumon droit est plus court à cause de :","o":["Du cœur, qui le refoule en dedans","Du foie, qui le repousse vers le haut","De la rate, qui soulève la coupole","De l'estomac, sous la coupole"],"r":1,"e":"Le foie en dessous fait remonter la coupole diaphragmatique droite.","s":18},{"q":"La limite entre voies respiratoires supérieures et inférieures se situe :","o":["Au cartilage cricoïde, en C6","À la carène, en T4","Au cartilage thyroïde, en C5","En T1, au manubrium"],"r":0,"e":"C'est là que débute la trachée.","s":18},{"q":"La trachée mesure :","o":["5 à 7 cm de long et 1 cm de diamètre","10 à 12 cm de long et 2 à 2,5 cm de diamètre","15 à 18 cm de long et 3 cm de diamètre, chez l'homme","20 cm de long et 4 cm de diamètre"],"r":1,"e":"Elle s'étend de C6 à la carène, en T4-T5.","s":18},{"q":"Les anneaux cartilagineux de la trachée sont au nombre de :","o":["5 à 10, fermés en anneau complet","15 à 20, en fer à cheval, ouverts en arrière","25 à 30, en spirale continue, ouverts en avant","40, en anneaux complets"],"r":1,"e":"La paroi postérieure, musculo-membraneuse, est constituée du muscle trachéal, au contact de l'œsophage. La paroi postérieure est musculo-membraneuse.","s":18},{"q":"La trachée cervicale s'étend :","o":["De C6 à T1, sous l'isthme de la thyroïde","De T1 à T4, dans le médiastin","De C4 à C6, au niveau du larynx","De T4 à T5, à la carène, sous la crosse de l'aorte"],"r":0,"e":"La trachée thoracique va de T1 à T4-T5, dans le médiastin supérieur.","s":18},{"q":"En arrière, la trachée répond à :","o":["L'œsophage","Le tronc brachio-céphalique veineux","Le thymus","La crosse aortique"],"r":0,"e":"En avant elle répond à l'isthme thyroïdien, au tronc brachio-céphalique veineux et au thymus.","s":18},{"q":"L'histologie de la trachée comprend :","o":["Un épithélium cilié, des glandes et des anneaux hyalins","Un épithélium pavimenteux stratifié","Une musculeuse à trois couches, comme l'estomac, et une séreuse","Des villosités et des cryptes"],"r":0,"e":"L'épithélium cilié et le mucus assurent l'escalator muco-ciliaire. Il y a des cellules caliciformes et une adventice.","s":18},{"q":"La bronche souche droite mesure environ :","o":["2,5 cm, avec un angle d'environ 25°","5 cm, avec un angle d'environ 45°, sous l'aorte","10 cm, avec un angle de 10°","1 cm, avec un angle de 90°"],"r":0,"e":"Plus courte, plus large et plus verticale, elle explique que les corps étrangers inhalés tombent préférentiellement à droite.","s":18},{"q":"La bronche souche gauche :","o":["Plus longue, plus étroite, plus horizontale, sous la crosse","Plus courte, plus large et plus verticale que la droite","Passe au-dessus de la crosse aortique","Est verticale, comme la trachée"],"r":0,"e":"Elle mesure environ 5 cm avec un angle d'environ 45°. La crosse est celle de l'aorte.","s":18},{"q":"Les bronches segmentaires sont au nombre de :","o":["3 à droite et 2 à gauche","10 à droite et 8 à 10 à gauche","5 de chaque côté","20 au total"],"r":1,"e":"Les bronches lobaires sont, elles, au nombre de 3 à droite et 2 à gauche.","s":18},{"q":"L'arbre bronchique compte environ :","o":["10 générations, jusqu'aux alvéoles","23 générations, jusqu'aux sacs alvéolaires","50 générations, très fines","5 générations, jusqu'aux bronchioles terminales comprises"],"r":1,"e":"Les bronchioles, dépourvues de cartilage, précèdent les bronchioles terminales puis respiratoires. La génération 0 est la trachée.","s":18},{"q":"La face médiastinale du poumon :","o":["Porte le hile pulmonaire","Est convexe","Repose sur le diaphragme","Est la plus étendue"],"r":0,"e":"La face costale est convexe contre la paroi thoracique et la face diaphragmatique concave repose sur le diaphragme.","s":18},{"q":"Le poumon droit représente environ :","o":["45 % du volume","55 % du volume","50 %","70 %"],"r":1,"e":"Il compte 3 lobes et deux scissures, mais est plus court du fait du foie ; le gauche présente l'incisure cardiaque et la lingula.","s":18},{"q":"Le hile pulmonaire contient :","o":["La bronche, les vaisseaux, les nerfs et les lymphatiques","La seule bronche souche, avec sa branche lobaire principale","Les seules veines pulmonaires","L'œsophage et la trachée, en arrière"],"r":0,"e":"C'est la zone de pénétration et de sortie du pédicule pulmonaire, sur la face médiastinale. L'artère pulmonaire, deux veines et les vaisseaux bronchiques en font partie.","s":18},{"q":"Le segment S6 du lobe inférieur droit porte le nom de :","o":["Segment apical de Nelson","Segment médio-basal","Segment latéral","Lingula"],"r":0,"e":"Le lobe inférieur droit comprend aussi les segments médio-basal, antéro-basal, latéro-basal et postéro-basal.","s":18},{"q":"Le lobe supérieur gauche comprend notamment :","o":["Les segments lingulaires supérieur et inférieur","Le segment moyen, latéral et médial, comme à droite","Le segment de Nelson, basal","Le segment médio-basal, en bas"],"r":0,"e":"Il comprend aussi l'apico-postérieur (S1+2) et l'antérieur (S3).","s":18},{"q":"L'intérêt clinique de la segmentation broncho-pulmonaire est :","o":["De cibler les résections et le drainage postural","De faciliter l'auscultation","De mesurer les volumes pulmonaires par spirométrie segmentaire","D'expliquer la vascularisation"],"r":0,"e":"Chaque segment est ventilé par une bronche segmentaire et vascularisé par une branche de l'artère pulmonaire. Le drainage postural est un geste de kinésithérapie respiratoire.","s":18},{"q":"Le segment broncho-pulmonaire se définit comme :","o":["Une unité anatomique et fonctionnelle indépendante","Un lobe, avec plusieurs bronches lobaires et segmentaires","Un lobule secondaire, polygonal","Un acinus, autour d'une bronchiole"],"r":0,"e":"Le poumon droit en compte 10 et le gauche 8 à 10.","s":18},{"q":"Le poumon adulte est décrit comme :","o":["Grisâtre chez l'adulte, alors qu'il est rosé chez l'enfant","Toujours rosé, de la naissance jusqu'à l'âge adulte avancé","Toujours grisâtre dès la naissance","Rouge foncé, gorgé de sang"],"r":0,"e":"Sa consistance est élastique et spongieuse, sa forme conique avec un apex dépassant la clavicule.","s":18},{"q":"Les bronches lobaires droites sont :","o":["Supérieure, moyenne et inférieure","Supérieure et inférieure, seules","Au nombre de quatre, avec une accessoire","Identiques aux gauches, avec une lingulaire"],"r":0,"e":"À gauche, il n'y a que les bronches lobaires supérieure et inférieure, en l'absence de lobe moyen.","s":18},{"q":"Les bronchioles se distinguent des bronches par :","o":["L'absence de cartilage","L'absence de muscle lisse","L'absence d'épithélium","La présence d'alvéoles"],"r":0,"e":"Elles précèdent les bronchioles terminales, puis les bronchioles respiratoires qui ouvrent la portion respiratoire.","s":18},{"q":"Nombre de paires de côtes :","o":["10","12","14","15"],"r":1,"e":"12 paires : 7 vraies, 3 fausses, 2 flottantes.","s":19},{"q":"Vraies côtes :","o":["Les côtes 1 à 5, reliées au sternum","Les côtes 1 à 7, articulées au sternum","Les côtes 8 à 10, par un cartilage commun","Les côtes 11 et 12, flottantes"],"r":1,"e":"Vraies côtes (1-7) ont leur propre cartilage costal vers le sternum. Chacune a son propre cartilage costal.","s":19},{"q":"Côtes flottantes :","o":["7 et 8","9 et 10","11 et 12","1 et 2"],"r":2,"e":"11-12 = flottantes (pas d'articulation antérieure).","s":19},{"q":"Sillon costal contient (VAN) :","o":["L'artère seule, sous la côte","La veine, l'artère et le nerf, de haut en bas","Le nerf, la veine et l'artère, de haut en bas","Un lymphatique, isolé"],"r":1,"e":"VAN : ponction au bord supérieur de la côte inférieure pour éviter le paquet.","s":19},{"q":"Sternum comporte :","o":["Deux parties, manubrium et corps","Trois parties, manubrium, corps et xiphoïde","Quatre parties, avec le cartilage costal de la 1ʳᵉ côte","Cinq parties, une par segment"],"r":1,"e":"Manubrium + corps + processus xiphoïde.","s":19},{"q":"Angle sternal (de Louis) correspond à :","o":["Au niveau de la 1ʳᵉ côte, en haut","Au 2ᵉ cartilage costal, et à T4-T5 en arrière","À la 5ᵉ côte, au niveau du mamelon, et à T8 en arrière","Au processus xiphoïde, en T9"],"r":1,"e":"Repère palpable majeur. Correspond à la carène en arrière. En arrière se trouve la carène.","s":19},{"q":"Articulation costo-vertébrale =","o":["Une seule articulation, entre la tête et le corps vertébral","La tête costale et la costo-transversaire","Trois articulations par côte","Aucune articulation, une fusion"],"r":1,"e":"2 articulations par côte avec les vertèbres. La tête s'articule sur deux facettes.","s":19},{"q":"Muscle inspirateur principal :","o":["Intercostaux internes","Diaphragme","Abdominaux","Triangulaire du sternum"],"r":1,"e":"Diaphragme = principal muscle inspiratoire. Innervé par nerf phrénique C3-C5.","s":19},{"q":"Innervation du diaphragme :","o":["Le nerf vague, ou X, au thorax","Le nerf phrénique, de C3 à C5","Le nerf pudendal, de S2 à S4","Le sympathique seul, de T1 à T12, par la chaîne"],"r":1,"e":"« C3-4-5 keeps the diaphragm alive ».","s":19},{"q":"Hiatus de la VCI :","o":["T10","T8","T12","L2"],"r":1,"e":"V8-Œ10-A12.","s":19},{"q":"Hiatus œsophagien :","o":["T8","T10","T12","L1"],"r":1,"e":"T10 (avec les nerfs vagues).","s":19},{"q":"Hiatus aortique :","o":["T8","T10","T12","L1"],"r":2,"e":"T12 (aorte + canal thoracique + azygos).","s":19},{"q":"Mouvement « en bras de pompe » :","o":["Les côtes inférieures, en transversal","Les côtes supérieures, en sagittal","Le diaphragme, en vertical, par sa coupole","L'abdomen, en avant, à l'inspiration"],"r":1,"e":"Bras de pompe = sagittal (côtes hautes).","s":19},{"q":"Mouvement « en anse de seau » :","o":["Les côtes inférieures, en transversal","Les côtes supérieures, en sagittal","Les côtes flottantes, seules","Le sternum, qui monte en avant, en sagittal"],"r":0,"e":"Anse de seau = transversal (côtes basses).","s":19},{"q":"Inspiration normale :","o":["Passive, par rétraction élastique","Active, par le diaphragme et les intercostaux externes","Réflexe, sans contraction musculaire","Volontaire uniquement, sous le contrôle du cortex moteur"],"r":1,"e":"Inspi active. Expi passive au repos.","s":19},{"q":"Expiration forcée fait intervenir :","o":["Le diaphragme, à lui seul, en se relâchant","Les abdominaux et les intercostaux internes","Le trapèze et les rhomboïdes","Le sterno-cléido-mastoïdien"],"r":1,"e":"Active : abdominaux (grand droit, obliques, transverse) + intercostaux internes.","s":19},{"q":"Volume courant au repos :","o":["100 mL","~500 mL","2 L","5 L"],"r":1,"e":"VC = 500 mL au repos.","s":19},{"q":"Capacité vitale (CV) :","o":["Environ 1 L, chez l'homme","Environ 4,8 L, chez l'homme","Environ 10 L, chez l'homme jeune et sportif","Environ 0,5 L, comme le volume courant"],"r":1,"e":"CV = VRI + VC + VRE. ~4,8 L chez l'homme. Elle additionne le volume courant et les deux volumes de réserve.","s":19},{"q":"Volume résiduel :","o":["0 (poumons vides)","~1,2 L (jamais expulsé)","3 L","5 L"],"r":1,"e":"~1,2 L. Maintien d'une réserve d'air pour les échanges constants.","s":19},{"q":"CPT (capacité pulmonaire totale) :","o":["3 L","~6 L","15 L","1 L"],"r":1,"e":"CPT = CV + VR ≈ 6 L.","s":19},{"q":"Intercostaux externes :","o":["Expirateurs, ils abaissent les côtes en bas","Inspirateurs, ils élèvent les côtes","Sans fonction respiratoire","Actifs dans la toux uniquement"],"r":1,"e":"Direction oblique en bas et avant. Inspirateurs.","s":19},{"q":"Muscles accessoires inspiratoires :","o":["Les abdominaux, le grand droit et les obliques externes","Les scalènes, le petit pectoral et le grand dentelé","Le carré des lombes, en arrière","Le diaphragme et les intercostaux internes"],"r":1,"e":"Accessoires inspiratoires en cas d'effort ou dyspnée. Le sterno-cléido-mastoïdien en fait aussi partie.","s":19},{"q":"Centre tendineux du diaphragme :","o":["Latéral, sur les côtes basses","Central, en aponévrose","Postérieur, sur les piliers","Inexistant chez l'adulte"],"r":1,"e":"Centre phrénique = partie tendineuse centrale.","s":19},{"q":"Piliers diaphragmatiques :","o":["Sur les cervicales, de C3 à C5","Sur les vertèbres lombaires, de L1 à L3","Sur les thoraciques basses, de T10 à T12","Sur le sacrum, de S1 à S3"],"r":1,"e":"Insertion vertébrale du diaphragme. Le pilier droit descend jusqu'à L3, le gauche jusqu'à L2.","s":19},{"q":"Artères intercostales postérieures naissent de :","o":["La carotide commune, au cou","L'aorte thoracique, sauf les deux premières","La veine cave inférieure","L'artère subclavière, directement, pour toutes"],"r":1,"e":"Postérieures = aorte. Antérieures = thoracique interne.","s":19},{"q":"Ponction pleurale (thoracocentèse) :","o":["Au bord inférieur de la côte supérieure","Au bord supérieur de la côte inférieure","Au milieu de l'espace intercostal, sans repère osseux précis","Sous le pubis, en position assise"],"r":1,"e":"Pour éviter le paquet vasculo-nerveux sous-jacent. On évite ainsi le paquet vasculo-nerveux.","s":19},{"q":"Détroit supérieur (orifice supérieur) du thorax délimité par :","o":["T8, la 8ᵉ côte et le corps du sternum","T1, la 1ʳᵉ côte et le manubrium","T12, la 12ᵉ côte et le xiphoïde","Le diaphragme et ses piliers"],"r":1,"e":"Détroit supérieur : T1 + 1ères côtes + manubrium sternal.","s":19},{"q":"Orifice inférieur du thorax fermé par :","o":["Péricarde","Diaphragme","Plèvre","Rien"],"r":1,"e":"Diaphragme sépare thorax/abdomen.","s":19},{"q":"Nerf intercostal vient des branches ventrales de :","o":["Des nerfs cervicaux, de C1 à C8","Des nerfs thoraciques, de T1 à T11","Des nerfs lombaires, de L1 à L5","Des nerfs sacrés, de S1 à S5"],"r":1,"e":"T1-T11. T12 = nerf subcostal. T12 donne le nerf subcostal.","s":19},{"q":"Drainage veineux des intercostales :","o":["La veine porte, par le foie","Le système azygos et hémi-azygos","La veine cave inférieure, directement","La veine cave supérieure, directement, sans relais"],"r":1,"e":"Azygos à droite, hémi-azygos à gauche → VCS. L'azygos est à droite, l'hémi-azygos à gauche.","s":19},{"q":"La paroi thoracique est décrite comme une structure :","o":["Ostéo-musculo-fibreuse, en forme de tronc de cône","Purement osseuse, rigide","Purement musculaire, sans os, très souple et mobile","Cylindrique et fixe, sans cône"],"r":0,"e":"Elle protège les organes intrathoraciques et participe activement à la ventilation.","s":19},{"q":"Parmi les rôles de la paroi thoracique, le cours cite :","o":["La protection, le soutien des bras et la ventilation","La seule protection des organes","La seule ventilation, au repos","Le seul support des membres supérieurs, par la scapula"],"r":0,"e":"Les muscles insérés viennent du cou, de l'abdomen et du membre supérieur. Elle sert aussi d'insertion à de nombreux muscles.","s":19},{"q":"L'orifice supérieur du thorax est délimité par :","o":["T1 en arrière, la 1ʳᵉ côte et le manubrium en avant","T12, la 12ᵉ côte et l'appendice xiphoïde en avant","T4, la 4ᵉ côte et le manubrium sternal","La clavicule et la 1ʳᵉ côte, en avant"],"r":0,"e":"Y passent la trachée, l'œsophage, les vaisseaux et les nerfs.","s":19},{"q":"Les fausses côtes sont les côtes :","o":["1 à 7","8 à 10","11 et 12","9 à 12"],"r":1,"e":"Leur cartilage rejoint celui de la côte sus-jacente, formant le rebord costal ; les côtes 11 et 12 sont flottantes.","s":19},{"q":"La tête d'une côte type s'articule avec :","o":["Deux vertèbres, la sus-jacente et la sienne","Une seule vertèbre, celle du même numéro, en T1","Le sternum, en avant","L'apophyse transverse, en arrière"],"r":0,"e":"Les côtes T1, T11 et T12 font exception avec une seule facette ; le tubercule s'articule, lui, avec l'apophyse transverse.","s":19},{"q":"Le sillon costal se situe :","o":["Sur le bord inférieur du corps de la côte","Sur le bord supérieur du corps de la côte","À la tête de la côte, en arrière","Au tubercule costal, près du col"],"r":0,"e":"Il abrite le paquet vasculo-nerveux intercostal, disposé de haut en bas en veine, artère, nerf.","s":19},{"q":"Lors d'une ponction pleurale, l'aiguille doit passer :","o":["Au bord supérieur de la côte inférieure","Au bord inférieur de la côte supérieure","Au milieu de l'espace","Au niveau du tubercule"],"r":0,"e":"Cela évite le paquet vasculo-nerveux logé dans le sillon costal du bord inférieur de la côte.","s":19},{"q":"Le processus xiphoïde est :","o":["Cartilagineux chez le jeune, il s'ossifie avec l'âge","Osseux dès la naissance, soudé au corps du sternum","Toujours cartilagineux, à tout âge","Absent chez l'adulte, résorbé"],"r":0,"e":"Le sternum comprend le manubrium, le corps et le processus xiphoïde.","s":19},{"q":"L'angle sternal de Louis correspond :","o":["Au 2ᵉ cartilage costal et à T4-T5, entre deux médiastins","Au 1ᵉʳ cartilage costal et à T2, sous la clavicule droite","À T8, au niveau du hiatus de la cave","À l'appendice xiphoïde, en T9"],"r":0,"e":"C'est aussi le niveau de la bifurcation trachéale, la carène. Il sépare les médiastins supérieur et inférieur.","s":19},{"q":"L'articulation manubrio-sternale est :","o":["Une symphyse, mobile lors de la respiration","Une articulation synoviale, très mobile","Une synchondrose fixe, ossifiée","Une arthrodie plane, glissante"],"r":0,"e":"L'articulation sterno-claviculaire est, elle, la seule articulation reliant le squelette du membre supérieur au tronc.","s":19},{"q":"L'articulation costo-chondrale est :","o":["Une synchondrose","Une synoviale","Une symphyse","Une syndesmose"],"r":0,"e":"L'articulation chondro-sternale, entre cartilage costal et sternum, est en revanche synoviale.","s":19},{"q":"L'intercostal externe est orienté :","o":["En bas et en avant, et il est inspirateur","En bas et en arrière, et il est expirateur","Verticalement, et il est inspirateur accessoire au cou","Horizontalement, sans rôle"],"r":0,"e":"Les intercostaux moyen et intime, obliques en bas et en arrière, sont expirateurs. L'orientation est oblique.","s":19},{"q":"Parmi les muscles inspirateurs accessoires, le cours cite :","o":["Le sterno-cléido-mastoïdien, les scalènes et le petit pectoral","Les abdominaux, le grand droit et les deux obliques, à l'effort","Le carré des lombes, en arrière","Le triangulaire du sternum, en avant"],"r":0,"e":"Le petit pectoral élève les côtes 3 à 5 et les scalènes les premières côtes. Le grand dentelé et les élévateurs des côtes en font aussi partie.","s":19},{"q":"Parmi les muscles expirateurs accessoires figurent :","o":["Les abdominaux, le triangulaire et le carré des lombes","Les scalènes et le petit pectoral","Le sterno-cléido-mastoïdien","Le grand dentelé et les élévateurs des côtes, en arrière"],"r":0,"e":"Les abdominaux comprennent le grand droit, les obliques et le transverse. Le triangulaire est celui du sternum.","s":19},{"q":"L'insertion costale du diaphragme se fait sur :","o":["La face interne des 6 dernières côtes et leurs cartilages","La face externe des 12 côtes, sur tout leur bord inférieur","Les 3 premières côtes, en haut","Le sternum seul, en avant"],"r":0,"e":"S'y ajoutent les insertions sternale sur le processus xiphoïde et vertébrale par les piliers.","s":19},{"q":"Le pilier droit du diaphragme s'insère sur :","o":["L1-L3","L1-L2","T10-T12","L3-L5"],"r":0,"e":"Le pilier gauche s'insère sur L1-L2 ; le centre tendineux, ou centre phrénique, en constitue l'aponévrose centrale.","s":19},{"q":"Le hiatus œsophagien se situe au niveau :","o":["De T8","De T10","De T12","De L1"],"r":1,"e":"Le mnémonique « V8 - Œ10 - A12 » rappelle la veine cave à T8, l'œsophage à T10 et l'aorte à T12.","s":19},{"q":"Le hiatus aortique livre passage :","o":["L'aorte, le canal thoracique et la veine azygos","L'aorte seule, sans le canal thoracique, en T12","La veine cave et le nerf phrénique droit","L'œsophage et les deux nerfs vagues"],"r":0,"e":"Le hiatus de la veine cave, en T8, livre passage à la VCI et au nerf phrénique droit.","s":19},{"q":"Le nerf phrénique naît des racines :","o":["C3, C4 et C5","C1 et C2","C6, C7, C8 et T1","T1 à T4"],"r":0,"e":"D'où la formule mnémotechnique « C3-4-5 keeps the diaphragm alive » ; les nerfs intercostaux innervent la partie périphérique.","s":19},{"q":"Lors de l'inspiration, la contraction du diaphragme :","o":["L'abaisse et augmente le diamètre vertical du thorax","L'élève et réduit le diamètre vertical du thorax","Augmente le seul diamètre transversal","N'a aucun effet sur le volume"],"r":0,"e":"Les intercostaux externes élèvent les côtes et augmentent les diamètres antéro-postérieur et transversal.","s":19},{"q":"À quel niveau vertébral se situent les reins ?","o":["D8 à D10","D11–D12 à L1–L2–L3","L3 à L5","D9 à D12 seulement"],"r":1,"e":"Reins de D11–D12 à L1–L2–L3. Le rein droit est plus bas (foie).","s":20},{"q":"Longueur moyenne d'un rein adulte ?","o":["6 cm","8 cm","12 cm","18 cm"],"r":2,"e":"12 cm × 6 cm × 3 cm. Poids ~140 g.","s":20},{"q":"Quel est le lieu de la filtration glomérulaire ?","o":["Le tubule contourné proximal","L'anse de Henle, dans la médulla profonde","Le corpuscule de Malpighi","Le tube collecteur"],"r":2,"e":"Le corpuscule de Malpighi filtre le plasma → ultrafiltrat dans la capsule de Bowman → tubule proximal. Il réunit le glomérule et la capsule de Bowman.","s":20},{"q":"Combien de segments comporte l'uretère ?","o":["Deux, lombaire et pelvien","Trois, lombaire, iliaque et pelvien, seulement","Quatre, de la portion lombaire à l'intravésicale","Cinq, avec une portion rénale"],"r":2,"e":"4 segments : lombaire, iliaque, pelvien, intravesical. Ce sont les segments lombaire, iliaque, pelvien et intravésical.","s":20},{"q":"Longueur de l'urètre féminin ?","o":["3 à 4 cm","10 cm","16 à 18 cm","20 cm"],"r":0,"e":"Femme : 3-4 cm (urinaire pur). Homme : 16-18 cm (uro-génital).","s":20},{"q":"Quel système nerveux contracte la vessie (détrusor) ?","o":["Sympathique (D11–L1)","Parasympathique (S2–S4)","Somatique (nerf pudendal)","Plexus mésentérique"],"r":1,"e":"Para S2–S4 contracte le détrusor (miction). Sympa contracte le col (continence). Pudendal = sphincter strié.","s":20},{"q":"Le trigone vésical est délimité par :","o":["Les quatre ostiums urétéraux, deux par côté","Les deux ostiums urétéraux et l'ostium urétral interne","Les piliers de la vessie","L'ouraque et les deux ligaments ombilicaux latéraux"],"r":1,"e":"Triangle : 2 orifices urétériques + 1 orifice urétral interne. Zone fixe et sensible.","s":20},{"q":"Comment sont classés les reins par rapport au péritoine ?","o":["Intra-péritonéaux, mobiles et libres","Rétropéritonéaux et thoraco-abdominaux","Sous-péritonéaux, dans le petit bassin","Mésentériques, suspendus"],"r":1,"e":"Les reins sont rétropéritonéaux et thoraco-abdominaux.","s":20},{"q":"Quelles enveloppes entourent le rein (de la profondeur vers la superficie) ?","o":["Fascia, puis graisse, puis capsule","Capsule, puis graisse périrénale, puis fascia","Albuginée, puis fascia, puis graisse pararénale","Péritoine, puis graisse, puis capsule"],"r":1,"e":"De profond à superficiel : capsule rénale (fibreuse), graisse périrénale, fascia rénal.","s":20},{"q":"La face postérieure du rein gauche est en rapport avec :","o":["12ème côte uniquement","11ème et 12ème côtes","10ème côte uniquement","Aucune côte"],"r":1,"e":"Rein gauche : 11ème et 12ème côtes. Rein droit : 12ème seulement (foie le pousse vers le bas).","s":20},{"q":"Le hile rénal contient :","o":["L'artère rénale seule, avec ses branches segmentaires","L'artère et la veine rénales, seules","Le pédicule rénal complet, avec l'uretère","L'uretère seul, et le bassinet"],"r":2,"e":"Hile = pédicule rénal complet : artère rénale, veine rénale, uretère, nerfs, lymphatiques. Il comprend l'artère, la veine, l'uretère, les nerfs et les lymphatiques.","s":20},{"q":"La zone périphérique du rein s'appelle :","o":["Cortex rénal","Médulla rénale","Pyramide de Malpighi","Pelvis rénal"],"r":0,"e":"Cortex = périphérie (corpuscules, tubules contournés). Médulla = centre (pyramides).","s":20},{"q":"Les pyramides de Malpighi se trouvent dans :","o":["Le cortex","La médulla","La capsule","Le pelvis"],"r":1,"e":"Médulla = pyramides de Malpighi. Leur base regarde le cortex, leur sommet (papille) le sinus rénal.","s":20},{"q":"Les colonnes de Bertin sont :","o":["Des vaisseaux sanguins du cortex","Des prolongements du cortex entre les pyramides","Les tubes collecteurs, médullaires","Les calices mineurs, qui coiffent chaque papille de la médulla"],"r":1,"e":"Colonnes de Bertin = prolongements corticaux entre les pyramides médullaires.","s":20},{"q":"L'unité fonctionnelle du rein est :","o":["Le lobule rénal","Le néphron","La pyramide","Le glomérule isolé"],"r":1,"e":"Néphron = unité histologique ET physiologique. ~1 million par rein.","s":20},{"q":"L'ordre correct de l'urine du néphron à l'extérieur :","o":["Néphron → uretère → vessie → urètre → calices","Néphron → calices → pelvis → uretère → vessie → urètre","Néphron → pelvis → calices → vessie → urètre","Néphron → vessie → calices → pelvis → uretère → urètre"],"r":1,"e":"Tube collecteur → canal papillaire → petit calice → grand calice → pelvis → uretère → vessie → urètre.","s":20},{"q":"Quelle artériole entre dans le glomérule ?","o":["Artériole afférente","Artériole efférente","Vasa recta","Artère arquée"],"r":0,"e":"Afférente entre, efférente sort. L'efférente donne les capillaires péritubulaires et les vasa recta.","s":20},{"q":"Le néphron justamédullaire se distingue par :","o":["Une anse de Henle courte, corticale","Une longue anse de Henle, qui plonge dans la médulla","L'absence de glomérule, avec un tubule direct vers le calice","Un tube collecteur double"],"r":1,"e":"Justamédullaire = longue anse, essentiel à la concentration des urines. Cortical = anse courte.","s":20},{"q":"La vessie vide a la forme de :","o":["D'une sphère régulière","D'un prisme triangulaire","D'un cylindre allongé","D'une poire, à grosse extrémité supérieure"],"r":1,"e":"Vessie vide = prisme triangulaire. Vessie distendue = forme variable selon le volume.","s":20},{"q":"Le muscle de la vessie s'appelle :","o":["Sphincter","Détrusor","Trigonal","Pubo-rectal"],"r":1,"e":"Détrusor = muscle lisse de la paroi vésicale, responsable de la contraction lors de la miction.","s":20},{"q":"Les uretères pénètrent la vessie par sa face :","o":["Antérieure","Supérieure","Postéro-latérale","Inférieure"],"r":2,"e":"Postéro-latérale, avec un trajet oblique anti-reflux.","s":20},{"q":"L'urètre masculin est divisé en :","o":["Deux portions, prostatique et pénienne","Trois portions, sans la pré-prostatique, chez l'adulte","Quatre portions, de la pré-prostatique à la pénienne","Cinq portions, avec le méat"],"r":2,"e":"4 portions : pré-prostatique → prostatique → membraneuse → spongieuse (pénienne). Ce sont les portions pré-prostatique, prostatique, membraneuse et pénienne.","s":20},{"q":"Le sphincter strié de l'urètre est innervé par :","o":["Le sympathique, de T11 à L1","Le parasympathique, de S2 à S4","Le nerf pudendal, somatique","Le plexus hypogastrique inférieur"],"r":2,"e":"Sphincter strié externe = contrôle volontaire via le nerf pudendal.","s":20},{"q":"La capsule rénale est composée de :","o":["Muscle lisse","Tissu conjonctif fibreux","Tissu adipeux","Épithélium pavimenteux"],"r":1,"e":"La capsule rénale est conjonctive fibreuse, directement au contact du parenchyme.","s":20},{"q":"La face antérieure du rein droit est en rapport avec :","o":["La rate et l'angle splénique, en dehors","Le foie, le duodénum et l'angle hépatique du côlon","L'estomac et le pancréas, en avant","L'utérus et les annexes, en bas, chez la femme adulte"],"r":1,"e":"Rein droit antérieur : foie (ligament hépato-rénal), D2 du duodénum, angle hépatique, tête du pancréas, surrénale.","s":20},{"q":"La face antérieure du rein gauche est en rapport avec :","o":["Le foie et la vésicule, en avant","L'estomac, la rate, la queue du pancréas et le côlon","Le duodénum, uniquement, en D2","L'appendice, le cæcum et l'iléon terminal, à gauche du bassin"],"r":1,"e":"Rein gauche antérieur : capsule surrénale, rate, queue du pancréas, estomac, angle splénique, anses jéjunales.","s":20},{"q":"Quelle est la 1ère étape du cycle mictionnel ?","o":["Le remplissage, détrusor relâché et sphincter contracté","La miction, détrusor contracté et sphincter relâché","L'évacuation passive, par la seule gravité, sans aucun muscle","La compression abdominale, en poussée"],"r":0,"e":"Phase de remplissage : détrusor relâché + sphincter contracté. Continence.","s":20},{"q":"Le poids moyen d'un rein adulte est de :","o":["60 g","140 g","300 g","500 g"],"r":1,"e":"~140 g. Le rein gauche est généralement plus volumineux que le droit.","s":20},{"q":"Le pôle inférieur du rein est en rapport avec :","o":["Le diaphragme et la plèvre","La surrénale et la veine cave, au-dessus du pôle","Le psoas et le carré des lombes","La rate et l'angle colique"],"r":2,"e":"Pôle inférieur : m. psoas et m. carré lombaire. Pôle supérieur : diaphragme + surrénale. Le pôle supérieur répond au diaphragme et à la surrénale.","s":20},{"q":"La forme caractéristique du rein est :","o":["Cylindrique","En haricot","Ovoïde régulier","Pyramidale"],"r":1,"e":"Forme de haricot — face antérieure convexe, postérieure plate, bord externe convexe, bord interne concave avec le hile.","s":20},{"q":"Le système urinaire est constitué de :","o":["2 reins, 2 uretères, 1 vessie et 1 urètre","2 reins, 1 vessie et 1 urètre, sans uretère","1 rein, 1 uretère et 1 vessie","2 reins, 2 uretères et 2 urètres"],"r":0,"e":"La production d'urine est continue, le stockage et l'évacuation discontinus.","s":20},{"q":"Les reins s'étendent verticalement :","o":["De D11-D12 à L1-L3","De T8 à T12, en haut","De L3 à L5, en bas","De T12 à S1, long"],"r":0,"e":"Ce sont des organes rétropéritonéaux et thoraco-abdominaux ; le rein gauche est généralement plus volumineux que le droit.","s":20},{"q":"La largeur et l'épaisseur moyennes d'un rein adulte sont :","o":["6 cm et 3 cm","12 cm et 6 cm","3 cm et 1 cm","8 cm et 4 cm"],"r":0,"e":"Sa longueur moyenne est de 12 cm et son poids d'environ 140 g.","s":20},{"q":"La face postérieure du rein est :","o":["Convexe","Plate","Concave","Irrégulière"],"r":1,"e":"La face antérieure est convexe, le bord externe convexe et le bord interne concave, portant le hile.","s":20},{"q":"La graisse périrénale a pour rôle :","o":["D'amortisseur mécanique","D'enveloppe résistante","De moyen de fixation","De filtre du sang, avec le cortex"],"r":0,"e":"La capsule rénale apporte la résistance et le fascia rénal maintient reins et surrénales en place.","s":20},{"q":"Le fascia rénal enveloppe :","o":["Les deux reins et les glandes surrénales","Le seul rein droit, sans la surrénale","La seule graisse périrénale, sans les reins ni les surrénales","La vessie et les uretères, en bas"],"r":0,"e":"C'est la plus superficielle des trois enveloppes concentriques.","s":20},{"q":"La face antérieure du rein droit répond notamment :","o":["Au foie, à l'angle colique droit et au duodénum","À la rate et à la queue du pancréas","À l'estomac et au cardia, en avant, par la bourse omentale","Aux anses jéjunales, en bas"],"r":0,"e":"Le foie y est relié par le ligament hépato-rénal et le côlon séparé par le fascia de Toldt. La tête du pancréas et la surrénale droite en font aussi partie.","s":20},{"q":"La face postérieure du rein gauche répond, dans la paroi thoracique, aux côtes :","o":["11ᵉ et 12ᵉ","12ᵉ uniquement","10ᵉ et 11ᵉ","9ᵉ à 12ᵉ"],"r":0,"e":"Le rein droit ne répond qu'à la 12ᵉ côte ; la paroi lombaire comprend le carré des lombes et le transverse de l'abdomen.","s":20},{"q":"Le bord interne du rein répond, dans sa partie supérieure :","o":["À la surrénale, aux transverses de L1-L2 et aux piliers","Au psoas et à l'uretère, en L3","Au carré des lombes, en arrière","Au côlon et au duodénum, en avant, par le fascia de Toldt"],"r":0,"e":"Sa partie inférieure répond au muscle psoas et à la partie initiale des uretères. L'aorte est à gauche et la VCI à droite.","s":20},{"q":"Le cortex rénal contient :","o":["Les corpuscules de Malpighi et les tubules contournés","Les pyramides de Malpighi et toutes les anses de Henle","Les calices mineurs et majeurs","Le bassinet, au centre du rein"],"r":0,"e":"La médulla, zone centrale, est organisée en pyramides dont la base regarde le cortex.","s":20},{"q":"Le trajet de l'urine suit l'ordre :","o":["Papille, calices, pelvis, uretère, vessie, urètre","Pelvis, grand calice, petit calice, papille, uretère, vessie","Uretère, vessie, pelvis, urètre","Papille, uretère, calice, vessie"],"r":0,"e":"Le pelvis rénal porte aussi le nom de bassinet. Le petit calice précède le grand calice.","s":20},{"q":"Le corpuscule de Malpighi comprend :","o":["La capsule de Bowman et le glomérule","Le tubule proximal et l'anse de Henle","Le tubule distal seul","Le tube collecteur"],"r":0,"e":"Le néphron comprend ensuite le tubule contourné proximal, l'anse de Henle, le tubule contourné distal et les tubes collecteurs.","s":20},{"q":"Les tubes collecteurs terminaux portent le nom de :","o":["Tubes de Bellini","Tubes de Henle","Canaux de Bertin","Canaux de Malpighi"],"r":0,"e":"Ils font suite au tubule contourné distal et déversent l'urine vers les papilles.","s":20},{"q":"L'artériole efférente donne naissance :","o":["Aux capillaires péritubulaires et aux vasa recta","Au glomérule, dans la capsule","À l'artère rénale, au hile","À la veine rénale, après avoir traversé la médulla externe"],"r":0,"e":"L'artériole afférente entre, elle, dans le glomérule ; les vasa recta entourent l'anse de Henle.","s":20},{"q":"Le néphron cortical se caractérise par :","o":["Un corpuscule dans la partie superficielle du cortex","Un corpuscule à la jonction cortico-médullaire","Une longue anse de Henle, médullaire","L'absence de glomérule, avec un tubule qui naît de la papille"],"r":0,"e":"Le néphron juxtamédullaire se distingue par un corpuscule profond et une longue anse de Henle.","s":20},{"q":"Le néphron est défini comme :","o":["L'unité histologique et physiologique du rein","Une simple structure de soutien","Un vaisseau du rein, qui filtre le sang dans le cortex","Un segment des voies excrétrices"],"r":0,"e":"C'est lui qui réalise la filtration du sang et la formation de l'urine.","s":20},{"q":"Le hile rénal livre passage :","o":["Les vaisseaux rénaux, l'uretère et les nerfs","L'uretère seul, sans les vaisseaux ni les nerfs","Les seuls vaisseaux, artère et veine","La surrénale, par sa veine"],"r":0,"e":"Il occupe le bord interne, concave, du rein. Les lymphatiques y passent aussi.","s":20},{"q":"Le pôle supérieur du rein répond :","o":["Au diaphragme, à la surrénale et à la 12ᵉ côte","Au psoas et à l'uretère, en dedans, vers L3","Au carré des lombes, en arrière","Au côlon et au duodénum, en avant"],"r":0,"e":"Le pôle inférieur répond, lui, au psoas et au carré des lombes. Il répond aussi au foie et à la VCI à droite, à la rate à gauche.","s":20},{"q":"La capsule rénale est constituée :","o":["De tissu conjonctif fibreux","De tissu adipeux","De tissu conjonctif lâche","De muscle lisse"],"r":0,"e":"Elle recouvre directement le rein et lui donne sa résistance ; la graisse périrénale et le fascia rénal la recouvrent.","s":20},{"q":"Le rein a une forme caractéristique :","o":["De haricot","De poire","Sphérique","Triangulaire"],"r":0,"e":"Il présente deux faces, deux bords et deux pôles, le bord interne concave portant le hile.","s":20},{"q":"Organes génitaux internes féminins ?","o":["Ovaires, trompes, utérus, vulve","Ovaires, trompes, utérus, vagin","Ovaires, utérus, vagin, clitoris","Ovaires, vagin, seins"],"r":1,"e":"Internes : ovaires + trompes + utérus + vagin. La vulve est externe.","s":21},{"q":"Position physiologique de l'utérus dans 80% des cas ?","o":["Antéversé et antéfléchi","Rétroversé et rétrofléchi","Vertical médian","Latérodévié"],"r":0,"e":"Antéversé (col regarde en arrière) + antéfléchi (corps penche en avant).","s":21},{"q":"Les grandes lèvres sont l'équivalent embryologique du :","o":["Pénis","Scrotum","Testicule","Glandes de Cowper"],"r":1,"e":"Grandes lèvres = scrotum. Clitoris = pénis. Bartholin = Cowper. Skene = prostate.","s":21},{"q":"Le sein s'étend entre :","o":["1ère et 4ème côte","2ème et 6ème côte","5ème et 8ème côte","6ème et 10ème côte"],"r":1,"e":"2ème à 6ème côte, repose sur le grand pectoral. Prolongement axillaire de Spence.","s":21},{"q":"Rôle de l'ocytocine sur la glande mammaire ?","o":["Production du lait","Éjection du lait","Développement des acini","Croissance des canaux"],"r":1,"e":"Prolactine = production. Ocytocine = éjection. Œstrogènes = canaux. Progestérone = acini.","s":21},{"q":"Combien d'organes génitaux externes féminins distincts ?","o":["Trois, sans le vestibule","Quatre, sans les glandes ni le mont du pubis","Cinq, sans les glandes annexes","Une vulve, réunissant six éléments"],"r":3,"e":"La vulve = mont pubis + grandes lèvres + petites lèvres + clitoris + vestibule + glandes annexes. Ce sont le mont du pubis, les grandes et petites lèvres, le clitoris, le vestibule et les glandes.","s":21},{"q":"Les ovaires sont situés dans :","o":["L'utérus, au fond de la cavité, contre le fundus","La fosse ovarienne, contre la paroi pelvienne","Le canal inguinal, en avant","L'abdomen sus-mésocolique"],"r":1,"e":"Fosse ovarienne sur la paroi latérale du pelvis.","s":21},{"q":"Longueur moyenne d'une trompe utérine ?","o":["3-5 cm","5-7 cm","10-12 cm","20 cm"],"r":2,"e":"~10-12 cm. 4 portions : pavillon, ampoule, isthme, interstitielle.","s":21},{"q":"La portion de la trompe où a lieu la fécondation ?","o":["Pavillon","Ampoule","Isthme","Portion interstitielle"],"r":1,"e":"Ampoule = portion la plus longue et large, lieu de la fécondation.","s":21},{"q":"L'utérus pèse en moyenne :","o":["20 g, chez la nullipare","50 g, chez la nullipare","150 g, chez la nullipare","500 g, chez la nullipare"],"r":1,"e":"Nullipare ~50 g, multipare ~70 g. Volume × 24 pendant la grossesse.","s":21},{"q":"Les 3 tuniques de l'utérus de l'extérieur vers l'intérieur :","o":["Endomètre, myomètre, séreuse","Périmètre, myomètre, endomètre","Muqueuse, sous-muqueuse, séreuse","Cortex, médulla, séreuse"],"r":1,"e":"De dehors à dedans : périmètre (séreuse) → myomètre (muscle) → endomètre (muqueuse).","s":21},{"q":"La couche fonctionnelle de l'endomètre :","o":["Est permanente","Est éliminée à chaque menstruation","Est en contact direct avec le myomètre","Ne se renouvelle pas"],"r":1,"e":"Couche fonctionnelle = éliminée chaque cycle, régénérée par la couche basale.","s":21},{"q":"Longueur du vagin ?","o":["3-4 cm","7-10 cm","15 cm","20 cm"],"r":1,"e":"7-10 cm, musculo-membraneux. pH acide (3,8-4,5) grâce aux lactobacilles.","s":21},{"q":"Le cul-de-sac postérieur du vagin (de Douglas) est :","o":["Le point le plus déclive du péritoine chez la femme","Un cul-de-sac recto-vésical, comme chez l'homme","Situé au-dessus de l'utérus","Situé à gauche du rectum"],"r":0,"e":"Cul-de-sac recto-utérin de Douglas = point le plus bas du péritoine féminin. Ponctionnable.","s":21},{"q":"Le clitoris est l'équivalent embryologique du :","o":["Pénis","Scrotum","Testicule","Prostate"],"r":0,"e":"Clitoris = équivalent du pénis (2 racines, 2 corps caverneux, 1 gland).","s":21},{"q":"Les glandes de Bartholin sont :","o":["Des glandes endocrines, sans canal","Les glandes vestibulaires majeures, lubrifiantes","Des glandes para-urétrales, de part et d'autre du méat urinaire","Des glandes mammaires accessoires"],"r":1,"e":"Bartholin = glandes vestibulaires majeures, sécrétion lubrifiante. Équivalentes des glandes de Cowper.","s":21},{"q":"Le périnée se divise en :","o":["Trois triangles, antérieur, moyen et postérieur","Deux triangles, uro-génital et anal","Quatre quadrants égaux","Deux plans transversaux"],"r":1,"e":"Ligne bi-ischiatique sépare le périnée en triangle uro-génital (avant) et triangle anal (arrière). L'uro-génital est en avant, l'anal en arrière.","s":21},{"q":"Le centre tendineux du périnée est situé :","o":["Entre vessie et vagin","Entre vagin et anus","À l'arrière de l'anus","Au-dessus du pubis"],"r":1,"e":"Nœud fibreux entre vagin et anus, point d'insertion de nombreux muscles. Risque déchirure à l'accouchement.","s":21},{"q":"Le muscle élévateur de l'anus appartient au :","o":["Au plan profond, ou diaphragme pelvien","Au plan moyen, ou diaphragme uro-génital","Au plan superficiel, sous la peau","À la paroi abdominale, en bas"],"r":0,"e":"Levator ani = plan profond = diaphragme pelvien. Soutien principal des organes pelviens.","s":21},{"q":"Les amygdales constituent l'anneau de :","o":["Vieussens","Waldeyer","Willis","Hering"],"r":1,"e":"Anneau de Waldeyer = amygdales pharyngée + tubaires + palatines + linguale.","s":21},{"q":"Le mamelon est percé par :","o":["Un seul canal, central","Cinq canaux, un par quadrant et un au centre","15 à 20 canaux galactophores","50 canaux, très fins"],"r":2,"e":"15-20 canaux galactophores, un par lobe de la glande mammaire.","s":21},{"q":"Les tubercules de Montgomery se trouvent sur :","o":["Le mamelon","L'aréole","La queue de Spence","Le creux axillaire"],"r":1,"e":"Glandes sébacées modifiées dans l'aréole, visibles sous forme de tubercules.","s":21},{"q":"Le drainage lymphatique du sein se fait à 75% vers :","o":["Ganglions mammaires internes","Ganglions axillaires","Ganglions sus-claviculaires","Ganglions cervicaux"],"r":1,"e":"75% axillaires + 25% mammaires internes. Important en cancérologie.","s":21},{"q":"Les ligaments de Cooper sont :","o":["Des ligaments de l'utérus, vers le sacrum","Les ligaments suspenseurs du sein","Des ligaments de la vessie","Des ligaments de l'ovaire"],"r":1,"e":"Travées fibreuses entre glande et peau. Soutiennent le sein.","s":21},{"q":"Le vagin a un pH normal de :","o":["7,4 (neutre)","3,8-4,5 (acide)","8,0 (alcalin)","5,5-6,5"],"r":1,"e":"pH acide grâce aux lactobacilles (bacille de Döderlein) qui transforment le glycogène en acide lactique.","s":21},{"q":"L'utérus est constitué de 3 parties :","o":["Tête, corps, queue","Fundus, corps, col","Apex, base, col","Pôle supérieur, médian, inférieur"],"r":1,"e":"Fundus (haut), corps (milieu), col (cervix - bas).","s":21},{"q":"L'orifice vaginal est partiellement fermé chez la vierge par :","o":["La caroncule","L'hymen","Le frein","La luette"],"r":1,"e":"Hymen = repli muqueux partiel à l'entrée du vagin.","s":21},{"q":"La fonction principale du myomètre est :","o":["La nidation de l'œuf fécondé","La sécrétion hormonale, en continu, des œstrogènes","La contraction, lors de l'accouchement","La filtration du sang"],"r":2,"e":"Myomètre = muscle lisse responsable des contractions (accouchement, menstruation).","s":21},{"q":"Le vestibule de la vulve contient :","o":["Les mamelons accessoires, sur la ligne lactée","Le méat urétral et l'orifice vaginal","Uniquement l'orifice vaginal","Uniquement le clitoris"],"r":1,"e":"Vestibule = espace entre les petites lèvres. Contient méat urétral + orifice vaginal + orifices Bartholin/Skene. Les orifices des glandes de Bartholin et de Skene y sont aussi.","s":21},{"q":"La prolactine est sécrétée par :","o":["L'hypothalamus, par ses noyaux","L'antéhypophyse, ou adénohypophyse","L'ovaire, par le corps jaune","Le placenta, en fin de grossesse"],"r":1,"e":"Antéhypophyse → prolactine → production du lait. L'éjection = ocytocine (post-hypophyse). L'éjection du lait dépend de l'ocytocine.","s":21},{"q":"Les fonctions du système reproducteur féminin comprennent :","o":["Les gamètes, les hormones, la gestation et la lactation","La seule gestation, de la nidation jusqu'à l'accouchement","La seule production d'ovocytes","La seule lactation, après l'accouchement"],"r":0,"e":"Il se répartit en organes internes pelviens et organes externes constituant la vulve. La fécondation, la nidation et l'accouchement en font aussi partie.","s":21},{"q":"Les ovaires mesurent environ :","o":["1 cm de long, comme un pois","3 cm de long, en amande","6 cm de long, comme un œuf","10 cm de long, comme une poire"],"r":1,"e":"Glandes paires ovoïdes, ils siègent dans la fosse ovarienne, sur la paroi latérale du pelvis.","s":21},{"q":"Les ovaires sont maintenus par :","o":["Trois ligaments, dont le lombo-ovarien","Le seul ligament rond","Le ligament large seul, par sa partie haute","Le ligament utéro-sacré"],"r":0,"e":"Ils assurent la production des ovocytes et des hormones sexuelles. Ce sont le ligament suspenseur ou lombo-ovarien, le ligament propre et le mésovarium.","s":21},{"q":"Les quatre portions de la trompe utérine sont :","o":["Infundibulum, ampoule, isthme et portion interstitielle","Pavillon, corps, col et isthme, de l'ovaire à l'utérus","Fundus, corps, isthme et col, comme l'utérus","Base, corps, apex et col, de dehors en dedans"],"r":0,"e":"La trompe mesure 10 à 12 cm ; la fécondation a lieu dans l'ampoule.","s":21},{"q":"L'infundibulum de la trompe :","o":["Porte des franges et capte l'ovocyte expulsé","Est le siège de la fécondation","Traverse la paroi utérine, sur environ un centimètre","Est la portion la plus étroite"],"r":0,"e":"La portion interstitielle traverse, elle, la paroi utérine.","s":21},{"q":"L'utérus mesure environ :","o":["7 à 8 cm de long, pour environ 50 g","12 cm de long, pour environ 150 g","3 cm de long, pour environ 10 g","15 cm de long, pour environ 500 g, chez la nullipare"],"r":0,"e":"En forme de poire inversée, il se situe entre la vessie en avant et le rectum en arrière. Ce poids est celui de la nullipare.","s":21},{"q":"Les trois parties de l'utérus sont :","o":["Fundus, corps et col","Base, corps et apex","Isthme, ampoule et pavillon","Périmètre, myomètre et endomètre"],"r":0,"e":"Périmètre, myomètre et endomètre en sont, eux, les trois tuniques.","s":21},{"q":"Le périmètre de l'utérus correspond :","o":["Au péritoine","Au muscle","À la muqueuse cyclique","Au col"],"r":0,"e":"Le myomètre est la tunique musculaire et l'endomètre la muqueuse soumise au cycle.","s":21},{"q":"Le vagin mesure :","o":["3 à 5 cm","7 à 10 cm","15 cm","20 cm"],"r":1,"e":"Conduit musculo-membraneux, il s'étend du col utérin à la vulve.","s":21},{"q":"Le fornix vaginal correspond :","o":["Au cul-de-sac formé autour du col utérin","À l'orifice vaginal, à l'entrée","Au vestibule, entre les petites lèvres, en avant de l'anus","À l'hymen, chez la jeune fille"],"r":0,"e":"Le vagin répond en avant à la vessie et à l'urètre, en arrière au rectum. Il a des portions antérieure, postérieure et latérales.","s":21},{"q":"Le pH acide du vagin est dû :","o":["Aux lactobacilles","Aux glandes de Bartholin","Au mucus cervical","Aux œstrogènes directement"],"r":0,"e":"Sa paroi comprend une muqueuse, une musculeuse et une adventice.","s":21},{"q":"Les petites lèvres se caractérisent par :","o":["L'absence de poils et l'union en capuchon","La présence de poils sur leur face externe","Un contenu graisseux important","L'équivalence avec le scrotum"],"r":0,"e":"Les grandes lèvres, graisseuses et poilues sur leur face externe, sont les équivalents du scrotum. Elles n'ont pas de glandes sudoripares ; le capuchon est celui du clitoris.","s":21},{"q":"Le clitoris comprend :","o":["Deux racines, deux corps caverneux et un gland","Un seul corps érectile, sans racine ni gland distinct","Trois corps caverneux, en triangle","Un corps spongieux, médian"],"r":0,"e":"Organe érectile très innervé, il est l'équivalent embryologique du pénis.","s":21},{"q":"Le vestibule vulvaire contient :","o":["Le méat urétral, l'orifice vaginal et des glandes","Le seul orifice vaginal, en bas","Le clitoris, le mont du pubis et les deux grandes lèvres","Le mont du pubis, en avant"],"r":0,"e":"Les glandes de Bartholin, vestibulaires majeures, assurent la lubrification ; les glandes de Skene sont péri-urétrales. Ce sont les glandes de Bartholin et de Skene.","s":21},{"q":"Le périnée est divisé par :","o":["Une ligne bi-ischiatique, en périnée urogénital et anal","Une ligne médiane, en deux moitiés","Le centre tendineux, en deux étages, supérieur et inférieur","Le diaphragme pelvien, en hauteur"],"r":0,"e":"Le périnée antérieur contient les organes génitaux externes et l'urètre, le postérieur l'anus et son sphincter. L'urogénital est en avant, l'anal en arrière.","s":21},{"q":"Le plan profond du périnée comprend :","o":["Les élévateurs de l'anus et le coccygien","Le transverse superficiel du périnée","Le bulbo-spongieux, en surface","Le sphincter externe de l'anus et le transverse profond"],"r":0,"e":"Le plan moyen comprend le transverse profond et le sphincter externe de l'urètre. Ils forment le diaphragme pelvien.","s":21},{"q":"Le centre tendineux du périnée est :","o":["Un nœud fibreux entre vagin et anus","Un muscle annulaire","Un ligament vertébral","Une aponévrose abdominale, en avant du pubis"],"r":0,"e":"Son importance obstétricale tient au risque de déchirure et à l'épisiotomie. De nombreux muscles s'y insèrent.","s":21},{"q":"Le prolongement axillaire du sein porte le nom de :","o":["Queue de Spence","Tubercule de Montgomery","Ligament de Cooper","Aréole"],"r":0,"e":"Le sein s'étend de la 2ᵉ à la 6ᵉ côte et repose sur le muscle grand pectoral.","s":21},{"q":"La glande mammaire comprend :","o":["15 à 20 lobes, chacun avec son canal galactophore","5 lobes, réunis par un seul canal, au centre","50 lobes, sans canal propre, en grappe","Un lobe unique, avec un canal central"],"r":0,"e":"Le tissu adipeux constitue le volume majoritaire du sein, maintenu par les ligaments suspenseurs de Cooper. Les canaux s'ouvrent au mamelon.","s":21},{"q":"La progestérone agit sur la glande mammaire en :","o":["Développant les canaux galactophores","Développant les acini","Produisant le lait","Éjectant le lait"],"r":1,"e":"Les œstrogènes développent les canaux, la prolactine produit le lait et l'ocytocine l'éjecte.","s":21},{"q":"Où s'effectue normalement la fécondation ?","o":["Ovaire","Ampoule de la trompe","Cavité utérine","Isthme"],"r":1,"e":"1/3 externe de la trompe (ampoule), dans les 24h post-ovulation.","s":22},{"q":"Vascularisation principale des ovaires :","o":["L'artère ovarienne seule, issue de l'aorte","L'artère utérine seule","L'artère ovarienne et une branche utérine","L'artère iliaque externe"],"r":2,"e":"Double vascularisation : ovarienne (aorte) + utérine (anastomose sous-ovarique).","s":22},{"q":"La veine ovarienne gauche se jette dans :","o":["VCI","Veine rénale gauche","Veine porte","Iliaque externe"],"r":1,"e":"À gauche : rénale gauche. À droite : VCI directement (asymétrie veineuse).","s":22},{"q":"Follicules primordiaux à la puberté ?","o":["~400","~40 000","~400 000","~4 millions"],"r":2,"e":"Naissance : 1-2M. Puberté : 400 000. Vie reproductive : ~400 ovulations.","s":22},{"q":"Structure qui capte l'ovocyte expulsé :","o":["Pavillon avec ses fimbriae","Isthme","Ligament suspenseur","Portion interstitielle"],"r":0,"e":"Infundibulum + franges (fimbriae). Une frange plus longue (fimbria ovarica) atteint l'ovaire.","s":22},{"q":"Dimensions moyennes d'un ovaire :","o":["1 cm sur 0,5 cm, comme un pois","3 à 4 cm sur 2 cm, sur 1 cm","7 cm sur 5 cm, comme un œuf","12 cm sur 6 cm, comme une poire"],"r":1,"e":"Forme d'amande, 3-4 cm × 2 × 1, poids 6-8 g. Il a la forme d'une amande.","s":22},{"q":"L'ovaire est :","o":["Rétro-péritonéal, accolé à la paroi","Le seul organe totalement intra-péritonéal","Sous-péritonéal, sous le cul-de-sac de Douglas, dans le pelvis","Extra-péritonéal, dans le muscle"],"r":1,"e":"Seul organe totalement intra-péritonéal — pas de couverture péritonéale.","s":22},{"q":"Le ligament suspenseur de l'ovaire contient :","o":["Le ligament rond","Les vaisseaux ovariens","L'uretère","L'utérus"],"r":1,"e":"Le ligament suspenseur (lombo-ovarien) contient l'artère ovarienne et les veines.","s":22},{"q":"Le drainage lymphatique de l'ovaire se fait vers :","o":["Ganglions inguinaux","Ganglions iliaques internes","Ganglions lombo-aortiques","Ganglions sus-claviculaires"],"r":2,"e":"Suit les vaisseaux ovariens jusqu'aux ganglions lombo-aortiques (≠ utérus qui draine en iliaques).","s":22},{"q":"Les 2 stades histologiques du néphron sont :","o":["Cortex et médulla","Cortical et juxtamédullaire","Antérieur et postérieur","Aucun, un seul type de néphron existant"],"r":1,"e":"Néphron cortical (anse courte) et néphron juxtamédullaire (anse longue, concentration). Le juxtamédullaire a une longue anse.","s":22},{"q":"Le corps jaune sécrète principalement :","o":["Œstrogènes","Progestérone","LH","FSH"],"r":1,"e":"Corps jaune = progestérone (phase lutéale, prépare la nidation).","s":22},{"q":"Le follicule de De Graaf est :","o":["Le follicule primordial, au repos","Le follicule mûr, prêt à ovuler","Le corps blanc, cicatrice d'un ancien corps jaune","Le corps jaune, après l'ovulation"],"r":1,"e":"Follicule de De Graaf = follicule mûr, prêt à expulser l'ovocyte (ovulation).","s":22},{"q":"La 1ère portion de la trompe utérine est :","o":["L'ampoule, siège de la fécondation","L'isthme, étroit","L'infundibulum, ou pavillon","La portion interstitielle"],"r":2,"e":"De l'ovaire vers l'utérus : pavillon → ampoule → isthme → interstitielle.","s":22},{"q":"La trompe utérine est suspendue par :","o":["Le ligament suspenseur de l'ovaire, en haut","Le mésosalpinx, bord supérieur du ligament large","Le ligament rond, en avant","Le ligament utéro-sacré"],"r":1,"e":"Mésosalpinx = bord supérieur du ligament large, méso de la trompe.","s":22},{"q":"La GEU (grossesse extra-utérine) se localise le plus souvent :","o":["Dans l'ampoule tubaire","Dans l'ovaire","Dans le péritoine","Dans le col utérin"],"r":0,"e":"Ampoule = site le plus fréquent de la GEU. Risque vital par rupture et hémorragie.","s":22},{"q":"La pénétration de l'ovocyte par le spermatozoïde aboutit à :","o":["Un embryon","Un zygote","Une morula","Un blastocyste"],"r":1,"e":"Fécondation → zygote (1 cellule) → segmentations → morula → blastocyste → nidation.","s":22},{"q":"La capsule fibreuse de l'ovaire s'appelle :","o":["Capsule de Bowman","Albuginée","Capsule de Glisson","Capsule splénique"],"r":1,"e":"Albuginée = capsule conjonctive blanche entourant l'ovaire (et le testicule).","s":22},{"q":"Le cortex ovarien contient :","o":["Les vaisseaux principaux de l'ovaire, au hile","Les follicules ovariens, à différents stades","Les nerfs périphériques, uniquement","Aucune structure fonctionnelle"],"r":1,"e":"Cortex = follicules (primordiaux, primaires, secondaires, tertiaires, De Graaf, corps jaune).","s":22},{"q":"Vestige du corps jaune dégénéré :","o":["Le corps de Howell-Jolly","Le corps blanc, ou albicans","Le corps de Barr","Le corps de Malpighi, du rein"],"r":1,"e":"Corps blanc (corpus albicans) = cicatrice fibreuse après dégénérescence du corps jaune.","s":22},{"q":"La portion interstitielle de la trompe est :","o":["Le pavillon, en dehors","La partie qui traverse la paroi utérine","La portion située entre les deux ovaires","La portion la plus longue"],"r":1,"e":"Interstitielle = traverse la paroi utérine (~1 cm), termine à l'ostium utérin.","s":22},{"q":"Trajet de l'embryon de la fécondation à la nidation :","o":["Quelques heures","3-4 jours","15 jours","1 mois"],"r":1,"e":"Migration tubaire ~3-4 jours. Nidation à J7 environ.","s":22},{"q":"La méiose des spermatocytes I produit :","o":["Deux spermatozoïdes, directement","Des spermatocytes de second ordre","Des spermatides, en une seule étape","Des spermatogonies souches"],"r":1,"e":"Spermatogonie → spermatocyte I → spermatocyte II (méiose) → spermatide → spermatozoïde. Ce sont les spermatocytes II.","s":22},{"q":"La couche basale de l'endomètre :","o":["Permet la régénération","Se desquame chaque mois","Contient le myomètre","Est exclusivement fibreuse"],"r":0,"e":"Basale = profonde, permet la régénération après les menstruations.","s":22},{"q":"La pression dans le système porte est :","o":["Plus de 30 mmHg","Environ 10 mmHg, basse","120/80 mmHg, comme l'aorte","0 mmHg, nulle en position debout"],"r":1,"e":"Système à basse pression, sans valves. Hypertension portale > 12 mmHg.","s":22},{"q":"Capacité d'absorption de l'intestin grêle est augmentée par :","o":["Les valvules conniventes seules, sans les villosités","Les villosités seules, sans microvillosités","Les valvules, les villosités et les microvillosités","Une surface lisse, sans relief"],"r":2,"e":"3 niveaux d'amplification = 250 m². Note : cette question concerne d'autres systèmes (validation transversale). La surface est multipliée par 600.","s":22},{"q":"L'ostium tubo-péritonéal est ouvert dans :","o":["Dans l'utérus, par l'isthme","Dans la cavité péritonéale, par le pavillon","Dans le vagin, par le col","Dans l'urètre, par une communication anormale congénitale"],"r":1,"e":"Pavillon = ouverture dans la cavité péritonéale. Voie de communication vers l'extérieur chez la femme.","s":22},{"q":"Le pôle vasculaire du corpuscule de Malpighi reçoit :","o":["L'artériole afférente, seulement, à l'entrée","L'afférente qui entre, l'efférente qui sort","Les vasa recta, médullaires","Aucun vaisseau, seulement l'urine"],"r":1,"e":"Note : question pertinente pour le rein. Le pôle urinaire mène au tubule proximal.","s":22},{"q":"La couche cuboïde des cellules folliculaires apparaît dans :","o":["Follicule primordial","Follicule primaire","Follicule secondaire","Corps jaune"],"r":1,"e":"Primordial : aplaties. Primaire : cuboïdes (1 couche). Secondaire : multiples couches.","s":22},{"q":"La zone pellucide apparaît dans :","o":["Follicule primordial","Follicule primaire","Follicule secondaire","Corps blanc"],"r":2,"e":"Apparaît au stade follicule secondaire — glycoprotéique autour de l'ovocyte.","s":22},{"q":"Le transport de l'ovocyte dans la trompe est assuré par :","o":["La pression sanguine locale","Les cils, le péristaltisme et le flux tubaire","La gravité, en position debout","La contraction utérine, qui aspire l'ovocyte vers la cavité"],"r":1,"e":"Mouvements ciliaires + péristaltisme musculaire + flux du liquide tubaire.","s":22},{"q":"L'ovaire pèse :","o":["2 à 3 g","6 à 8 g","15 g","30 g"],"r":1,"e":"En forme d'amande, il mesure 3-4 cm × 2 cm × 1 cm, de couleur blanchâtre et à surface irrégulière après la puberté.","s":22},{"q":"La fosse ovarienne est délimitée :","o":["Les vaisseaux iliaques et l'uretère","L'aorte et la veine cave, en haut","La vessie et le rectum, au centre","Le ligament rond, en avant"],"r":0,"e":"Elle siège sur la paroi latérale pelvienne. L'iliaque externe est en avant, l'uretère et l'iliaque interne en arrière.","s":22},{"q":"L'ovaire présente la particularité d'être :","o":["Le seul organe totalement intra-péritonéal","Rétro-péritonéal, accolé à la paroi pelvienne","Sous-péritonéal, dans le pelvis","Extra-péritonéal, dans le muscle"],"r":0,"e":"Il possède deux faces, deux bords — antérieur mésovarique et postérieur libre — et deux extrémités, tubaire et utérine.","s":22},{"q":"Le ligament propre de l'ovaire :","o":["Va du pôle utérin de l'ovaire à la corne utérine","Va du pôle tubaire à la paroi lombaire, en haut","Relie le pavillon à l'ovaire","Relie l'ovaire au ligament large"],"r":0,"e":"Le ligament suspenseur va du pôle tubaire à la paroi lombaire et contient les vaisseaux ovariens. Il contient des fibres musculaires lisses.","s":22},{"q":"Le ligament tubo-ovarien relie :","o":["Le pavillon de la trompe au pôle tubaire de l'ovaire","L'ovaire à l'utérus, par la corne utérine et l'isthme","L'ovaire au ligament large","La trompe à la paroi pelvienne"],"r":0,"e":"Le mésovarium relie, lui, l'ovaire au ligament large et contient les vaisseaux entrant par le hile.","s":22},{"q":"L'artère ovarienne naît de l'aorte abdominale à hauteur de :","o":["L1","L2","L3","T12"],"r":1,"e":"Elle chemine dans le ligament suspenseur et s'anastomose avec l'artère utérine par l'arcade sous-ovarique.","s":22},{"q":"Le drainage veineux de l'ovaire passe par :","o":["Le plexus pampiniforme puis la veine ovarienne","La veine utérine, directement","La veine iliaque interne, par le ligament large et le paracervix","Le plexus hypogastrique, veineux"],"r":0,"e":"À droite la veine ovarienne rejoint la VCI, à gauche la veine rénale gauche.","s":22},{"q":"La structure histologique de l'ovaire comprend, de la surface vers la profondeur :","o":["L'épithélium, l'albuginée, le cortex et la médulla","La séreuse, la musculeuse et la muqueuse","Le cortex, l'épithélium et la médulla","L'albuginée, la médulla, puis le cortex en profondeur"],"r":0,"e":"Le cortex contient les follicules à différents stades, la médulla du tissu conjonctif lâche, des vaisseaux et des nerfs. L'épithélium de surface est cubique simple.","s":22},{"q":"Le follicule primaire se distingue du follicule primordial par :","o":["Des cellules folliculaires cubiques, non plus aplaties","L'apparition de la zone pellucide","L'apparition de l'antrum, cavité remplie de liquide folliculaire","Sa maturité, prête à ovuler"],"r":0,"e":"Le follicule secondaire ajoute plusieurs couches de cellules et la zone pellucide, le tertiaire l'antrum.","s":22},{"q":"Le corps blanc, ou albicans, correspond :","o":["Au vestige fibreux du corps jaune dégénéré","Au follicule mûr, prêt à ovuler","À la zone pellucide, autour de l'ovocyte","À l'albuginée, la capsule fibreuse qui entoure l'ovaire"],"r":0,"e":"Le corps jaune, formé après l'ovulation, sécrète la progestérone.","s":22},{"q":"La réserve ovarienne à la naissance est d'environ :","o":["400 follicules environ","400 000 follicules environ","1 à 2 millions de follicules","10 millions de follicules, au moins"],"r":2,"e":"Elle tombe à environ 400 000 à la puberté, et seuls environ 400 follicules ovuleront durant la vie reproductive.","s":22},{"q":"Les trompes utérines mesurent :","o":["5 à 7 cm","10 à 14 cm","20 cm","3 cm"],"r":1,"e":"Elles cheminent dans le bord supérieur du ligament large, le mésosalpinx.","s":22},{"q":"La fimbria ovarica est :","o":["La plus longue frange du pavillon","L'ostium utérin de la trompe","La portion interstitielle","L'antrum du follicule mûr, juste avant l'ovulation"],"r":0,"e":"L'infundibulum, en entonnoir, est ouvert dans la cavité péritonéale et assure la captation de l'ovocyte. Elle atteint l'ovaire.","s":22},{"q":"L'ampoule tubaire mesure environ :","o":["1 cm","3 cm","7 cm","12 cm"],"r":2,"e":"C'est la portion la plus longue et la plus large, lieu habituel de la fécondation ; l'isthme mesure environ 3 cm.","s":22},{"q":"La portion interstitielle de la trompe :","o":["Traverse la paroi utérine sur 1 cm, jusqu'à l'ostium","Est la plus large des quatre","Est ouverte dans le péritoine, par un pavillon frangé, en dehors","Mesure 7 cm de long, au moins"],"r":0,"e":"C'est la portion la plus proximale des quatre. Elle se termine par l'ostium utérin.","s":22},{"q":"La muqueuse tubaire comporte :","o":["Un épithélium prismatique, cilié et sécrétoire","Un épithélium pavimenteux, stratifié","Des villosités intestinales et des glandes de Lieberkühn","Des glandes de Bartholin"],"r":0,"e":"La musculeuse comprend deux couches, circulaire interne et longitudinale externe, et la séreuse est péritonéale.","s":22},{"q":"La grossesse extra-utérine se localise le plus fréquemment :","o":["Dans l'ampoule tubaire","Dans l'isthme","Dans l'ovaire","Dans la cavité abdominale"],"r":0,"e":"Elle comporte un risque vital par rupture et hémorragie.","s":22},{"q":"L'innervation de l'ovaire est assurée par :","o":["Le plexus ovarien, issu du plexus aortique","Le plexus hypogastrique inférieur, pelvien","Le nerf pudendal, de S2 à S4","Les nerfs splanchniques pelviens"],"r":0,"e":"Elle est neuro-végétative, de nature sympathique.","s":22},{"q":"L'ovaire est décrit comme une glande :","o":["Exclusivement exocrine, par l'ovocyte","Exclusivement endocrine, par les hormones sexuelles","Mixte, exocrine par l'ovocyte et endocrine","Ni exocrine ni endocrine"],"r":2,"e":"Cette double nature explique qu'il produise à la fois les gamètes et les hormones sexuelles.","s":22},{"q":"L'arcade vasculaire sous-ovarique correspond :","o":["À l'anastomose entre l'artère ovarienne et l'utérine","À la veine ovarienne, à droite","Au plexus pampiniforme, veineux, dans le ligament suspenseur","Au mésovarium, au hile de l'ovaire"],"r":0,"e":"L'artère utérine, branche de l'iliaque interne, donne une branche ovarienne via le ligament propre.","s":22},{"q":"Position habituelle de l'utérus :","o":["Antéversé et antéfléchi","Rétroversé, en arrière","Vertical, dans l'axe","Latérodévié, à gauche"],"r":0,"e":"80% des cas : AVAF. Col vers l'arrière, corps vers l'avant. C'est la position AVAF, dans 80 % des cas.","s":23},{"q":"Poids moyen de l'utérus nullipare :","o":["15 g","50 g","150 g","300 g"],"r":1,"e":"Nullipare : 50 g. Multipare : 70 g.","s":23},{"q":"Les 3 parties de l'utérus :","o":["Tête, corps, queue","Fundus, corps, col","Apex, médian, isthme","Cardia, antre, pylore"],"r":1,"e":"Fundus (en haut), corps (milieu), col / cervix (bas).","s":23},{"q":"La cavité utérine est :","o":["Cylindrique, comme le canal cervical qui la prolonge","Triangulaire et aplatie d'avant en arrière","Sphérique, en boule, régulière","Étoilée, à cinq branches"],"r":1,"e":"Cavité corporéale triangulaire. Aux angles s'ouvrent les ostiums tubaires.","s":23},{"q":"Vascularisation principale de l'utérus :","o":["L'artère iliaque externe","L'artère utérine, issue de l'iliaque interne","L'artère ovarienne, à elle seule","L'artère mésentérique inférieure, en arrière"],"r":1,"e":"Artère utérine, branche de l'iliaque interne. Passe au-dessus de l'uretère (« l'eau sous le pont »). Elle passe au-dessus de l'uretère.","s":23},{"q":"L'uretère pelvien passe :","o":["Au-dessus de l'artère utérine","En dessous de l'artère utérine","Devant l'utérus","Derrière le vagin"],"r":1,"e":"« L'eau (uretère) sous le pont (artère) » — risque chirurgical d'hystérectomie.","s":23},{"q":"Les 3 phases du cycle utérin :","o":["Menstruelle, proliférative, sécrétoire","Folliculaire, lutéale, menstruelle","Œstrogénique, progestative, ovulatoire","Pré-ovulatoire, ovulatoire, post-ovulatoire"],"r":0,"e":"J1-5 menstruelle. J5-14 proliférative. J15-28 sécrétoire.","s":23},{"q":"La phase proliférative de l'endomètre est sous l'influence de :","o":["Œstrogènes","Progestérone","FSH","hCG"],"r":0,"e":"Œstrogènes (sécrétés par le follicule en croissance) → prolifération endométriale.","s":23},{"q":"La phase sécrétoire est sous l'influence de :","o":["Œstrogènes seuls","Progestérone","LH","Prolactine"],"r":1,"e":"Phase lutéale : corps jaune → progestérone → endomètre sécrétoire (prêt pour la nidation).","s":23},{"q":"Drainage lymphatique du fundus utérin :","o":["Iliaque externe","Lombo-aortique","Inguinal superficiel","Sus-claviculaire"],"r":1,"e":"Fundus + corps → lombo-aortiques (via le ligament suspenseur de l'ovaire).","s":23},{"q":"Le col utérin se draine vers :","o":["Les ganglions lombo-aortiques, comme l'ovaire","Les ganglions iliaques externes et internes","Les ganglions inguinaux profonds, uniquement","Les ganglions mésentériques"],"r":1,"e":"Col : iliaques externes et internes. Important en cancérologie du col.","s":23},{"q":"Le ligament rond de l'utérus :","o":["Soutient l'utérus en arrière, jusqu'au sacrum","Maintient l'antéversion, par le canal inguinal","Relie l'ovaire à l'utérus, en dedans","Soutient le rectum, en arrière"],"r":1,"e":"Corne utérine → canal inguinal → grande lèvre. Maintient l'antéversion. Il se termine dans la grande lèvre.","s":23},{"q":"Le ligament utéro-sacré maintient :","o":["L'antéversion","L'antéflexion","La latéralité","L'inversion"],"r":1,"e":"Ligaments utéro-sacrés (col → sacrum) : maintiennent l'antéflexion.","s":23},{"q":"La cavité utérine communique avec le canal cervical par :","o":["L'ostium externe, vers le vagin, en bas","L'ostium interne, au niveau de l'isthme","L'ostium tubaire, aux cornes","L'ostium vésical, vers la vessie"],"r":1,"e":"Ostium interne sépare cavité utérine et canal cervical. Ostium externe entre canal cervical et vagin.","s":23},{"q":"L'utérus en avant est en rapport avec :","o":["Rectum","Vessie","Ovaires","Foie"],"r":1,"e":"Vessie en avant (cul-de-sac vésico-utérin). Rectum en arrière (cul-de-sac de Douglas).","s":23},{"q":"Le myomètre comporte :","o":["Une seule couche, épaisse","Deux couches, circulaire et longitudinale, comme l'intestin","Trois plans, dont un plexiforme moyen","Quatre couches, dont deux obliques"],"r":2,"e":"3 plans musculaires. Le plan plexiforme moyen est le plus épais (« tunique vasculaire »). Les deux autres sont longitudinaux, externe et interne.","s":23},{"q":"Le périmètre utérin couvre :","o":["Tout l'utérus, col compris, en entier","Le fundus et le corps, sans le col","Le col, uniquement","Aucune partie de l'utérus"],"r":1,"e":"Péritoine viscéral sur fundus + corps. Pas de séreuse au niveau du col (sous-péritonéal).","s":23},{"q":"La partie intra-vaginale du col s'appelle :","o":["L'apex du col, en bas","Le museau de tanche","Le pavillon, comme pour la trompe","Le fundus du col"],"r":1,"e":"Museau de tanche = portion intra-vaginale du col, fait saillie dans le vagin.","s":23},{"q":"Le frottis cervico-utérin (FCU) explore :","o":["L'endomètre, par une biopsie du fond utérin","Le col utérin, à la jonction exo-endocol","Les ovaires, par échographie","Le vagin, sur sa paroi"],"r":1,"e":"Dépistage du cancer du col par prélèvement cellulaire à la jonction exo-endocol.","s":23},{"q":"La nidation a lieu vers :","o":["À J2-J3, dès les premières divisions de l'œuf","Vers J7, une semaine après la fécondation","À J14, au milieu du cycle","À J28, à la fin du cycle"],"r":1,"e":"J7 environ — le blastocyste s'implante dans l'endomètre en phase sécrétoire.","s":23},{"q":"L'hormone qui maintient le corps jaune en cas de grossesse :","o":["La LH, hormone lutéinisante hypophysaire","La FSH, de l'hypophyse","L'hCG, gonadotrophine chorionique","La TSH, thyroïdienne"],"r":2,"e":"hCG produite par le trophoblaste (embryon). Base des tests de grossesse.","s":23},{"q":"Le cul-de-sac vésico-utérin est :","o":["Antérieur, entre vessie et utérus","Postérieur, entre rectum et utérus","Latéral, contre le ligament large","Supérieur, au-dessus du fundus utérin"],"r":0,"e":"Vésico-utérin = antérieur. Recto-utérin (Douglas) = postérieur.","s":23},{"q":"Le ligament cardinal de Mackenrodt :","o":["Il soutient l'ovaire, en haut","Il stabilise le col, avec les vaisseaux utérins","Il relie l'utérus au foie, en passant par le ligament rond","Il soutient les trompes, en dehors"],"r":1,"e":"Paracervix = base des ligaments larges, contient les vaisseaux utérins. Stabilisation latérale du col.","s":23},{"q":"Le diaphragme pelvien comprend :","o":["Le sphincter externe de l'anus, à lui seul, en surface","L'élévateur de l'anus et le muscle coccygien","Le transverse profond du périnée","Le grand fessier, en arrière"],"r":1,"e":"Diaphragme pelvien profond : levator ani + coccygien. Soutien principal des organes.","s":23},{"q":"Le prolapsus utérin est dû à :","o":["Une hypertension artérielle, avec œdème","Une défaillance du plancher pelvien","Un excès de progestérone","Une hyperthyroïdie, mal traitée"],"r":1,"e":"Descente utérine par déficit musculaire (accouchements, ménopause, toux chronique).","s":23},{"q":"Le pic ovulatoire est marqué par :","o":["Pic de progestérone","Pic de LH","Pic de FSH","Pic d'œstrogènes"],"r":1,"e":"Pic de LH à J14 → rupture folliculaire → ovulation.","s":23},{"q":"L'innervation autonome de l'utérus provient de :","o":["Le plexus cœliaque, par le nerf vague","Le plexus hypogastrique inférieur","Le plexus brachial, au cou","Le nerf phrénique, de C3 à C5"],"r":1,"e":"Plexus hypogastrique inférieur (sympa T10-L1 + para S2-S4).","s":23},{"q":"Glande qui sécrète le mucus cervical :","o":["Glandes de Skene","Glandes de Bartholin","Glandes endocervicales","Glandes lacrymales"],"r":2,"e":"Glandes endocervicales du canal cervical sécrètent le mucus, dont la viscosité varie au cours du cycle.","s":23},{"q":"La fonctionnalité du myomètre nécessite :","o":["Une hypocalcémie, prolongée","L'ocytocine et les œstrogènes","La FSH, hypophysaire","Le cortisol, surrénalien"],"r":1,"e":"Ocytocine déclenche les contractions. Œstrogènes augmentent la sensibilité du myomètre à l'ocytocine.","s":23},{"q":"Le ligament large est :","o":["Un cordon fibreux unique, épais et résistant, en arrière","Un double feuillet péritonéal, latéral à l'utérus","Un muscle lisse, contractile","Une artère, issue de l'iliaque"],"r":1,"e":"Méso-utérin (ligament large) : 2 feuillets péritonéaux. Contient trompes, ligaments propres, vaisseaux.","s":23},{"q":"Les dimensions de l'utérus chez la multipare sont :","o":["6-7 cm de long et 50 g","7-8 cm de long et 70 g","4 cm de large","10 cm de long"],"r":1,"e":"Chez la nullipare, il mesure 6-7 cm pour 50 g, avec un fundus large de 4 cm.","s":23},{"q":"L'isthme utérin correspond :","o":["Au rétrécissement entre corps et col","À la partie supérieure arrondie","À la portion intra-vaginale du col","À la cavité corporéale, triangulaire et aplatie"],"r":0,"e":"Le fundus est la partie supérieure arrondie, au-dessus de la ligne des cornes. Il devient le segment inférieur en fin de grossesse.","s":23},{"q":"Le col utérin mesure environ :","o":["1 cm","3 cm","6 cm","8 cm"],"r":1,"e":"Cylindrique, il est divisé par l'insertion vaginale en portions supra-vaginale et intra-vaginale, cette dernière étant le museau de tanche.","s":23},{"q":"L'ostium externe du col est :","o":["Punctiforme puis transversal, selon la parité","Toujours transversal, à tout âge","Toujours punctiforme, à tout âge","Absent chez la femme ayant accouché par césarienne"],"r":0,"e":"L'ostium interne sépare, lui, la cavité utérine du canal cervical. Il est punctiforme chez la nullipare, transversal chez la multipare.","s":23},{"q":"La cavité corporéale de l'utérus est :","o":["Triangulaire et aplatie d'avant en arrière","Cylindrique, comme le col","Sphérique, en boule régulière","Fusiforme, comme le canal cervical, vers le bas"],"r":0,"e":"Le canal cervical, fusiforme, s'ouvre dans le vagin par l'ostium externe. Les ostiums des trompes sont à ses angles supérieurs.","s":23},{"q":"L'antéversion correspond à un angle :","o":["Entre le col et le vagin, d'environ 90°, ouvert en avant","Entre le corps et le col, d'environ 120°, en avant","De 120°, entre l'utérus et la vessie","Ouvert en arrière, de 45° environ"],"r":0,"e":"L'antéflexion correspond, elle, à un angle d'environ 120° entre l'axe du corps et celui du col. Ce sont les axes du col et du vagin.","s":23},{"q":"La rétroversion utérine concerne environ :","o":["5 % des femmes, toujours pathologique","20 % des femmes, sans caractère pathologique","50 % des femmes, en âge de procréer","80 % des femmes, ce qui en fait la norme"],"r":1,"e":"La position antéversée antéfléchie concerne 80 % des femmes.","s":23},{"q":"Le cul-de-sac de Douglas est :","o":["Le point le plus déclive du péritoine chez la femme","Situé entre la vessie et l'utérus","Un ligament épais, qui fixe l'utérus au sacrum en arrière","Un repli du vagin, en arrière"],"r":0,"e":"Il sépare l'utérus du rectum ; le cul-de-sac vésico-utérin le sépare, lui, de la vessie.","s":23},{"q":"La formule « l'eau sous le pont » rappelle que :","o":["L'uretère passe sous l'artère utérine","L'artère utérine passe sous l'uretère","La veine passe sous l'artère","L'uretère croise le ligament rond"],"r":0,"e":"Ce rapport est essentiel en chirurgie gynécologique, du fait du risque de plaie urétérale.","s":23},{"q":"Les ligaments ronds vont :","o":["De la corne utérine au mont du pubis, par le canal inguinal","Du col au sacrum, en arrière","De l'utérus aux parois latérales du pelvis, en éventail, en dehors","De l'ovaire à l'utérus, en dedans"],"r":0,"e":"Ils maintiennent l'antéversion ; les ligaments utéro-sacrés maintiennent l'antéflexion.","s":23},{"q":"Les ligaments larges sont :","o":["Des doubles feuillets du péritoine, de l'utérus à la paroi","Des faisceaux musculaires lisses","Des cordons fibreux, épais et ronds","Des ligaments vertébraux, qui relient l'utérus au rachis lombaire"],"r":0,"e":"Ils contiennent la trompe, les ligaments, les vaisseaux et les nerfs.","s":23},{"q":"Le soutien principal de l'utérus est assuré par :","o":["Le diaphragme pelvien, par les élévateurs de l'anus","Les ligaments ronds, par le canal inguinal","Les ligaments utéro-sacrés, tendus jusqu'au sacrum","Le ligament large, sur les côtés"],"r":0,"e":"Le plancher périnéal le complète ; les ligaments assurent, eux, la suspension et l'orientation.","s":23},{"q":"Les ligaments cardinaux de Mackenrodt :","o":["Forment le paracervix et contiennent les vaisseaux utérins","Vont du col jusqu'au sacrum, en contournant le rectum","Vont de la corne utérine au pubis, par l'aine","Sont des muscles lisses, contractiles"],"r":0,"e":"Ils appartiennent au système d'orientation de l'utérus. Ils sont à la base des ligaments larges.","s":23},{"q":"Le prolapsus utérin est favorisé par :","o":["Les accouchements, la ménopause et la toux chronique","La nulliparité, avec un périnée jamais distendu par l'enfant","L'âge jeune, avant 30 ans","L'activité physique, modérée"],"r":0,"e":"Son traitement associe rééducation périnéale, pessaire et chirurgie.","s":23},{"q":"L'artère utérine est une branche :","o":["De l'iliaque interne","De l'iliaque externe","De l'aorte","De l'artère ovarienne"],"r":0,"e":"Elle s'anastomose avec les artères ovarienne et vaginale.","s":23},{"q":"Le drainage veineux de l'utérus suit la voie :","o":["Plexus utérin, veines utérines, puis veine iliaque interne","La veine ovarienne, puis la veine rénale gauche","La veine cave inférieure, directement, sans aucun relais","La veine rénale, par le plexus pampiniforme"],"r":0,"e":"Le drainage lymphatique varie selon le segment : lombo-aortique pour le fundus et le corps, iliaque pour le col.","s":23},{"q":"Le ligament rond de l'utérus se draine vers :","o":["Les ganglions inguinaux superficiels","Les ganglions lombo-aortiques","Les ganglions iliaques internes","Les ganglions sacrés"],"r":0,"e":"Ce drainage particulier explique certaines localisations ganglionnaires inattendues en pathologie utérine.","s":23},{"q":"L'innervation autonome de l'utérus provient :","o":["Du plexus hypogastrique inférieur, mixte","Du plexus aortique, comme pour l'ovaire","Du nerf pudendal, de S2 à S4","Du nerf vague, ou X, au thorax"],"r":0,"e":"Le plexus ovarien, issu du plexus aortique, innerve l'ovaire. Le sympathique vient de T10-L1, le parasympathique de S2-S4.","s":23},{"q":"Parmi les fonctions de l'utérus, le cours cite :","o":["La nidation, la gestation et l'accouchement","La seule gestation, jusqu'au terme","La seule menstruation, chaque mois","La production d'ovocytes et d'hormones, comme l'ovaire"],"r":0,"e":"L'accouchement repose sur les contractions du myomètre. La réception de l'œuf et la menstruation en font aussi partie.","s":23},{"q":"L'utérus se situe :","o":["Entre vessie et rectum, au-dessus du vagin","Derrière le rectum, contre le sacrum, en bas","Devant la vessie, contre le pubis","Au-dessus de la vessie, uniquement"],"r":0,"e":"Latéralement, il répond aux ligaments larges, à l'uretère et aux vaisseaux utérins. Il est sous les anses intestinales.","s":23},{"q":"Longueur du vagin :","o":["3-5 cm","7-10 cm","15 cm","20 cm"],"r":1,"e":"7-10 cm. Direction oblique en haut et arrière.","s":24},{"q":"Le fornix vaginal le plus profond est :","o":["Antérieur","Postérieur","Latéral droit","Latéral gauche"],"r":1,"e":"Fornix postérieur = le plus profond, point de ponction du Douglas.","s":24},{"q":"La flore vaginale normale est dominée par :","o":["Des streptocoques, surtout ceux du groupe B","Des lactobacilles, ou bacilles de Döderlein","Des colibacilles, ou E. coli","Des levures, du genre Candida"],"r":1,"e":"Lactobacilles → acide lactique → pH 3,8-4,5 = barrière contre infections.","s":24},{"q":"L'épithélium vaginal est :","o":["Cylindrique simple, mucipare","Pavimenteux stratifié non kératinisé","Cubique simple, comme dans le rein","Cilié, comme la trompe"],"r":1,"e":"Pavimenteux stratifié non kératinisé, riche en glycogène (œstrogènes).","s":24},{"q":"Les glandes de Bartholin sont équivalentes à :","o":["Aux glandes bulbo-urétrales de Cowper","À la prostate, autour de l'urètre","Aux vésicules séminales, en arrière","À l'épididyme, testiculaire"],"r":0,"e":"Bartholin = Cowper (lubrification). Skene = prostate.","s":24},{"q":"Les bulbes vestibulaires sont équivalents à :","o":["Corps caverneux","Corps spongieux","Testicules","Prostate"],"r":1,"e":"Bulbes vestibulaires = équivalent féminin du corps spongieux du pénis (érectile).","s":24},{"q":"Le clitoris est composé de :","o":["Un corps caverneux et un corps spongieux, avec un gland","Deux racines, deux corps caverneux et un gland","Trois corps caverneux, sans gland","Du muscle lisse uniquement"],"r":1,"e":"2 racines + 2 corps caverneux + 1 gland recouvert par le prépuce.","s":24},{"q":"L'innervation sensitive du clitoris vient du :","o":["Le nerf obturateur, par sa branche cutanée médiale","Le nerf dorsal du clitoris, issu du pudendal","Le nerf phrénique, de C3 à C5","Le nerf cubital, au bras"],"r":1,"e":"Nerf dorsal du clitoris, branche terminale du pudendal (S2-S4).","s":24},{"q":"Le périnée féminin se divise en :","o":["Un triangle uro-génital en avant et un anal en arrière","Quatre quadrants égaux, autour du centre tendineux","Trois niveaux superposés, de la peau au diaphragme","Deux hémisphères, droit et gauche, symétriques"],"r":0,"e":"Ligne bi-ischiatique sépare le périnée en 2 triangles.","s":24},{"q":"Le centre tendineux du périnée :","o":["Entre vessie et utérus","Entre vagin et anus","Au-dessus du pubis","Derrière le sacrum"],"r":1,"e":"Noyau fibreux entre vagin et anus. Risque déchirure obstétricale.","s":24},{"q":"Plan profond du périnée :","o":["Le bulbo-spongieux, en surface","Le transverse superficiel","L'élévateur de l'anus et le coccygien","L'ischio-caverneux et le bulbo-spongieux, en surface"],"r":2,"e":"Diaphragme pelvien profond : levator ani + coccygien.","s":24},{"q":"Plan moyen du périnée (diaphragme uro-génital) :","o":["L'élévateur de l'anus, profond","Le transverse profond et le sphincter strié de l'urètre","Le bulbo-spongieux uniquement, en surface, autour du vestibule","Le muscle coccygien, en arrière"],"r":1,"e":"Transverse profond + sphincter urétral externe (strié, volontaire).","s":24},{"q":"Innervation du sphincter strié externe :","o":["Le sympathique, de T10 à L1","Le parasympathique, de S2 à S4","Le nerf pudendal, de S2 à S4","Le nerf obturateur, de L2 à L4"],"r":2,"e":"Sphincter strié → contrôle volontaire → nerf pudendal.","s":24},{"q":"Les 3 lèvres de la vulve sont :","o":["Trois paires distinctes, en éventail","Deux paires, les grandes et les petites","Trois niveaux superposés, du mont du pubis au vestibule","Une seule paire, médiane"],"r":1,"e":"Grandes lèvres (avec poils) + petites lèvres (sans poils, dans le vestibule).","s":24},{"q":"Devant les petites lèvres, en avant :","o":["Elles forment le frein, seulement","Elles forment le prépuce et le frein du clitoris","Elles forment l'hymen, à l'entrée du vagin, chez la jeune fille","Elles forment le centre tendineux"],"r":1,"e":"Les petites lèvres se divisent en avant : lamelle sup → prépuce, lamelle inf → frein du clitoris.","s":24},{"q":"Le 1/3 inférieur du vagin reçoit la sensibilité :","o":["Très réduite","Riche par le nerf pudendal","Plexus cœliaque","Nerf splanchnique pelvien"],"r":1,"e":"Tiers inférieur : nerf pudendal, très sensible. Tiers supérieur : autonome, peu sensible.","s":24},{"q":"Le mont du pubis (Vénus) est :","o":["Une protubérance osseuse, sur la symphyse","Une saillie graisseuse au-dessus du pubis","Une glande sébacée, volumineuse","Un ligament, tendu au pubis"],"r":1,"e":"Saillie cutanée graisseuse au-dessus de la symphyse pubienne, pileuse après la puberté. Elle devient pileuse après la puberté.","s":24},{"q":"Le drainage lymphatique du périnée superficiel se fait vers :","o":["Les ganglions iliaques internes, profonds","Les ganglions inguinaux superficiels","Les ganglions lombo-aortiques","Les ganglions mésentériques"],"r":1,"e":"Périnée superficiel + organes génitaux externes → inguinaux superficiels.","s":24},{"q":"La paroi vaginale comprend :","o":["Muqueuse + musculeuse + adventice","4 tuniques comme l'intestin","Cortex + médulla","2 plans uniquement"],"r":0,"e":"Muqueuse (pavimenteuse stratifiée) + muscle lisse + adventice. Pas de glandes propres.","s":24},{"q":"La lubrification vaginale provient principalement de :","o":["Des glandes vaginales propres, nombreuses et actives","Les sécrétions du col et une transsudation","Des glandes salivaires, à distance","Des glandes lacrymales, à distance"],"r":1,"e":"Pas de glandes vaginales propres. Mucus cervical + transsudation transmurale.","s":24},{"q":"L'épisiotomie classique est :","o":["Verticale et médiane, vers l'anus","Latérale, sur le périnée","Transverse, d'un ischion à l'autre","Au niveau du clitoris, en avant, vers le pubis"],"r":1,"e":"Incision latérale pendant l'accouchement, pour éviter une déchirure périnéale médiane.","s":24},{"q":"L'ischio-caverneux recouvre :","o":["Le mont du pubis, en avant","Les racines du clitoris","Le vagin, en arrière","L'anus, en arrière"],"r":1,"e":"Ischio-caverneux recouvre les racines clitoridiennes (équivalent du pénis).","s":24},{"q":"Le bulbo-spongieux recouvre :","o":["Les racines du clitoris","Les bulbes vestibulaires","Le centre tendineux","Le sphincter anal"],"r":1,"e":"Recouvre les bulbes vestibulaires. Aide à la fermeture de la vulve.","s":24},{"q":"Le pH vaginal augmente (devient + alcalin) :","o":["Pendant l'ovulation","À la ménopause","Pendant la grossesse","Jamais"],"r":1,"e":"Ménopause = ↓ œstrogènes → ↓ glycogène → ↓ lactobacilles → pH plus alcalin → vulnérabilité aux infections.","s":24},{"q":"Le méat urétral chez la femme s'ouvre :","o":["Sur le clitoris, au sommet","Dans le vestibule, en avant de l'orifice vaginal","Dans le vagin, sur sa paroi antérieure, à 2 cm de l'entrée","Sur le mont du pubis, en avant"],"r":1,"e":"Vestibule : méat urétral en avant + orifice vaginal en arrière (+ glandes Bartholin/Skene).","s":24},{"q":"La fosse naviculaire :","o":["N'existe pas chez la femme","Concerne l'urètre masculin","Est dans le vagin","Est sur l'utérus"],"r":1,"e":"Fosse naviculaire = dilatation terminale de l'urètre pénien (masculin).","s":24},{"q":"La commissure postérieure de la vulve correspond à :","o":["Une zone au-dessus du pubis","L'union des grandes lèvres, en arrière","Une zone au-dessus du clitoris, en avant","Le centre du vagin, au fond"],"r":1,"e":"Commissures antérieure et postérieure des grandes lèvres. Elle est juste devant l'anus.","s":24},{"q":"La transsudation vaginale est augmentée par :","o":["Le stress, par l'activation du système sympathique","L'excitation sexuelle, par le parasympathique","Une inhibition parasympathique","Une hypoglycémie, à jeun"],"r":1,"e":"Parasympathique → vasodilatation → transsudation augmentée à travers la paroi vaginale.","s":24},{"q":"Devant la vessie, séparée par une cloison :","o":["Le vagin et le col, en arrière","Le rectum et le Douglas, en arrière","La symphyse pubienne, par l'espace de Retzius","Le sacrum, en arrière, par une cloison fibreuse épaisse"],"r":2,"e":"Espace de Retzius (rétro-pubien, pré-vésical) entre symphyse pubienne et vessie.","s":24},{"q":"Réduction œstrogénique post-ménopause provoque :","o":["Hypertrophie endométriale","Atrophie de la muqueuse vaginale","Augmentation du glycogène","Hypertrophie clitoridienne"],"r":1,"e":"↓ œstrogènes → atrophie muqueuse, sécheresse vaginale, dyspareunie.","s":24},{"q":"Le vagin est orienté :","o":["En haut et en arrière, à environ 70° de l'horizontale","Verticalement, à 90° de l'horizontale, en position debout","Horizontalement, à 0°, dans l'axe du sacrum","En bas et en avant, vers le pubis"],"r":0,"e":"Il est aplati d'avant en arrière, sa paroi antérieure étant plus courte que la postérieure.","s":24},{"q":"Le fornix postérieur du vagin est :","o":["Le plus profond, point de ponction du Douglas","Le moins profond des fornix","Latéral, au contact de l'uretère et de l'artère utérine","Absent chez la nullipare"],"r":0,"e":"L'extrémité supérieure du vagin entoure le col utérin en formant les fornix antérieur, postérieur et latéraux.","s":24},{"q":"En avant, la partie inférieure du vagin répond :","o":["À la vessie et au trigone","À l'urètre, par la cloison uréthro-vaginale","Au cul-de-sac de Douglas","Au rectum et au canal anal, par la cloison recto-vaginale"],"r":1,"e":"Sa partie supérieure répond à la vessie et au trigone vésical.","s":24},{"q":"En arrière, la partie supérieure du vagin répond :","o":["Au cul-de-sac de Douglas","Au rectum","Au centre tendineux du périnée","À l'urètre"],"r":0,"e":"Sa partie moyenne répond au rectum par la cloison recto-vaginale et sa partie inférieure au centre tendineux du périnée.","s":24},{"q":"Le paracolpium désigne :","o":["Le tissu conjonctif lâche latéral au vagin","Un ligament fibreux, tendu du vagin au sacrum","Un muscle lisse, péri-vaginal","Une couche de la paroi vaginale"],"r":0,"e":"L'uretère passe à proximité du fornix latéral, ce qui en fait un rapport chirurgical important. L'uretère passe à proximité du fornix latéral.","s":24},{"q":"L'artère vaginale est une branche :","o":["De l'iliaque interne","De l'iliaque externe","De l'artère utérine","De l'aorte"],"r":0,"e":"Les branches cervico-vaginales de l'artère utérine et l'artère pudendale interne complètent la vascularisation.","s":24},{"q":"La partie supérieure du vagin se draine vers :","o":["Les ganglions iliaques externes et internes","Les ganglions inguinaux superficiels","Les ganglions lombo-aortiques, comme l'ovaire","Les ganglions sacrés, en arrière"],"r":0,"e":"La partie inférieure se draine, elle, vers les ganglions inguinaux superficiels.","s":24},{"q":"Le tiers supérieur du vagin est innervé par :","o":["Le plexus hypogastrique, et il est peu sensible","Le nerf pudendal, et il est très sensible","Le nerf obturateur, et il est sensible au toucher profond","Le plexus aortique, autonome"],"r":0,"e":"Le tiers inférieur, innervé par le nerf pudendal, est somatique et très sensible. L'innervation est autonome.","s":24},{"q":"La muqueuse vaginale est constituée :","o":["D'un épithélium pavimenteux stratifié non kératinisé","D'un épithélium prismatique simple","D'un épithélium cubique, comme les canaux glandulaires du rein","D'un épithélium cilié, comme la trompe"],"r":0,"e":"La paroi comprend ensuite une musculeuse à deux couches et une adventice conjonctive lâche. Elle forme des plis transversaux.","s":24},{"q":"Le vagin se caractérise par :","o":["L'absence de glandes propres dans sa paroi","La présence de nombreuses glandes","Des glandes de Bartholin dans sa paroi, sur toute la longueur","Des cryptes sécrétoires, profondes"],"r":0,"e":"Ses cellules épithéliales sont en revanche riches en glycogène, sous l'effet des œstrogènes. La lubrification vient des sécrétions cervicales et de la transsudation.","s":24},{"q":"Les lactobacilles, ou bacilles de Döderlein :","o":["Transforment le glycogène en acide lactique, à pH 4","Produisent du mucus, à pH 7, pour neutraliser l'acidité","Digèrent les protéines du mucus","Sécrètent des œstrogènes locaux"],"r":0,"e":"Ce pH acide constitue une barrière contre les infections. Le pH est de 3,8 à 4,5.","s":24},{"q":"Avant la puberté et après la ménopause, la muqueuse vaginale :","o":["Est fine, pauvre en glycogène et plus vulnérable","Est épaisse et riche en glycogène, donc très protégée","A un pH plus acide qu'à l'âge adulte","Est inchangée, quel que soit l'âge"],"r":0,"e":"C'est la conséquence directe de la carence œstrogénique. Son pH est plus alcalin.","s":24},{"q":"Les grandes lèvres mesurent environ :","o":["3 cm de long","7 à 8 cm de long","12 cm de long","15 cm de long"],"r":1,"e":"Leur face externe est cutanée pigmentée avec poils et glandes, leur face interne muqueuse ; ce sont les homologues du scrotum.","s":24},{"q":"En avant, les petites lèvres se divisent en deux lamelles formant :","o":["Le prépuce et le frein du clitoris","Les grandes lèvres, en dehors d'elles","La commissure postérieure","L'hymen, à l'entrée du vagin"],"r":0,"e":"Elles délimitent le vestibule, dépourvues de poils. La lamelle supérieure forme le prépuce, l'inférieure le frein.","s":24},{"q":"Le clitoris est composé :","o":["De deux racines, de deux corps caverneux et d'un gland","D'un corps spongieux, médian","D'un seul corps caverneux","De trois corps érectiles, comme le pénis, sans racine propre"],"r":0,"e":"Les racines s'insèrent sur les branches ischio-pubiennes et sont recouvertes par les muscles ischio-caverneux.","s":24},{"q":"L'innervation sensitive du clitoris est assurée par :","o":["Le nerf dorsal du clitoris, branche du pudendal","Le plexus hypogastrique inférieur","Le nerf obturateur, en dedans","Le nerf génito-fémoral, par sa branche génitale et labiale"],"r":0,"e":"Sa vascularisation provient des artères profondes et dorsale du clitoris, branches de la pudendale interne.","s":24},{"q":"Les glandes de Bartholin sont les homologues :","o":["Des glandes bulbo-urétrales de Cowper","De la prostate, autour de l'urètre","Des vésicules séminales","Des testicules, endocrines"],"r":0,"e":"Paires, elles siègent à la partie postéro-latérale du vestibule.","s":24},{"q":"Le mont du pubis est limité au-dessus par :","o":["Le sillon supra-pubien","La commissure antérieure","Le clitoris","Les grandes lèvres"],"r":0,"e":"C'est une saillie cutanée graisseuse recouverte de poils après la puberté.","s":24},{"q":"Le rôle du clitoris est décrit dans le cours comme :","o":["Exclusivement dédié au plaisir sexuel","Mixte, urinaire et sexuel","Reproductif, par le transport des gamètes","De soutien du périnée"],"r":0,"e":"Il compte des milliers de terminaisons nerveuses et constitue l'homologue du pénis.","s":24},{"q":"Le vestibule vulvaire est délimité par :","o":["Les petites lèvres","Les grandes lèvres","Le mont du pubis","Le périnée"],"r":0,"e":"S'y ouvrent le méat urinaire en avant, l'orifice vaginal en arrière et les orifices des glandes vestibulaires.","s":24},{"q":"Hormone responsable de la production de lait :","o":["Ocytocine","Prolactine","Œstrogènes","FSH"],"r":1,"e":"Prolactine = lactogenèse. Ocytocine = éjection.","s":25},{"q":"La grossesse dure :","o":["35 semaines d'aménorrhée","40 semaines d'aménorrhée","42 semaines d'aménorrhée","50 semaines d'aménorrhée"],"r":1,"e":"40 semaines d'aménorrhée = 38 semaines de grossesse réelle. 3 trimestres. Cela fait 38 semaines de grossesse réelle.","s":25},{"q":"Le colostrum est riche en :","o":["Des lipides, en grande quantité","Des IgA, ou immunoglobulines A","Du lactose, en grande quantité","De la caséine, et un peu d'IgG"],"r":1,"e":"Colostrum = premier lait, riche en IgA → immunité passive du nouveau-né.","s":25},{"q":"Le ganglion sentinelle est :","o":["Le ganglion le plus volumineux de l'aisselle","Le premier relais ganglionnaire d'une tumeur","Le ganglion sus-claviculaire","Le ganglion à l'origine du cancer"],"r":1,"e":"Premier relais d'une tumeur. Permet d'éviter le curage axillaire complet si négatif.","s":25},{"q":"Le pic de LH déclenche :","o":["Menstruations","Ovulation","Nidation","Accouchement"],"r":1,"e":"Pic de LH à J14 → rupture folliculaire → ovulation.","s":25},{"q":"La FSH agit sur :","o":["Corps jaune","Croissance folliculaire","Endomètre directement","Glande mammaire"],"r":1,"e":"FSH = folliculo-stimulante → croissance des follicules ovariens.","s":25},{"q":"La phase folliculaire dure environ :","o":["Environ 5 jours, fixe","Environ 14 jours, variable","Environ 20 jours, fixe","Environ 28 jours, variable"],"r":1,"e":"Phase folliculaire ~14 jours (variable). Phase lutéale ~14 jours (constante).","s":25},{"q":"L'hCG est produite par :","o":["L'ovaire, par le corps jaune","Le trophoblaste, futur placenta","L'hypophyse antérieure","L'utérus, par l'endomètre"],"r":1,"e":"Trophoblaste → hCG → maintient le corps jaune. Marqueur de grossesse.","s":25},{"q":"Effet principal des œstrogènes :","o":["Une hausse de la température corporelle","La prolifération de l'endomètre et les caractères sexuels","Une glaire cervicale épaisse","Une relaxation utérine, en préparation de la nidation de l'œuf"],"r":1,"e":"Œstrogènes : prolifération endomètre + caractères sexuels secondaires + glaire fluide. Les caractères sexuels sont secondaires.","s":25},{"q":"Effet principal de la progestérone :","o":["La prolifération de l'endomètre, en première phase","La phase sécrétoire et la hausse de température","Les caractères sexuels secondaires","L'ostéoprotection, après 50 ans"],"r":1,"e":"Progestérone : sécrétion endo + ↑ T° + glaire épaisse + relaxation utérine. Elle relâche aussi l'utérus.","s":25},{"q":"Ménopause = arrêt des règles depuis :","o":["3 mois consécutifs","6 mois consécutifs, avec bouffées de chaleur","12 mois consécutifs","24 mois consécutifs"],"r":2,"e":"12 mois sans règles définissent la ménopause. Âge moyen 50-52 ans.","s":25},{"q":"À la ménopause, FSH et LH :","o":["Diminuent, faute de stimulation","Augmentent, faute de rétrocontrôle","Restent stables, comme avant la ménopause","Disparaissent du sang"],"r":1,"e":"↓ œstrogènes/progestérone → levée du rétrocontrôle → ↑ FSH/LH (diagnostic biologique).","s":25},{"q":"Complications majeures de la ménopause :","o":["Une hypertension artérielle, seule, sans autre risque","L'ostéoporose, le risque cardiovasculaire et l'atrophie","Une polykystose ovarienne","Aucune complication notable"],"r":1,"e":"Carence œstrogénique → ostéoporose, risque CV, sécheresse, bouffées de chaleur. L'atrophie est vaginale.","s":25},{"q":"Drainage lymphatique principal du sein (75%) :","o":["Mammaire interne","Ganglions axillaires","Sus-claviculaires","Cervicaux"],"r":1,"e":"75% axillaires (surtout pectoraux), 25% mammaires internes.","s":25},{"q":"Plexus veineux de Batson :","o":["Un plexus pelvien, utérin","Un plexus vertébral sans valves, voie des métastases","Un plexus du cou, jugulaire","Un plexus de l'aisselle, qui draine le bras et la paroi"],"r":1,"e":"Plexus rachidien sans valves → voie de dissémination métastatique vers la colonne vertébrale.","s":25},{"q":"Le placenta sécrète :","o":["La FSH, uniquement","L'hCG, l'hPL et les hormones sexuelles","Le cortisol, l'insuline et la thyroxine","La TSH, thyroïdienne"],"r":1,"e":"Placenta = organe endocrine : hCG, hPL, œstrogènes, progestérone. Les hormones sexuelles sont les œstrogènes et la progestérone.","s":25},{"q":"Volume utérin augmente pendant la grossesse :","o":["× 2","× 6","× 24","× 50"],"r":2,"e":"Volume × 24, par hyperplasie et hypertrophie des fibres musculaires.","s":25},{"q":"Étape 1 de l'accouchement :","o":["Le travail, avec contractions et dilatation du col","L'expulsion du fœtus, après la dilatation complète du col","La délivrance, avec le placenta","L'allaitement, après la naissance"],"r":0,"e":"1. Travail (contractions + dilatation). 2. Expulsion. 3. Délivrance (placenta).","s":25},{"q":"Bilirubine élevée chez le nouveau-né :","o":["Est toujours pathologique, et à traiter vite","Est souvent physiologique, en ictère néonatal","Indique une infection grave","Est toujours absente à la naissance"],"r":1,"e":"Ictère néonatal physiologique : foie immature, hémolyse post-natale.","s":25},{"q":"Le canal galactophore se termine :","o":["Dans l'aréole, par des pores","Au mamelon, par 15 à 20 pores","Dans la peau du sein, par 50 orifices","Dans le creux axillaire"],"r":1,"e":"15-20 canaux galactophores s'ouvrent au mamelon (1 par lobe).","s":25},{"q":"Le sein est suspendu par :","o":["Ligaments scapulaires","Ligaments de Cooper","Ligaments costaux","Pas de ligaments"],"r":1,"e":"Ligaments suspenseurs de Cooper : entre glande et peau.","s":25},{"q":"Prolongement axillaire du sein :","o":["Aréole","Queue de Spence","Mamelon de Montgomery","Lobule de Cooper"],"r":1,"e":"Queue de Spence : prolongement glandulaire dans l'aisselle. Importance en cancérologie.","s":25},{"q":"Glandes de Montgomery :","o":["Des glandes mammaires accessoires, en haut","Des glandes sébacées modifiées de l'aréole","Des glandes salivaires ectopiques","Des glandes sudoripares"],"r":1,"e":"Glandes sébacées modifiées sur l'aréole (tubercules de Morgagni).","s":25},{"q":"Artère principale du sein :","o":["L'aorte thoracique, directement","L'artère thoracique interne, ou mammaire interne","L'artère axillaire, à elle seule","L'artère vertébrale, par ses branches cervicales et thoraciques"],"r":1,"e":"Thoracique interne (branches perforantes) + thoracique latérale + intercostales. La thoracique latérale et les intercostales y participent.","s":25},{"q":"Tétée stimule directement :","o":["La sécrétion de FSH et de LH","La sécrétion de prolactine et d'ocytocine","La sécrétion d'insuline, au repas","La sécrétion de cortisol et d'adrénaline, par le stress"],"r":1,"e":"Stimulation du mamelon → réflexe neuro-hormonal → ↑ prolactine + ocytocine.","s":25},{"q":"Pic de l'œstrogène est juste avant :","o":["Menstruations","Ovulation","Phase sécrétoire","Nidation"],"r":1,"e":"Œstrogènes culminent en fin de phase folliculaire → pic LH → ovulation.","s":25},{"q":"Sécrétion endocrinienne ovarienne :","o":["Les cellules de Sertoli, de soutien","Les cellules de la thèque et de la granulosa","Les cellules de Leydig, entre les tubes, dans l'ovaire","Les cellules de Bowman, du rein"],"r":1,"e":"Thèque + granulosa coopèrent pour la synthèse des œstrogènes.","s":25},{"q":"Test de grossesse détecte :","o":["LH","FSH","β-hCG","Progestérone"],"r":2,"e":"β-hCG urinaire ou sanguine, détectable dès 8-10 jours post-fécondation.","s":25},{"q":"La caduque est :","o":["Le placenta, à terme","L'endomètre transformé pendant la grossesse","L'embryon, avant 8 semaines","Le myomètre, épaissi pendant toute la grossesse"],"r":1,"e":"Caduque = endomètre gravidique, expulsé à la délivrance. Elle est expulsée à la délivrance.","s":25},{"q":"Hormones de l'allaitement bloquées par :","o":["L'adrénaline, lors du stress","La dopamine, pendant la grossesse","La sérotonine, au niveau cérébral","Le cortisol, au stress"],"r":1,"e":"Dopamine inhibe la prolactine. La chute des œstrogènes/progestérone post-partum lève cette inhibition. La dopamine inhibe la prolactine.","s":25},{"q":"Le sein s'étend, selon ce cours :","o":["De la 3ᵉ à la 7ᵉ côte, du sternum à la ligne axillaire","De la 1ʳᵉ à la 4ᵉ côte, de la clavicule au mamelon, en haut","De la 5ᵉ à la 9ᵉ côte, sous le sein","Sur tout l'hémithorax, en avant"],"r":0,"e":"Il repose sur le grand pectoral et le grand dentelé, avec un prolongement axillaire appelé queue de Spence. La ligne axillaire est la ligne axillaire moyenne.","s":25},{"q":"Le mamelon est percé de :","o":["5 pores","15 à 20 pores","50 pores","1 pore"],"r":1,"e":"Ce sont les ouvertures des canaux galactophores, un par lobe.","s":25},{"q":"Les tubercules de Morgagni de l'aréole correspondent :","o":["Aux glandes de Montgomery, des glandes sébacées","Aux canaux galactophores, qui s'ouvrent à leur sommet","Aux acini, sécréteurs de lait","Aux ligaments de Cooper"],"r":0,"e":"L'aréole est la zone circulaire pigmentée entourant le mamelon. Ce sont des glandes sébacées modifiées.","s":25},{"q":"Dans la glande mammaire, les unités sécrétrices sont :","o":["Les alvéoles, ou acini, des lobules","Les lobes, au nombre de 15 à 20","Les canaux galactophores","Les ligaments de Cooper, entre la glande et la peau"],"r":0,"e":"Chaque lobe contient plusieurs lobules, dont les acini se drainent vers un canal galactophore.","s":25},{"q":"Les ligaments suspenseurs de Cooper sont :","o":["Des travées fibreuses entre la glande et la peau","Des canaux excréteurs du lait","Des vaisseaux nourriciers","Des muscles lisses, qui soulèvent le sein et le mamelon"],"r":0,"e":"Le tissu adipeux, qui enveloppe et imprègne la glande, donne au sein son volume.","s":25},{"q":"Le plexus veineux de Batson :","o":["N'a pas de valves et favorise les métastases vertébrales","Draine le sein vers le foie, par la porte","Est un plexus artériel, vertébral","Contient de nombreuses valves, qui empêchent tout reflux veineux"],"r":0,"e":"Le drainage veineux du sein se fait sinon vers les veines thoracique interne, axillaire et intercostales.","s":25},{"q":"Le drainage lymphatique du sein se fait pour 20 à 25 % vers :","o":["Les ganglions axillaires, par le groupe pectoral","La chaîne mammaire interne","Les ganglions sus-claviculaires","Le sein controlatéral, par anastomose"],"r":1,"e":"75 % va aux ganglions axillaires, avec des anastomoses vers le sein controlatéral et la paroi abdominale. Elle suit l'artère thoracique interne.","s":25},{"q":"L'analyse du ganglion sentinelle permet :","o":["D'éviter un curage complet et le risque de lymphœdème","De poser à lui seul le diagnostic de cancer du sein","De déterminer le type histologique","De remplacer la mammographie"],"r":0,"e":"C'est le premier relais ganglionnaire d'une tumeur. Le curage est axillaire.","s":25},{"q":"La GnRH est sécrétée :","o":["Par l'hypothalamus, de façon pulsatile","Par l'hypophyse antérieure","Par les ovaires, de façon continue, pendant tout le cycle","Par le placenta, à terme"],"r":0,"e":"L'hypophyse antérieure sécrète ensuite la FSH et la LH.","s":25},{"q":"L'inhibine est sécrétée par les ovaires et assure :","o":["Un rétrocontrôle négatif","Un rétrocontrôle positif","L'ovulation","La nidation"],"r":0,"e":"Les ovaires sécrètent aussi les œstrogènes par le follicule et la progestérone par le corps jaune.","s":25},{"q":"Parmi les effets de la progestérone, le cours cite :","o":["La phase sécrétoire et la hausse de la température","La prolifération de l'endomètre","Une glaire fluide et filante","L'ostéoprotection, par l'inhibition des ostéoclastes"],"r":0,"e":"Prolifération endométriale, glaire fluide et ostéoprotection relèvent des œstrogènes. Elle relâche l'utérus, épaissit la glaire et développe les acini mammaires.","s":25},{"q":"Entre J6 et J13, le cycle ovarien est en :","o":["Phase folliculaire tardive, à œstrogènes croissants","Phase lutéale, avec le corps jaune","Ovulation, avec le pic de LH et de FSH","Menstruations, avec la desquamation de l'endomètre fonctionnel"],"r":0,"e":"L'ovulation survient à J14 avec le pic de LH, puis la phase lutéale de J15 à J28. L'endomètre prolifère.","s":25},{"q":"La fécondation a lieu :","o":["Dans le tiers externe de la trompe, sous 24 heures","Dans l'utérus, à la nidation, vers J7","Dans l'ovaire, à l'ovulation, à J14","Dans l'isthme tubaire, dans les 72 heures qui suivent les rapports"],"r":0,"e":"Un seul spermatozoïde pénètre l'ovocyte, formant le zygote. Le délai court à partir de l'ovulation.","s":25},{"q":"Le zygote arrive dans la cavité utérine en :","o":["24 heures","3 à 4 jours","7 jours","10 jours"],"r":1,"e":"Il passe par les stades 2 cellules, 4 cellules, morula puis blastocyste.","s":25},{"q":"La nidation survient :","o":["À J7 après la fécondation, en phase sécrétoire","À J3, dans la trompe, au stade morula","À J14, au moment de l'ovulation, dans l'ovaire","À J21, dans le col de l'utérus"],"r":0,"e":"Le trophoblaste produit alors l'hCG, qui maintient le corps jaune.","s":25},{"q":"La durée de la gestation est de :","o":["38 semaines d'aménorrhée","40 semaines d'aménorrhée, soit 38 de grossesse","42 semaines de grossesse, soit 44 d'aménorrhée","36 semaines, soit 34 de grossesse"],"r":1,"e":"Elle se répartit en trois trimestres.","s":25},{"q":"Pendant la grossesse, le volume utérin est multiplié par :","o":["6","12","24","50"],"r":2,"e":"S'y associent une hyperplasie et une hypertrophie des fibres du myomètre et une forte augmentation de la vascularisation.","s":25},{"q":"L'ocytocine a pour effets :","o":["L'éjection du lait et les contractions utérines","La production du lait, par les acini","La prolifération de l'endomètre","L'ovulation, par le pic de LH qu'elle déclenche à J14"],"r":0,"e":"La prolactine assure, elle, la production de lait.","s":25},{"q":"La FSH agit principalement sur :","o":["La croissance folliculaire","L'ovulation, au milieu du cycle","Le corps jaune, qu'elle entretient jusqu'aux règles","L'endomètre, en prolifération"],"r":0,"e":"La LH déclenche l'ovulation et entretient le corps jaune.","s":25},{"q":"Les cinq groupes de ganglions axillaires sont :","o":["Pectoraux, subscapulaires, brachiaux, centraux et apicaux","Trois groupes seulement, antérieur, central et apical","Cervicaux, axillaires et sus-claviculaires","Mammaires internes et externes, de chaque côté"],"r":0,"e":"Ils reçoivent 75 % du drainage lymphatique du sein, surtout par le groupe pectoral.","s":25},{"q":"Lieu de la spermatogenèse :","o":["L'épididyme, en sa tête","Les tubes séminifères des testicules","La prostate, dans sa zone périphérique","Les vésicules séminales"],"r":1,"e":"Tubes séminifères contournés des testicules. Dure 74 jours. Elle dure 74 jours.","s":26},{"q":"Cellules productrices de testostérone :","o":["Cellules de Leydig","Cellules de Sertoli","Spermatogonies","Cellules de la granulosa"],"r":0,"e":"Leydig (interstitielles) → testostérone (sous LH). Sertoli → soutien des spermatogonies (sous FSH).","s":26},{"q":"Poids moyen d'un testicule :","o":["5 g","20 g","50 g","100 g"],"r":1,"e":"~20 g. Dimensions : 4-5 × 3 × 2,5 cm.","s":26},{"q":"Température testiculaire optimale :","o":["37°C comme le corps","2-3°C inférieure","10°C inférieure","2°C supérieure"],"r":1,"e":"2-3°C en-dessous du corps. Le scrotum thermorégule via dartos et crémaster.","s":26},{"q":"Capsule fibreuse du testicule :","o":["Capsule rénale","Albuginée","Albumine","Tunique fibreuse"],"r":1,"e":"Albuginée (comme l'ovaire). Envoie des septa qui divisent en 200-300 lobules.","s":26},{"q":"Maturation des spermatozoïdes :","o":["Dans les tubes séminifères","Dans l'épididyme","Dans le canal déférent","Dans la prostate"],"r":1,"e":"Épididyme = maturation (mobilité) + réservoir. Tube unique de ~6 m pelotonné.","s":26},{"q":"Longueur du canal déférent :","o":["10 cm","20 cm","~45 cm","1 m"],"r":2,"e":"~45 cm. Du scrotum à l'ampoule, traverse le canal inguinal (cordon spermatique).","s":26},{"q":"Le cordon spermatique contient :","o":["Le seul canal déférent, isolé","Le canal déférent, les vaisseaux, les nerfs et le crémaster","Le canal déférent et l'uretère","La vésicule séminale, la prostate et les canaux éjaculateurs"],"r":1,"e":"Contenu complet : canal déférent + artère testiculaire + plexus veineux pampiniforme + nerfs + crémaster. Les veines forment le plexus pampiniforme.","s":26},{"q":"Vésicules séminales contribuent à :","o":["10% du sperme","30%","60-70%","90%"],"r":2,"e":"60-70% du volume. Liquide alcalin riche en fructose (énergie).","s":26},{"q":"Prostate contribue au sperme à :","o":["5%","25-30%","50%","75%"],"r":1,"e":"25-30% du sperme. Liquide alcalin riche en zinc, citrate, PSA.","s":26},{"q":"Zone prostatique où se développe l'HBP :","o":["La zone centrale, en arrière","La zone périphérique, palpable au toucher rectal","La zone de transition, péri-urétrale","Le stroma antérieur, fibreux"],"r":2,"e":"HBP = zone de transition (péri-urétrale) → dysurie. Cancer = zone périphérique.","s":26},{"q":"Zone prostatique où se développe le cancer :","o":["La zone centrale, à 25 %","La zone périphérique, à 70 %","La zone de transition, autour de l'urètre, à 5 %","Le stroma antérieur, sans glande"],"r":1,"e":"Cancer de prostate dans la zone périphérique → palpable au TR.","s":26},{"q":"Le pénis comporte :","o":["Un seul corps caverneux et deux spongieux","Deux corps caverneux et un corps spongieux","Trois corps caverneux, sans spongieux","Deux corps spongieux, sans caverneux"],"r":1,"e":"2 corps caverneux dorsaux + 1 corps spongieux ventral (traversé par l'urètre).","s":26},{"q":"Innervation parasympathique du pénis :","o":["Les racines T11 à L2, sympathiques","Les racines S2 à S4, pour l'érection","Les racines C3 à C5, du phrénique","Les racines L4 à S1, du sciatique"],"r":1,"e":"S2-S4 (« keeps the penis off the floor ») → érection. Sympa T11-L2 → éjaculation.","s":26},{"q":"L'urètre masculin a une longueur de :","o":["5 cm","10 cm","16-20 cm","30 cm"],"r":2,"e":"16-20 cm. Beaucoup plus long que le féminin (3-4 cm).","s":26},{"q":"Portion la plus courte de l'urètre masculin :","o":["La prostatique, de 3 cm","La membraneuse, de 1 à 2 cm","La spongieuse, de 12 cm","La pré-prostatique, de 1 cm environ"],"r":1,"e":"Membraneuse (1-2 cm) traverse le diaphragme uro-génital. Sphincter strié.","s":26},{"q":"Le verumontanum est :","o":["Un sphincter de l'urètre","Une saillie de l'urètre prostatique","Une glande accessoire","Un nerf du plancher pelvien, sensitif"],"r":1,"e":"Colliculus séminal = saillie de l'urètre prostatique où s'abouchent les canaux éjaculateurs + canaux prostatiques. Les canaux éjaculateurs s'y abouchent.","s":26},{"q":"Le scrotum est divisé en 2 par :","o":["Aponévrose","Septum scrotal","Diaphragme","Os"],"r":1,"e":"Septum scrotal au milieu. Visible en surface par le raphé scrotal.","s":26},{"q":"Innervation des cellules de Sertoli :","o":["LH","FSH","TSH","Prolactine"],"r":1,"e":"FSH stimule les cellules de Sertoli (support spermatogenèse). LH → Leydig (testostérone).","s":26},{"q":"Le mécanisme de l'érection implique :","o":["Une vasoconstriction des artères","Une vasodilatation des artères caverneuses par le NO","Une contraction striée, sous contrôle volontaire du SNC","Le seul système sympathique, en continu"],"r":1,"e":"Para → NO → vasodilatation → afflux sanguin → compression veineuse → maintien.","s":26},{"q":"Le sildénafil (Viagra) agit sur :","o":["Les récepteurs adrénergiques","L'inhibition de la PDE5, qui potentialise le NO","Les récepteurs cholinergiques","Les hormones sexuelles, en augmentant la LH de 20 %"],"r":1,"e":"Inhibiteur de la PDE5 → potentialise l'effet du NO sur les corps caverneux.","s":26},{"q":"Volume éjaculatoire normal :","o":["0,1 mL","2-5 mL","20-50 mL","100 mL"],"r":1,"e":"2-5 mL. Concentration normale > 15 millions/mL.","s":26},{"q":"Veine testiculaire gauche se jette dans :","o":["VCI directement","Veine rénale gauche","Veine fémorale","Plexus de Batson"],"r":1,"e":"À gauche : veine rénale gauche (asymétrie). À droite : VCI directement.","s":26},{"q":"Varicocèle :","o":["Une augmentation du volume testiculaire","Une dilatation du plexus pampiniforme","Un cancer testiculaire, chez l'homme jeune, de 20 à 35 ans","Une inflammation de l'épididyme"],"r":1,"e":"Varices du plexus pampiniforme (drainage testiculaire). Plus fréquente à gauche (anatomie veineuse). Elle est plus fréquente à gauche.","s":26},{"q":"Spermatogenèse dure :","o":["7 jours","28 jours","~74 jours","1 an"],"r":2,"e":"~74 jours dans les tubes séminifères, + ~14 jours dans l'épididyme.","s":26},{"q":"Glande la plus volumineuse de l'appareil génital masculin :","o":["Vésicule séminale","Prostate","Glandes de Cowper","Testicules"],"r":1,"e":"Prostate ~20 g, en forme de châtaigne. Sous la vessie.","s":26},{"q":"La torsion testiculaire est :","o":["Une affection bénigne, sans gravité, qui régresse seule","Une urgence chirurgicale, par risque ischémique","Une infection du testicule","Une malformation congénitale"],"r":1,"e":"Urgence : torsion du cordon → ischémie → nécrose si > 6h. Détorsion chirurgicale rapide.","s":26},{"q":"Drainage lymphatique testiculaire :","o":["Les ganglions inguinaux superficiels","Les ganglions lombo-aortiques","Les ganglions iliaques internes","Les ganglions axillaires, par la paroi thoracique"],"r":1,"e":"Testicule = origine abdominale → drainage lombo-aortique. Scrotum (peau) → inguinal. Le drainage suit les vaisseaux testiculaires.","s":26},{"q":"Andropause :","o":["Un arrêt brutal de la testostérone, comme la ménopause","Une baisse progressive de la testostérone avec l'âge","Un cancer de la prostate","Un phénomène qui n'existe pas"],"r":1,"e":"Baisse progressive de la testostérone, beaucoup plus douce que la ménopause féminine.","s":26},{"q":"Marqueur biologique de cancer de prostate :","o":["CA 125","PSA","ACE","CA 19-9"],"r":1,"e":"PSA (Prostate Specific Antigen) = marqueur de dépistage et de suivi du cancer prostatique.","s":26},{"q":"Les dimensions du testicule sont :","o":["4-5 × 3 × 2,5 cm, pour 20 g","2 × 1 × 1 cm, pour 5 g","8 × 5 × 3 cm, pour 60 g, chez l'adulte","6 × 4 × 3 cm, pour 40 g"],"r":0,"e":"Le testicule gauche descend généralement plus bas que le droit.","s":26},{"q":"Le bord postérieur du testicule :","o":["Est libre, sans aucune attache, en arrière","Est le lieu de fixation de l'épididyme","Porte le cordon spermatique","Porte l'albuginée seule"],"r":1,"e":"Le testicule présente deux faces, deux bords et deux pôles ; le bord antérieur est libre.","s":26},{"q":"La vaginale testiculaire est :","o":["Une séreuse à deux feuillets, vestige du péritoine","Une capsule fibreuse, blanche et résistante, au contact direct","Un muscle lisse, le dartos","Un fascia spermatique, interne"],"r":0,"e":"L'albuginée est la capsule fibreuse blanche résistante, la plus profonde des enveloppes.","s":26},{"q":"Les enveloppes du testicule comprennent, de la profondeur à la surface :","o":["De l'albuginée à la peau, en sept couches","Peau, dartos et albuginée, en trois couches","Albuginée et peau, seulement","Vaginale et peau, seulement"],"r":0,"e":"Le muscle crémaster remonte les testicules au froid. Ce sont l'albuginée, la vaginale, le fascia spermatique interne, le crémaster, le fascia spermatique externe, le dartos et la peau.","s":26},{"q":"L'albuginée divise le testicule en :","o":["10 à 20 lobules","50 lobules environ","200 à 300 lobules","1 000 lobules, dans chaque testicule"],"r":2,"e":"Chaque lobule contient 1 à 4 tubes séminifères contournés, qui confluent en tubes droits puis dans le rete testis.","s":26},{"q":"Les cellules de Sertoli :","o":["Soutiennent les spermatogonies, dans les tubes séminifères","Sécrètent la testostérone, entre les tubes séminifères","Sont situées entre les tubes séminifères","Produisent le liquide séminal"],"r":0,"e":"Les cellules de Leydig, situées entre les tubes, sécrètent la testostérone.","s":26},{"q":"La spermatogenèse dure environ :","o":["24 jours","46 jours","74 jours","120 jours"],"r":2,"e":"Ses stades sont spermatogonie, spermatocyte I, spermatocyte II après méiose, spermatide puis spermatozoïde.","s":26},{"q":"Le muscle dartos :","o":["Se contracte au froid et remonte les testicules","Se contracte au chaud et abaisse le scrotum","Est un muscle strié volontaire","Assure la spermatogenèse"],"r":0,"e":"Au chaud, il se relâche, le scrotum devient pendant et sa surface augmente. Il ride la peau.","s":26},{"q":"L'épididyme est constitué :","o":["D'un tube unique pelotonné, d'environ 6 mètres","De plusieurs tubes parallèles, de 1 mètre","D'un tissu glandulaire plein","D'un conduit court, de 5 cm"],"r":0,"e":"En forme de virgule, il comprend une tête, un corps et une queue.","s":26},{"q":"L'épididyme est le lieu :","o":["De la maturation des spermatozoïdes","De la spermatogenèse, complète","De la production de testostérone par les cellules de Leydig","De la sécrétion du liquide séminal"],"r":0,"e":"Il sert aussi de réservoir, jusqu'à plusieurs semaines. Ils y acquièrent leur mobilité.","s":26},{"q":"Le canal déférent mesure environ :","o":["15 cm","30 cm","45 cm","60 cm"],"r":2,"e":"Il monte dans le scrotum, traverse le canal inguinal dans le cordon spermatique, contourne l'uretère et s'élargit en ampoule déférentielle.","s":26},{"q":"Le cordon spermatique contient notamment :","o":["Le canal déférent, des artères, des veines et des nerfs","Le seul canal déférent, entouré de graisse et de fascias","L'urètre et le corps spongieux","La prostate et les vésicules"],"r":0,"e":"L'artère testiculaire naît de l'aorte et l'artère du canal déférent de l'iliaque interne. Les veines forment le plexus pampiniforme ; le crémaster en fait aussi partie.","s":26},{"q":"Les canaux éjaculateurs s'abouchent :","o":["Dans l'urètre prostatique, au verumontanum","Dans l'urètre spongieux, au niveau du bulbe","Dans la vessie, au trigone","Dans l'épididyme, à sa queue"],"r":0,"e":"Ils naissent de la réunion du canal déférent et du canal de la vésicule séminale et traversent la prostate.","s":26},{"q":"Les vésicules séminales sécrètent un liquide :","o":["Alcalin et riche en fructose","Acide, riche en citrate","Riche en protéines contractiles","Purement aqueux, sans aucun soluté nutritif"],"r":0,"e":"Elles contribuent à 60-70 % du volume du sperme et mesurent environ 5 cm, derrière la vessie. Le fructose nourrit les spermatozoïdes.","s":26},{"q":"Les glandes de Cowper :","o":["Sont petites et sécrètent un liquide pré-éjaculatoire","Sont impaires, médianes et volumineuses","Mesurent 5 cm de long, derrière la vessie, comme les vésicules","Produisent le fructose du sperme"],"r":0,"e":"Ce sont les glandes bulbo-urétrales, homologues des glandes de Bartholin chez la femme. Elles sont de la taille d'un pois, dans le diaphragme uro-génital.","s":26},{"q":"La prostate mesure :","o":["4 × 3 × 2 cm, pour environ 20 g","8 × 5 × 3 cm, pour 60 g","2 × 2 × 1 cm, pour 5 g","6 × 4 × 3 cm, pour environ 40 g, chez l'adulte"],"r":0,"e":"Glande impaire et médiane en forme de châtaigne, elle siège sous la vessie et est traversée par l'urètre prostatique.","s":26},{"q":"La zone centrale de la prostate représente :","o":["25 % du volume, autour des canaux éjaculateurs","70 % du volume, en périphérie","5 % du volume, autour de l'urètre, chez le jeune adulte","50 % du volume, en avant"],"r":0,"e":"La classification zonale est celle de McNeal.","s":26},{"q":"Le testicule doit être maintenu à une température :","o":["Identique à la température du corps, soit 37 °C","De 2 à 3 °C sous la température du corps","De 2 à 3 °C au-dessus de celle du corps","De 10 °C en dessous de celle du corps"],"r":1,"e":"Cette exigence explique la position scrotale et le rôle thermorégulateur du dartos et du crémaster.","s":26},{"q":"Le raphé scrotal correspond :","o":["À la ligne médiane visible sur la peau du scrotum","Au septum interne du scrotum","Au muscle dartos, sous la peau","Au cordon spermatique, à la racine des bourses, en haut"],"r":0,"e":"Le septum scrotal divise, lui, la bourse en deux loges.","s":26},{"q":"Les fonctions du système reproducteur masculin comprennent :","o":["Les gamètes, la testostérone, le transport et l'émission","La seule production de gamètes","La seule production hormonale, par les cellules de Leydig","Le seul transport des spermatozoïdes"],"r":0,"e":"L'urètre y est commun aux appareils urinaire et génital. Le stockage des spermatozoïdes en fait aussi partie.","s":26},{"q":"Constitution de l'os coxal :","o":["Deux os fusionnés, ilion et pubis","Trois os, ilion, ischion et pubis","Quatre os, avec le sacrum, soudés à l'adolescence","Un os unique dès la naissance"],"r":1,"e":"Ilion + ischion + pubis fusionnent à l'adolescence.","s":27},{"q":"Symphyse pubienne est :","o":["Une articulation synoviale, mobile","Une amphiarthrose, à disque fibrocartilagineux","Une suture fibreuse, comme le crâne","Une diarthrose, très mobile, avec une capsule et une synoviale"],"r":1,"e":"Amphi-arthrose entre les 2 pubis, disque fibrocartilagineux.","s":27},{"q":"Angle pubien féminin :","o":["Inférieur à 60°, très aigu","Inférieur à 90°, aigu","Supérieur à 90°, obtus","De 120° exactement"],"r":2,"e":"Femme : > 90° (adaptation obstétricale). Homme : < 90° (aigu).","s":27},{"q":"Détroit supérieur passe par :","o":["Coccyx → ischions → pubis","Promontoire → lignes arquées → crête pubienne","Sacrum → tête fémorale → pubis","L4 → ailes iliaques → épines iliaques antéro-supérieures"],"r":1,"e":"Promontoire sacré (arr) + ligne arquée (lat) + symphyse (avant).","s":27},{"q":"Cul-de-sac le plus déclive chez la femme :","o":["Le vésico-utérin, en avant","Le recto-utérin, de Douglas","Le recto-vésical, comme chez l'homme","Le sous-phrénique, sous le diaphragme, à droite"],"r":1,"e":"Douglas (recto-utérin) = point le plus bas chez la femme. Ponctionnable.","s":27},{"q":"Cul-de-sac le plus déclive chez l'homme :","o":["Recto-utérin","Recto-vésical","Vésico-rectal","Pré-vésical"],"r":1,"e":"Recto-vésical chez l'homme (pas d'utérus).","s":27},{"q":"Plancher pelvien profond :","o":["Le transverse profond, dans le plan moyen du périnée","L'élévateur de l'anus et le muscle coccygien","Le bulbo-spongieux, en surface","Le sphincter externe de l'anus"],"r":1,"e":"Diaphragme pelvien = levator ani + coccygien.","s":27},{"q":"3 faisceaux du levator ani :","o":["Pubo-rectal, pubo-coccygien, ilio-coccygien","Sacro-coccygien, ischio-pubien, transverse","Antérieur, moyen, postérieur","Pubo-spongieux, levator, sphincter"],"r":0,"e":"3 faisceaux : pubo-rectal (le plus médial, fronde) + pubo-coccygien + ilio-coccygien (le plus latéral).","s":27},{"q":"Innervation du levator ani :","o":["Le nerf obturateur, de L2 à L4, par le canal obturateur","Le plexus sacré, de S3 à S4, et le nerf pudendal","Le nerf phrénique, de C3 à C5","Le nerf fémoral, de L2 à L4"],"r":1,"e":"Plexus sacré direct (S3-S4) + nerf pudendal.","s":27},{"q":"Sympathique pelvien provient de :","o":["De T10 à L2, par les plexus hypogastriques","De S2 à S4, par les nerfs splanchniques","De T1 à T4, par le cœur","De C3 à C5, par le phrénique"],"r":0,"e":"Sympathique pelvien : T10-L2 (plexus hypogastriques sup et inf).","s":27},{"q":"Parasympathique pelvien :","o":["Le nerf vague, jusqu'au pelvis","Les nerfs splanchniques pelviens, de S2 à S4","Le sympathique, de T10 à L2, par les plexus hypogastriques","Le plexus brachial, au cou"],"r":1,"e":"Para S2-S4 : vidange (urine, selles) + érection.","s":27},{"q":"Nerf pudendal naît de :","o":["L4-L5","S2-S4","T12-L1","L5-S1"],"r":1,"e":"S2-S4. Traverse le canal d'Alcock. Innerve périnée + sphincters striés + organes génitaux externes.","s":27},{"q":"Artère iliaque commune se divise en :","o":["Iliaque + fémorale","Iliaque externe + iliaque interne","Hypogastrique + obturatrice","Sacrée + pudendale"],"r":1,"e":"Iliaque commune → externe (cuisse) + interne (organes pelviens).","s":27},{"q":"Niveau de bifurcation aortique :","o":["L2","L3","L4","L5"],"r":2,"e":"Aorte se divise à L4 en 2 iliaques communes.","s":27},{"q":"Le « ligne arquée » de l'os iliaque correspond à :","o":["L'ouverture inférieure du bassin","La limite latérale du détroit supérieur","Le bord du grand fessier","Le sillon iléo-pectiné, au bord antérieur du coxal"],"r":1,"e":"Ligne arquée = repère latéral du détroit supérieur du bassin.","s":27},{"q":"Petit bassin =","o":["La partie au-dessus du détroit supérieur, en haut","La partie sous le détroit supérieur, ou vrai pelvis","Le côté droit du bassin, sous l'ilion","Le diaphragme pelvien, au fond"],"r":1,"e":"Grand bassin = sus-détroit (cavité abdominale). Petit bassin = sous-détroit (vraie cavité pelvienne).","s":27},{"q":"EIAS signifie :","o":["Échancrure ilio-sciatique antérieure","Épine iliaque antéro-supérieure","Articulation interne-supérieure","Élévateur ischio-acétabulaire"],"r":1,"e":"EIAS = repère antérieur palpable, insertion du Sartorius et du ligament inguinal.","s":27},{"q":"Articulation sacro-iliaque est :","o":["Très mobile","Très peu mobile","Synoviale mobile","Inexistante"],"r":1,"e":"Articulation peu mobile. Mobilité augmentée pendant la grossesse (relaxine).","s":27},{"q":"Foramen obturé :","o":["Identique dans les deux sexes","Triangulaire chez la femme, ovale chez l'homme","Carré chez l'homme, rond chez la femme, à l'adolescence","Absent chez l'adulte, fermé"],"r":1,"e":"Forme du foramen obturé varie entre les sexes.","s":27},{"q":"Branches de l'iliaque interne :","o":["La seule artère vésicale, pour la vessie et l'urètre","Des branches vésicales, utérine et pudendale","La seule obturatrice, à la cuisse","Les mêmes que l'iliaque externe"],"r":1,"e":"Multiples branches viscérales et pariétales. Tronc antérieur + postérieur. La rectale moyenne, l'obturatrice et les glutéales en font aussi partie.","s":27},{"q":"Drainage lymphatique pelvien terminal :","o":["Cervicaux","Lombo-aortiques","Axillaires","Inguinaux"],"r":1,"e":"Iliaques int et ext → lombo-aortiques → citerne du chyle → canal thoracique.","s":27},{"q":"Au-dessus du diaphragme uro-génital :","o":["Le sphincter strié de l'urètre, dans le plan moyen","Le diaphragme pelvien, avec l'élévateur de l'anus","Le vagin et le col, en arrière","La vessie et l'urètre, en avant"],"r":1,"e":"Profond : diaphragme pelvien. Moyen : diaphragme uro-génital. Superficiel : muscles érectiles.","s":27},{"q":"Canal d'Alcock :","o":["Le canal de l'urètre, membraneux","Le canal du nerf et des vaisseaux pudendaux","Le canal de l'uretère, pelvien","La veine génitale, dans la paroi pelvienne, avec l'artère"],"r":1,"e":"Dédoublement du fascia obturateur. Contient le paquet vasculo-nerveux pudendal. C'est un dédoublement du fascia obturateur.","s":27},{"q":"Rééducation périnéale prévient :","o":["Lombalgie uniquement","Incontinence et prolapsus","Sciatique","Tendinite"],"r":1,"e":"Indication majeure en kinésithérapie : post-partum, ménopause, incontinence.","s":27},{"q":"Plexus hypogastrique inférieur :","o":["Strictement sympathique, de T10 à L2","Mixte, sympathique et parasympathique","Somatique, sous contrôle volontaire","Sans aucune innervation viscérale, vasculaire seulement"],"r":1,"e":"Plexus mixte autonome. Innerve viscères pelviens.","s":27},{"q":"Promontoire =","o":["Le sommet du coccyx, en bas","L'angle sacro-vertébral, en L5-S1","La pointe du sacrum, en S5, au contact du coccyx","La crête iliaque, en L4"],"r":1,"e":"Angle entre L5 et S1, projection antérieure. Repère du détroit supérieur.","s":27},{"q":"Anneau de Pirogoff :","o":["Un anneau pelvien, osseux","Le confluent jugulo-subclavier, lymphatique","Le cercle artériel du cerveau, à la base du crâne","Un espace de l'abdomen"],"r":1,"e":"Angle jugulo-subclavier où se jettent les troncs lymphatiques (canal thoracique à gauche).","s":27},{"q":"Diamètre obstétrical antéro-postérieur :","o":["Symphyso-pubien","Promonto-pubien","Pubo-coccygien","Sacro-pubien"],"r":1,"e":"Promonto-pubien minimum = diamètre du détroit supérieur, important en obstétrique.","s":27},{"q":"La grande échancrure sciatique est traversée par :","o":["Le seul nerf pudendal, avec ses vaisseaux et ses branches","Le sciatique, les vaisseaux glutéaux et le pudendal","Aucun élément vasculo-nerveux","Les seuls vaisseaux fémoraux"],"r":1,"e":"Grande échancrure : nerf sciatique, vaisseaux et nerfs glutéaux, pudendal (qui contourne par la petite).","s":27},{"q":"Le sphincter externe de l'anus est :","o":["Un muscle lisse involontaire","Un muscle strié, innervé par le nerf pudendal","Un muscle cardiaque, à contraction autonome rythmique","Absent chez l'adulte, involué"],"r":1,"e":"Strié, volontaire, innervé par le nerf pudendal. Continence anale.","s":27},{"q":"Parmi les fonctions de la cavité pelvienne, le cours cite :","o":["Contenir les viscères et transmettre le poids du tronc","La seule protection des viscères","Le seul soutien du tronc, par les sacro-iliaques et la symphyse","La seule fonction obstétricale"],"r":0,"e":"Elle occupe la partie inférieure de la cavité abdomino-pelvienne, sous le détroit supérieur. Elle soutient aussi la gestation et forme la filière obstétricale.","s":27},{"q":"L'os coxal résulte de la fusion, à l'adolescence :","o":["De l'ilion, de l'ischion et du pubis","Du sacrum, du coccyx et de l'ilion","De deux os iliaques, soudés en avant","De l'ilion et du sacrum, par la sacro-iliaque"],"r":0,"e":"L'ilion est supérieur, l'ischion postéro-inférieur et le pubis antéro-inférieur.","s":27},{"q":"Les articulations sacro-iliaques sont :","o":["Très peu mobiles","Très mobiles","Fixes","Synoviales à grande amplitude"],"r":0,"e":"La symphyse pubienne est, elle, une amphiarthrose à disque fibrocartilagineux.","s":27},{"q":"La ligne arquée et l'éminence ilio-pectinée constituent :","o":["Les limites du détroit supérieur","Les limites du détroit inférieur","Des repères du sacrum","Des insertions musculaires"],"r":0,"e":"EIAS, EIPS, crête iliaque, symphyse pubienne et tubérosité ischiatique complètent les repères osseux.","s":27},{"q":"Le détroit supérieur féminin est :","o":["Ovalaire transverse","En forme de cœur","Circulaire","Triangulaire"],"r":0,"e":"Chez l'homme, il est en forme de cœur ; l'ensemble de ces différences tient à l'adaptation obstétricale du bassin féminin.","s":27},{"q":"Le sacrum féminin est :","o":["Court, large et peu courbé","Long, étroit et courbé","Identique à celui de l'homme","Absent de la comparaison"],"r":0,"e":"L'échancrure sciatique féminine est large et le foramen obturé triangulaire, contre étroite et ovale chez l'homme.","s":27},{"q":"Le détroit supérieur passe par :","o":["Le promontoire, les lignes arquées et la symphyse pubienne","Les tubérosités ischiatiques et la pointe du coccyx, plus bas","Le coccyx et le sacrum, en arrière","Les crêtes iliaques, en haut"],"r":0,"e":"C'est un plan oblique, limite supérieure de la cavité pelvienne. Le promontoire est en arrière, la crête pubienne en avant.","s":27},{"q":"Le grand bassin :","o":["Se situe au-dessus du détroit et appartient à l'abdomen","Est la véritable cavité pelvienne, sous le détroit","Est situé sous le détroit supérieur, en bas","Contient la vessie et le rectum"],"r":0,"e":"Le petit bassin, sous le détroit supérieur, constitue la véritable cavité pelvienne.","s":27},{"q":"Les limites latérales de la cavité pelvienne sont :","o":["Les os iliaques et les muscles obturateurs internes","Le sacrum et le coccyx, en arrière","La symphyse pubienne et les branches ischio-pubiennes","Le plancher pelvien, en bas"],"r":0,"e":"La limite antérieure est la symphyse pubienne et la limite postérieure le sacrum et le coccyx.","s":27},{"q":"Chez la femme, l'organisation du contenu pelvien se fait :","o":["En trois plans, vessie, utérus et vagin, puis rectum","En deux plans, vessie puis rectum","En un seul plan, tous les organes se trouvant côte à côte","Sans aucun ordre défini, au hasard"],"r":0,"e":"Chez l'homme, l'organisation est à deux plans : vessie avec prostate et vésicules séminales, puis rectum. Chez l'homme, il n'y a que deux plans.","s":27},{"q":"Le cul-de-sac recto-vésical est :","o":["Le point le plus déclive du péritoine chez l'homme","Une structure propre à la femme","Un cul-de-sac entre la vessie et l'utérus, en avant","Situé au-dessus du détroit supérieur"],"r":0,"e":"Chez la femme, c'est le cul-de-sac recto-utérin, ou de Douglas, qui est le plus déclive.","s":27},{"q":"La ponction du Douglas s'effectue :","o":["Par le fornix postérieur du vagin, ou par le rectum","Par voie abdominale, sous l'ombilic","Par voie périnéale antérieure","Par le canal inguinal, en suivant le ligament rond de l'utérus"],"r":0,"e":"Elle est indiquée en cas d'épanchement pelvien, sang ou pus.","s":27},{"q":"Le muscle élévateur de l'anus comprend :","o":["Les faisceaux pubo-rectal, pubo-coccygien et ilio-coccygien","Deux faisceaux, le pubo-coccygien et l'ilio-coccygien","Quatre faisceaux, dont le muscle coccygien","Un faisceau unique, tendu en hamac"],"r":0,"e":"Le pubo-rectal, le plus médial, forme la fronde pubo-rectale ; le muscle coccygien complète le diaphragme pelvien.","s":27},{"q":"Le diaphragme uro-génital comprend :","o":["Le transverse profond et le sphincter strié de l'urètre","Le levator ani et le coccygien","Le bulbo-spongieux, en surface","Le sphincter externe de l'anus et le transverse superficiel"],"r":0,"e":"Il constitue le plan moyen, dans le triangle uro-génital.","s":27},{"q":"Le plan superficiel du périnée comprend :","o":["Les muscles érectiles et le sphincter externe de l'anus","Le levator ani, en profondeur","Le transverse profond, au plan moyen","Le muscle coccygien et le pubo-rectal, dans le plan profond"],"r":0,"e":"Le plan profond correspond au diaphragme pelvien et le plan moyen au diaphragme uro-génital. Le transverse superficiel en fait aussi partie ; les érectiles sont l'ischio-caverneux et le bulbo-spongieux.","s":27},{"q":"Parmi les fonctions du plancher pelvien, le cours cite :","o":["Le soutien des organes, la continence et la sexualité","Le seul soutien des organes","La seule continence, urinaire et anale, sans rôle de soutien","La seule fonction sexuelle"],"r":0,"e":"Sa rééducation est essentielle en post-partum et chez la femme ménopausée. Il stabilise aussi le tronc et forme la filière obstétricale.","s":27},{"q":"La rééducation périnéale combine :","o":["Le Kegel, le biofeedback et l'électrostimulation","Des étirements passifs du périnée, en position gynécologique","Des mobilisations articulaires du bassin","Un massage seul, superficiel"],"r":0,"e":"Elle prévient l'incontinence urinaire d'effort et les prolapsus. Les contractions de Kegel sont volontaires.","s":27},{"q":"Le diaphragme pelvien est décrit comme :","o":["En forme d'entonnoir","Plan et horizontal","Convexe vers le bas","Vertical"],"r":0,"e":"Il constitue le plan profond, formé de l'élévateur de l'anus et du muscle coccygien.","s":27},{"q":"Parmi les organes pelviens communs aux deux sexes figurent :","o":["La vessie, le rectum, le sigmoïde et les uretères pelviens","L'utérus et les ovaires, en arrière","La prostate, les vésicules séminales et les canaux déférents","Les ovaires et les trompes, latéraux"],"r":0,"e":"La vessie est antérieure et le rectum postérieur. Les anses grêles en font aussi partie.","s":27},{"q":"Le mésorectum et le mésocôlon sigmoïde sont :","o":["Des mésos péritonéaux pelviens","Des muscles lisses, viscéraux","Des ligaments osseux, tendus du sacrum aux ischions","Des fascias, sous-péritonéaux"],"r":0,"e":"Le ligament large, ou méso-utérin, s'y ajoute chez la femme.","s":27}]};
